\section{Ind-cluster algebras}
%\input{IndClusters3}
\subsection{Rooted cluster algebras}

A holistic definition of a structure preserving map between cluster algebras is hard to come by: The recursive combinatorial definition of a cluster structure on an algebra, which contributes to its computational attractiveness, also makes it difficult to pin down what a map preserving this structure should look like.

A version of a category of pointed cluster algebras has been proposed by Assem, Dupont and Schiffler \cite{ADSClus}. They introduce the category $\sf{Clus}$ of rooted cluster algebras. Its object are {\em rooted cluster algebras}, that is, cluster algebras with a fixed initial seed. This allows for a convenient definition of what it means for a ring homomorphism to commute with mutation. Before we treat the morphisms, we give a brief introduction to (rooted) cluster algebras. We follow the convention and notation from\cite{ADSClus}; the definitions in this section go, unless otherwise stated, back to Fomin and Zelevinsky \cite{FZI}. While for the reader encountering cluster algebras for the first time, the definitions might appear at first quite technical, they will soon become more natural when observed in concrete examples.

We explicitly include seeds of infinite rank, as introduced in \cite{GG1}. For this purpose, we consider {\em infinite integer matrices}: Specifically, given a set $\X$ of arbitrary cardinality, and a subset $\ex \subseteq \X$, we consider tuples of the form $B = (b_{vw})_{v \in \ex, w \in \X}$ from $\bZ$, and call this an integer matrix with rows labelled by $\ex$ and columns labelled by $\X$. The submatrix $B \mid_\ex = (b_{vw})_{v,w \in \ex}$ is called the {\em $\ex$-part of $B$}. The matrix $B$ is called {\em $\ex$-locally finite}, if  every row has only finitely many non-zero entries, that is, for all $v \in \ex$ there are only finitely many $w \in \X$ such that $b_{vw} \neq 0$. It is called {\em skew-symmetriseable} if the $\ex$-part of $B$ is skew-symmetriseable, that is, there exist positive integers $\{d_v \in \bZ_{>0}\}_{v \in \ex}$ such that for all $v,w \in \ex$ we have $d_vb_{vw} = -b_{wv}d_w$.

\begin{definition}\label{D:seed}
	A {\em seed} is a triple $\Sigma = (\X,\ex,B)$, where $\X$ is a set of indeterminates, $\ex \subseteq \X$ and $B = (b_{vw})_{v \in \ex,w\in \X}$ is an $\ex$-locally finite skew-symmetriseable integer matrix.

		The set $\X$ is called the {\em cluster}, the elements of the set $\ex$ the {\em exchangeable variables}, the elements of the set $\X \setminus \ex$ the {\em frozen variables}, and the matrix $B$ the {\em exchange matrix of $\Sigma$}. The cardinality $|\X|$ is the {\em rank of $\Sigma$}. The $\ex$-part of $B$ is called the {\em principal part of $B$}.
\end{definition}

\begin{remark}\rm
	Conventionally, the cluster $\X$ is assumed to be finite. We explicitly allow the infinite rank case. The only concession we make is the $\ex$-local finiteness condition on the exchange matrix $B$. This will ensure that the exchange relations (\ref{eqn:exchange relation}) from Definition \ref{D:mutation} are well-defined.
\end{remark}

\begin{remark}\label{R:quiver}\rm
	If the principal part of the exchange matrix $B$ of a seed $\Sigma = (\X,\ex,B)$ is skew-symmetric, that is, if for all $v,w \in \ex$ we have $b_{vw} = - b_{wv}$, we can consider the {\em associated ice quiver} instead: It is the quiver with vertices given by $\X$ and with $b_{uv}$ arrows from vertex $u$ to vertex $v$ whenever $b_{uv}>0$ and $-b_{uv}$ arrows from $u$ to $v$ whenever $b_{uv}<0$. The vertices corresponding to frozen cluster variables are marked as frozen, symbollically this is done by drawing a box around the vertex. When working in concrete examples, it will sometimes be useful to allow arrows between frozen variables (cf. Section \ref{S:combinatorial_description}). These are of no importance for the seeds, and are not recorded in the exchange matrix.
The ice quiver associated with a seed encodes all the information of the seed. In examples of seeds, we will often present the ice quiver in lieu of the triple of cluster, exchangeable variables, and exchange matrix. For example, the seed 
\[
	\Sigma = (\{x_1, x_2, x_3, x_4\}, \{x_1,x_2\}, B=\begin{bmatrix} 0 & 1 & 1 & 1 \\ -1 & 0 & -2 & 1 
    %\\ -1 & -2 & 0 & -1 \\ -1 & 0 & 1 & 0
    \end{bmatrix})
\]
can be represented by either of the two ice quivers
\begin{equation*}
\begin{tikzpicture}
	\node (1) at (0,0) {$x_1$};
	\node[draw] (2) at (1,1) {$x_3$};
	\node (3) at (1,-1) {$x_2$};
	\node[draw] (4) at (-1,-1) {$x_4$};

	\draw[->] (1) to (2);
	\draw[->] (1) to (3);
	\draw[->] (1) to (4);

	\draw[->, bend left] (2) to (3);
	\draw[->, bend right] (2) to (3);

	\draw[->] (3) to (4);
\end{tikzpicture}
\qquad\text{ or }\qquad 
\begin{tikzpicture}
	\node (1) at (0,0) {$x_1$};
	\node[draw] (2) at (1,1) {$x_3$};
	\node (3) at (1,-1) {$x_2$};
	\node[draw] (4) at (-1,-1) {$x_4$};

	\draw[->] (1) to (2);
	\draw[->] (1) to (3);
	\draw[->] (1) to (4);

	\draw[->, bend left] (2) to (3);
	\draw[->, bend right] (2) to (3);

        \draw[->, bend right] (2) to (4);

	\draw[->] (3) to (4);
\end{tikzpicture}.
\end{equation*}
Note that the requirement for a skew-symmetric exchange matrix to be $\ex$-locally finite translates to each exchangeable vertex in the associated ice quiver having finite valency.
\end{remark}

\begin{definition}\label{D:mutation}
	Let $\Sigma = (\X,\ex,B = (b_{uv}))$ be a seed, and let $x \in \ex$. The {\em mutation $\mu_x(\Sigma)$ of $\Sigma$ at $x$} is the seed 
	\[
		\mu_x(\Sigma) = (\mu_x(\X),\mu_x(\ex),\mu_x(B)),
	\]
where, setting
\begin{eqnarray}\label{eqn:exchange relation}
	x' = \frac{\prod_{b_{xu}>0}v^{b_{xu}} + \prod_{b_{xv}<0}v^{-b_{xv}}}{x} \in \bQ(\X)
\end{eqnarray}
we have
\begin{itemize}
	\item $\mu_x(X) = (X \setminus \{x\}) \cup x'$;
	\item $\mu_x(\ex) = (\ex \setminus \{x\}) \cup x'$;
	\item $\mu_x(B)$ is Fomin-Zelevinsky mutation of the matrix $B$ at the row and column labelled by $x$, i.e.\ we have $\mu_x(B) = (b'_{uv})_{u \in \mu_x(\ex),v \in \mu_{x}(\X)}$, where
\[
	b'_{uv} = \begin{cases}
			- b_{xv} & \text{ if $u = \mu_{x}(x)$}\\
			-b_{ux} & \text{ if $v = \mu_x(x)$} \\
			b_{uv} + \frac{1}{2}(|b_{ux}| b_{xv} + b_{ux}|b_{xv}|) & \text{otherwise.}

		\end{cases}
\]
\end{itemize}

Equation (\ref{eqn:exchange relation}) is referred to as an {\em exchange relation}. Furthermore, given $y \in \X$ we write
\[
	\mu_x(y) = \begin{cases}
							x' & \text{if $y = x$} \\
							y & \text{else},
						\end{cases}
\]
so that we have $\mu_x(\X) = \{\mu_x(y) \mid x \in \X\}$.
\end{definition}

We can naturallly iterate mutation from a given seed. This prepares the definition of a rooted cluster algebra later.

\begin{definition}
	Let $\Sigma = (\X,\ex,B = (b_{vw}))$ be a seed. A {\em $\Sigma$-admissible sequence} is a finite sequence $(x_1, \ldots, x_\ell)$ such that $x_1 \in \ex$ and for all $2 \leq i \leq \ell$ we have 
	\[
		x_i \in \mu_{x_{i-1}} \circ \cdots \circ \mu_{x_1}(\ex).
	\]
We call $\ell$ the {\em length} of the sequence $(x_1, \ldots, x_\ell)$.
Two seeds $\Sigma$ and $\Sigma'$ are called {\em mutation equivalent}, if there exists a $\Sigma$-admissible sequence $(x_1, \ldots, x_\ell)$ such that 
\[
	\Sigma' = \mu_{x_\ell} \circ \cdots \mu_{x_1}(\Sigma).
\]
\end{definition}

Given a $\Sigma$-admissible sequence $\underline{x} = (x_1, \ldots, x_\ell)$ we write $\mu_{\underline{x}}$ for the composite $\mu_{x_\ell} \circ \cdots \circ \mu_{x_1}$. By convention, mutation along the empty sequence $\varnothing$ of length $\ell = 0$ does not change the seed: $\mu_{\varnothing}(\Sigma) = \Sigma$.
Indeed, mutation equivalence defines an equivalence relation on the class of all seeds. Given a seed $\Sigma$, we denote by $[\Sigma]$ its mutation equivalence class.

\begin{definition}[{\cite[Definition~2.3]{FZI} \cite[Definition~1.4]{ADSClus}}]\label{D:cluster algebra}
	Let $\Sigma = (\X,\ex,B)$ be a seed. The {\em cluster algebra associated to $\Sigma$} is the subalgebra
	\[
		\cA(\Sigma) = \bZ\Bigl[ \bigcup_{(\tilde{\X},\tilde{\ex},\tilde{B}) \in [\Sigma]} \tilde{\X}\Bigr] \subseteq \bQ(\X)
	\]
of the field of rational functions in $\X$, generated by the elements of clusters of seeds in $[\Sigma]$.
\begin{itemize}
 \item The elements in $\bigcup_{(\tilde{\X},\tilde{\ex},\tilde{B}) \in [\Sigma]} \tilde{\X}$ are called the {\em cluster variables of $\cA(\Sigma)$}.
\item  The elements in $\bigcup_{(\tilde{\X},\tilde{\ex},\tilde{B}) \in [\Sigma]} \tilde{\ex}$ are called the {\em exchangeable cluster variables of $\cA(\Sigma)$}
\item The elements in $\X \setminus \ex$, are called the {\em frozen variables of $\cA(\Sigma)$}. 
\item The {\em rank of $\cA(\Sigma)$} is $|\X|$, the rank of $\Sigma$. 
\item The seeds in $[\Sigma]$ are called the {\em seeds of $\cA$}. 
\item The pair $(\cA(\Sigma), \Sigma)$ is called the {\em rooted cluster algebra with initial seed $\Sigma$}. 
\end{itemize}
\end{definition}

Note that the cluster algebra associated to $\Sigma$ only depends on the mutation equivalence class of $\Sigma$. We remove this freedom when passing to the rooted cluster algebra, which comes with a fixed initial seed. By abuse of notation, we write $\cA(\Sigma)$ for the rooted cluster algebra $(\cA(\Sigma),\Sigma)$.


\begin{notation}\label{N:integer mutation}
    For ease of notation, for any $\Sigma$-admissible sequence $(x_1, \ldots, x_k)$ and any integer $m \in \bZ$ we will allow the expression $\mu_{x_k} \circ \cdots \circ \mu_{x_1}(m)$ to mean
\[
    \mu_{x_k} \circ \cdots \circ \mu_{x_1}(m) = m,
\]
that is, mutation of an integer along an admissible sequence leaves the integer unchanged.
\end{notation}

\subsection{A category of rooted cluster algebras}

Let $\cA(\Sigma)$ and $\cA(\Sigma')$ be rooted cluster algebras with initial seeds $\Sigma = (\X, \ex, B)$ and $(\X', \ex', B')$ respectively. Given a ring homomorphism $f \colon \cA(\Sigma) \to \cA(\Sigma')$ and a $\Sigma$-admissible sequence $(x_1, \ldots, x_\ell)$, we call the sequence $(f,\Sigma,\Sigma')$-{\em biadmissible} if its image $(f(x_1), \ldots, f(x_\ell))$ is $\Sigma'$-admissible. When the rootings are clear from context, we usually just write that a sequence $(x_1, \ldots, x_\ell)$ is {\em $f$-biadmissible}. We now have the tools to define structure preserving maps between cluster algebras.


\begin{definition}\label{D:melting}[\cite[Definition~2.2]{ADSClus}]
A {\em melting cluster morphism} $f \colon \cA(\Sigma) \to \cA(\Sigma')$ between rooted cluster algebras with seeds $\Sigma = (\X,\ex,B)$ and $\Sigma' = (\X',\ex',B')$ respectively, is a unital ring homomorphism satisfying the following:
	\begin{description}
		\item[CM1] $f(\X) \subseteq \X' \cup \bZ$;
		\item[CM2] for any {\em $f$-biadmissible sequence} $(x_1, \ldots, x_\ell)$ and for all $y \in \X$, we have
		\[
			f(\mu_{x_\ell} \circ \cdots \circ \mu_{x_1}(y)) = \mu_{f(x_\ell)} \circ \cdots \circ \mu_{f(x_1)}(f(y));
		\]
		\item[MCM] $f(\ex) \subseteq \ex' \cup \bZ$.
	\end{description}
\end{definition}

Axioms CM1 and CM2 are not enough to ensure composability of cluster morphisms, hence further assumptions are required. The first M in the name of axiom MCM stands for {\em melting}: We are allowed to {\em melt} frozen cluster variables, that is, send a frozen cluster variable to an exchangeable. However, we are not allowed to freeze: An exchangeable cluster variable in the domain's initial seed $\Sigma$ must be sent to an exchangeable cluster variable in the target's initial seed $\Sigma'$. In \cite{Wierzbicki} the opposite case is treated, where we are allowed {\em freezing} (sending exchangeable cluster variables to frozen variables), but not melting.

\begin{proposition}[{\cite[Proposition~2.5]{ADSClus}}]
	There is a category $\sf{Clus}$ which has as objects rooted cluster algebras and as morphisms melting cluster morphisms. 
\end{proposition}

However, melting cluster morphisms may exhibit degenerate behaviour; they do not necessarily preserve the cluster structure in a meaningful way, as the following example illustrates.

\begin{example}\rm
	Consider the seed $\Sigma$ of rank $3$ and the seed $\Sigma'$ of rank $1$ determined by their ice quivers, the latter with a single vertex:
\begin{center}
\begin{tikzpicture}
	\node (label) at (-2,0) {$\Sigma=$};
	\node (1) at (0,0) {$x$};
	\node[draw] (2) at (1,0) {$y_1$};
	\node[draw] (3) at (-1,0) {$y_2$};

	\draw[->] (1) to (2);
	\draw[->] (3) to (1);


	\node (label') at (3,0) {$\Sigma'=$};
	\node (label) at (4,0) {$z$};
\end{tikzpicture}
\end{center}	
We have $\cA(\Sigma) = \bZ[x, y_1, y_2, \frac{y_1+y_2}{x}]$ and $\cA(\Sigma') = \bZ[z,\frac{2}{z}]$. The map
\begin{eqnarray*}
	f \colon \cA(\Sigma) & \to & \cA(\Sigma') \\
		x &\mapsto & 0 \\
		y_1 &\mapsto & 1 \\
		y_2 &\mapsto & -1 \\
		\frac{y_1 + y_2}{x} & \mapsto & r
\end{eqnarray*}
is a rooted cluster morphism for any $r \in \cA(\Sigma)$. The cluster structure is not meaningfully preserved.
\end{example}

Therefore, we restrict our attention to melting cluster morphisms which guarantee that the cluster structure is preserved, and the morphism is controlled by its values on the initial cluster. These morphisms were first studied by Chang and Zhu in \cite{Chang-Zhu-rooted}.

\begin{definition}[{\cite[Definition~2.8]{Chang-Zhu-rooted}}]
	A melting cluster morphism $f \colon \cA(\Sigma) \to \cA(\Sigma')$ between rooted cluster algebras with initial seeds $\Sigma = (\X,\ex,B)$ and $\Sigma' = (\X',\ex',B')$ respectively is called {\em inducible} if it satisfies the following axiom:
	\begin{itemize}	
	\item[iMCM] $f(\ex) \subseteq \ex' \cup \bZ \setminus \{0\}$.
	\end{itemize}
\end{definition}

By the Laurent phenomenon \cite[Theorem~3.1]{FZI}, which asserts that every cluster variable can be expressed as a Laurent polynomial in its initial cluster, with denominator a product of exchangeable cluster variables, an inducible cluster morphism is uniquely determined by its values on the initial cluster.



\begin{definition}
	We denote by $\mCl$ the wide subcategory of $\sf{Clus}$ consisting of inducible melting cluster morphisms, and call this the {\em category of melting cluster morphisms}.
\end{definition}

We recall that a {\em wide} subcategory of a category of $\cC$ is a subcategory of $\cC$ which has the same objects as $\cC$, but not necessarily all of its morphisms. We are now ready to discuss the main new objects, ind-cluster algebras.

\subsection{Cluster algebras of infinite rank are ind-cluster algebras}

Cluster algebras of infinite rank have first been studied in \cite{GG1}. It was shown in \cite{Gcolimits} that any cluster algebra of infinite rank $\cA$ can be realised as a colimit of cluster algebras of finite rank in $\mCl$. 

\begin{theorem}[\cite{Gcolimits}]
\label{T:colimit}
	Let $\cA$ be a cluster algebra of infinite rank, and let $\Sigma$ be any seed of $\cA$. The rooted cluster algebra $\cA(\Sigma)$ is isomorphic to a filtered colimit of rooted cluster algebras of finite rank in $\mCl$.
\end{theorem}

\begin{proof}
	In \cite[Theorem~4.6]{Gcolimits} it is shown that every rooted cluster algebra of countably infinite rank is isomorphic to an $\bN$-shaped colimit of rooted cluster algebras of finite rank in $\mCl$. It follows from Remark \ref{R:uncountable_rank} that every rooted cluster algebra of infinite rank is isomorphic to a filtered colimit of rooted cluster algebras of countable rank. 
    The assertion follows.
	\end{proof}

The converse also holds: filtered colimits of finite rank cluster algebras exist in $\mCl$. In fact:

\begin{theorem}\label{T:filteredclosed}
	The category $\mCl$ has filtered colimits. 
 \end{theorem}

 \begin{proof}
    By \cite[Theorem~1]{AndrekaNemeti} the existence of directed colimits implies the existence of filtered colimits. The claim now follows from the explicit construction from Theorem \ref{T:directed_closed}, which is proved in Section \ref{S:construction}.
 \end{proof}

In Sections \ref{S:construction_seed} and \ref{S:construction}, we explicitly construct directed colimits in $\mCl$, which requires us to consider exchangeably connected components.

\subsection{Neighbours and exchangeably connected components}

Each seed consists of distinct exchangeably connected components.

\begin{definition}\label{D:exchangeably connected}
	Let $\Sigma=(\X,\ex,B)$ be a seed. Two cluster variables $x \in \ex$ and $y \in \X$ are called {\em $B$-neighbours} if $b_{xy} \neq 0$. For any subset $S \subseteq \X$ we write
\[
	N_{B}(S) = \{y \in \X \mid \text{$y$ is a $B$-neighbour of $z$ for some $z \in S$}\}.
\] 
If $x \in \X$, we willl usually just write $N_B(x)$ for $N_B(\{x\})$.
Two elements $v,w \in \X$ are called {\em $B$-exchangeably connected} if there exists a sequence $(x_i)_{i=0}^{n+1}$ with 
	\begin{itemize}
		\item $v = x_0$ and $w = x_{n+1}$;
		\item $x_1, \ldots, x_n \in \ex$;
		\item for all $i = 0, \ldots, n$ the consecutive elements $x_i$ and $x_{i+1}$ are $B$-neighbours.
	\end{itemize}
\end{definition}

\begin{remark} \rm
	Note that two frozen variables in $\X$ cannot be $B$-neighbours. However, they may still be exchangeably connected.
\end{remark}

Let $\Sigma = (\X,ex,B = (b_{vw})_{v,w \in \X})$ be a seed. For every $v \in \ex$ we obtain the unique {\em exchangeably connected component} $\X[v]$ of $\X$ consisting of all cluster variables in $\X$ which are exchangeably connected to $v$. Setting $\ex[\alpha] = \X[\alpha] \cap \ex$ we can decompose $\ex$ into its $B$-exchangeably connected components $\ex = \bigsqcup_{\alpha \in I} \ex[\alpha]$.
We call the seeds 
\[
    \Sigma_\alpha = (\X[\alpha], \ex[\alpha], B[\alpha] = (b_{vw})_{v,w \in \X[\alpha]})
\]
the {\em exchangeably connected components of $\Sigma$}. Note that if $v \in \X \setminus \ex$ is an isolated frozen cluster variable, that is, we have $b_{vw} = 0$ for all $w \in \X$, then it is not contained in any exchangeably connected component.


