\begin{remark}\label{R:uncountable_rank}\rm
    Every rooted cluster algebra $\cA(\Sigma)$ can be realised, in $\mCl$, as a filtered colimit of its exchangeably connected components, and its isolated  frozens. In particular, every rooted cluster algebra can be realised in this manner as a colimit of countable rank rooted cluster algebras in $\mCl$, since by \cite[Remark~3.18]{Gcolimits} every exchangeably connected component is countable, and every isolated frozen component has finite rank $1$.

    Concretely, let the index set $I_1$ label the exchangeably connected components $\Sigma_\alpha = (\X[\alpha],\ex[\alpha],B \mid_{\X[\alpha]})$ of $\Sigma$, where $\alpha \in I_1$, and let the index set $I_2$ label its isolated frozen components $\Sigma_\beta = (\X_\beta =  \{x_\beta\}, \varnothing, \varnothing)$, where $\beta \in I_2$. Set $I = I_1 \sqcup I_2$ and consider the set $\cF(I) \subseteq 2^I$ of finite subsets of $I$. For $f \in \cF(I)$ we set $\Sigma_f = (\X_f = \bigcup_{\alpha \in f} \X[\alpha], \bigcup_{\alpha \in f} \ex[\alpha],B \mid_{\X_f})$. If $f \subseteq g \in F(I)$, the inclusion $\X_f \to \X_g$ induces a map $\cA(\Sigma_f) \to \cA(\Sigma_g)$ in $\mCl$. Hence we obtain a filtered diagram $\cF(I) \to \mCl$, of which $\cA(\Sigma)$ is the colimit.
\end{remark}

We can read off from the initial seeds whether two rooted  cluster algebras are isomorphic in $\mCl$. The key is the notion of {\em similarity}.

\begin{definition}\label{D:similar}[{\cite[Definition~3.24]{Gcolimits}}]
	Two seeds $\Sigma = (\X,\ex,B = (b_{uv})_{u,v \in \X})$ and $\Sigma'=(\X',\ex',B' = (b')_{u' v'})_{u',v' \in \X'}$ are called {\em similar}, if there exists a bijection $\varphi \colon \X \to \X'$ such that
	\begin{itemize}
			\item the map $\varphi$ restricts to a bijection $\varphi \colon \ex \to \ex'$;
			\item for every exchangeably connected component $\Sigma[\alpha] = (\X[\alpha],\ex[\alpha],B[\alpha])$ of $\Sigma$ there exists a $\sigma_\alpha \in \{+1,-1\}$ such that following holds: If $u \in \ex[\alpha]$ and $v \in \X[\alpha]$, then
			\[
				b_{uv} = \sigma_\alpha b'_{\varphi(u)\varphi(v)}. 
			\]
	\end{itemize}
	If the map $\varphi$ is the identity map, then we call the seeds {\em strongly similar}.
\end{definition}

\begin{proposition}\label{P:similar_iso}[{\cite[Theorem~3.25]{Gcolimits}}]
    Two rooted cluster algebras are isomorphic in $\mCl$ if and only if their initial seeds are similar.
\end{proposition}

\begin{remark}\rm
    Mutation at an exchangeable variable $x \in \ex$ only affects the exchangeably connected component containing $x$: If $\Sigma_\alpha$ is an exchangeably connected component of $\Sigma$ with $x \in \ex \setminus \ex[\alpha]$, then $\mu_x(\Sigma_\alpha) = \Sigma_\alpha$.
\end{remark}

\begin{lemma}\label{L:ws}[{\cite[Lemma~3.28]{Gcolimits}\cite[Proposition~3.8]{Gcolimits}}]
	Let $\Sigma = (\X,ex,B = (b_{vw})_{v,w \in \X})$ and $\Sigma'=(\X',\ex',B'= (b'_{vw})_{v,w \in \X'})$ be seeds. 
	Let $f \colon \X \to \X'$ be a melting cluster morphism. The following hold.
	\begin{enumerate}	
	\item\label{ws1} If $x,y \in \X$ with $x \neq y$ but $f(x) = f(y) \in \X'$, then $x,y \in \X \setminus \ex$ are frozen variables.
	\item\label{ws2} For every exchangeably connected component $\Sigma'_\alpha = (\X'[\alpha],\ex'[\alpha],(B')^\alpha)$ of $\Sigma'$ there exists a $\sigma_\alpha \in \{+,-\}$ such that the following holds: For every $v \in \ex$ with $f(v) \in \ex'[\alpha]$ and every $w' \in \X'$ we have
		\[
			b_{f(v)w'} = \sigma_\alpha \sum_{f(w)=w'} b_{vw}.
		\]
		Moreover, the summands in the sum are either all positive or all negative.
		\end{enumerate}
\end{lemma}


We conclude the section with an observation on possible specialisations of neighbours of exchangeable cluster variables: Neighbours of $x \in \ex$ with $f(x) \in \ex'$ can only be specialised to either $1$ or $-1$, and the product of all of their images is $1$.

\begin{lemma}\label{L:specialisation of neighbours}
	Let $f \colon \cA(\Sigma) \to \cA(\Sigma')$ be a melting cluster morphism, where $\Sigma = (\X,\ex,B = (b_{uv}))$ and $\Sigma' = (\X',\ex',B' = (b'_{uv}))$. Denote by $\X_\bZ = f^{-1}(\bZ) \cap \X$ the initial cluster variables which get sent to integers. If $x \in \ex$ with $f(x) \in \ex'$, then 
	\[
		f(\prod_{y \in {\X_\bZ} \colon b_{xy}>0} y^{b_{xy}}) = 1 = f(\prod_{y \in {\X_\bZ} \colon b_{xy}<0} y^{-b_{xy}}).
	\]
	In particular, setting $\X_{cl} = \X \setminus \X_{\bZ} =\{x \in \X \mid f(x) \in \X'\}$, we have
	\[
		f(\mu_x(x)) = \frac{\prod_{u \in \X_{cl} \colon b_{xu}>0}u^{b_{xu}} + \prod_{v \in \X_{cl} \colon b_{xv}<0}v^{-b_{xv}}}{x}.
	\]
\end{lemma}



\begin{proof}
	Set $f(x) =x'$. Since the sequence $(x)$ is $f$-biadmissible, we have
	\begin{eqnarray*}
		 \frac{\prod_{y \in \X \colon b_{xy}>0}f(y)^{b_{xy}} + \prod_{y \in \X \colon b_{xy}<0} f(y)^{-b_{xy}}}{f(x)} &=& f(\mu_x(x)) =
		\mu_{f(x)}(f(x))
		\\
		&=& \frac{\prod_{y' \in \X' \colon b'_{x'y'}>0}{y'}^{b'_{x'y'}} + \prod_{y' \in \X' \colon b'_{x'y'}<0} {y'}^{-b'_{x'y'}}}{f(x)} 
	\end{eqnarray*}
	Since $\prod_{y' \in \X' \colon b'_{x'y'}>0}{y'}^{b'_{x'y'}}$ and $\prod_{y' \in \X' \colon b'_{x'y'}<0} {y'}^{-b'_{x'y'}}$ are coprime, by algebraic independence of $\X'$ we must have
	\[
		\prod_{y \in \X \colon b_{xy}>0}f(y)^{b_{xy}}  = \prod_{y' \in \X' \colon b'_{x'y'}>0}{y'}^{b'_{x'y'}} \; \text{ and } \prod_{y \in \X \colon b_{xy}<0} f(y)^{-b_{xy}} = \prod_{y' \in \X' \colon b'_{x'y'}<0} {y'}^{-b'_{x'y'}}
	\]
	or vice versa. Hence, all of these are monic monomials; the claim follows.
\end{proof}

\subsection{Construction of ind-seeds}\label{S:construction_seed}

Throughout this section, we fix a directed system $F \colon \cF \to \mCl$. For all $i \in \cF$ set $F(i) = \cA(\Sigma_i)$ with seed $\Sigma_i = (\X_i,\ex_i,B^i = (b_{vw}^i)_{v,w \in \X_i})$, and for a morphism $i \leq j$ in $\cF$ set $F(i \leq j) = f_{ij}$.

\begin{definition}
The {\em initial cluster functor $\bX$} is the functor $\bX \colon \mCl \to \mathrm{Set}$ which assigns to each rooted cluster algebra 
$\cA((\X,\ex,B))$ the set $\X \cup \bZ$, and to each melting cluster morphism $f \colon \cA((\X,\ex,B)) \to \cA((\X',\ex',B'))$ its restriction $f \mid_{\X \cup \bZ} \colon \X \cup \bZ \to \X' \cup \bZ$. 

Similarly, the {\em exchangeable initial cluster functor $\bE$} is the functor which assigns to each rooted cluster algebra $\cA((\X,\ex,B))$ the set $\ex \cup \bZ$, and to each melting cluster morphism $f \colon \cA((\X,\ex,B)) \to \cA((\X',\ex',B'))$ its restriction $f \mid_{\ex \cup \bZ} \colon \ex \cup \bZ \to \ex' \cup \bZ$.
\end{definition}
We will use these functors to define seeds for ind-cluster algebras. Their clusters and exchangeable variables can be computed using colimits in the category of sets.
\begin{remark}\label{R:ind-cluster}\rm
	We want to consider the sets $\X = (\colim \bX \circ F) \setminus \bZ$ and $\ex = (\colim \bE \circ F) \setminus \bZ$. These are computed via colimits in the category of sets. We remind the reader that this means that 
\[
	\X  \cong \left(\bigsqcup_{i \in \cF} (\X_i \cup \bZ) \big/ \sim \right) \setminus \bZ,
\] 
where for $x \in \X_i$ and $y \in \X_j$ we have $x \sim y$ if and only if $f_{ik}(x) = f_{jk}(y)$ for some $k \in \cF$ with $i,j \leq k$. Setting $\tilde{X}_i = \{x \in \X_i \mid f_{ij}(x) \in \X_j \text{ for all } j \geq i\}$, we can also write
\[
	\X \cong \bigsqcup_{i \in \cF} \tilde{X}_i \big/ \sim
\]
  Similarly, we have 
\[
	\ex \cong  \left(\bigsqcup_{i \in \cF} (\ex_i \cap \tilde{X}_i) \big/ \sim \right) \; \subseteq \X.
\]
For every $k \in \cF$, the colimit map $f_k \colon \X_k \to \X$ restricts to the colimit map $f_k \colon \ex_k \to \ex$.
\end{remark}

The sets $\X$ and $\ex$ from Remark \ref{R:ind-cluster} will give us the cluster, and set of exchangeable variables respectively, for the seed of an ind-cluster algebra. Defining the exchange matrix of this seed requires a bit more finesse, and we set this up via a series of lemmata below.


\begin{lemma}\label{L:well-defined-seed}
	Set $\X = (\colim \bX \circ F) \setminus \bZ$ and $\ex = (\colim \bE \circ F) \setminus \bZ$ with colimit maps $f_k \colon \X_k \to \X \cup \bZ$. The following hold:
	\begin{enumerate}
		\item\label{well-defined-seed1} For all $x \in \ex$ there exists an $\ell \in \cF$ such that for all $k \geq \ell$ there exists a unique $x_k \in \X_k$ with $f_k(x_k) = x$. Moreover, we have $x_k \in \ex_k$.
		\item\label{well-defined-seed2}{Let $x \in \ex, y \in \X$. One of the following holds:
		\begin{itemize}
			\item For all $k \in \cF$ and all $x_k,y_k \in \X_k$ with $f_k(x_k) = x$ and $f_k(y_k) = y$ we have
			\[
				b^k_{x_ky_k} = 0.
			\]
			In this case, we set $\tilde{b}_{xy} = 0$, and we say that $\tilde{b}_{xy}$ is {\em attained at every $k \in \cF$}.
			\item There exists an $\ell \in \cF$ such that for all $k \geq \ell$ there exists a unique $x_k \in \ex_k$ and a unique $y_k \in \X_k$ with $f_k(x_k) = x$ and $f_k(y_k) = y$ and $b^k_{x_ky_k} \neq 0$. Moreover, we have
			\[
				b^k_{x_ky_k} = \pm b^\ell_{x_\ell y_\ell}
			\]
			and for all $j \geq k \geq \ell$ we have $f_{kj}(x_k) = x_j$ and $f_{kj}(y_k)=y_j$.
			In this case, we set $\tilde{b}_{xy} = |b_{x_\ell y_\ell}|$ and say $\tilde{b}_{xy}$ is {\em attained at $\ell$ by $(x_\ell, y_\ell)$.}
		\end{itemize}
		}

		\item\label{well-defined-seed3}{Let $\X_\alpha$ be a $\tilde{B}$-exchangeably connected component and let $u,x \in \X_\alpha \cap \ex$ and $v,y \in \X_\alpha$ with $\tilde{b}_{uv} > 0$ and $\tilde{b}_{xy} > 0$, both attained at all $k \geq \ell \in \cF$ by $(u_k,v_k)$ and $(x_k,y_k)$ respectively.  Then there exists an $\ell' \geq \ell$ such that  either for all $k \geq \ell'$
		\[
			(b^k_{x_ky_k}) \cdot (b^k_{u_kv_k}) > 0 
		\]
 or for all $k \geq \ell'$ 
	\[
		(b^k_{x_ky_k}) \cdot (b^k_{u_kv_k}) <0.
	\]
 If the product is always positive, we say that  the pairs $(u,v)$ and $(x,y)$ are {\em positively aligned} and if it is always negative, we say that the pairs $(u,v)$ and $(x,y)$ are {\em negatively aligned}.}
	\end{enumerate}
\end{lemma}

\begin{proof}
	Let $x \in \ex$. Then there exists some $\ell \in \cF$ and $x_\ell \in \ex_\ell$ such that $f_\ell(x_\ell) = x$. For all $k \geq \ell$ we have $x_k = f_{\ell k}(x_\ell) \in \ex_k \cup \bZ$, since $f_{\ell k}$ is a melting cluster morphism. Since $f_k(x_k) = x \in \ex$, we must have $x_k \in \ex_k$. Moreover, if $x'_k \in \X_k$ with $f_k(x'_k) = x$ then there exists a $m \geq k$ such that $f_{km}(x'_k) = f_{km}(x_k)$. By Lemma \ref{L:ws} we have $x'_k = x_k$. This proves the first claim.

	Let $x \in \ex, y \in \X$. Assume that there exists some $m \in \cF$ with $x_m, y_m \in \X_m$, $f_m(x_m)=x$, $f_m(y_m)=y$ and $b^m_{x_my_m} \neq 0$. For all $k \geq m$ set $x_k = f_{mk}(x_m) \in \X_k$ and $y_k = f_{mk}(y_m) \in \X_k$. By Lemma \ref{L:ws} we have
	\[
		0 < |b^m_{x_m y_m}| \leq  |b^k_{x_ky_k}| = \sum_{y'_m \in \X_m \colon f_{mk}(y'_m)=y_k} |b^m_{x_my'_m}| \leq  \sum_{z \in \X_m}|b^m_{x_mz}| = \alpha.
	\]
Hence the non-empty set $\{|b^k_{x_ky_k}| \mid k \geq m \}$ is bounded above by $\alpha$, and has a maximum. Assume the maximum is attained by $|b^\ell_{x_\ell y_\ell}| > 0$ for some $\ell \geq m$. For all $k \geq \ell$ we have
\[
	|b^\ell_{x_\ell y_\ell}| \geq |b^k_{x_k y_k}| = \sum_{y'_\ell \in \X_\ell \colon f_{\ell k}(y'_\ell) = y_k} |b^\ell_{x_\ell y'_\ell}| \geq |b^\ell_{x_\ell y_\ell}|
\]
and hence
\[
	b^k_{x_k y_k} = \pm b^\ell_{x_\ell y_\ell} \neq 0.
\]
By the first part, we can choose $\ell \in \cF$ big enough such that for all $k \geq \ell$ the element $x_k \in \ex_k$ is the unique cluster variable in $\X_k$ such that $f_k(x_k) = x$. For $k \geq \ell$ assume that $y_k \neq y'_k \in \X_k$ is such that $f_k(y'_k) = y$. Then there exists an $m \geq k$ such that
\[
	f_{km}(y'_k) = y_m
\]
and hence
\[
	|b^k_{x_k y_k}| = |b^m_{x_m y_m}| = \sum_{z \in \X_k \colon f_{km}(z) = y_m} |b^k_{x_k z}| \geq |b^k_{x_k y_k}| + |b^k_{x_k y'_k}|.
\]
Hence $b^k_{x_ky'_k} = 0$. This proves the second claim.

For the third claim, observe that since $u,v,x,y \in \X$ are $\tilde{B}$-exchangeably connected, by the second claim there exists an $\ell' \geq \ell$ such that for all $k \geq \ell'$, $u_k, v_k, x_k$ and $y_k$ are $B^k$-exchangeably connected. By (\ref{ws2}) of Lemma \ref{L:ws}, the entries $b^{\ell'}_{u_{\ell'} v_{\ell'}}$ and $b^{\ell'}_{x_{\ell'} y_{\ell'}}$ have the same sign if and only if $b^{k}_{u_k v_k}$ and $b^{k}_{x_k y_k}$ have the same sign for all $k \geq \ell'$. 
\end{proof}

We are now ready to define the candidate for a seed of an ind-cluster algebra.

\begin{definition}\label{D:ind-seed}
	We define the {\em ind-seed associated to $F \colon \cF \to \mCl$} to be the triple $\Sigma(F)=(\X,\ex,B)$ given by the following data.
	\begin{itemize}
			\item{ The {\em cluster $\X$} is the set $\X = (\colim \bX \circ F) \setminus \bZ$.}
			\item{The {\em set of exchangeable variables $\ex$} is the set $\ex = (\colim \bE \circ F) \setminus \bZ$.}
			\item{Consider the matrix $\tilde{B}=(\tilde{b}_{vw})_{v,w \in \X}$ defined as in Lemma \ref{L:well-defined-seed}(2). For each $\tilde{B}$-exchangeably connected component $\X[\alpha]$ of $\X$ with $|\X[\alpha]| \geq 2$, we pick a {\em sign-determining entry $\tilde{b}_{xy} >0$ of $\tilde{B}$}. For every $u \in \ex,v \in \X$ we set
			\[
				b_{uv} = \begin{cases}
									\tilde{b}_{uv} & \text{if $(u,v)$ and $(x,y)$ are positively aligned}\\
			-\tilde{b}_{uv} & \text{if $(u,v)$ and $(x,y)$ are negatively aligned}		\\
			0 & \text{if $\tilde{b}_{uv} = 0$}.				
								\end{cases}
			\]
			This defines the {\em exchange matrix $B = (b_{uv})_{u \in \ex,v \in \X}$ associated to $F$}. By Lemma \ref{L:well-defined-seed} it is well-defined.
			}
	\end{itemize}
\end{definition}



\begin{remark}\rm
	Definition \ref{D:ind-seed} relies on a choice of sign-determining entry for each $\tilde{B}$-exchangeably connected component with at least two elements. The signs of the entries in the exchange matrix $B$ are dependent on this choice. A different choice will lead to a seed $\tilde{\Sigma}$ which is strongly similar to $\Sigma(F)$, and hence to a cluster algebra $\cA(\tilde{\Sigma})$ which is canonically isomorphic in $\mCl$ to $\cA(\Sigma(F))$.
\end{remark}

We need the following stabilising property for entries in the exchange matrices to prove that $\mCl$ is closed under directed colimits.

\begin{lemma}\label{L:attain finite submatrix}
	Consider the ind-seed $\Sigma(F) = (\X,\ex,B)$ and let $\tilde{\X} \subseteq \X$ be a finite subset, with $\tilde{\ex} = \tilde{\X} \cap \ex$ labelling the rows and $\tilde{\X}$ labelling the columns of a finite submatrix  $\tilde{B}$ of $B$. Then there exists an $\ell \in \cF$ such that for all $i \geq \ell$ and all $y \in \tilde{\X}$ the following holds:
\begin{enumerate}
\item{If $y \in \ex$ there exists a unique $y_i \in \X_i$ with $f_i(y_i) = y$.}
 \item{If $y \in \X \setminus \ex$, and $N_{\tilde{B}}(y) \cap \ex \neq \varnothing$ there exists a unique $y_i$ such that for all $x \in N_{\tilde{B}}(x) \cap \ex$ we have
\[
	|b_{xy}| = |b^i_{x_i y_i}|.
\]
}
\item{ If $y \in \X \setminus \ex$ and $N_{\tilde{B}}(y) \cap \ex = \varnothing$, there exists some $y_i \in \X_i$, not necessarily unique, such that $f_i(y_i) = y$. In this case, for all $x \in \tilde{\X} \cap \ex$ we have 
\[
	b_{xy} = b^i_{x_i y_i} =0.
\]
}
\end{enumerate} 
We say that the submatrix $\tilde{B}$ is {\em uniformly attained at $\ell$}, and that {\em $y$ is $\tilde{B}$-attained by $y_i$}.
\end{lemma}

\begin{proof}
Claim (1) is (\ref{well-defined-seed1}) of Lemma \ref{L:well-defined-seed} repeated for notational purposes. Claim (3) follows immediately from the construction of $B$.
It remains to show Claim (2). Observe that by (\ref{well-defined-seed2}) of Lemma \ref{L:well-defined-seed} there exists an $\ell \in \cF$ such that every entry of $\tilde{B}$ is attained at $\ell$. Let $i \geq \ell$ and consider the set $\tilde{\X} \setminus \ex = \{u_1, \ldots, u_m\}$ of frozen variables  of $\tilde{\X}$. 
For $u = u_1$ consider the set $N_{\tilde{B}}(u) \cap \ex$ of exchangeable $\tilde{B}$-neighbours of $u$. This set is finite, since it only contains entries from $\tilde{\X} \cap \ex$, say $N_{\tilde{B}}(u) \cap \ex = \{x(1), \ldots, x(n)\}$. For every $1 \leq p \leq n$ there exists a unique $x_i(p) \in \ex_i$ such that $f_i(x_i(p)) = x(p)$. Moreover, for every $1 \leq p \leq n$ the entry $b_{x(p)u}$ is attained at $\ell$, so there exists a unique $u_i(p)$ with $f_i(u_i(p)) = u$ and 
	\[
		|b_{x(p)u}| = |b_{x_i(p)u_i(p) }|.
	\]
Note that a priori we cannot guarantee that $u_i(p) = u_i(q)$ for $p \neq q$. However, since $f_i(u_i(p)) = f_i(u_i(q))$ for all $1 \leq p,q \leq n$ there exists a $\ell_1 \geq \ell$ such that for all $j \geq \ell_1$ and all $1 \leq p,q \leq n$ we have $f_{ij}(u_i(p)) = f_{ij}(u_i(q)) = u_j$. Setting $x_j(p) = f_{ij}(x_i(p))$ and we have, for all $1 \leq p \leq n$,
\[
	|b^j_{x_j(p)u_j }| = \sum_{u'_i \colon f_{ij}(u'_i) = u_j} |b^i_{x_i(p)u'_k }| = |b^i_{x_i(p)u_i(p) }| = |b_{x(p)u}|.
\]
Hence $u=u_1$ is $\tilde{B}$-attained at $\ell_1$. Repeating the procedure one by one for $u_2, u_3, \ldots, u_m$ allows us to find an $\ell \in \cF$ as desired.
\end{proof}

We now  can show that the ind-seed satisfies the properties of a seed (Definition \ref{D:seed}), and therefore gives rise to a cluster algebra.

\begin{lemma}\label{L:ex-locally finite}
	The ind-seed associated to the directed system $F \colon \cF \to \mCl$ is a seed called the {\em seed of $F$}.
\end{lemma}

\begin{proof}
	We  need to show that $B$ is $\ex$-locally finite and skew-symmetriseable. To see that it is $\ex$-locally finite, let $v \in \ex$ and take $k \in \cF$ such that $v = f_k(v_k)$ for a unique $v_k \in \X_k$. Since $B^k$ is $\ex_k$-locally finite, the set of $B^k$-neighbours
\[
	N_k(v_k) = \{w_k \in \X_k \mid b^k_{v_kw_k} \neq 0\}
\]
of $v_k$ is finite.
Let now $w \in \X$. If $b_{vw} \neq 0$ then by (\ref{well-defined-seed2}) of Lemma \ref{L:well-defined-seed}, the entry $\tilde{b}_{vw} > 0$ is attained at some $\ell \geq k$ by $(v_\ell,w_\ell)$. By (\ref{ws2}) of Lemma \ref{L:ws} we have
\[
	0 < |b_{vw}| = \tilde{b}_{vw} = |b^\ell_{v_\ell w_\ell}| = \sum_{f_{k \ell}(w_k) = w_\ell} |b^k_{v_k w_k}|.
\]
Therefore, there exists a $w_k \in N_k(v_k)$ such that $f_{k \ell}(w_k) = w_\ell$, i.e.\ $w = f_k(w_k)$ for some $w_k \in N_k(v_k)$. Since $N_k(v_k)$ is finite, so is the set of $B$-neighbours $N(v) = \{w \in \X \mid b_{vw} \neq 0\}$ of $v$.

To see that $B$ is skew-symmetriseable, we observe that for every finite subset $\tilde{\ex} \subseteq \ex$ the submatrix $\tilde{B} = B \mid_{\tilde{\ex}}$ of $B$ with rows and columns labelled by $\tilde{\ex}$ is uniformly attained at some $\ell$. 
Since $B^\ell$ is skew-symmetriseable, so is $\tilde{B}$. Hence, so is $B$.
\end{proof}

