\subsection{Directed colimits}\label{S:construction} Throughout this section, we keep working with a fixed directed system $F \colon \cF \to \mCl$. For all $i \in \cF$ set $F(i) = \cA(\Sigma_i)$ with seed $\Sigma_i = (\X_i,\ex_i,B^i = (b_{vw}^i)_{v,w \in \X_i})$, and for a morphism $i \leq j$ in $\cF$ set $F(i \leq j) = f_{ij}$. The ind-seed $\Sigma(F)$ of $F$ gives rise to a co-cone $\cA(\Sigma(F))$ of the diagram $F$.

\begin{proposition}\label{P:cone}
	The colimit maps $f_i \colon \X_i \to \X \cup \bZ$ uniquely extend to ring homomorphisms $f_i \colon \cA(\Sigma_i) \to \cA(\Sigma(F))$. Moreover, the following holds:
\begin{enumerate}	
	\item Every $f_i$-biadmissible sequence $\underline{x}_i$ is $f_{ij}$-biadmissible for all $j \geq i$. We set $f_i(\underline{x}_i) = \underline{x}$ and $f_{ij}(\underline{x}_i) = \underline{x}_j$.
	\item Every such sequence gives rise to a directed system $\mu_{\underline{x}}(F) \colon \cF_{\geq i} \to \mCl$ given by $\mu_{\underline{x}}(F)(j) = \cA(\mu_{\underline{x}_j}\Sigma_j)$ with maps $\mu_{\underline{x}}(F)(i \leq j) = F(i \leq j) = f_{ij}$. Here, $\cF_{\geq i}$ is the full subcategory of objects in $\cF$ that are at least $i$.
	\item We have a strong similarity of seeds $\mu_{\underline{x}}(\Sigma(F)) \cong \Sigma(\mu_{\underline{x}}(F))$. 
	%\item The ring homomorphisms $f_i \colon \cA(\Sigma_i) \to \cA(\Sigma(F))$ are inducible melting cluster morphisms.
    \item For all $y_i \in \X_i$ with $f_i(y_i) = y$ we have $f_i(\mu_{\underline{x}_i}(y_i)) = \mu_{\underline{x}}(y)$.
\end{enumerate}
In particular, the rooted cluster algebra $\cA(\Sigma(F))$ is a co-cone of $F$ in $\mCl$.
\end{proposition}

\begin{proof}
	By the Laurent phenomenon, every cluster variable in $\cA(\Sigma_i)$ can be written as a Laurent polynomial $\frac{P(\X_i)}{M(\ex_i)}$, where $P$ is a polynomial expression in $\X_i$, and $M$ is a monic monomial expression in $\ex_i$. Since the maps $f_{ij}$ are inducible, we have that $f_i(\ex_i) \subseteq \ex \cup \bZ \setminus \{0\}$, and we can algebraically extend the map $f_i$ to a unique ring homomorphism
\[
	f_i \colon \cA(\Sigma_i) \to \cA(\Sigma).
\]
By construction, these ring homomorphisms satisfy CM1 and iMCM, and for all $i \leq j$ we have $f_i = f_j \circ f_{ij}$. In particular, if we can show Claim (4) then we know that $f_i$ also satisfies axiom CM2, and hence is an induced melting cluster morphism. Thus we will have shown that $\cA(\Sigma(F))$ is a co-cone of $F$ in $\mCl$.

The Claims (1)-(4) are trivially true for sequences of length $0$. Now assume they hold for sequences of length $\ell-1$. Let $\underline{x}_i = (x_1(i), \ldots, x_\ell(i))$ and consider its truncation $\underline{x}'_i = (x_1(i), \ldots, x_{\ell-1}(i))$ of length $\ell-1$. For $j \geq i$ we set $\underline{x}'_j = f_{ij}(\underline{x}'_i)$ and $\underline{x}' = f_{i}(\underline{x}'_i)$. By induction assumption for Claim (2), by mutating $\Sigma_j$ along $\underline{x}'_j$ for all $j \geq i$, we get a directed system $\mu_{\underline{x}'}(F)$ with colimit $\cA(\Sigma(\mu_{\underline{x}'}(F)))$, which, by induction assumption for Claim (3) and Proposition \ref{P:similar_iso}, is canonically isomorphic to $\cA(\mu_{\underline{x}'}(\Sigma(F)))$. To show that Claims (1)-(4) hold for the sequence $\underline{x}_i$ it is thus enough to show that they hold for mutation sequences of length $1$, by passing from the directed system $F$ to the directed system $\mu_{\underline{x}'}(F)$.


%By induction it is enough to prove Claims (1)-(4) for sequences of length $1$: This follows for Claims (1), (2) and (3) by \cite[Proposition~3.5]{Gcolimits} and holds for Claim (4) by Claim (3). 
%For Claim (4), assume Claims (1)-(4) are true for sequences of length $1$ and consider our $\Sigma_i$-admissible sequence $\underline{x}_i = (x^i_1, \ldots, x^i_\ell)$ with $f_i(\underline{x}_i) = (x_1, \ldots, x_\ell)$. By Claim (3) we have a canonical isomorphism $\cA(\mu_{x_{\ell-1}} \circ \cdots \circ \mu_{x_1}(\Sigma(F))) \cong \cA(\Sigma(\mu_{x_{\ell-1}} \circ \cdots \circ \mu_{x_1}(F)))$ given by the identity map on $\mu_{x_{\ell-1}} \circ \cdots \circ \mu_{x_1}(\X)$. For all $y_i \in \X_i$ we therefore have $f_i(\mu_{x^i_{\ell-1}} \circ \cdots \circ \mu_{x^i_1} (y_i)) = \mu_{x_{\ell-1}} \circ \cdots \circ \mu_{x_1}(f_i(y_i))$ and the Claim (4) now follows from our assumption for the directed system $\mu_{x_{\ell-1}} \circ \cdots \circ \mu_{x_1}(F)$, since $(x_\ell)$ is a $\mu_{x^i_{\ell-1}} \circ \cdots \circ \mu_{x^i_1}(\Sigma_i)$-biadmissible sequence of length $1$.


 Consider thus a length one $\Sigma_i$-admissible sequence $\underline{x}_i = (x_i)$ for some $x_i \in \ex_i$. For all $j \geq i$, set $f_{ij}(x_i) = x_j$ and $f_i(x_i) = x$. We have 
\[
	x_j = f_{ij}(x_i) \in f_{ij}(\ex_i) \subseteq \ex_j \cup \bZ.
\]
Since $f_j(x_j) =  f_i(x_i) \notin \bZ$, we must have $x_j \in \ex_j$ as desired. This proves Claim (1). Claim (2) is a direct consequence of Claim (1) combined with \cite[Proposition~3.5]{Gcolimits}. 

It remains to prove Claims (3) and (4). Consider the set of $B$-neighbours $N_B(x)$ of $x$. This set is finite by Lemma \ref{L:ex-locally finite}, and thus gives rise to a finite submatrix $A$ of $B$. By Lemma \ref{L:attain finite submatrix}, the submatrix $A$ is uniformly attained at some $j \geq i$. Hence there exists a $\sigma \in \{1, -1\}$ such that for all $v \in N(x)$ with $b_{uv} \neq 0$ we have
\[
	b_{uv} = \sigma b^j_{u_j v_j}
\]
for a unique $v_j \in \X_j$. Without loss of generality we will assume that $\sigma = 1$, the case $\sigma=-1$ follows symmetrically. For all $x_i \neq y_i \in \X_i$ with $f_{i}(y_i) = y$ we have $x \neq y$, since otherwise $f_{ij}(x_i) = f_{ij}(y_i)$ for some $j \geq i$ contradicting Lemma \ref{L:ws}. Therefore we have
\[
	f_i(\mu_{x_i}(y_i)) = f_i(y_i) = y = \mu_{x}(x).
\]
On the other hand, we have
\begin{eqnarray*}
	f_i(\mu_{x_i}(x_i)) &=& f_j(\mu_{x_j}(x_j)) \\
	& = &  \frac{\prod_{u_j \in \X_j \colon b_{x_ju_j} > 0} f_j(u_j)^{b_{x_ju_j}} + \prod_{v_j \in \X_j \colon b_{x_jv_j} < 0} f_j(v_j)^{-b_{x_jv_j}}}{f_j(x_j)}.
\end{eqnarray*}
Consider the sets $(\X_j)_{\bZ}$ and $(\X_j)_{cl}$, where 
\[
	(\X_j)_{\bZ}= \{v_j \in \X_j \mid f_j(v_j) \in \bZ\} \; \; \text{ and } (\X_j)_{cl}= \{v_j \in \X_j \mid f_j(v_j) \in \X\}.
\]
There exists a $k \geq j$ such that for all $v_j \in (\X_j)_{\bZ}$ we have $f_{jk}(v_j) = f_j(v_j) \in \bZ$. 
By Lemma \ref{L:specialisation of neighbours} we obtain
\begin{eqnarray*}
	f_i(\mu_{x_i}(x_i)) &=& f_j(\mu_{x_j}(x_j)) = f_k \circ f_{jk}(\mu_{x_j}(x_j))\\
	& = &  \frac{\prod_{u_j \in (\X_j)_{cl} \colon {b^j}_{x_ju_j}>0} f_j(u_j)^{b_{x_ju_j}} + \prod_{v_j \in (\X_j)_{cl} \colon b^j_{x_jv_j}<0} f_j(v_j)^{-b_{x_jv_j}}}{f_j(x_j)} \\
	& = &  \frac{\prod_{u \in \X \colon b_{xu}>0} u^{b_{xu}} + \prod_{v \in \X \colon b_{xv}<0} v^{-b_{xv}}}{x} \\
	&=& \mu_{x}(x).
\end{eqnarray*}
