\begin{center}
\includegraphics[width=\linewidth]{fig_cl.eps}
\caption{\corr{Probably change the position.} An illustration of the closed-loop system. $r(t)$, $u(t)$, and $y(t)$ are the reference value, input, and output of the system. $C(s)$ and $H(s)$ are the controller and system transfer functions. The error $r(t) - y(t)$ is fed into the controller, and it calculates the input $u(t)=K_p\cdot e(t) + K_I \cdot \int^{t}_{0}e(\tau)d\tau$.}
\label{fig:cl}
