\omega(x_1,e_3)=-b_{1,2}, & \omega(x_1,x_1)=\alpha_2b_{4,4},  &\omega(x_1,x_2)=\beta_2b_{4,4},\\[1mm]
 \omega(x_2,e_2)=b_{5,2},& \omega(x_2,e_3)=-b_{1,2},& \omega(x_2,x_1)=\alpha_2b_{5,4}, \\ [1mm]
