 \omega(e_2,x_1)=b_{2,4}, &  \omega(e_2,x_2)=-b_{2,4}, &  \omega(e_3,x_2)=b_{1,2}, & \omega(x_1,e_1)=-b_{1,4},\\ [1mm]
