 \omega(e_2,x_1)=b_{2,4}, &  \omega(e_2,x_2)=b_{2,5}, &  \omega(e_3,x_1)=b_{1,2}, & \omega(x_1,e_1)=-b_{1,4},\\ [1mm]
\omega(x_1,e_2)=-b_{2,4},& \omega(x_1,e_3)=-b_{1,2},  & \omega(x_1,x_2)=b_{4,5},& \omega(x_2,e_1)=-b_{1,5},\\ [1mm] \omega(x_2,e_2)=-b_{2,5}, & \omega(x_2,x_1)=-b_{4,5}.\end{array}\end{equation}

