\end{prop}
\begin{proof} For any $\omega\in Z^2(H,l,r),$
let us denote $\omega(x,y)=b_{i,j}e_4,$ $1\leq i,j\leq 5$, where $x,y\in \{e_1,e_2,e_3,x_1,x_2\}.$

Using equality \eqref{c4}, we compute the cocycles and obtain the following relations:
$$\begin{array}{llll}
\beta_1b_{1,1}=0, & \beta_2b_{1,1}=0, & \alpha_1b_{1,1}=0, & (2-\alpha_2)b_{1,1}=0,\\[1mm]
b_{1,3}=-b_{3,1},&  b_{2,3}=-b_{3,2}, & b_{3,3}=0,\\[1mm]
(2+\alpha_1)b_{1,3}=0, & (2-\alpha_2)b_{1,3}=0, & (1+\beta_1)b_{1,3}=0, &(1-\beta_2)b_{1,3}=0,\\[1mm]
\beta_1b_{1,4}=(\alpha_2-1)b_{5,1},&\beta_2b_{1,4}=(\alpha_2-1)b_{1,5},\\[1mm]
b_{1,4}=(\alpha_1+\alpha_2-1)b_{4,1},& (\alpha_1+1)b_{1,4}=(\alpha_2-1)b_{4,1},\\[1mm]
\beta_1b_{1,5}=\beta_2b_{5,1},& b_{1,5}=\alpha_1b_{5,1}+\beta_2b_{4,1},\\[1mm]
\alpha_1b_{2,2}=0, & \alpha_2b_{2,2}=0,& \beta_1b_{2,2}=0, & (2-\beta_2)b_{2,2}=0,\\[1mm]
(1-\alpha_2)b_{2,3}=0,& (2-\beta_2)b_{2,3}=0,& (\alpha_1+1)b_{2,3}=0, &(2+\beta_1)b_{2,3}=0, \\[1mm]
\alpha_1b_{2,4}=\alpha_2b_{4,2},& b_{2,4}=\beta_1b_{4,2}+\alpha_2b_{5,2}, & (1+\beta_1)b_{2,4}=\alpha_2b_{5,2},\\[1mm]
\alpha_1b_{2,5}=(\beta_2-1)b_{4,2},& \alpha_2b_{2,5}=(\beta_2-1)b_{2,4},\\[1mm]
(\beta_1+1)b_{2,5}=(\beta_2-1)b_{5,2},& b_{2,5}=(\beta_1+\beta_2-1)b_{5,2},\\[1mm]
b_{3,4}=(1-\alpha_2)b_{1,2},& b_{3,4}=(\alpha_2-1)b_{2,1},\\[1mm] (\alpha_1+1)b_{3,4}=(\alpha_2-1)b_{4,3},&b_{3,4}=(\alpha_1+\alpha_2-1)b_{4,3},\\[1mm]
(\beta_1+1)b_{3,4}=(\alpha_2-1)b_{5,3}, & b_{3,4}=\beta_1b_{4,3}+(\alpha_2-1)b_{5,3},\\[1mm]
 b_{3,5}=(1-\beta_2)b_{1,2},& b_{3,5}=(\beta_2-1)b_{2,1}, &  (\alpha_1+1)b_{3,5}=(\beta_2-1)b_{4,3},\\[1mm] b_{3,5}=\alpha_1b_{5,3}+(\beta_2-1)b_{4,3}, & (\beta_1+1)b_{3,5}=(\beta_2-1)b_{5,3}, & b_{3,5}=(\beta_1+\beta_2-1)b_{5,3},\\[1mm]
\beta_2b_{4,1}=(\alpha_1+1)b_{1,5},& \beta_1b_{4,1}=(1-\alpha_2)b_{5,1}, \\[1mm]
(1-\beta_2)b_{4,2}=\alpha_1b_{5,2}, & (\alpha_1+\alpha_2)b_{4,2}=0,\\[1mm]
 b_{4,3}=-(\alpha_1+1)b_{1,2},&  b_{4,3}=\alpha_1b_{2,1}-b_{1,2},\\[1mm]
 \alpha_1b_{4,4}=0, & \beta_1b_{4,4}=0,&  \alpha_1b_{5,5}=0, & \beta_1b_{5,5}=0,  \\[1mm]
 (\alpha_1+\alpha_2)b_{4,5}=\beta_2b_{4,4},&  b_{5,3}=b_{2,1}-\beta_1b_{1,2},& b_{5,3}=(1+\beta_1)b_{2,1},\\[1mm]
(\beta_1+\beta_2)b_{5,1}=0,& \alpha_2b_{5,5}=(\beta_1+\beta_2)b_{5,4},\\[1mm]
\beta_2b_{4,4}=\alpha_2b_{4,5}-\alpha_1b_{5,4}, &\alpha_2b_{5,5}=\beta_2b_{5,4}-\beta_1b_{4,5}. \end{array}$$


 By \eqref{Hz}, we derive that $\alpha_1=\beta_1=0$ or $\alpha_1=-\alpha_2$ and $\beta_1=-\beta_2.$ Thus,
 to determine the values of $b_{i,j}$ we consider the following two cases:

\begin{itemize}
\item[Case 1.]Let $\alpha_1=\beta_1=0.$  Then we have
$$\begin{array}{lll}
b_{1,3}=0,& b_{1,4}= (\alpha_2-1)b_{4,1}, & b_{1,5}= \beta_2b_{4,1}, \\[1mm]
b_{2,3}=0, & b_{2,4}= \alpha_2b_{5,2}, & b_{2,5}= (\beta_2-1)b_{5,2}, \\[1mm]
b_{3,1}=0,& b_{3,2}=0, & b_{3,3}=0,\\[1mm]
b_{3,4}= (1-\alpha_2)b_{1,2}, & b_{3,5}= (\beta_2-1)b_{2,1}, \\[1mm]
b_{4,3}= - b_{1,2}, & b_{5,3}= b_{2,1}, \\[1mm]
 \end{array}$$
and the following restrictions
$$\begin{array}{llll}
 \beta_2b_{1,1}=0, & (\alpha_2-2)b_{1,1}=0,& (\alpha_2-1)(b_{1,2}+b_{2,1})=0, \\[1mm]
 \alpha_2b_{2,2}=0,& (\beta_2-2)b_{2,2}=0,&(\beta_2-1)(b_{1,2}+b_{2,1})=0,\\[1mm]
 \alpha_2b_{4,2}=0,& (\beta_2-1)b_{4,2}=0,& \alpha_2b_{4,5}=\beta_2b_{4,4},\\[1mm]
\beta_2b_{5,1}=0, & (\alpha_2-1)b_{5,1}=0,& \alpha_2b_{5,5}=\beta_2b_{5,4}.\\[1mm]
 \end{array}$$




Now, consider the following subcases:

\begin{itemize}
\item[1.1.] If $\alpha_2=1,$ $\beta_2=0,$ then we obtain $b_{2,1}=-b_{1,2}$ and
$b_{1,1}=b_{2,2}=b_{4,2}=b_{4,5}= b_{5,5}=0.$ Hence, we conclude that any $2$-cocycles on $H$ with respect to the pair $(l,r)$ is given by the expression in \eqref{eq4.2}.

\item[1.2.] If $\alpha_2=0,$ $\beta_2=1,$ then we obtain $b_{2,1}=-b_{1,2}$ and
$b_{1,1}=b_{2,2}=b_{4,4}=b_{5,1}= b_{5,4}=0.$ Hence, we get that any $2$-cocycles on $H$ with respect to the pair $(l,r)$ has the form \eqref{eq4.3}.

  \item[1.3.] If $\alpha_2=2,$ $\beta_2=0,$ then we obtain $b_{2,1}=-b_{1,2}$ and
$b_{2,2}=b_{4,2}=b_{4,5}= b_{5,1}= b_{5,5}=0.$ Hence, any $2$-cocycles on $H$ with respect to the pair $(l,r)$ has the form \eqref{eq4.4}.

\item[1.4.] If $\alpha_2=0,$ $\beta_2=2,$ then we obtain $b_{2,1}=-b_{1,2}$ and
$b_{1,1}=b_{4,2}=b_{4,4}= b_{5,1}= b_{5,4}=0.$ Hence, we get that any $2$-cocycles on $H$ with respect to the pair $(l,r)$ has the form \eqref{eq4.5}.


\item[1.5.] If $\alpha_2=1,$ $\beta_2=1,$ then we obtain $b_{4,5}=b_{4,4},$ $b_{5,5}=b_{5,4}$   and
$b_{1,1}=b_{2,2}=b_{4,2}= b_{5,1}=0.$ Hence, we get that any $2$-cocycles on $H$ with respect to the pair $(l,r)$ has the form \eqref{eq4.6}.

 \item[1.6.] If $ (\alpha_2,\beta_2)\neq (1,0),(0,1),(2,0),(0,2),(1,1), $ then we obtain $b_{2,1}=-b_{1,2},$  $\alpha_2b_{4,5}=\beta_2 b_{4,4},$ $\alpha_2b_{5,5}=\beta_2b_{5,4}$   and
$b_{1,1}=b_{2,2}=b_{4,2}= b_{5,1}=0.$ Hence, we get that any $2$-cocycles on $H$ with respect to the pair $(l,r)$ has the form \eqref{eq4.7}.
\end{itemize}

 \item [Case 2.] Let $\alpha_1=-\alpha_2$ and $\beta_1=-\beta_2.$  Then we have
$$\begin{array}{lllll}
b_{1,1}=0, & b_{2,1}=-b_{1,2},& b_{2,2}=0, & b_{3,1}=-b_{1,3}, \\[1mm]
  b_{3,2}=-b_{2,3}, & b_{3,3}=0,  & b_{3,4}= (1+\alpha_1)b_{1,2}, & b_{3,5}=(1+\beta_1)b_{1,2}, \\[1mm]
  b_{4,1}=-b_{1,4}, & b_{4,2}=-b_{2,4},& b_{4,3}= -b_{3,4}, & b_{4,4}=0, \\[1mm]
 b_{5,1}=-b_{1,5},& b_{5,2}= -b_{2,5}, &
 b_{5,3}=- b_{3,5},& b_{5,4}=-b_{4,5}, & b_{5,5}=0.
 \end{array}$$
and the following restrictions
$$\begin{array}{llll}
 (\alpha_1+2)b_{1,3}=0,& (\beta_1+1)b_{1,3}=0, & \beta_1b_{1,4}=(1+\alpha_1)b_{1,5}, \\[1mm]
 (\alpha_1+1)b_{2,3}=0,& (\beta_1+2)b_{2,3}=0,&  \alpha_1b_{2,5}=(1+\beta_1)b_{2,4},\\ [1mm]
 \end{array}$$


Now, consider the following subcases:

\begin{itemize}
\item[2.1.] If $\alpha_1=-1,$ $\beta_1=0,$ then we obtain $b_{2,5}=-b_{2,4}$ and
$b_{1,3}=b_{2,3}=0.$ Hence, we get that any $2$-cocycles on $H$ with respect to the pair $(l,r)$ has the form \eqref{eq4.8}.

\item[2.2.] If $\alpha_1=0,$ $\beta_1=-1,$ then we obtain $b_{1,5}=-b_{1,4}$ and
$b_{1,3}=b_{2,3}=0.$ Hence, we get that any $2$-cocycles on $H$ with respect to the pair $(l,r)$ has the form \eqref{eq4.9}.

\item[2.3.] If $\alpha_1=-1,$ $\beta_1=-2,$ then we obtain $b_{2,5}=b_{2,4}$ and
$b_{1,3}=b_{1,4}=0.$ Hence, we get that any $2$-cocycles on $H$ with respect to the pair $(l,r)$ has the form \eqref{eq4.10}.


\item[2.4.] If $\alpha_1=-2,$ $\beta_1=-1,$ then we obtain $b_{1,5}=b_{1,4}$ and
$b_{2,3}=b_{2,5}=0.$ Hence, we get that any $2$-cocycles on $H$ with respect to the pair $(l,r)$ has the form \eqref{eq4.11}.

\item[2.5.] If $(\alpha_1,\beta_1)\neq (-1,0), (0,-1), (-1,-2), (-2,-1),$ then we obtain $$b_{1,3}=b_{2,3}=0, \quad \beta_1b_{1,4}=(1+\alpha_1)b_{1,5},\quad \alpha_1b_{2,5}=(1+\beta_1)b_{2,4}.$$

    In this case we conclude that any $2$-cocycles on $H$ with respect to the pair $(l,r)$ has the form \eqref{eq4.12}.
\end{itemize}
