By Propositions \ref{B2} and \ref{Z2forH}, we obtain the following corollary:
\begin{cor}\label{cor4.4} We have the following:
\begin{itemize}
\item [I.] If $\alpha_1=\beta_1=\beta_2=0,$ $\alpha_2=1,$ then  $\operatorname{dim} Z^2(H,l,r) =6,$
$\operatorname{dim} B^2(H,l,r) =5;$
\item [II.] If $\alpha_1=\alpha_2=\beta_1=0,$ $\beta_2=1,$ then  $\operatorname{dim} Z^2(H,l,r) =6,$
$\operatorname{dim} B^2(H,l,r) =5;$

\item [III.] If $\alpha_1=\beta_1=\beta_2=0,$ $\alpha_2=2,$ then  $\operatorname{dim} Z^2(H,l,r) =6,$
$\operatorname{dim} B^2(H,l,r) =5;$
\item [IV.] If $\alpha_1=\alpha_2=\beta_1=0,$ $\beta_2=2,$ then  $\operatorname{dim} Z^2(H,l,r) =6,$
$\operatorname{dim} B^2(H,l,r) =5;$

\item [V.] If $\alpha_1=\beta_1=0,$ $\alpha_2=\beta_2=1$, then  $\operatorname{dim} Z^2(H,l,r) =6,$ $\operatorname{dim} B^2(H,l,r) =5;$


\item [VI.] If $\alpha_1=\beta_1=0,$ $ (\alpha_2,\beta_2)\neq (1,0),(0,1),(2,0),(0,2),(1,1),$ then $\operatorname{dim} Z^2(H,l,r) =5,$ $\operatorname{dim} B^2(H,l,r) =5;$


\item [VII.] If $\alpha_1=-\alpha_2=-1,$ $\beta_1=\beta_2=0$, then  $\operatorname{dim} Z^2(H,l,r) =5,$ $\operatorname{dim} B^2(H,l,r) =3;$

 \item [VIII.] If $\alpha_1=\alpha_2=0,$ $\beta_1=-\beta_2=-1$, then  $\operatorname{dim} Z^2(H,l,r) =5,$ $\operatorname{dim} B^2(H,l,r) =3;$

\item [IX.] If $\alpha_1=-\alpha_2=-1,$ $\beta_1=-\beta_2=-2$, then  $\operatorname{dim} Z^2(H,l,r) =5,$
$\operatorname{dim} B^2(H,l,r) =4;$
\item [X.] If $\alpha_1=-\alpha_2=-2,$ $\beta_1=-\beta_2=-1$, then  $\operatorname{dim} Z^2(H,l,r) =5,$
$\operatorname{dim} B^2(H,l,r) =4;$


\item [XI.] If $\alpha_1=-\alpha_2,$ $\beta_1=-\beta_2,$ and $(\alpha_1, \beta_1) \neq (-1,0), (0,-1), (-2,-1), (-1,-2),$ then $\operatorname{dim} Z^2(H,l,r) =4,$
$\operatorname{dim} B^2(H,l,r) =4.$


 \end{itemize}
\end{cor}


In the following theorem, we determine all one-dimensional abelian extensions of the solvable Leibniz algebra $H.$
  \begin{thm}\label{thmH} Let $\widehat{H}$ be an extension of the solvable Leibniz algebra $H$ by the abelian algebra $\mathfrak{h}=\{e_4\}.$ Then
   $\widehat{H}$ is isomorphic to one of the following non-isomorphic algebras:
$$\widehat{H}_1:\begin{array}{lllll} [e_1,e_2]=e_3,& [e_2,e_1]=-e_3,& [e_1,x_1]=e_1, & [x_1,e_1]=-e_1,\\ [1mm]
[e_3,x_1]=e_3,&[x_1,e_3]=-e_3,& [e_4,x_1]=e_4,& [x_2,e_1]=e_4,\\ [1mm]
[e_2,x_2]=e_2,& [x_2,e_2]=-e_2,& [e_3,x_2]=e_3, & [x_2, e_3]=-e_3.\end{array} $$
$$\widehat{H}_2:\begin{array}{lllll} [e_1,e_1]=e_4,& [e_1,e_2]=e_3,& [e_2,e_1]=-e_3,& [e_1,x_1]=e_1, \\ [1mm]
[x_1,e_1]=-e_1, & [e_3,x_1]=e_3,&[x_1,e_3]=-e_3,& [e_4,x_1]=2e_4,\\ [1mm]
[e_2,x_2]=e_2,& [x_2,e_2]=-e_2,& [e_3,x_2]=e_3, & [x_2, e_3]=-e_3.\end{array} $$
$$\widehat{H}_3:\begin{array}{lllll}  [e_1,e_2]=e_3+e_4,& [e_2,e_1]=-e_3+e_4,& [e_1,x_1]=e_1, & [x_1,e_1]=-e_1,\\ [1mm]
 [e_3,x_1]=e_3,&[x_1,e_3]=-e_3+e_4,& [e_4,x_1]=e_4,& [e_4,x_2]=e_4,\\ [1mm]
[e_2,x_2]=e_2,& [x_2,e_2]=-e_2,& [e_3,x_2]=e_3, & [x_2, e_3]=-e_3+e_4.\end{array} $$
$$\widehat{H}_4:\begin{array}{lllll} [e_1,e_2]=e_3,& [e_2,e_1]=-e_3,& [e_1,x_1]=e_1+e_4, & [x_1,e_1]=-e_1-e_4,\\ [1mm]
[e_3,x_1]=e_3,&[x_1,e_3]=-e_3,& [e_4,x_1]=e_4,& [x_1,e_4]=-e_4, \\ [1mm]
[e_2,x_2]=e_2,& [x_2,e_2]=-e_2,& [e_3,x_2]=e_3, & [x_2, e_3]=-e_3.\end{array} $$
$$\widehat{H}_5(\delta):\begin{array}{lllll} [e_1,e_2]=e_3,& [e_2,e_1]=-e_3,& [e_1,x_1]=e_1+\delta e_4, & [x_1,e_1]=-e_1-\delta e_4,\\ [1mm]
[e_1,x_2]=e_4, & [x_2,e_1]=-e_4, & [e_3,x_1]=e_3,&[x_1,e_3]=-e_3, \\ [1mm]
[e_4,x_1]=e_4,& [x_1,e_4]=-e_4, & [e_2,x_2]=e_2,& [x_2,e_2]=-e_2,\\[1mm]
 [e_3,x_2]=e_3, & [x_2, e_3]=-e_3.\end{array} $$
$$\widehat{H}_6:\begin{array}{lllll} [e_1,e_2]=e_3,& [e_2,e_1]=-e_3,&[e_1,e_3]=e_4, & [e_3,e_1]=-e_4,\\ [1mm]
 [e_1,x_1]=e_1, & [x_1,e_1]=-e_1, & [e_3,x_1]=e_3, &[x_1,e_3]=-e_3,\\ [1mm]
 [e_4,x_1]=2e_4, & [x_1,e_4]=-2e_4, &   [e_2,x_2]=e_2,& [x_2,e_2]=-e_2, \\ [1mm]
[e_3,x_2]=e_3, & [x_2, e_3]=-e_3, & [e_4,x_2]=e_4, &[x_2,e_4]=-e_4.\end{array} $$
\end{thm}
\begin{proof} By Corollary \ref{cor4.4}, we have that $H^2(H,l,r)=0$ in cases VI and XI. Thus, it is enough to consider the remaining cases.

\begin{itemize}
\item [I.] Let $\alpha_1=\beta_1=\beta_2=0,$ $\alpha_2=1.$ In this case $\dim H^2(H,l,r) =1$ and $2$-cocycle defined by $\omega(x_2,e_1)=e_4$ provides a basis for this space, i.e.  $H^2(H,l,r) =\langle\overline{\omega}\rangle.$

By any automorphism $\varphi_1 \in \operatorname{Aut}(H)$ of Proposition \ref{Aut3-dim}  and by $\psi \in \operatorname{Aut}(\mathfrak{h}),$ where $\psi(e_{4}) = \lambda e_{4}$  the element $\delta\overline{\omega} \in H^2(H,l,r)$ acts on the element $\overline{\omega'} \in H^2(H,l,r)$, such that $\omega'(x_2, e_1) = \delta \lambda a_{1,1}e_{4},$ with $l'=l,$ $r'=r.$ Taking $\lambda =1$ and  $a_{1,1} = \frac 1 {\delta},$ we can assume that $\omega'(x_2, e_1) = e_{4}.$


Moreover, if we consider the action by the automorphism $\varphi_2$ of Proposition \ref{Aut3-dim}, then the element $\overline{\omega}$ acts on the element $\overline{\omega'} \in H^2(H,l,r)$, such that $\omega'(x_1, e_2) =  \lambda e_{4},$ with $r'_{x_1}=r_{x_2},$ $r'_{x_2}=r_{x_1}.$
Note that the 2-cocycle $\omega'(x_1, e_2) =  \lambda e_{4}$ provides a basis for Case II.

Therefore, we conclude that all elements of $H^2(H,l,r)$ in the cases I and II belong to one orbit. Thus, we can define the products of the extension algebra $\widehat{H}=H\oplus\{e_{4}\}$ as follows:
$$[x_2,e_1]=\omega(x_2,e_1)=e_4, \quad [e_4,x_1]=r_{x_1}e_{4}=e_4. $$

Hence, we obtain the algebra $\widehat{H}_1$.


\item [III.] Let $\alpha_1=\beta_1=\beta_2=0,$ $\alpha_2=2.$ Then $\overline{\omega}$ forms a basis of $H^2(H,l,r),$ where $\omega(e_1,e_1)=e_4.$
An automorphisms $\varphi_1 \in \operatorname{Aut}(H)$ and $\psi \in \operatorname{Aut}(\mathfrak{h})$ act the element $\delta\overline{\omega}$ to $\delta'\overline{\omega}$ as $$\delta'=\delta \lambda a_{1,1}^2.$$

Taking $\lambda =\frac 1 {\delta}$ and  $a_{1,1} = 1,$ we can suppose $\delta'= 1.$


Moreover, if we consider the action by the automorphism $\varphi_2$, then the element $\overline{\omega}$ acts on the element $\overline{\omega'}$, such that $\omega'(e_2, e_2) =  \lambda e_{4},$ with $r'_{x_1}=r_{x_2},$ $r'_{x_2}=r_{x_1}.$
Note that the cocycle $\omega'(e_2, e_2) =  \lambda e_{4},$ provides a basis for Case IV.
Therefore, we derive that all elements of $H^2(H,l,r)$ in the cases III and IV belong to one orbit.
Thus, we can define the products of the extension algebra $\widehat{H}=H\oplus\{e_{4}\}$ as follows:
$$[e_1,e_1]=\omega(e_1,e_1)=e_4, \quad [e_4,x_1]=r_{x_1}e_{4}=2e_4. $$

Therefore, we obtain the algebra  $\widehat{H}_2$.

\item [V.] Let $\alpha_1=\beta_1=0,$ $\alpha_2=\beta_2=1.$ Then $\dim H^2(H,l,r) =1$ and $2$-cocycle defined as $$\omega(e_1,e_2)=\omega(e_2,e_1)=\omega(x_1,e_3)=\omega(x_2,e_3)=e_4,$$ provides a basis on $H^2(H,l,r).$ An automorphisms $\varphi_1 \in \operatorname{Aut}(H)$ and $\psi \in \operatorname{Aut}(\mathfrak{h})$ act the element $\delta\overline{\omega}$ to $\delta'\overline{\omega}$ as $$\delta'=\delta \lambda a_{1,1} a_{2,2}.$$

Taking $\lambda =\frac 1 {\delta}$ and  $a_{1,1} = a_{2,2}=1,$ we can suppose $\delta'= 1.$
Define the products of the extension algebra $\widehat{H}=H\oplus\{e_{4}\}$ as follows:
$$\begin{array}{lllll} [e_1,e_2]=e_3+\omega(e_1,e_2)=e_3+e_4,& [e_2,e_1]=-e_3+\omega(e_2,e_1)=-e_3+e_4,\\[1mm]
[x_1,e_3]=-e_3+\omega(x_1,e_3)=-e_3+e_4, & [x_2,e_3]=-e_3+\omega(x_2,e_3)=-e_3+e_4,\\[1mm] [e_4,x_1]=r_{x_1}e_{4}=e_4,  & [e_4,x_2]=r_{x_2}e_{4}=e_4. \end{array}$$

Therefore, we obtain the algebra $\widehat{H}_3$.

\item [VII.] $\alpha_1=-\alpha_2=-1,$ $\beta_1=\beta_2=0.$ In this case $\dim H^2(H,l,r) =2$ and the basis of this space defined by the 2-cocycles
    $$\begin{array}{lllll}\omega_1(e_1, x_1) =e_4, &\omega_1(x_1, e_1)=-e_{4}, && \omega_2(e_1, x_2)=e_4, &\omega_2(x_2, e_1) =-e_{4}.\end{array}$$

An automorphisms $\varphi_1 \in \operatorname{Aut}(H)$ and $\psi \in \operatorname{Aut}(\mathfrak{h})$ act the element $\delta_1\overline{\omega_1}+\delta_2\overline{\omega_2}$ to $\delta_1'\overline{\omega_1}+\delta_2'\overline{\omega_2}$ as
$$\delta_1'=\delta_1 a_{1,1},\quad \delta_2'=\delta_2a_{1,1}.$$

\begin{itemize}
\item If $\delta_2=0$, then
$\delta_2'=0$ and $\delta_1\neq 0.$ Taking $ a_{1,1} = \frac 1 {\delta_1},$ we can suppose $\delta_1'=1$ and obtain the algebra $\widehat{H}_4.$
\item If $\delta_2\neq 0$, then choosing $a_{1,1}=\frac{1}{\delta_2},$ we get $\delta_2'=1$
and obtain the algebra $\widehat{H}_5(\delta).$
\end{itemize}

Moreover, if we consider an action by the automorphism $\varphi_2$, then the element $\delta_1\overline{\omega_1}+\delta_2\overline{\omega_2}$ acts on the element $\delta_1\overline{\omega_1'}+\delta_2\overline{\omega_2'}$, such that
$$\begin{array}{lllll}\omega_1'(e_2, x_1) =e_4, &\omega_1'(x_1, e_2)=-e_{4}, && \omega_2'(e_2, x_2)=e_4, &\omega_2'(x_2, e_2) =-e_{4},\end{array}$$
with $l'_{x_1}=l_{x_2},$ $l'_{x_2}=l_{x_1},$ $r'_{x_1}=r_{x_2},$ $r'_{x_2}=r_{x_1}.$
Note that the cocycles $\omega'_1$ and $\omega'_2$ form a basis for Case VIII. Therefore, Case VIII also gives the algebras $\widehat{H}_4$ and $\widehat{H}_5(\delta).$



\item [IX.] $\alpha_1=-\alpha_2=-2,$ $\beta_1=-\beta_2=-1.$ Then 2-cocycle $\omega(e_1, e_3) = e_{4},$ $\omega(e_3, e_1) =-e_{4}$ form a basis of $H^2(H,l,r)$ and
automorphisms $\varphi_1 \in \operatorname{Aut}(H)$ and $\psi \in \operatorname{Aut}(\mathfrak{h})$ act the element $\delta\overline{\omega}$ to $\delta'\overline{\omega}$ as $$\delta'=\delta \lambda a_{1,1}^2 a_{2,2}.$$

Taking $\lambda =\frac 1 {\delta}$ and  $a_{1,1} = a_{2,2}=1,$ we can suppose $\delta'= 1.$
The new products of the algebra  $\widehat{H}=H\oplus\{e_{4}\}$ are defined as follows:
    $$\begin{array}{lllll} [e_1,e_3]=\omega(e_1,e_3) =  e_{4}, & [e_3,e_1]=-\omega(e_1,e_3) =-e_{4},\\[1mm] [e_4,x_1]=r_{x_1}e_{4}=2e_4, & [x_1,e_4]=l_{x_1}e_{4}=-2e_4, \\[1mm]
[e_4,x_2]=r_{x_2}e_{4}=e_4, & [x_2,e_4]=l_{x_2}e_{4}=-e_4, \end{array}$$

Therefore, we get the algebra $\widehat{H}_6$.

Moreover, if we consider an action by the automorphism $\varphi_2$, then the element $\delta\overline{\omega}$ acts on the element $\delta\overline{\omega'}$, such that
$$\begin{array}{lllll}\omega(e_2, e_3) = e_4, &\omega(e_3, e_2)=-e_{4},\end{array}$$
with $l'_{x_1}=l_{x_2},$ $l'_{x_2}=l_{x_1},$ $r'_{x_1}=r_{x_2},$ $r'_{x_2}=r_{x_1}.$
Note that the cocycle $\omega$ form a basis of Case X. Therefore, Case X also gives the algebra $\widehat{H}_6.$
\end{itemize}
\end{proof}





\subsection{Extensions of the algebra $L_1$}
Now, using the algorithm for constructing solvable Leibniz algebras, we obtain all extensions of the solvable Leibniz algebra $L_1$
by the one-dimensional abelian algebra $\mathfrak{h}=\{e_4\}$.
The condition \eqref{c3}, for the linear maps $l,r: L_1 \rightarrow \operatorname{End}(\mathfrak{h})$ such that
$$\begin{array}{ll}l_{x_1}(e_{4})=\alpha_1 e_{4}, & r_{x_1}(e_{4})=\alpha_2e_{4},\\[1mm]
l_{x_2}(e_{4})=\beta_1 e_{4}, & r_{x_2}(e_{4})=\beta_2e_{4}.\end{array}$$
leads to the following equalities:
\begin{equation}\label{L_1z}\begin{array}{ll} \alpha_1(\alpha_1+\alpha_2)=0, & \alpha_1(\beta_1+\beta_2)=0,\\[1mm]
\beta_1(\alpha_1+\alpha_2)=0,& \beta_1(\beta_1+\beta_2)=0.\end{array}\end{equation}

In the following Proposition, we describe all $2$-cocycles on $L_1$ with respect to the pair $(l,r),$ where $\mathfrak{h}=\{e_4\}$.



\begin{prop}{\label{Z2forL1}}
