\omega(e_2,x_1)=b_{2,4}, & \omega(e_2,x_2)=b_{2,5},& \omega(e_3,x_1)=b_{2,1},\\ [1mm]
\omega(x_1,e_1)=-b_{1,4}, &
\omega(x_1,x_2)= b_{4,5},  & \omega(x_2,x_2)=b_{5,5}.\end{array}\end{equation}
\item[V.] $\alpha_1=\beta_1=0, $  $(\alpha_2,\beta_2)\neq (1,0), (2,0), (2,1), (0,1):$
