 \omega(e_2,e_1)=b_{2,1}, \\ [1mm]
 \omega(e_2,x_1)=\alpha_2b_{2,4}, & \omega(e_2,x_2)=(\beta_2-1)b_{2,4},& \omega(e_3,x_1)=(1-\alpha_2)b_{2,1}, \\ [1mm]
\omega(e_3,x_2)=(1-\beta_2)b_{2,1},&
 \omega(x_1,e_1)=b_{4,1}, &
 \omega(x_1,x_1)=\alpha_2 b_{4,5}, \\ [1mm]
  \omega(x_1,x_2)= \beta_2b_{4,5}, &\omega(x_2,x_1)= \alpha_2 b_{5,5}, & \omega(x_2,x_2)=\beta_2b_{5,5}.\end{array}\end{equation}
\item[VI.] $\alpha_1=-\alpha_2=-1,$ $\beta_1=\beta_2=0:$
