 \omega(e_2,x_2)=b_{2,5}, & \omega(e_3,x_2)=b_{2,1}, & \omega(x_1,e_1)=-b_{1,4}, & \omega(x_1,e_2)=b_{2,5},\\ [1mm]
 \omega(x_1,e_3)= b_{2,1},&  \omega(x_1,x_2)=b_{4,5},  & \omega(x_2,e_1)=-b_{1,5},
