\item[VII.] $\alpha_1=-\alpha_2,$ $\beta_1=-\beta_2,$ $(\alpha_1, \beta_1) \neq (-1,0):$
 \begin{equation}\label{eq4.19}\begin{array}{llll}\omega(e_1,x_1)=(1+\alpha_1)b_{1,5}, & \omega(e_1,x_2)=\beta_1b_{1,5}, &
  \omega(e_2,e_1)=b_{2,1},  \\ [1mm]
   \omega(e_2,x_1)=\alpha_1b_{2,5},& \omega(e_2,x_2)=(1+\beta_1)b_{2,5},&
  \omega(e_3,x_1)=(1+\alpha_1)b_{2,1},  \\ [1mm]
