  \omega(x_1,e_3)=-\alpha_1 b_{2,1},&\omega(x_1,x_2)=b_{4,5},&
\omega(x_2,e_1)=-\beta_1b_{1,5},\\[1mm]
\omega(x_2,e_2)=-\beta_1b_{2,5},&
 \omega(x_2,e_3)=-\beta_1 b_{2,1},
