\end{prop}
\begin{proof}
For any $\omega\in Z^2(L_1,l,r),$
denote by $\omega(x,y)=b_{i,j}e_4,$ $1\leq i,j\leq 5$, where $x,y\in \{e_1,e_2,e_3,x_1,x_2\}.$
Using equality \eqref{c4}, we obtain the following relations:
$$\begin{array}{lllll}
\beta_1b_{1,1}=0, & \beta_2b_{1,1}=0, & \alpha_1b_{1,1}=0, & (2-\alpha_2)b_{1,1}=0,\\[1mm]
\beta_1b_{1,2}=0,&  \beta_2b_{1,2}=0, & (1-\beta_2)b_{1,2}=0,& (1+\alpha_1)b_{1,2}=0,\\[1mm]
(1-\alpha_2)b_{1,2}=0,& b_{1,3}=0,&  b_{2,3}=0, & b_{3,2}=0,\quad b_{3,3}=0,\\[1mm]
\beta_1b_{1,4}=(\alpha_2-1)b_{5,1},&\beta_2b_{1,4}=(\alpha_2-1)b_{1,5},&
b_{1,4}=(\alpha_1+\alpha_2-1)b_{4,1},& (\alpha_1+1)b_{1,4}=(\alpha_2-1)b_{4,1},\\[1mm]
\beta_1b_{1,5}=\beta_2b_{5,1},& b_{1,5}=\alpha_1b_{5,1}+\beta_2b_{4,1},\\[1mm]
\alpha_1b_{2,2}=0, & \alpha_2b_{2,2}=0,& \beta_1b_{2,2}=0, & (2-\beta_2)b_{2,2}=0,\\[1mm]
(1-\beta_2)b_{2,2}=0,& \alpha_1b_{2,4}=\alpha_2b_{4,2},& \beta_1b_{2,4}=\alpha_2b_{5,2}, \\[1mm]
\alpha_1b_{2,5}=(\beta_2-1)b_{4,2},& \alpha_2b_{2,5}=(\beta_2-1)b_{2,4},&\beta_1b_{2,5}=(\beta_2-1)b_{5,2}\\[1mm]
\beta_1a_{3,1}=0, & (1-\beta_2)b_{3,1}=0,&\alpha_1a_{3,1}=0 &(2-\alpha_2)b_{3,1}=0,\\[1mm]
b_{3,4}=(1-\alpha_2)b_{2,1},& \beta_1b_{3,4}=(\alpha_2-1)b_{5,3},& (1-\beta_2)b_{3,4}=(1-\alpha_2)b_{3,5}, \\[1mm] b_{3,5}=(1-\beta_2)b_{2,1}, & \beta_1b_{3,5}=(\beta_2-1)b_{5,3},\\[1mm]
\beta_1b_{4,1}=(1-\alpha_2)b_{5,1},& \beta_1b_{4,2}=-\alpha_2b_{5,2}, & \beta_2b_{4,2}=-\alpha_1b_{5,2}, &(\alpha_1+\alpha_2)b_{4,2}=0, \\[1mm]
b_{4,3}=b_{1,2}-\alpha_1b_{2,1}, &\beta_1b_{4,3}=-\alpha_2b_{5,3}, &  \beta_2b_{4,3}=-\alpha_1b_{5,3},& (\alpha_1+\alpha_2)b_{4,3}=0, \\[1mm]
 \alpha_1b_{4,4}=0, & \beta_1b_{4,4}=0,&  \alpha_1b_{5,5}=0, & \beta_1b_{5,5}=0,  \\[1mm]
 (\alpha_1+\alpha_2)b_{4,5}=\beta_2b_{4,4},& (\beta_1+\beta_2)b_{5,1}=0, & (\beta_1+\beta_2)b_{5,2}=0,\\[1mm]
 b_{5,3}=-\beta_1b_{2,1},& (\beta_1+\beta_2)b_{5,3}=0,& \alpha_2b_{5,5}=(\beta_1+\beta_2)b_{5,4},\\[1mm]
\beta_2b_{4,4}=\alpha_2b_{4,5}-\alpha_1b_{5,4}, &\alpha_2b_{5,5}=\beta_2b_{5,4}-\beta_1b_{4,5}. \end{array}$$

 By \eqref{L_1z}, we derive that $\alpha_1=\beta_1=0$ or $\alpha_1=-\alpha_2$ and $\beta_1=-\beta_2.$ Thus, we consider the following two cases:


\begin{itemize}
\item[Case 1.]Let $\alpha_1=\beta_1=0.$  Then we have
$$\begin{array}{llll}
b_{1,2}=0, & b_{1,3}=0,& b_{1,4}= (\alpha_2-1)b_{4,1}, & b_{1,5}= \beta_2b_{4,1}, \\[1mm]
b_{2,2}=0, &b_{2,3}=0, & b_{3,2}=0,& b_{3,3}=0, \\[1mm]
 b_{3,3}=0,& b_{3,4}= (1-\alpha_2)b_{2,1}, & b_{3,5}= (1-\beta_2)b_{2,1}, \\[1mm]
b_{4,2}=0, & b_{4,3}= 0, & b_{5,2}=0, & b_{5,3}= 0,
 \end{array}$$
and the following restrictions
$$\begin{array}{llll}
 \beta_2b_{1,1}=0, & (\alpha_2-2)b_{1,1}=0,& \alpha_2b_{2,5}=(\beta_2-1)b_{2,4},\\[1mm]
 (\beta_2-1)b_{3,1}=0, & (\alpha_2-2)b_{3,1}=0,&  \alpha_2b_{4,5}=\beta_2b_{4,4}, \\[1mm]
\beta_2b_{5,1}=0, & (\alpha_2-1)b_{5,1}=0,& \alpha_2b_{5,5}=\beta_2b_{5,4}.\\[1mm]
 \end{array}$$
Now, consider the following subcases:

\begin{itemize}
\item[1.1.] If $\alpha_2=1,$ $\beta_2=0,$ then we obtain $b_{2,5}=-b_{2,4}$ and
$b_{1,1}=b_{3,1}=b_{4,5}= b_{5,5}=0.$ Hence, we conclude that any $2$-cocycles on $L_1$ with respect to the pair $(l,r)$ has the form \eqref{eq4.13}.

  \item[1.2.] If $\alpha_2=2,$ $\beta_2=0,$ then we obtain $b_{2,4}=-2b_{2,5}$ and
$b_{3,1}=b_{4,5}= b_{5,1}= b_{5,5}=0.$ Hence, we deduce that any $2$-cocycles on $L_1$ with respect to the pair $(l,r)$ has the form \eqref{eq4.14}.

\item[1.3.] If $\alpha_2=2,$ $\beta_2=1,$ then we obtain $b_{4,4}=2b_{4,5},$ $b_{5,4}=2b_{5,5}$   and
$b_{1,1}=b_{2,5}= b_{5,1}=0.$ Hence, we get that any $2$-cocycles on $L_1$ with respect to the pair $(l,r)$ has the form \eqref{eq4.15}.


\item[1.4.] If $\alpha_2=0,$ $\beta_2=1,$ then we obtain
$b_{1,1}=b_{3,1}=b_{4,4}=b_{5,1}=b_{5,4}=0.$ Hence, we get that any $2$-cocycles on $L_1$ with respect to the pair $(l,r)$ has the form \eqref{eq4.16}.

 \item[1.5.] If $ (\alpha_2,\beta_2)\neq (1,0),(2,0),(2,1),(0,1) $ then we obtain $b_{1,1}=b_{3,1}= b_{5,1}=0$ and $$ \alpha_2b_{2,5}=(\beta_2-1)b_{2,4},\quad \alpha_2b_{4,5}=\beta_2 b_{4,4},\quad \alpha_2b_{5,5}=\beta_2b_{5,4}.$$

 In this case, we obtain that any $2$-cocycles on $L_1$ with respect to the pair $(l,r)$ has the form \eqref{eq4.17}.
\end{itemize}

 \item [Case 2.] Let $\alpha_1=-\alpha_2$ and $\beta_1=-\beta_2.$  Then we have
$$\begin{array}{lllll}
b_{1,1}=0, & b_{1,2}=0,& b_{1,3}=0, & b_{2,2}=0, \\[1mm]
b_{3,1}=0, & b_{3,2}=0, & b_{3,3}=0,  & b_{3,4}= (1+\alpha_1)b_{2,1}, \\[1mm]
 b_{3,5}=(1+\beta_1)b_{2,1}, &   b_{4,1}=-b_{1,4},  & b_{4,2}=-b_{2,4},&
b_{4,3}= -\alpha_1b_{2,1}, \\[1mm] b_{4,4}=0,&
b_{5,1}=-b_{1,5},& b_{5,3}=- \beta_1b_{2,1},& b_{5,4}=-b_{4,5}, & b_{5,5}=0.
 \end{array}$$
and the following restrictions
$$
 \beta_1b_{1,4}=(1+\alpha_1)b_{1,5}, \quad \alpha_1b_{2,5}=(1+\beta_1)b_{2,4},\quad  \beta_1b_{2,5}=-(1+\beta_1)b_{5,2}.
$$


Consider the following subcases:

\begin{itemize}
\item[2.1.] If $\alpha_1=-1,$ $\beta_1=0,$ then we obtain $b_{2,5}=-b_{2,4}$ and
$b_{5,2}=0.$ Hence, we get that any $2$-cocycles on $L_1$ with respect to the pair $(l,r)$ has the form \eqref{eq4.18}.

\item[2.2.] If  $(\alpha_1, \beta_1) \neq (-1,0),$ then we conclude that any $2$-cocycles on $L_1$ with respect to the pair $(l,r)$ has the form \eqref{eq4.19}.

\end{itemize}
\end{itemize}



\end{proof}


By Propositions \ref{B2} and \ref{Z2forL1}, we obtain the following corollary:
\begin{cor}\label{cor4.7} We have the following:
\begin{itemize}
\item[I.] If $\alpha_1=\beta_1=\beta_2=0,$ $\alpha_2=1,$ then  $\operatorname{dim} Z^2(L_1,l,r) =6,$
$\operatorname{dim} B^2(L_1,l,r) =5;$
\item[II.] If $\alpha_1=\beta_1=\beta_2=0,$ $\alpha_2=2,$ then  $\operatorname{dim} Z^2(L_1,l,r) =6,$
$\operatorname{dim} B^2(L_1,l,r) =5;$
\item[III.] If $\alpha_1=\beta_1=0,$ $\alpha_2=2,$ $\beta_2=1$, then  $\operatorname{dim} Z^2(L_1,l,r) =6,$
$\operatorname{dim} B^2(L_1,l,r) =5;$
\item[IV.] If $\alpha_1=\alpha_2=\beta_1=0,$ $\beta_2=1$, then  $\operatorname{dim} Z^2(L_1,l,r) =6,$
$\operatorname{dim} B^2(L_1,l,r) =4;$
\item[V.] If $\alpha_1=\beta_1=0, $  $(\alpha_2,\beta_2)\neq (1,0), (2,0), (2,1), (0,1),$ then  $\operatorname{dim} Z^2(L_1,l,r) =5,$
$\operatorname{dim} B^2(L_1,l,r) =5;$
\item[VI.] If $\alpha_1=-\alpha_2=-1,$ $\beta_1=\beta_2=0$, then  $\operatorname{dim} Z^2(L_1,l,r) =5,$
$\operatorname{dim} B^2(L_1,l,r) =3;$
\item[VII.] If $\alpha_1=-\alpha_2,$ $\beta_1=-\beta_2,$ $(\alpha_1, \beta_1) \neq (-1,0),$ then  $\operatorname{dim} Z^2(L_1,l,r) =4,$
$\operatorname{dim} B^2(L_1,l,r) =4.$

 \end{itemize}
\end{cor}


Now, we can formulate the following result.
 \begin{thm}\label{thmL1} Let $\widehat{L}_1$ be an extension of the solvable Leibniz algebra $L_1$ by the abelian algebra $\mathfrak{h}=\{e_4\}.$ Then
   $\widehat{L}_1$ is isomorphic to one of the following non-isomorphic algebras:
  $$\widehat{L}^1_1:\begin{array}{lllll} [e_2,e_1]=e_3,& [e_1,x_1]=e_1, &[x_1,e_1]=-e_1, & [x_2,e_1]=e_4,\\ [1mm]
  [e_3,x_1]=e_3, & [e_2,x_2]=e_2,& [e_3,x_2]=e_3, & [e_4,x_1]=e_4,.\end{array} $$
$$\widehat{L}^2_1:\begin{array}{lllll} [e_1,e_1]=e_4,& [e_2,e_1]=e_3,& [e_1,x_1]=e_1, &[x_1,e_1]=-e_1, \\ [1mm]
  [e_3,x_1]=e_3, & [e_2,x_2]=e_2,& [e_3,x_2]=e_3, & [e_4,x_1]=2e_4.\end{array} $$
$$\widehat{L}^3_1:\begin{array}{llllll} [e_2,e_1]=e_3,& [e_3,e_1]=e_4,& [e_1,x_1]=e_1, &  [x_1,e_1]=-e_1, \\ [1mm]
 [e_3,x_1]=e_3, & [e_2,x_2]=e_2, & [e_3,x_2]=e_3, & [e_4,x_1]=2e_4,& [e_4,x_2]=e_4.\end{array} $$
 $$\widehat{L}^4_1:\begin{array}{lllll} [e_2,e_1]=e_3,& [e_1,x_1]=e_1, &[x_1,e_1]=-e_1,&   [e_2,x_1]=e_4, \\ [1mm]
[e_3,x_1]=e_3,& [e_2,x_2]=e_2,& [e_3,x_2]=e_3, & [e_4,x_2]=e_4.\end{array} $$
 $$\widehat{L}^5_1(\delta):\begin{array}{lllll} [e_2,e_1]=e_3,& [e_1,x_1]=e_1, &[x_1,e_1]=-e_1,&   [e_2,x_1]=\delta e_4, \\ [1mm]
[e_3,x_1]=e_3,& [e_2,x_2]=e_2+e_4,& [e_3,x_2]=e_3, & [e_4,x_2]=e_4.\end{array} $$
$$\widehat{L}^6_1:\begin{array}{lllll} [e_2,e_1]=e_3,& [e_1,x_1]=e_1+e_4, &[x_1,e_1]=-e_1-e_4,& [e_2,x_2]=e_2,\\ [1mm]
[e_3,x_1]=e_3,& [e_3,x_2]=e_3, & [e_4,x_1]=e_4, & [x_1,e_4]=-e_4,\end{array} $$
 $$\widehat{L}^7_1(\delta):\begin{array}{lllll} [e_2,e_1]=e_3,& [e_1,x_1]=e_1+\delta e_4, &  [e_1,x_2]=e_4,& [e_2,x_2]=e_2,\\ [1mm]
[e_3,x_1]=e_3,& [e_3,x_2]=e_3, &
[x_1,e_1]=-e_1-\delta e_4,&  [x_2,e_1]=-e_4,\\ [1mm]
[e_4,x_1]=e_4, & [x_1,e_4]=-e_4.\end{array} $$
 \end{thm}

\begin{proof} By Corollary \ref{cor4.7}, we have that $H^2(L_1,l,r)=0$ in cases V and VII. Thus, it is enough to consider the remaining  cases.


\begin{itemize}

\item [I.] $\alpha_1=\beta_1=\beta_2=0,$ $\alpha_2=1.$ In this case $\dim H^2(L_1,l,r) =1$ and $2$-cocycle defined by $\omega(x_2,e_1)=e_4$ form a basis on this space, i.e.  $H^2(L_1,l,r) =\langle\overline{\omega}\rangle.$

Any automorphism $\varphi\in \operatorname{Aut}(L_1)$ of Proposition \ref{Aut3-dim}  and any automorphism $\psi \in \operatorname{Aut}(\mathfrak{h}),$ where $\psi(e_{4}) = \lambda e_{4}$ act the element $\delta\overline{\omega} \in H^2(L_1,l,r)$ to $\delta'\overline{\omega} \in H^2(L_1,l,r)$, as follows:
$$\delta' = \delta\lambda a_{1,1}, \quad l'=l, \quad r'=r.$$

By taking $\lambda =1$ and  $a_{1,1} = \frac 1 {\delta},$ we can assume  $\delta' =1.$
Thus, the new products of the algebra $\widehat{L}_1=L_1\oplus\{e_{4}\}$ are given by
    $$\begin{array}{llll}[x_2,e_1]=\omega(x_2,e_1) =e_{4},&
[e_4,x_1]=r_{x_1}e_{4}=e_4. \end{array}$$

Hence, we obtain  the algebra $\widehat{L}^1_1$.





\item [II.] $\alpha_1=\beta_1=\beta_2=0,$ $\alpha_2=2.$
In this case $\dim H^2(L_1,l,r) =1$ and $2$-cocycle defined by $\omega(e_1,e_1)=e_4$ provides a basis on this space, i.e.  $H^2(L_1,l,r) =\langle\overline{\omega}\rangle.$
Any automorphisms $\varphi \in \operatorname{Aut}(L_1)$ and $\psi \in \operatorname{Aut}(\mathfrak{h})$ act the element $\delta\overline{\omega}$ to $\delta'\overline{\omega}$, as follows:
$$\delta' = \delta\lambda a_{1,1}^2.$$

Taking $\lambda =\frac 1 {\delta}$ and  $a_{1,1} = 1,$ we can suppose $\delta' =1.$
Thus, the new products of the algebra  $\widehat{L}_1=L_1\oplus\{e_{4}\}$ are defined as follows:
$$[e_1,e_1]=\omega(e_1,e_1)=e_4, \quad [e_4,x_1]=r_{x_1}e_{4}=2e_4. $$

Therefore, we obtain the algebra $\widehat{L}^2_1$.



\item [III.] $\alpha_1=\beta_1=0,$ $\alpha_2=2,$ $\beta_2=1.$
In this case $\dim H^2(L_1,l,r) =1$ and $H^2(L_1,l,r) =\langle\overline{\omega}\rangle,$ where $\omega(e_3,e_1)=e_4.$
Automorphisms $\alpha \in \operatorname{Aut}(L_1)$ and  $\psi \in \operatorname{Aut}(\mathfrak{h})$ act the element $\delta\overline{\omega}$ to $\delta'\overline{\omega}$, as follows:
$$\delta' = \delta\lambda a_{1,1}^2a_{2,2}.$$

Taking $\lambda =\frac 1 {\delta}$ and  $a_{1,1} = a_{2,2}=1,$ we can suppose $\delta' =1.$
Thus, the new products of the algebra  $\widehat{L}_1=L_1\oplus\{e_{4}\}$ are given by:
    $$\begin{array}{llll}[e_3,e_1]=\omega(e_3,e_1) =e_{4},&
[e_4,x_1]=r_{x_1}e_{4}=2e_4, & [e_4, x_2]=r_{x_2}e_{4}=e_4. \end{array}$$

Therefore, we obtain  the algebra $\widehat{L}^3_1$.



\item [IV.] $\alpha_1=\alpha_2=\beta_1=0, $ $\beta_2=1.$
In this case $\dim H^2(L_1,l,r) =2$ and the basis of this space is given by the 2-cocycles
    $$\begin{array}{lllll}\omega_1(e_2, x_1) =e_4, && \omega_2(e_2, x_2)=e_4.\end{array}$$

Automorphisms $\varphi\in \operatorname{Aut}(L_1)$ and $\psi \in \operatorname{Aut}(\mathfrak{h})$ act the element $\delta_1\overline{\omega_1}+\delta_2\overline{\omega_2}$ to $\delta_1'\overline{\omega_1}+\delta_2'\overline{\omega_2}$ as
$$\delta_1'=\delta_1 \lambda a_{2,2},\quad \delta_2'=\delta_2\lambda a_{2,2}.$$

\begin{itemize}
\item If $\delta_2=0$, then
$\delta_2'=0$ and $\delta_1\neq 0.$ Taking $\lambda=1,$ $a_{2,2} = \frac 1 {\delta_1},$ we can suppose $\delta_1'=1$ and obtain the algebra $\widehat{L}_1^4.$
\item If $\delta_2\neq 0$, then choosing $\lambda=1,$ $a_{2,2}=\frac{1}{\delta_2},$ we get $\delta_2'=1$
and obtain the algebra $\widehat{L}_1^5(\delta).$
\end{itemize}






\item [VI.] $\alpha_1=-\alpha_2=-1,$ $\beta_1=\beta_2=0.$
In this case $\dim H^2(L_1,l,r) =2$ and the basis of this space is given by the 2-cocycles
    $$\begin{array}{lllll}\omega_1(e_1, x_1) =e_4, &\omega_1(x_1, e_1)=-e_{4}, && \omega_2(e_1, x_2)=e_4, &\omega_2(x_2, e_1) =-e_{4}.\end{array}$$

Automorphisms $\varphi \in \operatorname{Aut}(L_1)$ and $\psi \in \operatorname{Aut}(\mathfrak{h})$ act the element $\delta_1\overline{\omega_1}+\delta_2\overline{\omega_2}$ to $\delta_1'\overline{\omega_1}+\delta_2'\overline{\omega_2}$ as
$$\delta_1'=\delta_1 \lambda a_{1,1},\quad \delta_2'=\delta_2\lambda a_{1,1}.$$

\begin{itemize}
\item If $\delta_2=0$ , then
$\delta_2'=0$ and $\delta_1\neq 0.$ Taking $\lambda=1,$ $a_{1,1} = \frac 1 {\delta_1},$ we can suppose $\delta_1'=1$ and obtain the algebra $\widehat{L}_1^6.$
\item If $\delta_2\neq 0$, then choosing $\lambda=1,$ $a_{1,1}=\frac{1}{\delta_2},$ we get $\delta_2'=1$ and obtain the algebra $\widehat{L}_1^7(\delta).$
\end{itemize}
\end{itemize}


\end{proof}

