$\operatorname{dim} B^2(L_2,l,r) =5;$
\item If $\alpha_1=\beta_1=0,$  $(\alpha_2,\beta_2)\neq (1,0), (3,0), (0,1), (1,1)$, then   $\operatorname{dim} Z^2(L_2,l,r) =5,$
$\operatorname{dim} B^2(L_2,l,r) =5;$
\item If $\alpha_1=-\alpha_2=-1,$ $\beta_1=\beta_2=0$, then  $\operatorname{dim} Z^2(L_2,l,r) =5,$
$\operatorname{dim} B^2(L_2,l,r) =3;$
\item If $\alpha_1=-\alpha_2,$ $\beta_1=-\beta_2,$ $(\alpha_1,\beta_1)\neq (-1,0),$ then $\operatorname{dim} Z^2(L_2,l,r) =4,$
$\operatorname{dim} B^2(L_2,l,r) =4;$

 \end{itemize}
\end{cor}



\begin{thm}
Let $\widehat{L}_2$ be an extension of the solvable Leibniz algebra $L_2$ by the abelian algebra $\mathfrak{h}=\{e_4\}.$ Then
   $\widehat{L}_2$ is isomorphic to one of the following non-isomorphic algebras:
  $$\widehat{L}^1_2:\begin{array}{lllll} [e_1,e_1]=e_3,& [e_1,x_1]=e_1, & [x_1,e_1]=-e_1, & [e_3,x_1]=2e_3,\\ [1mm] [x_2,e_1]=e_4, & [e_2,x_2]=e_2, & [e_4,x_1]=e_4.\end{array} $$
   $$\widehat{L}^2_2:\begin{array}{lllll} [e_1,e_1]=e_3,& [e_3,e_1]=e_4,& [e_1,x_1]=e_1, & [x_1,e_1]=-e_1, \\ [1mm] [e_3,x_1]=2e_3, & [e_2,x_2]=e_2, & [e_4,x_1]=3e_4.\end{array} $$
   $$\widehat{L}^3_2:\begin{array}{lllll} [e_1,e_1]=e_3,& [e_1,x_1]=e_1, &[x_1,e_1]=-e_1,& [e_2,x_1]=e_4, \\ [1mm]
  [e_3,x_1]=2e_3,&  [e_2,x_2]=e_2, & [e_4,x_2]=e_4.\end{array} $$
 $$\widehat{L}^4_2(\delta):\begin{array}{lllll} [e_1,e_1]=e_3,& [e_1,x_1]=e_1, &[x_1,e_1]=-e_1,& [e_2,x_1]=\delta e_4,  \\ [1mm]
  [e_3,x_1]=2e_3, & [e_1,x_2]=e_4,& [e_2,x_2]=e_2+e_4, & [e_4,x_2]=e_4.\end{array} $$
   $$\widehat{L}^5_2:\begin{array}{lllll} [e_1,e_1]=e_3,& [e_2,e_1]=e_4,& [e_1,x_1]=e_1, &[x_1,e_1]=-e_1, \\ [1mm]
  [e_3,x_1]=2e_3, & [e_2,x_2]=e_2,& [e_4,x_1]=e_4 & [e_4,x_2]=e_4.\end{array} $$
 $$\widehat{L}^6_2:\begin{array}{lllll} [e_1,e_1]=e_3,& [e_1,x_1]=e_1+e_4, &[x_1,e_1]=-e_1-e_4, \\ [1mm]
  [e_3,x_1]=2e_3,&  [e_2,x_2]=e_2, & [e_4,x_1]=e_4,& [x_1,e_4]=-e_4.\end{array} $$
 $$\widehat{L}^7_2(\delta):\begin{array}{lllll} [e_1,e_1]=e_3,& [e_1,x_1]=e_1+\delta e_4, &[x_1,e_1]=-e_1-\delta e_4, \\ [1mm]
  [e_3,x_1]=2e_3, & [e_1,x_2]=e_4,& [x_2,e_1]=-e_4,\\ [1mm] [e_2,x_2]=e_2, & [e_4,x_1]=e_4,& [x_1,e_4]=-e_4.\end{array} $$
 \end{thm}

\begin{proof} The proof follows a similar approach to Theorems \ref{thmH} and \ref{thmL1}. \end{proof}


