\subsection{Higher order cases}

\begin{theorem}\label{PbnSUB}
For all $n \ge 1$, $\Pb{n}$-SUB and $\Sb{n}$-SUB are $\Pi^1_n$-complete.
\end{theorem}

We split the proof into Lemmas \ref{pisubin}, \ref{pisubhard} and \ref{sisubhard}.

\begin{remark}\label{calcfonda}
All problems of the form $\exists_1 X_1 \exists x_1 \forall x_2 \ R$ with $R$ a decidable predicate, are in $\Sigma^0_2$. Dually, all problems of the form $\forall_1 X_1 \forall x_1 \exists x_2 \ R$ with $R$ a decidable predicate, are in $\Pi^0_2$.
\end{remark}

%I removed the proof of the previous remark.

\begin{lemma} \label{pisubin}
For all $n \ge 1$, $\Pb{n}$-SUB and $\Sb{n}$-SUB are in $\Pi^1_n$.
\end{lemma}

%In the following proof, I removed the part where we use the main argument to conclude the lemma.

\begin{proof}%[sketch]
  Let $\phi \in \Pb{n}$ with $m$ second order quantifiers (the $\Sb{n}$ case is similar). Denote by $\phi^*$ the first order formula on $\A \times \{0,1\}^m$ obtained from $\phi$ by removing second order quantifiers and replacing each $v \in X_i$ with $\bigvee_{c \in \pi_i^{-1}(1)} P_c(v)$, where $\pi_i (c_0, \hdots, c_m)=c_i$. For a configuration $x \in \A^{\Z^2}$, we have $x \vDash \phi$ if and only if
  \begin{equation}
    \label{eq:pisubin}
    \forall X_1 \ \hdots \ Q X_m \ x \times X_1 \times \hdots \times X_m \vDash \phi^*
  \end{equation}
for $Q=\exists$ if $n$ is even, $Q=\forall$ otherwise.
From Corollary \ref{fofonda} we deduce that $x \times X_1 \times \hdots \times X_m \vDash \phi^*$ is a $\Delta^0_2$ condition, when $\phi^*$ is given as input and $x$ and the $X_i$ are given as oracles.
With Remark \ref{calcfonda} it follows that \eqref{eq:pisubin}, and hence $x \vDash \phi$, is $\Pi^0_2$ for $n = 1$, and $\Pi^1_{n-1}$ for $n \geq 2$, with $\phi$ as input and $x$ as an oracle.

The set $X_\phi$ is closed if and only if for all sequences $x_n$ of configurations such that $x_n \vDash \phi$ for all $n$ and $x_n |_{[-n,n]^2} = x_m|_{[-n,n]^2}$ for all $m \geq n$, we have $\lim_n x_n \vDash \phi$.
By the above, this condition is $\Pi^1_n$.
\end{proof}

\begin{lemma} \label{pisubhard}
For all $n \ge 1$, $\Pb{n}$-SUB is $\Pi^1_n$-hard.
\end{lemma}

\begin{proof}
  We reduce an arbitrary problem in $\Pi^1_n$. Let $R$ be a computable predicate. We construct a formula $\phi \in \Pb{n}$ such that $\forall A_1 \hdots Q A_n \ \ob{Q} k \  Q m \ R$ holds if and only if $X_\phi$ is a subshift, with $Q=\exists$ if $n$ is even and $Q=\forall$ otherwise.

  Let $\phi'$ be the formula which describes a tiling where a northeast quarter-plane is coloured with 0 and 1 such that each row is coloured in a same way, and the other tiles are blank. Since the quarter-plane must appear, $X_{\phi'}$ is not a subshift. The infinite binary sequence repeated on each line is interpreted as the oracle $A_1$ in the following.

  Let $\phi=\forall X_2 \in X_{\phi'} \hdots \ \ob{Q} X_n \in X_{\phi'} \ \ob{Q} Z \ \phi' \wedge \psi$, where $\psi$ is the formula stating the following:
  \begin{itemize}
  \item each of $X_2, \ldots, X_n$ has a northeast quarter-plane at the same position as the main configuration $x \in X_{\phi'}$,
  \item the configuration $Z$ contains, in the same quarter-plane, a simulated computation of a Turing machine $M$ that can use the binary sequences of $x$ and the $X_i$ as oracles,
  \item if $\ob{Q} = \exists$, then $M$ visits a special state $q_s$ an infinite number of times (a $\Pb{1}$ condition by Example \ref{ex:finite}), and
  \item if $\ob{Q} = \forall$, then $M$ visits the state $q_s$ a finite number of times.
  \end{itemize}
  Notice that the configuration $Z$ is determined by what was quantified before, so its quantifier is irrelevant.
  Hence $\phi$ is $\Pb{n}$.

We specify the machine $M$.
Starting with $k = 0$, it enumerates $m = 0, 1, 2, \ldots$ until it finds one such that $R(A_1, \ldots, A_n, k, m)$ does not hold. Whan this happens, it visits the state $q_s$, increments $k$, and starts the enumeration again.

Notice that $x \vDash \phi$ if and only if $\forall A_2 \hdots \ \ob{Q} A_n \ \ Q k \ \ob{Q} m \ \lnot R$ holds.
Hence, if $\forall A_1 \exists A_2 \hdots Q A_n \ \ob{Q}k \ Q m \ R$ holds, then $X_{\phi}$ is empty, and so a subshift.
If the formula does not hold, then at least one configuration with a quarter-plane is in $X_{\phi}$. But the blank configuration is not in $X_\phi$, so $X_{\phi}$ is not a subshift.
\end{proof}

\begin{lemma} \label{sisubhard}
For all $n \ge 1$, $\Sb{n}$-SUB is $\Pi^1_n$-hard.
\end{lemma}

