\begin{proof}[of Lemma \ref{equivclass}]
%We know thanks to \cite{rect} that $X_{\phi}$ is indeed a union of equivalence classes and that $(n,k)$ is computable from $\phi$. Let us prove that we can compute this union. 
We may assume that the radius of $\phi$ is at most 1, by introducing new existentially quantified variables for intermediate terms if needed; for example, a subformula $v = \mathrm{East}(\mathrm{East}(w))$ can be replaced by $\exists u \ v = \mathrm{East}(u) \land u = \mathrm{East}(w)$.
We also assume $\phi$ is in prenex normal form, so $\phi = Q_1 v_1 Q_2 v_2 \cdots Q_m v_m \psi$, where each $Q_i$ is a quantifier and $\psi$ is quantifier-free.

For $0 \le \ell \le m$, consider the alphabet $\A_\ell=\A \times \{0,1\}^\ell$.
For $0 \le i \le \ell$, let $\pi_i$ be the natural projection from $\A_\ell$ to $\A$ if $i = 0$ and to $\{0,1\}$ if $i \ge 1$.
Also, for $\ell < m$ let $\rho_\ell$ be the natural projection from $\A_{\ell+1}$ to $\A_\ell$.
We extend these projections to work on patterns and configurations as well.

A configuration $x = (y, b_1, \ldots, b_\ell) \in \A_\ell$ is \emph{consistent} if there is exactly one 1-symbol on each binary layer $b_i$. Such a consistent configuration \emph{satisfies} $\phi$, if the first layer $y$ satisfies $Q_{\ell+1} v_{\ell+1} \cdots Q_m v_m \psi$ when for each $i \in [1, \ell]$, the value of $v_i$ is the position of the 1-symbol on $b_i$.

Let $n \geq 0$ and $0 \le \ell \le m$.
Let $C_f$ be a $\sim_{(n,k)}$ equivalence class on $\A_\ell$.
We say that $C_f$ is \emph{consistent} if the following conditions hold.
\begin{itemize}
    \item For each $\vec{v} \in \nsq$ and each $j \in \llbracket 1, \ell \rrbracket$, there is exactly one pattern $P \in \A_\ell^{n \times n}$ such that $\pi_j(P_{\vec{v}}) = 1$ and $f(P)>0$. In this case, we must have $f(P)=1$.
    \item For each $j \in \llbracket 1, \ell \rrbracket$, the patterns $P \in \A_\ell^{n \times n}$ such that $f(P) > 0$ and $\pi_j(P)$ contains a 1 can be \emph{glued} together, i.e.\ there exists a single pattern $Q$ over $\A_\ell$ in which all of these patterns appear and with only one 1-symbol on each $\{0,1\}$-layer.
\end{itemize}
Notice that if an equivalence class $C_f$ is consistent then all $x \in C_f$ are consistent.

We inductively define unions $\C_\ell$ of equivalence classes on the alphabets $\A_\ell$, starting from $\C_m$ and finishing with $\C_0$.
Let $\C_m=\bigcup_f C_f$ be the union of those consistent $\sim_{(3,2)}$-equivalence classes on the alphabet $\A_m$ such that all $x \in C_f$ satisfy $\phi$. The set $\C_m$ is computable since all variables are interpreted in a fixed position and the radius of $\phi$ is 1.

Let now $0 \le \ell < m$, and suppose $\C_{\ell+1} = \bigcup_f C_f$ has been defined as a union of $(n,k)$-equivalence classes on $\A_{\ell+1}$ for some $n = 2p+1 \geq 3$ odd and $k \geq 2$.
Let $R = [0, n-1]^2$ and $T = [-p, n+p-1]^2$.
We say that a $\sim_{(n,k)}$ equivalence class $C_g = \bigcap_{P \in \A_{\ell+1}^R} g(P)$ is an \emph{extension} of a $\sim_{(4p+1,n^2+k)}$-equivalence class $C_f = \bigcap_{Q \in \A_\ell^T} f(Q)$ if the following conditions hold.
\begin{enumerate}
    \item For each $P \in \A_\ell^R$, we have
      \begin{equation}
        \label{eq:ext}
    \sum_{\substack{Q \in \A_\ell^T \\ Q|_R=P}} f(Q) \ge \sum_{\substack{Q \in \A_{\ell+1}^R \\ \rho_\ell(Q)=P}} g(Q)
    \end{equation}
    and equality must hold when $g(P \times 0^R)<k$.
    \item Let $Q \in \A_{\ell+1}^T$ be such that $\pi_{\ell+1}(Q_{(p,p)}) = 1$ and the $n \times n$ patterns $Q_1$, $Q_2$, $Q_3$ and $Q_4$ at each corner of $Q$ satisfy $g(Q_i) = 1$. Then we require $f(\rho_{\ell}(Q)) \geq 1$.
\end{enumerate}

Similarly, a configuration $y \in \A_{\ell+1}^{\Z^2}$ is an \emph{extension} of $x \in \A_\ell^{\Z^2}$ if both are consistent and $\rho_\ell(y) = x$.

\begin{claim}
\label{cl:extension}
If $y \in C_g$ is an extension of $x \in C_f$, then $C_g$ is an extension of $C_f$.
\end{claim}

\begin{proof}[of Claim]
  Let $P \in \A_\ell^R$.
  Since $y$ is an extension of $x$, we have
  \begin{equation}
    \label{eq:ext2}
    \sum_{\substack{Q \in \A_\ell^T \\ Q|_R=P}} \#_x(Q) = \sum_{\substack{Q \in \A_{\ell+1}^R \\ \rho_\ell(Q)=P}} \#_y(Q).
  \end{equation}
  Also, $\sum_{\substack{Q \in \A_{\ell+1}^R \\ \rho_\ell(Q)=P}} g(Q) \le n^2+k$, since $g(P \times 0^R) \le k$ and $g(Q) \le 1$ for every other $Q \in \A_{\ell+1}^R$ extending $P$.
  If~\eqref{eq:ext} were false, every $Q \in \A_\ell^T$ such that $Q_{|R}=P$ would thus satisfy $f(Q) < n^2+k$, implying $f(Q) = \#_x(Q)$.
  Using~\eqref{eq:ext2} we now have
  \[
    \sum_{\substack{Q \in \A_\ell^T \\ Q|_R=P}} f(Q) = \sum_{\substack{Q \in \A_\ell^T \\ Q|_R=P}} \#_x(Q) = \sum_{\substack{Q \in \A_{\ell+1}^R \\ \rho_\ell(Q)=P}} \#_y(Q) \geq \sum_{\substack{Q \in \A_{\ell+1}^R \\ \rho_\ell(Q)=P}} g(Q),
  \]
  a contradiction.

  Now suppose that $g(P \times 0^R)<k$.
  In this case, $g(Q) = \#_y(Q)$ holds for all $Q \in \A_{\ell+1}^R$ extending $P$, so the wanted equality.

%  The sum of these numbers, which is equal to $\#_x(P)$, is also strictly less than $n^2+k$.
%  Hence $f(Q) = \#_x(Q) < n^2+k$ for all $Q \in \A_\ell^T$ extending $P$.
%  From~\eqref{eq:ext2} we deduce that~\eqref{eq:ext} holds with equality.

  Finally, if $Q \in \A_{\ell+1}^T$ satisfies the hypothesis of the second condition, then such a $Q$ appears in $y$ since $\pi_{\ell+1}(y)$ contains a single 1-symbol.
  So $\rho_\ell(Q)$ appears in $x$, which implies $f(\rho_\ell (Q)) \ge 1$.
\end{proof}

We have two cases depending on the quantifier $Q_{\ell+1}$.
If $Q_{\ell+1} = \exists$, then let $\C_\ell$ be the union of consistent equivalence classes on $\A_\ell$ such that at least one of their consistent extensions is in $\C_{\ell+1}$.
If $Q_{\ell+1} = \forall$, then $\C_\ell$ is the the union of consistent equivalence classes on $\A_\ell$ such that all of their consistent extensions are in $\C_{\ell+1}$.

Now we prove by downward induction on $\ell$ that for each $0 \le \ell \le m$, the union $\C_\ell$ equals the set $X_\ell$ of consistent configurations $x \in \A_\ell^{\Z^2}$ that satisfy $\phi$.
For the initialization step $\ell = m$, it is clear that $X_m = \C_m$.
Let then $\ell < m$, and suppose the claim holds for $\C_{\ell+1}$. Let $x \in \A_\ell^{\Z^2}$.

Suppose first that $Q_\ell = \exists$. If $x \in X_\ell$, then it has a consistent extension $y \in X_{\ell+1}$, which we obtain by choosing the value of $v_\ell$ so that $\phi$ is still satisfied, and putting a 1-symbol at that coordinate. We have $y \in \C_{\ell+1}$ by the induction hypothesis, and so $x$ is in $\C_\ell$ thanks to the Claim.
%Hence $x$ lies in some equivalence class $C_f \in \C_\ell$.

For the other direction, suppose $x \in \C_\ell$, so $x$ lies in some consistent equivalence class $C_f \subseteq \C_\ell$.
By the definition of $\C_\ell$, there exists a consistent equivalence class $C_g \subseteq \C_{\ell+1}$ that is an extension of $C_f$.
Since $C_g$ is consistent, there exists a pattern $Q \in \A_{\ell+1}^T$ that contains occurrences of all patterns $P \in \A_{\ell+1}^R$ such that $g(P) > 0$ and $\pi_{\ell+1}(P)$ contains a 1.
The corners of this pattern satisfy $g(Q_i) = 1$, so item 2 of the definition of extension guarantees $f(\rho_\ell(Q)) \geq 1$; in particular, $\rho_\ell(Q)$ occurs in $x$.
Let $y \in \A_{\ell+1}^{\Z^2}$ be an extension of $x$ where the 1-symbol in $\pi_{\ell+1}(y)$ is at the middle of an occurrence of $\rho_\ell(Q)$.

Now we prove $g(P) = \min(\#_y(P), k)$ for all $P \in \A_{\ell+1}^R$.
We have $y \in C_g \subseteq \C_{\ell+1}$, and thus $y \in X_{\ell+1}$ by the induction hypothesis, which in turn implies $x \in X_{\ell}$.
If $P$ is an extension of $P' \in \A_\ell^R$ with a 1 on the last $\{0,1\}$ layer, then $g(P) = \#_y(P) \leq 1$ by construction.

Suppose then $P = P' \times 0^R$. If $g(P)<k$, then we have equality in~\eqref{eq:ext} and the right hand side is strictly less than $n^2+k$.
Now every $Q' \in \A_{\ell}^T$ such that $Q'|_R=P'$ appears exactly $f(Q')$ times in $x$.
This implies
\[
  \sum_{\substack{Q' \in \A^R_{\ell+1} \\ \rho_{\ell}(Q')=P'}} \#_y(Q') =
  \sum_{\substack{Q' \in \A^T_{\ell} \\ Q'|_R=P'}} \#_x(Q') =
  \sum_{\substack{Q' \in \A^T_{\ell} \\ Q'|_R=P'}} f(Q') =
  \sum_{\substack{Q' \in \A^R_{\ell+1} \\ \rho_{\ell}(Q')=P'}} g(Q').
\]
Then we can conclude that $\#_y(P' \times 0^R)=g(P' \times 0^R)$.

The only one remaining case is when $g(P' \times 0^R)=k$.
%Assume for a contradiction that $\#_y(P' \times 0^R)<k$. Then $\#_y(Q') < k$ for every $Q' \in \A^R_{\ell+1}$ extending $P'$.
Using~\eqref{eq:ext2} and~\eqref{eq:ext} we compute
\begin{align*}
  \sum_{\substack{Q' \in \A^R_{\ell+1} \\ \rho_{\ell}(Q')=P'}} \#_y(Q')= {} &
  \sum_{\substack{Q' \in \A^T_{\ell} \\ Q'|_R=P'}} \#_x(Q') \ge
  \sum_{\substack{Q' \in \A^T_{\ell} \\ Q'|_R=P'}} f(Q') \\
  {} \ge {} &
  \sum_{\substack{Q' \in \A^R_{\ell+1} \\ \rho_{\ell}(Q')=P' \\ Q' \neq P' \times 0^R}} g(Q') =
  k + \sum_{\substack{Q' \in \A^R_{\ell+1} \\ \rho_{\ell}(Q')=P' \\ Q' \neq P' \times 0^R}} \#_y(Q').
\end{align*}
This implies $\#_y(P' \times 0^R) \ge k$, as desired.

The case of $Q_\ell = \forall$ is dual to the above.
If $x \in C_f \subseteq \C_\ell$ and $y \in \A_{\ell+1}^{\Z^2}$ is an extension of $x$, then by the Claim the equivalence class $C_g$ of $y$ is an extension of $C_f$.
This implies $C_g \subseteq \C_{\ell+1}$ by the definition of $\C_\ell$, and by the induction hypothesis $y \in X_{\ell+1}$.
Hence $x \in X_\ell$.

For the other direction, if $x \in X_\ell$, then all extensions of $x$ are in $X_{\ell+1} = \C_{\ell+1}$.
Let $C_f$ be the equivalence class of $x$ and $C_g$ a consistent extension of $C_f$; we wish to show that $C_g \subseteq \C_{\ell+1}$.
As in the $Q_\ell = \exists$ case, let $y \in \A_{\ell+1}^{\Z^2}$ be an extension of $x$ such that the 1-symbol in $\pi_{\ell+1}(y)$ is in the middle of the pattern $\rho_\ell(Q)$ given by item 2 of the definition of extension.
As before, we can prove $y \in C_g$, and since $y \in X_{\ell+1}= \C_{\ell+1}$, this implies $C_g \subseteq \C_{\ell+1}$ and so $x \in C_\ell$.

%Suppose now that $Q_{\ell}=\forall$. If $x \in X_{\ell}$, then all extensions of $x$ are in $X_{\ell+1}$. By the induction hypothesis, they are also in $\C_{\ell+1}$. Let $C_f$ be the equivalence class of $x$ and $C_g$ a consistent extension of $C_f$. Let $y \in \A_{\ell+1}^{\Z^2}$ be the extension of $x$ with a 1-symbol in a middle of a pattern whose existence is given by the point (2) of $C_g$. We can verify thanks to the same technique as before that $y \in C_g$ and since $y \in \C_{\ell+1}$ then $C_g \subseteq \C_{\ell+1}$. Therefore $x \in C_f \subseteq \C_{\ell}$.

%If $x \in C_f \subseteq \C_{\ell}$, then for all $C_g$ consistent extensions of $C_f$, $C_g \subseteq \C_{\ell+1}$. Let $y \in \A_{\ell+1}^{\Z^2}$ which is an extension of $x$. $y \in C_g$ where $C_g$ is a consistent extension of $C_f$ by Claim~\ref{cl:extension}, so $y \in \C_{\ell+1}$ and then in $X_{\ell+1}$ by induction hypothesis. We have $x \in X_{\ell}$.

We conclude that $X_{\phi}=\C_0$.
This construction is computable, since there is only a finite number of $\sim_{(n,k)}$-equivalence classes for each $n$, $k$ and alphabet $\A_\ell$.
\end{proof}

\begin{proof}[of Lemma \ref{mfoin}]
    Let $\phi$ be a first order formula.
  Using Lemma \ref{equivclass} we can compute $n, k \in \N$ and disjoint $\sim_{(n,k)}$-equivalence classes $C_1, \ldots, C_r$ such that $X_{\phi}=\bigcup_{i=1}^r C_i$. We want to prove that knowing whether $\bigcup_{i=1}^r C_i$ is closed is $\Pi^0_4$.

  For a $\sim_{(n,k)}$-equivalence class $C=\iC{\A}$, define the function $f_C : \A^{n^2} \to \{0, \ldots, k\}$ by $f_C(P)=a_P$.
  A \emph{map} of $C$ is a function $M: \A^{n^2} \rightarrow \Pe_{\mathrm{fin}}(\Z^2)$. % such that $|M(P)| \le f_C(P)$ for all $P$.
  For $\ell \in \N$ and two maps $M_1, M_2$ of $C$, we say that $(C,\ell,M_1,M_2)$ \emph{tiles the plane} if there exists $x \in \A^{\Z^2}$ such that for each $P \in \A^{n^2}$:
\begin{itemize}
    \item if $f_C(P) < k$, then the pattern $P$ appears at positions $M_1(P) \cup M_2(P)$ and no other positions,
    \item if $f_C(P) = k$, then the pattern $P$ appears on positions $M_1(P) \cup M_2(P)$ (with $|M_1(P) \cup M_2(P)|\ge k$), and if $|M_1(P)|<k$, the only positions of $[-\ell,\ell-1]^2$ at which $P$ appears are in $M_1(P)$.
    \end{itemize}
    To decide whether a given quadruple tiles the plane is $\Pi^0_1$.
    Namely, by compactness, it is equivalent to the condition that for all $m \geq L$, where $L$ is the maximum of $\ell$ and $\| \vec v \|_\infty + n$ for $P \in \A^{n^2}$ and $\vec v \in M_1(P) \cup M_2(P)$, there exists a finite pattern $Q \in \A^{[-m,m]^2}$ that satisfies the two conditions above.
    The configuration $x$ exists as a limit point of such patterns.

  Now let us consider the following arithmetical formula $F$:
  there exist $m \in \N$, an index $i \in \{1, \ldots, r\}$ and two functions $I_1, I_2 : \A^{n^2} \to \{0, \ldots, k\}$ such that $I_1 + I_2 = f_{C_i}$, and
  for all $\ell > m$ there exist two maps $M_1, M_2$ of $C_i$ such that
  \begin{itemize}
  \item $|M_j(P)| = I_j(P)$ for each $j = 1,2$ and $P \in \A^{n^2}$,
  \item $M_1(P) \subseteq [-m,m]^2$ and $M_2(P) \cap [-\ell,\ell-1]^2 =\emptyset$ for each $P \in \A^{n^2}$,
  \item $(C_i,\ell,M_1,M_2)$ tiles the plane, and
  \item there is no $j \in \{1, \ldots, r\}$ such that $(C_j,0,M_1,P \mapsto \emptyset)$ tiles the plane.
  \end{itemize}
  By its form, $F$ is $\Sigma^0_4$.

  We prove that $F$ holds if and only if $\bigcup_{i=1}^r C_i$ is not closed.
  Suppose first that $F$ holds with $m$, $i$, $I_1$ $I_2$ and the maps $M^\ell_1, M^\ell_2$ and tilings $(x_\ell)_{\ell > m}$ they induce. By compactness, we may assume without loss of generality that $x_\ell$ converges to a limit configuration $x \in \A^{\Z^2}$, and that the maps $M^\ell_1 = M_1$ are all equal since their image is contained in $[-m,m]^2$. If $x \in C_j$ for some $j$, then $x$ is a tiling for $(C_j,0,M_1, P \mapsto \emptyset)$, as the positions $\bigcup_{P \in \A^{n^2}} M^\ell_2(P)$ move away from the origin as $\ell$ grows and vanish in the limit. But such a tiling does not exist by the assumption that $F$ holds. Hence we have $x \notin \bigcup_{j=1}^r C_j$, and the set is not closed.

Suppose then that $\bigcup_{i=0}^r C_i$ is not closed. Let $(x_j)_{j \in \N}$ be a sequence of tilings in $\bigcup_{i=0}^r C_i$ such that $x_j \overset{j \rightarrow \infty}{\longrightarrow} x \notin \bigcup_{i=0}^r C_i$. Assume without loss of generality that there is an index $i$ such that $x_j \in C_i$ for all $j$.

Let $m \in \N$ be such that all occurrences of every $n \times n$ pattern which appears less than $k$ times in $x$ are in $[-m,m]^2$. For $P \in \A^{n^2}$, let $I_1(P)$ be the number of occurrences of $P$ in $x$ counted up to $k$, and $I_2(P) = f_{C_i}(P) - I_1(P)$.
%Let $(I_1,I_2)$ be a $C_i$ partition such that $I_1$ gives exactly the patterns in $x$.
Then, given $\ell > m$, we can choose a large $j$ and define $M_1$ and $M_2$ to give the positions of patterns in $x_j$ inside and outside of $[-m,m]^2$, choosing some subsets of positions of sizes $I_1(P)$ and $I_2(P)$ if there are more that that. Doing so, $M_1$ maps only in the square $[-m,m]^2$ and $M_2$ only outside the square $[-\ell,\ell-1]^2$ if $j$ is chosen large enough.

We claim that these choices verify the formula $F$.
The first two items hold by the definition of the $M_j$, and the quadruple $(C_i, \ell, M_1, M_2)$ tiles the plane as witnessed by $x_j$.
Finally, the quadruple $(C_j, 0, M_1, P \mapsto \emptyset)$ does not tile the plane for any $j \in \{1, \ldots, r\}$; if it did, and $y \in \A^{\Z^2}$ was the witness, then necessarily $y \in C_j$ and $y \sim_{(n,k)} x$, implying that $x \in C_j$, a contradiction.
\end{proof}

\begin{proof}[of Lemma \ref{mfohard}]
  We reduce the $\Pi^0_4$-complete problem $\forall COF$: given a Turing Machine $M$ which takes two inputs, does $M(v,\_)$ have a cofinite language for all $v$?
For this, we define an SFT $X$ %(which is definable by a first order formula)
and add on it a first order formula to get a formula $\phi$. Then, we will prove that $M \in \forall COF$ if and only if $\phi \in \MFOSUB$.

Let $M$ be a turing machine. The SFT $X$ is the one described by Figure \ref{fig:mfohard} (the only allowed patterns are those of size $2 \times 2$ in this figure, but other inputs $v$ and $w$ are possible, even the infinite one). %We use standard techniques to simulate $M$ (see Property \ref{computationtiles}).
The input $v$ is copied to the southeast until it hits the gray diagonal signal emitted by the ${*}$-symbol at the end of the second input $w$, where it is erased.
The diagonal turns black after the point of erasure.
%Configurations of $X$ with two finite inputs $x$ and $y$ and a simulated computation are called \emph{classical configurations}.
%but keep in mind that there are many others since it is a subshift.
The machine $M$ is not allowed to halt, so in all configurations containing two finite inputs $v$ and $w$, $M(v,w)$ does not halt. 

Let $\phi'$ be the formula which defines this SFT, and let $\phi=\phi' \land ((\exists x \ \exists y \ P_1(x) \land P_2(y)) \Rightarrow \exists z \ P_3(z))$, where tiles 1, 2 and 3 are showed in Figure \ref{fig:mfohard}). Intuitively, $\phi$ requires the configuration to satisfy $\phi'$, and if there is a diagonal with a finite input $v$ written on it, then there also exists a finite input $w$.

We show that $M \in \forall COF$ if and only if $\phi \in MFOSUB$.
Suppose first $M \notin \forall COF$. We prove that $X_{\phi}$ is not closed. Let $v$ be an input such that for infinitely many inputs $w_1, w_2, w_3, \ldots$ the computation $M(v,w_n)$ does not halt. For each $n$, let $x_n$ be a configuration of $X_{\phi}$ that contains a simulated computation with the inputs $v$ and $w_n$, and the endpoint of the black diagonal line is at the origin. This sequence has a limit configuration $x \in \A^{\Z^2}$, which is not in $X_{\phi}$ since it contains both black and gray diagonal tiles but no $\$$. Hence $X_{\phi}$ is not a subshift.

Now we suppose that $X_{\phi}$ is not a subshift (hence not closed) and prove that $M \notin \forall COF$. Let $(x_n)_{n \in \N}$ be such that $x_n \overset{n \rightarrow \infty}{\longrightarrow} x$ with $x_n \in X_{\phi}$ for all $n$ and $x \notin X_{\phi}$. Notice that the $x_n$ and $x$ are in $X_{\phi'}$ since this set is closed. As $x$ does not satisfy $\phi$, it must have a diagonal with a finite input $v$ on it but no computation tile. For large $n$, all $x_n$ have such a diagonal with the same $v$. But they are in $X_{\phi}$, so they must contain $\$$-symbols, and hence simulated computations. Since $x_n$ converges to $x$, it means that for all $m$, there exists $x_n$ such that the second input $w$ written on it is longer than $n$ symbols. It implies that for infinitely many $w$, $M(v,w)$ does not halt, and so $M \notin \forall COF$.
\end{proof}

