\section{Construction and analysis of a CoSMIC normalizing flow}
\label{apdx:cosmic-details}















\noindent\textbf{\method{} IAF procedure:} Draw reference samples  
\[
   \refvars=(\refvarcoord^{(1)},\dots,\refvarcoord^{(\dmax)})\sim\refdist_{\dmax}.
\]
For a given $\mdl$, define the permutation matrix $P_\mdl$ that groups active coordinates first:
\[
   (\refvars_\mdl,\refvars_{\setminus\mdl}) := P_\mdl \refvars
   \quad\Longrightarrow\quad
   \refvars_\mdl\in\mathbb R^{d_\mdl},\;
   \refvars_{\setminus\mdl}\in\mathbb R^{\setminus d_\mdl},\,\setminus d_\mdl=\dmax-d_\mdl.
\]

Concatenate the coordinate-wise transforms $\indivtransform_{\ap_i}$ into the map $\transform_\vipp$ and bookend with permutations $P_\mdl$ to give the strict \method{} bijection
\[
   T_{\phi}^{(P_m)}(\refvars)
      :=P_m^{-1}\,
        \bigl(\tau_{\rho_{1}^{C(m)}}(\refvars^{(1)})
              ,\cdots,
              \tau_{\rho_{\dmax}^{C(m)}}(\refvars^{(\dmax)})\bigr)
        \,P_m .
\]

\label{apdx:cosmic-proof}










\begin{proof}[Proof of \cref{prop:cosmic-factorisation}]


\smallskip
\noindent
\emph{(a)–(b) Density factorization and marginal consistency.}

\smallskip
We aim to prove \begin{align*}
\text{(a)}&\quad\satvipq^{(P_\mdl)}(\cvars,\auxvars_{\setminus\mdl}\mid\mdl)
   \;=\;
   q_\vipp (\cvars\mid\mdl)\;
   \refdist_{d_{\setminus\mdl}}\!\bigl(\auxvars_{\setminus\mdl}\bigr),\\
\quad
\text{and so (b)}&\quad
\int \satvipq^{(P_\mdl)}(\cvars,\auxvars_{\setminus\mdl}\mid\mdl)\,
      d\auxvars_{\setminus\mdl}
   = q_\vipp (\cvars\mid\mdl).
\end{align*}
Write $\transform_{\phi}^{(P_\mdl),-1}=(\transform_{\vipp,\mdl}^{-1},\operatorname{Id})$, where $\operatorname{Id}$ denotes the identity transform, and let the permuted reference vector be
$P_\mdl\refvars=(\refvars_\mdl,\refvars_{\setminus\mdl})
                 \in\mathbb{R}^{\dmdl}\times\mathbb{R}^{d_{\setminus\mdl}}$.
Because the masking function $\ctm$ sets every transform
$\indivtransform_{\ap_i}$ with $\ctm_i(\mdl)=0$ to the identity,
the inverse flow splits as
\[
\transform_{\vipp}^{(P_\mdl),-1}(\cvars,\auxvars_{\setminus\mdl})
   \;=\;
   \bigl(
        \transform_{\vipp,\mdl}^{-1}(\cvars),
        \;\auxvars_{\setminus\mdl}
    \bigr),
\]
where
$\transform_{\vipp,\mdl}^{-1}: \Theta_\mdl\to\mathbb{R}^{\dmdl}$
is the active block and the dummy block is exactly the identity.
Consequently, the Jacobian matrix of
$\transform_{\vipp}^{(P_\mdl),-1}$ is block upper‑triangular with
\(
\det\nabla\transform_{\vipp}^{(P_\mdl),-1}
  = \det\nabla\transform_{\vipp,\mdl}^{-1}\times 1.
\)



Apply change‑of‑variables with
$\refdist_{\dmax}=\refdist_{d_m}\otimes\refdist_{\setminus d_m}$ to obtain
\[
\begin{aligned}
\satvipq^{(P_\mdl)}(\cvars,\auxvars_{\setminus\mdl}\!\mid\!\mdl)
 &=
 \refdist_{\dmax}\!\bigl(
     \transform_{\vipp}^{(P_\mdl),-1}(\cvars,\auxvars_{\setminus\mdl})
 \bigr)
 \bigl|\det\nabla\transform_{\vipp}^{(P_\mdl),-1}\bigr|
\\
 &=
 \refdist_{\dmdl}\!\bigl(
     \transform_{\vipp,m}^{-1}(\cvars)
 \bigr)
 \,\refdist_{d_{\setminus\mdl}}(\auxvars_{\setminus\mdl})\,
 \bigl|\det\nabla\transform_{\vipp,m}^{-1}(\cvars)\bigr|
\\
 &=
 q_{\vipp}(\cvars\!\mid\!\mdl)\;
 \refdist_{d_{\setminus\mdl}}(\auxvars_{\setminus\mdl}),
\end{aligned}
\]
which proves the factorization (a).




Integrating the right‑hand side over
$\auxvars_{\setminus\mdl}$ recovers (b)
$q_{\vipp}(\cvars\!\mid\!\mdl)$, completing the proof.\end{proof}



\label{apdx:cancellation-proof}

\begin{proof}[Proof of \cref{prop:cancellation}]
It is sufficient to show $\dkl(\tilde{q}_{\vimkp,\vipp}||\sattargetunnorm) = \dkl(q_{\vimkp,\vipp}||\targetunnorm) := \mc{L}(\vimkp,\vipp)$. Note by \eqref{eq:saturatedtarget}, $\sattargetunnorm(\mdl,\cvars,\auxvars_{\setminus\mdl})=\prior(\mdl)\sattargetunnorm(\cvars, \auxvars_{\setminus\mdl}\mid\mdl)=\prior(\mdl)\targetunnorm(\cvars\mid\mdl)\refdist_{d_{\setminus\mdl}}(\auxvars_{\setminus\mdl})$.
\[
\begin{aligned}
    \dkl(\tilde{q}_{\vimkp,\vipp}||\sattarget)
    &= \Ex_{\mdl\sim\vimkq}\left[
            \Ex_{(\cvars,\auxvars_{\setminus\mdl})\sim\satvipq}\left[
                \log\left(
                    \dfrac
                        {\vimkq(\mdl)\satvipq(\cvars,\auxvars_{\setminus\mdl}\mid\mdl)}
                        {\prior(\mdl)\sattargetunnorm(\cvars,\auxvars_{\setminus\mdl}\mid\mdl)}
                \right)
            \right]
        \right] \\
        &= \Ex_{\mdl\sim\vimkq}\left[
            \Ex_{(\cvars,\auxvars_{\setminus\mdl})\sim\satvipq}\left[
                \log\left(
                    \dfrac
                        {\satvipq(\cvars,\auxvars_{\setminus\mdl}\mid\mdl)}
                        {\sattargetunnorm(\cvars,\auxvars_{\setminus\mdl}\mid\mdl)}
                \right)
            \right]
            +\log\left(\vimkq(\mdl)\right) - \log\left(\prior(\mdl)\right)
        \right]\\
        &= \Ex_{\mdl\sim\vimkq}\left[
        \log\left(\vimkq(\mdl)\right) - \log\left(\prior(\mdl)\right)
        \right]+\\
        &\quad
        \Ex_{\mdl\sim\vimkq}\left[
            \Ex_{\refvars\sim\refdist_{\dmax}}\left[
                \log\left(
                    \dfrac
                        {\refdist_{d_\mdl}(\refvars_{d_\mdl})\cancel{\refdist_{d_{\setminus\mdl}}(\refvars_{\setminus\mdl})}|\det \nabla\transform_\vipp (\refvars)|^{-1}}
                        {\targetunnorm(\cvars\mid\mdl)\cancel{\refdist_{d_{\setminus\mdl}}(\auxvars_{\setminus\mdl})}}
                \right)
            \right]
        \right]\,\,\text{by Proposition \ref{prop:cosmic-factorisation}}\\  
        &=   \dkl(q_{\vimkp,\vipp}||\target) \\
        &= \mc{L}(\vimkp,\vipp).
\end{aligned}
\]
\end{proof}

\subsection{\method{} IAF computational complexity}\label{apdx:cosmic-complexity}
\begin{corollary}[Computational complexity]
\smallskip
\noindent
\begin{itemize}
      \item \emph{Sampling (forward IAF)}:
            all coordinates can be updated in parallel
            $\;\Rightarrow\;$ $\mc{O}(1)$ wall‑time depth.
      \item \emph{Evaluation (inverse direction)}:
            must populate $\refvars^{(<i)}$ sequentially
            $\;\Rightarrow\;$ $\mc{O}(\dmax)$ arithmetic operations,
            identical to a standard IAF.
      \end{itemize}
\end{corollary}
\begin{proof}
    The forward IAF updates $\theta_m$ via closed‑form $\tau_i$
that read \emph{previous outputs}—all available after one pass through
the network— which are thereby fully parallelizable.
Conversely, evaluating $T_{\phi}^{(m),-1}$ at an arbitrary point in
$\Theta_m\times\mathcal M$ must reconstruct $z$ sequentially,
exactly as for any IAF, giving $O(d_{\max})$ time.
\end{proof}

\subsection{Experimental \method{} transform compositions}
\label{apdx:flowarchitecture}

\newcommand{\mdlrevperm}{P_{<d_\mdl}^{\operatorname{rev}}}

The experiments use the below compositions of transforms as inverse autoregressive flows $\transform_\vipp(\refvars\mid\mdl)$ where $\refvars$ are the inputs from the reference distribution and $\mdl$ is the context input. All compositions except for the diagonal Gaussian are assumed to have the strict left-right permutations discussed in~\cref{apdx:cosmic-details}. The term ``block'' is defined in \cref{apdx:madedefinitions}.

\paragraph{Context encoder:} Experiments will sometimes use a context encoder that projects the context input to a higher dimensional space. Typically this will take the form of a multi-layered perceptron with hidden layers of increasing size (fixed to powers of 2) and terminating in an activation layer at the largest size, say $2^{12}$ nodes.

\paragraph{Model-specific reverse-permutation:} Flow compositions commonly include reverse permutations to ensure expressibility of an autoregressive-NN-based flow is (approximately) the same for all coordinates. Denoting the generic reverse permutation for all coordinates as $P^{\operatorname{rev}}$, we assume the strict left-right permutation $P_\mdl$ (as per \cref{apdx:cosmic-details}) has been applied, and hence define the left-most $d_\mdl$-coordinate reverse permutation $\mdlrevperm$.

\newcommand{\TMAF}[1]{\transform_{\vipp_{#1}}^{\operatorname{Affine}}}
\newcommand{\TRQSMAF}[1]{\transform_{\vipp_{#1}}^{\operatorname{RQ-Spline}}}

\paragraph{Affine(5,5):} The learned component is the affine masked autoregressive transform~\citep{PapamakariosMasked2017}, denoted here as $\TMAF{k}$ for transforms $k=1,\dots,5$, each having 5 blocks. We set $\transform_\vipp:=\TMAF{5}\circ\mdlrevperm\circ\dots\circ\mdlrevperm\circ\TMAF{1}$.

\paragraph{Spline(4,6):} The learned component is the rational quadratic spline masked autoregressive flow architecture \citep{Durkan2019Neural}, denoted here as $\TRQSMAF{k}$. Each $\TRQSMAF{k}$ has 6 blocks. Additionally, we define a fixed global affine  transform $\transform_{\mu_g,\sigma_g}$ that is not dependent on inputs nor context and hence has only two learnable parameters: scale $\mu_g$ and shift $\sigma_g$. We set $\transform_\vipp:=\transform_{\mu_g,\sigma_g}\circ\TRQSMAF{5}\circ\mdlrevperm\circ\dots\circ\mdlrevperm\circ\TRQSMAF{1}$.

\subsection{Autoregressive flow definitions}\label{apdx:madedefinitions}
\newcommand{\madearchinputs}{\mathbf{x}}
\newcommand{\madearchcontext}{\mathbf{z}}
\newcommand{\madearchfeatures}{d}
\newcommand{\madearchactivation}{\sigma}
\newcommand{\madearchdropout}{\mathrm{Dropout}}
\newcommand{\madearchBN}{\mathrm{BN}}
\newcommand{\madearchmaskedlinear}{\mathrm{MaskedLinear}}
\newcommand{\madearchblockoutput}{\mathbf{h}}

We use the residual variant of the Masked Autoencoder for Distribution Estimation (MADE) \citep{GermainMADE2015}, implemented in PyTorch by \citep{Durkan2020Nflows}. Each block maintains the autoregressive property by assigning degrees \(\{1, \dots, \madearchfeatures\}\) to inputs and propagating them forward.

Given input $\madearchinputs\in\mathbb{R}^{\madearchfeatures}$ and optional context $\madearchcontext$, each residual block computes:
\[
\begin{aligned}
\madearchblockoutput &= \madearchinputs + \madearchmaskedlinear_2\left(
    \madearchactivation\left(
      \madearchBN_2\left(
        \madearchmaskedlinear_1\left(
          \madearchactivation\left(
            \madearchBN_1(\madearchinputs)
          \right)
        \right) + \delta(\madearchcontext)
      \right)
    \right)
  \right).
\end{aligned}
\]
Here, \(\madearchmaskedlinear_i\) are masked linear layers respecting the autoregressive structure, \(\madearchBN_i\) are optional batch norm layers, and \(\delta(\madearchcontext)\) is an optional context projection. All layers preserve feature dimensionality and respect degree ordering to ensure autoregressive validity.








 \newpage\section{Theoretical analysis of the model weights distribution}\label{apdx:theoreticalanalysis}
We consider the following bi-level stochastic optimization problem over a function $\objective: \mdlspace \times \vpspace \to \sR$ as:
\begin{equation}
    \vipp^* \in \argmax_{\vipp \in \vpspace} \max_{\vim_\objective \in \pspace(\mdlspace)} \Ex_{\mdl \sim \vim} [\objective(\mdl, \vipp) + \log\prior(\mdl)] + \entropy[\vim_\objective] = \argmax_{\vipp\in\vpspace} \Ex_{\mdl \sim \vim_{\objective,\vipp}^*}[\objective(\mdl, \vipp) + \log\prior(\mdl)]\,,
    \label{eq:prob-general}
\end{equation}
where $\pspace(\mdlspace)$ denotes the space of probability measures over $\mdlspace$, $\entropy$ is the entropy, and the optimal $\vim_\objective$ for a given $\vipp$ can be shown to be:
\begin{equation}
    \vim_{\objective,\vipp}^*(\mdl) := \frac{\prior(\mdl) \exp \objective(\mdl,\vipp)}{\sum_{\mdl'\in \mdlspace} \prior(\mdl') \exp \objective(\mdl', \vipp)}\,, \quad \mdl \in \mdlspace\,.
\end{equation}
This formulation corresponds to a stochastic optimization problem over two variables $\vipp$ and $\vim_\objective$, where the optimum for $\vim_\objective$ has a closed-form expression $\vim_{\objective,\vipp}^*$ for every given $\vipp\in\vpspace$. To solve this problem, we will follow a sequential optimization process over $\vipp$ (e.g., stochastic gradient descent).
However, sampling from the optimal model distribution $\vim_{\objective,\vipp}^*$ (above) requires evaluating the summation in the normalization constant, which is expensive. 
Therefore, we will instead approximate each $\vim_{\objective, \vipp_\iterIdx}^*$ with a distribution $\vim_{\ucb, \iterIdx}$ composed of a cheaper-to-evaluate surrogate $\ucb_\iterIdx$ based on noisy observations $\observation_{\iterIdx-1, i} = \observable(\refvars_i, \mdl_i, \vipp_{\iterIdx-1})$, where $\refvars_i\sim\refdist$ and $\mdl_i \sim \vim_{\ucb, \iterIdx-1}$, $i \in \{1, \dots, \nbatch\}$, such that $\Ex_{\refvars\sim\refdist}[\observable(\refvars, \mdl, \vipp)] = \objective(\mdl, \vipp)$.
If we ensure that $\vim_{\ucb, \iterIdx}$ approaches $\vim_{\objective, \vipp_\iterIdx}^*$ over time, optimization steps based on $\vim_{\ucb, \iterIdx}$ will eventually follow $\vim_{\objective, \vipp_\iterIdx}^*$ and allow for the optimum $\vipp^*$ to be reached.

\subsection{Regularity assumptions}
We make the following assumptions about the function $\objective$ and the observation noise.

\begin{assumption}
    \label{a:k-continuous}
    The objective $\objective$ is a sample from a zero-mean Gaussian process prior with a bounded, positive-semidefinite covariance function $\kernel: (\mdlspace \times \vpspace)^2\to\R$, which is continuous over $\vpspace$.
\end{assumption}

The GP assumption allows us to derive closed-form expressions for predictions over $\objective$ and their associated uncertainty. The continuity assumption on $\kernel$ is easily satisfied by most practical covariance functions and ensures that, if $\vipp_\iterIdx$ converges to some $\vipp^*$, GP-based estimates $\objective(\mdl, \vipp^*)$ will also converge for every $\mdl\in\mdlspace$. To model predictions over $\objective$ with closed-form GP updates, we also need Gaussian assumptions about the observation noise, which is given by:
\begin{equation}
    \obsnoise_{\mdl, \vipp} := \observable(\refvars, \mdl, \vipp) - \objective(\mdl, \vipp), \quad \refvars\sim\refdist, \quad \mdl \in \mdlspace, \vipp\in\vpspace\,.
\end{equation}
However, as we will show in our analysis, sub-Gaussian tails are enough for GP modeling, which we formalize next.

\begin{assumption}
    \label{a:sub-g-noise}
    The observation noise is $\sigma_\obsnoise^2$-sub-Gaussian, i.e., given any $\mdl\in\mdlspace$ and $\vipp\in\vpspace$, we have: \begin{equation}
        \forall s\in\sR, \quad \Ex[\exp(s\obsnoise_{\mdl, \vipp})] \leq \exp\left(\frac{1}{2}s^2\sigma_\obsnoise^2\right).
    \end{equation}
\end{assumption}

This mild assumption is satisfied, for example, when $\refdist$ is a zero-mean Gaussian distribution and $\observable$ is Lipschitz continuous on its first argument, in which case $\sigma_\obsnoise$ only depends on $\observable$ through its Lipschitz constant \citep{Boucheron2013, Pisier2016}.




\subsection{Gaussian process model}
Under the GP assumption $\objective\sim\gp(0, \kernel)$, the posterior over $\objective$ is again a Gaussian process. Suppose at each iteration $\iterIdx\geq 1$ of stochastic gradient descent we sample a mini-batch $\{\mdl_{\iterIdx, i}\}_{i=1}^\nbatch$ from a variational posterior approximating $\vim_{\objective, \vipp}^*$ 
at $\vipp = \vipp_{\iterIdx-1}$. Given a batch of observations $\batch_\iterIdx := \{\vipp_{\iterIdx-1}, \mdl_{\iterIdx, i}, \observation_{\iterIdx,i} \}_{i=1}^\nbatch$, the GP posterior $\objective|\batch_{1, \dots, \iterIdx} \sim \gp(\gpMean_\iterIdx, \kernel_\iterIdx)$ has its mean and covariance described by the following recursive equations:
\begin{align}
    \gpMean_\iterIdx(\mdl, \vipp) &= \gpMean_{\iterIdx-1}(\mdl, \vipp) + \vct\kernel_{\iterIdx-1}(\mdl, \vipp)^\transpose(\mKernel_{\iterIdx-1} + \sigma_\obsnoise^2\eye)^{-1}(\vct\observation_\iterIdx - \vct{\gpMean}_{\iterIdx-1})\\
    \kernel_\iterIdx(\mdl, \vipp, \mdl', \vipp') &= \kernel_{\iterIdx-1}(\mdl, \vipp, \mdl',\vipp') - \vct\kernel_{\iterIdx-1}(\mdl, \vipp)^\transpose(\mKernel_{\iterIdx-1} + \sigma_\obsnoise^2\eye)^{-1}\vct\kernel_{\iterIdx-1}(\mdl', \vipp),
\end{align}
where $\vct\kernel_{\iterIdx-1}(\mdl, \vipp) := [\kernel_{\iterIdx-1}(\mdl, \vipp, \mdl_{\iterIdx, i}, \vipp_{\iterIdx-1})]_{i=1}^\nbatch \in \sR^\nbatch$, $\mKernel_{\iterIdx-1} := [\kernel_{\iterIdx-1}(\mdl_{\iterIdx,i}, \vipp_{\iterIdx-1}, \mdl_{\iterIdx,j}, \vipp_{\iterIdx-1})]_{i,j=1}^\nbatch \in \sR^{\nbatch\times\nbatch}$, and $\vct\gpMean_{\iterIdx-1} := [\gpMean_{\iterIdx-1}(\mdl_{\iterIdx,i}, \vipp_{\iterIdx-1})]_{\iterIdx=1}^\nbatch \in \sR^\nbatch$, with $\gpMean_0 = 0$ and $\kernel_0 = \kernel$. Any pointwise prediction is then modeled as $\objective(\mdl, \vipp)|\batch_{1, \dots, \iterIdx} \sim \normal(\gpMean_\iterIdx(\mdl, \vipp), \sigma_\iterIdx^2(\mdl, \vipp))$, where $\sigma_\iterIdx^2(\mdl, \vipp) := \kernel_\iterIdx(\mdl, \vipp, \mdl, \vipp)$, for $(\mdl, \vipp) \in \mdlspace\times\vpspace$.



\subsection{Upper confidence bound (UCB) algorithm}
Given the GP posterior, we formulate an upper confidence bound algorithm \citep{SrinivasGaussian2010} with:
\begin{equation}
    \ucb_\iterIdx(\mdl) := \gpMean_\iterIdx(\mdl, \vipp_\iterIdx) + \beta_\iterIdx\sigma_\iterIdx(\mdl, \vipp_\iterIdx), \quad \mdl \in \mdlspace\,,
\end{equation}
where $\beta_\iterIdx > 0$ is a parameter controlling the size of the confidence bound, which we will discuss in our analysis.
We then derive a sampling distribution based on using the UCB as a surrogate for $\objective$ as:
\begin{equation}
    \vim_{\ucb, \iterIdx} \in \argmax_{\vim \in \pspace(\mdlspace)}  \Ex_{\mdl\sim\vim}[\ucb_\iterIdx(\mdl) + \log \prior(\mdl) - \log \vim(\mdl)]\,.
\end{equation}
The solution to this optimization is available in closed form as the UCB softmax:
\begin{equation}
    \vim_{\ucb, \iterIdx}(\mdl) = \frac{\prior(\mdl) \exp \ucb_\iterIdx(\mdl)}{\sum_{\mdl'\in\mdlspace} \prior(\mdl') \exp\ucb_\iterIdx(\mdl')}, \quad \mdl\in\mdlspace\,.
\end{equation}
Equipped with this UCB-based sampling distribution, we follow the generic procedure outlined in \autoref{alg:ucb}. The algorithm starts by sampling from the current UCB distribution. A sample-based estimate of the optimization objective $\Ex_{\mdl\sim\vipp_\iterIdx}[\objective(\mdl, \vipp_{\iterIdx-1})] \approx \frac{1}{\nbatch} \sum_{i=1}^\nbatch \observable(\refvars_{\iterIdx, i}, \mdl_{\iterIdx,i}, \vipp_{\iterIdx-1})$ is then passed to the algorithm responsible for updating the parameters $\vipp_\iterIdx$, e.g., a stochastic gradient descent update.
Once the parameters are updated, we reevaluate the objective and update our GP. The procedure then repeats up to a given number of iterations $\nIterations \in \sN$.

\begin{algorithm}[t]
    \caption{Stochastic optimization with UCB sampling}
    \label{alg:ucb}
    \begin{algorithmic}
        \FOR{$\iterIdx\in\{1,\dots,\nIterations\}$}
\STATE $\{\mdl_{\iterIdx, i}\}_{i=1}^\nbatch \sim \vim_{\ucb, \iterIdx-1}$
           \STATE $\{\refvars_{\iterIdx, i}\}_{i=1}^\nbatch \sim \refdist$
\STATE $\observation_{\iterIdx, i} = \observable(\refvars_{\iterIdx, i}, \mdl_{\iterIdx, i}, \vipp_{\iterIdx-1})$, for $i \in \{1, \dots, \nbatch\}$
           \STATE $\vipp_{\iterIdx} \leftarrow$ \textsc{UpdateParameters}$\left(\vipp_{\iterIdx-1}, \{\observable(\refvars_{\iterIdx, i}, \mdl_{\iterIdx,i}, \vipp_{\iterIdx-1})\}_{i=1}^\nbatch, \vim_{\ucb,\iterIdx-1} \right)$
           \STATE $\gpMean_\iterIdx, \kernel_\iterIdx \leftarrow$ \textsc{UpdateSurrogate}$(\{\mdl_{\iterIdx, i}, \observation_{\iterIdx, i}\}_{i=1}^\nbatch, \vipp_{\iterIdx-1}, \gpMean_{\iterIdx-1}, \kernel_{\iterIdx-1})$
        \ENDFOR
    \end{algorithmic}
\end{algorithm}
















\subsection{Approximation errors under sub-Gaussian noise}
In the following, we derive generic concentration bounds for GP predictions under sub-Gaussian observation noise. We start by showing that the approximation error between the GP mean and the true function is sub-Gaussian.
\begin{lemma}
    \label{thr:sub-g-process}
    Let $\objective \sim \gp(0, \kernel)$ be a zero-mean Gaussian process with a given positive-definite covariance function $\kernel: \domain \times \domain \to \sR$. Assume we are given a sequence of observations $\observation_\obsIdx = \objective(\location_\obsIdx) + \obsnoise_\obsIdx$, where $\location_\obsIdx \in \domain$ and $\obsnoise_\obsIdx$ is $\sigma_\obsnoise^2$-sub-Gaussian noise, for all $\obsIdx \in \sN$. Let $\gpMean_\obsIdx$ and $\sigma_\obsIdx^2$ denote the predictive mean and variance, respectively, of the GP posterior under the assumption that the noise is zero-mean Gaussian with variance given by $\sigma_\obsnoise^2$. Then, for all $\obsIdx\geq 0$ and all $\location\in\domain$, we have that $\objective(\location) - \gpMean_\obsIdx(\location)$ is $\sigma_\obsIdx^2(\location)$-sub-Gaussian.
\end{lemma}
\begin{proof}For $\obsIdx=0$, the proof is trivial as, without observations, we only have the prior with $\gpMean_0(\location) = 0$ and $\sigma_0^2(\location) = \kernel(\location,\location)$. Now let $\locations_\obsIdx := \{\location_i\}_{i=1}^\obsIdx \subset\domain$ denote a set of $\obsIdx \geq 1$ observed locations. For any given $\location\in\domain$, expanding the GP posterior mean from its definition, the approximation error can be decomposed as:
	\begin{equation}
		\begin{split}
			\Delta_\obsIdx(\location) := \objective(\location) - \gpMean_\obsIdx(\location) &= \objective(\location) - \kernel(\location, \locations_\obsIdx)(\Kernel_\obsIdx + \sigma_\obsnoise^2\eye)^{-1}(\vct\objective_\obsIdx + \vct\obsnoise_\obsIdx)\\
            &= \objective(\location) - \kernel(\location, \locations_\obsIdx)(\Kernel_\obsIdx + \sigma_\obsnoise^2\eye)^{-1}\vct\objective_\obsIdx - \kernel(\location, \locations_\obsIdx)(\Kernel_\obsIdx + \sigma_\obsnoise^2\eye)^{-1}\vct\obsnoise_\obsIdx\,,
		\end{split}
		\label{eq:sub-g-process-approximation-components}
	\end{equation}
    where $\kernel(\location, \locations_\obsIdx) := [\kernel(\location,\location_1), \dots, \kernel(\location,\location_\obsIdx)]$, $\mKernel_\obsIdx := [\kernel(\location_i, \location_j)]_{i,j=1}^\obsIdx$, $\vct\objective_\obsIdx := [\objective(\location_i)]_{i=1}^\obsIdx$, and $\vct\obsnoise_\obsIdx := [\obsnoise_i]_{i=1}^\obsIdx$.
	The last term on the right-hand side above is sub-Gaussian, since $\Ex[\vct\obsnoise_\obsIdx] = 0$ and, letting $\vct \alpha_\obsIdx := (\Kernel_\obsIdx + \sigma_\obsnoise^2\eye)^{-1} \kernel(\locations_\obsIdx, \location)$, we have a sum of independent sub-Gaussian random variables, see e.g.~\citep{Pisier2016}, Lemma 1.1:
\begin{equation}
		\Ex[\exp(\vct\alpha_\obsIdx^\transpose \vct\obsnoise_\obsIdx)] = \Ex\left[\exp\left(\sum_{i=1}^\obsIdx \alpha_{\obsIdx,i}\obsnoise_{\obsIdx,i} \right)\right] = \prod_{i=1}^\obsIdx\Ex[\exp(\alpha_{\obsIdx,i}\obsnoise_{\obsIdx,i})] \leq \exp \left(\frac{1}{2} \sigma_\obsnoise^2\sum_{i=1}^\obsIdx\alpha_{\obsIdx,i}^2\right), \label{eq:sub-g-noise-component}
	\end{equation}
    which follows from the definition of sub-Gaussian noise (cf. \autoref{a:sub-g-noise}).
The remaining term on the right-hand side of \eqref{eq:sub-g-process-approximation-components} is a zero-mean Gaussian random variable with
variance given by:
	\begin{equation}
		\begin{split}
			&\Var[\objective(\location) - \kernel(\location, \locations_\obsIdx)(\Kernel_\obsIdx + \sigma_\obsnoise^2\eye)^{-1}\vct\objective_\obsIdx]\\
			 &= \kernel(\location,\location) - 2 \kernel(\location, \locations_\obsIdx)(\Kernel_\obsIdx + \sigma_\obsnoise^2\eye)^{-1}\kernel(\locations_\obsIdx,\location) +  \kernel(\location, \locations_\obsIdx)(\Kernel_\obsIdx + \sigma_\obsnoise^2\eye)^{-1}\Kernel_\obsIdx(\Kernel_\obsIdx + \sigma_\obsnoise^2\eye)^{-1}\kernel(\locations_\obsIdx,\location)\\
			 &= \kernel(\location,\location)
			 - 2 \kernel(\location, \locations_\obsIdx)(\Kernel_\obsIdx + \sigma_\obsnoise^2\eye)^{-1}\kernel(\locations_\obsIdx,\location)
			 +  \vct\alpha_\obsIdx^\transpose \Kernel_\obsIdx \vct\alpha_\obsIdx\,.\label{eq:sub-g-objective-component}
		\end{split}
	\end{equation}
	   As \eqref{eq:sub-g-process-approximation-components} describes the sum of two independent sub-Gaussian random variables, we can follow similar reasoning to the one applied in \eqref{eq:sub-g-noise-component} to show that $\Delta_\obsIdx(\location)$ is $s_\obsIdx^2(\location)$-sub-Gaussian for some $s_\obsIdx^2(\location) > 0$. The resulting sub-Gaussian parameter $s_\obsIdx^2(\location)$ is then bounded by the sum of the individual sub-Gaussian parameters in equations \ref{eq:sub-g-noise-component} and \ref{eq:sub-g-objective-component} as:
	\begin{equation}
		\begin{split}
			s_\obsIdx^2(\location) &\leq \kernel(\location,\location)
			- 2 \kernel(\location, \locations_\obsIdx)(\Kernel_\obsIdx + \sigma_\obsnoise^2\eye)^{-1}\kernel(\locations_\obsIdx,\location)
			+  \vct\alpha_\obsIdx^\transpose \Kernel_\obsIdx \vct\alpha_\obsIdx
			+ \sigma_\obsnoise^2 \vct\alpha_\obsIdx^\transpose \vct\alpha_\obsIdx\\
            &= \kernel(\location,\location) - 2 \kernel(\location, \locations_\obsIdx)(\Kernel_\obsIdx + \sigma_\obsnoise^2\eye)^{-1}\kernel(\locations_\obsIdx,\location) +  \vct\alpha_\obsIdx^\transpose(\Kernel_\obsIdx+\sigma_\obsnoise^2\eye)\vct\alpha_\obsIdx\\
			&= \kernel(\location,\location) - 2 \kernel(\location, \locations_\obsIdx)(\Kernel_\obsIdx + \sigma_\obsnoise^2\eye)^{-1}\kernel(\locations_\obsIdx,\location) +  \kernel(\location, \locations_\obsIdx)(\Kernel_\obsIdx + \sigma_\obsnoise^2\eye)^{-1}\kernel(\locations_\obsIdx,\location)\\
			&=\kernel(\location,\location) - \kernel(\location, \locations_\obsIdx)(\Kernel_\obsIdx + \sigma_\obsnoise^2\eye)^{-1}\kernel(\locations_\obsIdx,\location)\\
			&= \sigma_\obsIdx^2(\location)\,,
		\end{split}
	\end{equation}
	which concludes the proof.
\end{proof}










\subsection{Convergence guarantees}
Now we apply the error bounds above to the general optimization problem in \eqref{eq:prob-general}.

\begin{assumption}
	\label{a:param-seq}
	The sequence of parameters $\{\vipp_\iterIdx\}_{\iterIdx=1}^\infty$ is a Cauchy sequence, i.e.:
	\begin{equation}
		\forall \stepsize > 0, \quad \exists \nIterations_\stepsize \in \sN:\quad \norm{\vipp_{\iterIdx+1} - \vipp_{\iterIdx}} \leq \stepsize, \quad \forall \iterIdx \geq \nIterations_\stepsize\,.
	\end{equation}
\end{assumption}
The assumption above can be guaranteed by, e.g., diminishing step sizes during (stochastic) gradient descent. It essentially means that $\vipp_\iterIdx$ will converge to some $\hat\vipp\in\vpspace\subseteq\sR^{n_\vipp}$, though not requiring it to be the optimum.

\begin{assumption}
    \label{a:prior}
    The prior $\prior(\mdl)$ has full support over $\mdlspace$. 
\end{assumption}
Such assumption ensures that the prior would not wrongly assign zero probability to plausible models.

\begin{lemma}
	\label{thr:variance-convergence}
	Let assumptions \ref{a:k-continuous} to \ref{a:prior} hold, and set $\beta_\iterIdx= \beta > 0$, for all $\iterIdx\in \{0, 1, 2, \dots\}$. Then the following almost surely holds:
	\begin{equation}
		\sigma_\iterIdx^2(\mdl, \vipp_\iterIdx) \in \bigo(\iterIdx^{-1}), \quad \forall \mdl \in \mdlspace\,.
	\end{equation}
\end{lemma}
\begin{proof}
	Consider the following upper bound on the predictive variance of a GP model \cite[Lem. D.3]{Steinberg2024Variational}:
	\begin{equation}
		\forall \iterIdx\in \sN, \quad \sigma_\iterIdx^2(\mdl, \vipp) \leq \frac{\sigma_\obsnoise^2\sigma_0^2(\mdl, \vipp)}{\sigma_\obsnoise^2 + \sigma_0^2(\mdl,\vipp)\obscount_\iterIdx(\mdl, \vipp)}, \quad \forall (\mdl, \vipp) \in \mdlspace\times\vpspace\,,
		\label{eq:variance-bound}
	\end{equation}
	where $\obscount_\iterIdx(\mdl, \vipp)$ denotes the number of observations collected at $(\mdl, \vipp) \in \mdlspace\times\vpspace$ up to time $\iterIdx\geq 1$. In addition, letting $\history_\iterIdx$ denote the $\sigma$-algebra generated by the history of all random variables measurable at time $\iterIdx$, and setting $\hat\vipp := \lim_{\iterIdx\to\infty} \vipp_\iterIdx$, the second Borel-Cantelli lemma \citep{Dubins1965Sharper} tells us that:\footnote{More precisely, the second Borell-Cantelli lemma tells us the two sides are proportional to each other, while equality holds if the right-hand side diverges.}
	\begin{equation}
		\forall\mdl \in \mdlspace, \quad \lim_{\iterIdx\to\infty} \obscount_\iterIdx(\mdl, \hat\vipp) = \lim_{\iterIdx\to\infty} \sum_{i=1}^\iterIdx \Prob\left[ \mdl_\iterIdx = \mdl \mid \history_{\iterIdx-1} \right]\,.
		\label{eq:count-limit}
	\end{equation}
	Therefore, for $\sigma_\iterIdx^2(\mdl, \hat\vipp)\to 0$, we need the series above to diverge. To ensure the latter, we can show that the conditional probabilities in \cref{eq:cond-probs} have a nonzero lower bound or, if they converge to zero, that they do so slowly enough.

	We now derive a lower bound on the sampling probabilities. First, observe that:
	\begin{equation}
		\forall\iterIdx\in \sN, \quad \Ex\left[\norm{\gpMean_\iterIdx(\cdot, \vipp_\iterIdx)}_\infty\right]
		= \Ex[\norm{\Ex[\objective(\cdot, \vipp_\iterIdx) \mid \history_\iterIdx]}_\infty] 
		\leq \Ex[\Ex[\norm{\objective(\cdot, \vipp)}_\infty \mid \history_\iterIdx ] ],
		\quad \forall \vipp \in \vpspace\,,
	\end{equation}
	where  $\norm{\objective(\cdot, \vipp)}_\infty = \sup_{\mdl\in\mdlspace} |\objective(\mdl, \vipp)|$ denotes the supremum norm of $\objective(\cdot,\vipp)$, and we applied Jensen's inequality in the last step. Since the kernel $\kernel$ is continuous and bounded, the sub-Gaussian parameter $\sigma_\iterIdx^2(\cdot,\vipp_\iterIdx)$ has a maximum in $\mdlspace$, which is finite. As the expected value of the maximum of a finite collection of sub-Gaussian random variables is bounded \cite[see, e.g.,][Thr. 2.5]{Boucheron2013}, it follows that the GP mean $\gpMean_\iterIdx$ is almost surely bounded at all times (by, e.g., Markov's inequality). Considering the model sampling probabilities and that $\prior_{\min} := \min_{\mdl \in \mdlspace} \prior(\mdl) > 0$ by \autoref{a:prior}, we then have that the following almost surely holds:
	\begin{equation}
		\begin{split}
			\forall\iterIdx \geq 0, \quad \Prob\left[ \mdl_{\iterIdx+1}
			= \mdl \mid \history_{\iterIdx} \right] = \vim_{\ucb, {\iterIdx}}(\mdl)
			&\geq \frac{
				\prior_{\min} \exp(-\norm{\gpMean_\iterIdx(\cdot, \vipp_\iterIdx)}_\infty + \beta\sigma_\iterIdx(\mdl, \vipp_\iterIdx))
			}{
				\sum_{\mdl'\in\mdlspace} \exp(\norm{\gpMean_\iterIdx(\cdot, \vipp_\iterIdx)}_\infty + \beta\sigma_\iterIdx(\mdl', \vipp_\iterIdx))
			}\\
			&\geq \frac{
				\prior_{\min} \exp(-2\norm{\gpMean_\iterIdx(\cdot, \vipp_\iterIdx)}_\infty + \beta\sigma_\iterIdx(\mdl, \vipp_\iterIdx))
			}{
				|\mdlspace| \max_{\mdl'\in\mdlspace}\exp(\beta\sigma_\iterIdx(\mdl', \vipp_\iterIdx)) }\,.
		\end{split}
		\label{eq:cond-probs}
	\end{equation}
	As, for every $\mdl\in\mdlspace$, the sequence $\{\sigma_\iterIdx^2(\mdl,\vipp_\iterIdx)\}_{\iterIdx=0}^\infty$ is non-negative and non-increasing, it has a limit by the monotone convergence theorem. 
	Let $\sigma_* :=  \lim_{\iterIdx\to\infty} \max_{\mdl\in\mdlspace}\sigma_\iterIdx(\mdl, \vipp_\iterIdx)$, and let $\mdl_* \in \mdlspace$ be one of the maximizers of $\lim_{\iterIdx\to\infty} \sigma_\iterIdx(\cdot, \vipp_\iterIdx)$. If $\sigma_* > 0$, by \autoref{eq:cond-probs}, we have for $\mdl_*$ that:
	\begin{equation}
		\begin{split}
			\lim_{\iterIdx\to\infty} \Prob\left[ \mdl_{\iterIdx+1} = \mdl_* \mid \history_{\iterIdx} \right]
			&\geq
			\lim_{\iterIdx\to\infty} 
			\frac{
				\prior_{\min} \exp(-2\norm{\gpMean_\iterIdx(\cdot, \vipp_\iterIdx)}_\infty+\beta\sigma_\iterIdx(\mdl_*, \vipp_\iterIdx))
			}{
				|\mdlspace| \max_{\mdl\in\mdlspace}\exp(\beta\sigma_\iterIdx(\mdl, \vipp_\iterIdx))
			}\\
			&= 
			\lim_{\iterIdx\to\infty} 
			\frac{
				\prior_{\min} \exp(-2\norm{\gpMean_\iterIdx(\cdot, \vipp_\iterIdx)}_\infty+\beta\sigma_*)
			}{
				|\mdlspace| \exp(\beta\sigma_*)
			}\\
			&=
			\lim_{\iterIdx\to\infty} \frac{\prior_{\min} \exp(-2\norm{\gpMean_\iterIdx(\cdot, \vipp_\iterIdx)}_\infty)}{|\mdlspace|}\\
			&\geq \frac{\prior_{\min} \exp(-2\Ex[\norm{\objective(\cdot, \hat\vipp)}_\infty \mid \history_\infty])}{|\mdlspace|}\\
			&=: \bound_\mdl > 0\,,
		\end{split}
		\label{eq:cond-probs-lb}
	\end{equation}
	which implies $\obscount_\iterIdx(\mdl_*, \hat\vipp)\to\infty$ by \autoref{eq:count-limit}. However, in that case, we must have $\sigma_*^2 = \lim_{\iterIdx\to\infty} \sigma_\iterIdx^2(\mdl_*, \vipp_\iterIdx) = 0$ by \autoref{eq:variance-bound}, which is a contradiction. Therefore, $\sigma_* = 0$, and consequently $\lim_{\iterIdx\to\infty} \sigma_\iterIdx(\mdl, \vipp_\iterIdx) \leq \sigma_* = 0$, for all $\mdl\in\mdlspace$.

	Finally, we show that $\sigma_\iterIdx^2(\cdot,\vipp_\iterIdx)\in\bigo(\iterIdx^{-1})$. As we have seen that $\lim_{\iterIdx\to\infty} \sigma_\iterIdx(\cdot, \vipp_\iterIdx) = 0$ above, applying the limit to \eqref{eq:cond-probs}, we see that $\Prob\left[ \mdl_\iterIdx = \mdl \mid \history_{\iterIdx-1} \right] \to \bound_\mdl > 0$,  for each $\mdl\in\mdlspace$. Hence, $\obscount_\iterIdx(\mdl,\vipp_\iterIdx)^{-1} \in \bigo(\iterIdx^{-1})$, implying that $\sigma_\iterIdx^2(\cdot, \vipp_\iterIdx)$ is $\mc{O}(\iterIdx^{-1})$ asymptotically by \autoref{eq:count-limit}, which concludes the proof.
\end{proof}

\begin{theorem}
    \label{thr:kl-bound}
Under the assumptions in \cref{thr:variance-convergence}, we have that the following holds in probability: \begin{equation}
        \dkl(\vim_{\ucb, \iterIdx} || \vim_{\objective, \vipp_\iterIdx}^*) \in \bigo_{\Prob}(\iterIdx^{-1/2})\,, \end{equation}
    where for a stochastic process $\{\xi_\iterIdx\}_{\iterIdx\in\sN}$, denoting $\xi_\iterIdx \in \bigo_{\Prob}(\anyfunction(\iterIdx))$, for a positive function $\anyfunction:\sN\to(0,\infty)$, means that:
    \begin{equation}
    	\forall \varepsilon > 0, \quad \exists \anyconstant_\varepsilon \in (0, \infty), \obscount_\varepsilon\in\sN: \quad \Prob\left[\frac{|\xi_\iterIdx|}{\anyfunction(\iterIdx)} > \anyconstant_\varepsilon\right] \leq \varepsilon, \quad \forall \iterIdx \geq \obscount_\varepsilon\,,
    \end{equation}
    or equivalently that:
    \begin{equation}
    	\lim_{\anyconstant\to\infty} \limsup_{\iterIdx\to\infty} \Prob\left[\frac{|\xi_\iterIdx|}{\anyfunction(\iterIdx)} > \anyconstant\right] = 0\,.
    \end{equation}
\end{theorem}
\begin{proof}
Expanding from the definition of the KL divergence and the variational distributions, we have that:
    \begin{equation}
    	\begin{split}
    		 \iterIdx\geq 0, \quad \dkl(\vim_{\ucb, \iterIdx} || \vim_{\objective, \vipp_\iterIdx}^*) &= \Ex_{\mdl\sim\vim_{\ucb, \iterIdx}}\left[\log \vim_{\ucb, \iterIdx}(\mdl) - \log \vim_{\objective,\vipp_\iterIdx}^*(\mdl)\right]\\
    		 &=\Ex_{\mdl\sim\vim_{\ucb, \iterIdx}} [ \ucb_\iterIdx(\mdl) - \objective(\mdl, \vipp_\iterIdx) ]\\
             &\quad + \log \left(\sum_{\mdl'\in\mdlspace}  \prior(\mdl') \exp \objective(\mdl', \vipp_\iterIdx) \right) - \log \left(\sum_{\mdl'\in\mdlspace}  \prior(\mdl') \exp \ucb_\iterIdx(\mdl') \right) \,.
    		 \label{eq:kl-error-expansion}
    	\end{split}
    \end{equation}
    Under assumptions \ref{a:k-continuous} and \ref{a:sub-g-noise}, given any $\beta>0$, applying standard sub-Gaussian concentration results \citep{Boucheron2013} and a union bound, we have that, for all $\iterIdx\geq 0$:
    \begin{equation}
    	\begin{split}
	    	\Prob[ \exists \mdl\in\mdlspace:\:|\objective(\mdl, \vipp_\iterIdx) - \gpMean_\iterIdx(\mdl, \vipp_\iterIdx)| > \beta\sigma_\iterIdx(\mdl, \vipp_\iterIdx) ]
	    	&\leq \sum_{\mdl\in\mdlspace} \Prob[|\objective(\mdl, \vipp_\iterIdx) - \gpMean_\iterIdx(\mdl, \vipp_\iterIdx)| > \beta\sigma_\iterIdx(\mdl, \vipp_\iterIdx)]\\
	    	&\leq 2|\mdlspace|\exp\left(-\frac{\beta^2}{2}\right)\\
	    	&=: \delta_\beta\,.
	    \end{split}
    \end{equation}
    With probability at least $1-\delta_\beta$, it then follows that:
    \begin{align}
    	 \ucb_\iterIdx(\mdl) - \objective(\mdl, \vipp_\iterIdx) = \gpMean_\iterIdx(\mdl, \vipp_\iterIdx) + \beta\sigma_\iterIdx(\mdl, \vipp_\iterIdx) - \objective(\mdl, \vipp_\iterIdx) &\leq 2\beta\sigma_\iterIdx(\mdl,\vipp_\iterIdx)\\
    	 \log \left(\sum_{\mdl'\in\mdlspace}  \prior(\mdl') \exp \objective(\mdl', \vipp_\iterIdx) \right) - \log \left(\sum_{\mdl'\in\mdlspace}  \prior(\mdl') \exp \ucb_\iterIdx(\mdl') \right) &\leq 0
	\end{align}
    for all $\mdl\in\mdlspace$. Hence, with the same probability, it holds that:
    \begin{equation}
    	\forall\iterIdx\geq 0, \quad \dkl(\vim_{\ucb, \iterIdx} || \vim_{\objective, \vipp_\iterIdx}^*) \leq 2\beta \Ex_{\mdl\sim\vim_{\ucb,\iterIdx}}[\sigma_\iterIdx(\mdl, \vipp_\iterIdx)] \leq 2\beta \norm{\sigma_\iterIdx(\cdot, \vipp_\iterIdx)}_\infty\,.
    \end{equation}
    By \cref{thr:variance-convergence}, we know that $\sigma_\iterIdx(\mdl, \vipp_\iterIdx) \in \bigo(\iterIdx^{-1/2})$, so that there exists $\anyconstant > 0$ such that $\sigma_\iterIdx(\mdl, \vipp_\iterIdx) \leq \anyconstant\iterIdx^{-1/2}$, for all $\mdl\in\mdlspace$. We then have that:
    \begin{equation}
    	\begin{split}
    		\lim_{\beta\to\infty} \limsup_{\iterIdx\to\infty} \Prob\left[\frac{\dkl(\vim_{\ucb, \iterIdx} || \vim_{\objective, \vipp_\iterIdx}^*)}{\anyconstant\iterIdx^{-1/2}} > 2\beta\right] &\leq \lim_{\beta\to\infty} \limsup_{\iterIdx\to\infty}\Prob\left[\dkl(\vim_{\ucb, \iterIdx} || \vim_{\objective, \vipp_\iterIdx}^*) > 2\beta\norm{\sigma_\iterIdx(\cdot, \vipp_\iterIdx)}_\infty\right]\\
    		&\leq \lim_{\beta\to\infty} 2|\mdlspace|\exp\left(-\frac{\beta^2}{2}\right) = 0\,,
    	\end{split}
    \end{equation}
    which concludes the proof.
\end{proof}
















 \newpage\section{Proof of bijective equivalence between discrete distributions}\label{apdx:categoricaldiscreteproof}
\begin{proof}[Proof of \cref{prop:unique_categorical_representation}]
    Let \( \mathcal{P} \) denote the set of all finite discrete distributions over \( \mdlspace \), and let \( \mathcal{C} \) denote the set of categorical distributions parameterized by \( \boldsymbol{\theta} \).

    \textbf{Injectivity:} Suppose \( \boldsymbol{\theta} \) and \( \boldsymbol{\phi} \) are two distinct probability vectors in \( \mathcal{C} \). Then, there exists at least one index \( i \) such that \( \theta_i \neq \phi_i \). Consequently, the corresponding distributions assign different probabilities to \( \mdl_i \), implying \( \boldsymbol{\theta} \neq \boldsymbol{\phi} \).

    \textbf{Surjectivity:} For any finite discrete distribution \( \mathbf{p} \in \mathcal{P} \), define \( \boldsymbol{\theta} = \mathbf{p} \). Since \( \mathbf{p} \) satisfies \( \theta_i \geq 0 \) and \( \sum_{i=1}^{k} \theta_i = 1 \), \( \boldsymbol{\theta} \) is a valid parameterization in \( \mathcal{C} \). Thus, every \( \mathbf{p} \) corresponds to some \( \boldsymbol{\theta} \).

    Since the mapping is both injective and surjective, it is bijective. Therefore, every finite discrete distribution has a unique categorical distribution representation.
\end{proof} \newpage\section{Monte Carlo gradients via score function estimation}\label{apdx:mcgsfe}


An alternative to the reparameterization trick is the score function estimator (SFE), which circumvents the issue of non-differentiable samples from discrete distributions by using the log trick to compute the gradients of a function with respect to variational parameters. In the case of the distribution of models, we have the identity
\begin{align}
    \nabla_{\vimkp}q_{\vimkp}(\mdl) = q_{\vimkp}(\mdl) \nabla_{\vimkp}\log q_{\vimkp}(\mdl).
\end{align}
By the Leibniz integral rule, the gradient of the expectation in \eqref{eq:varloss_by_mixture} with respect to the parameters of the discrete distribution is
\begin{align*}
    \nabla_\vimkp \mc{L}(\vipp,\vimkp)
    &=
    \nabla_\vimkp \Ex_{\mdl\sim\vimkq}
            \left[\ell(\mdl) \right] +
    \nabla_\vimkp\Ex_{\mdl\sim\vimkq}\left[\log\dfrac{q_\vimkp(\mdl)}{\prior(\mdl)}\right]\\
    &=
    \Ex_{\mdl\sim\vimkq}
            \left[ \ell(\mdl) \nabla_\vimkp \log\vimkq(\mdl) \right]
    +
    \Ex_{\mdl\sim\vimkq}\left[\log\dfrac{q_\vimkp(\mdl)}{\prior(\mdl)}\nabla_\vimkp \log\vimkq(\mdl)\right].
\end{align*}
In practice, the variance of this estimator can be very high when the batch size is not large. However, there are techniques to reduce this variance for general applications. The simplest of which is to use a control variate $\controlvariate$ in the form
\begin{align}
    \nabla_\vimkp \mc{L}(\vipp,\vimkp)
    &=
    \Ex_{\mdl\sim\vimkq}
        \left[
            \Ex_{\vct{z}\sim \nu_\dmax}
                \left[
                    h(\vimkp,\vipp,\refvars)-\varsigma
                \right]
                \nabla_\vimkp\log\vimkq(\mdl)
            \right].
\end{align}
By simply choosing $\controlvariate=\Ex_{t\in\{1,\dots,T\}}\left[\mc{L}(\vipp,\vimkp)\right]$, where the expectation is estimated online over the iterations of the optimizer, we can reduce variance of $\nabla_\vimkp\mc{L}(\vipp,\vimkp)$. See \cref{apdx:sfecontrolvariate} for implementation details.



\subsection{Control variate for score function estimator}\label{apdx:sfecontrolvariate}


\newcommand{\mcgcvbeta}{\beta}              \newcommand{\mcgcvB}{B}                     \newcommand{\mcgcvIter}{t}                  \newcommand{\mcgcvLoss}{\ell}               \newcommand{\mcgcvBiased}{\tilde{\mu}}        \newcommand{\mcgcvUnbiased}{\mu}              \newcommand{\mcgcvGrad}{\tilde{\nabla}_{\vimkp}}                  \newcommand{\mcgcvGradIter}[1]{\tilde{\nabla}_{\vimkp,#1}}                  \newcommand{\mcgcvpsi}{\vimkp}                \newcommand{\mcgcvk}{\mdl}                     

We adopt the approach used in \citet{KingmaAdam2017} for obtaining an unbiased running first moment of the loss function. 
At iteration $\mcgcvIter$ we draw $\mcgcvB$ samples
$\{\mcgcvk_{\mcgcvIter,n}\}_{n=1}^{\mcgcvB}$ and compute
\[
  \mcgcvLoss_{\mcgcvIter,n} \;=\; -\widehat{\mc{L}}_{\mcgcvIter,n},
  \qquad n=1,\dots,\mcgcvB.
\]

With fixed decay $\mcgcvbeta\in(0,1)$, update the (biased) first moment exactly as in the approach of the Adam optimizer~\citep{KingmaAdam2017}:
\[
  \mcgcvBiased_{\mcgcvIter}
  \;\gets\;
  \mcgcvbeta\,\mcgcvBiased_{\mcgcvIter-1}
  \;+\;
  (1-\mcgcvbeta)\,
  \bar{\mcgcvLoss}_{\mcgcvIter},
  \qquad
  \bar{\mcgcvLoss}_{\mcgcvIter}
  =\frac{1}{\mcgcvB}\sum_{n=1}^{\mcgcvB}\mcgcvLoss_{\mcgcvIter,n}.
\]

To remove the initialization bias,
\[
  \mcgcvUnbiased_{\mcgcvIter}
  \;\gets\;
  \frac{\mcgcvBiased_{\mcgcvIter}}
       {1-\mcgcvbeta^{\mcgcvIter}}.
\]

Using $\controlvariate_{\mcgcvIter}:=\mcgcvUnbiased_{\mcgcvIter}$ as a baseline,
the Monte Carlo gradient estimator becomes
\[
  \mcgcvGradIter{\mcgcvIter}
  \;\gets\;
  \frac{1}{\mcgcvB}
  \sum_{n=1}^{\mcgcvB}
  \bigl(\mcgcvLoss_{\mcgcvIter,n}-\controlvariate_{\mcgcvIter}\bigr)
  \nabla_{\mcgcvpsi}\log q_{\mcgcvpsi}\!\bigl(\mcgcvk_{\mcgcvIter,n}\bigr).
\]
Because $\controlvariate_{\mcgcvIter}$ is independent of each
$\mcgcvk_{\mcgcvIter,n}$, the estimator remains unbiased while the baseline substantially
reduces its variance.
 \subsection{Controlling learning rate via the information gain}\label{apdx:ig_threshold}



When using stochastic gradient descent for optimization over parameters of both $\vimkq$ and $\vipq$, it is necessary to use careful scaling of the estimated gradients to ensure the optimizer does not ``drop off a cliff'' into a local minimum. Such phenomena has been observed in related fields such as proximal policy gradients~\citep{SchulmanProximal2017} where the authors demonstrate empirically such a necessity in reinforcement learning problems. In essence, we want to control the learning rate of $\vimkp$ with respect to the convergence of $\vipp\rightarrow\vipp^*$. We show empirical results for controlling this rate and leave any mathematical properties for the optimal scaling to future research.


One approach is to control the rate of \textit{information gain} (IG) of $\vimkq$ during the simultaneous optimization over both $\vimkp$ and $\vipp$. By assuming a bounded rate of information gain for $\vipq$ (achieved via gradient clipping) we only need to consider computing the IG over successive $q_{\vimkp}^{(t)}$ for steps $t=1,\dots,T$. Defining the IG in terms of entropy, we have
\begin{align}
    \mathrm{IG}(q_{\vimkp}^{(t+1)}\gvn q_{\vimkp}^{(t)}) &= \mathrm{H}(q_{\vimkp}^{(t)}) - \mathrm{H}(q_{\vimkp}^{(t+1)}).
\end{align}
When $\vimkq$ is a categorical distribution, this quantity is available analytically.
However, in general this is not available, but it can be estimated via Monte Carlo integration and importance sampling using available quantities (see \cref{apdx:montecarloinformation}). 
We choose to set a threshold for the IG between steps, denoted $\igthreshold$, and then at each successive step $t$ we scale $\nabla_\vimkp$ using an iterative method such as bisection\footnote{In preliminary investigations, other approaches for implementation of this threshold such as constrained optimization and computation of Lagrange multipliers were trialed without success, possibly due to the geometry of the optimization landscape.}.

\subsection{Monte Carlo estimation of information}
\label{apdx:montecarloinformation}

\newcommand{\MADEFN}{\operatorname{NN}_\vimkp}
\newcommand{\MADEFNPRIME}{\operatorname{NN}_{\vimkp'}}
The below procedure assumes $\vimkq$ represents a distribution over strings of Bernoulli variables. Let $\vimkp\in\R^{n_\vimkp}$ parameterize a masked autoencoder that determines logits for a product Bernoulli distribution
\[
\vimkq(\mdl)
=\prod_{i=1}^{d}\sigma\!\bigl(\MADEFN^{(i)}(\mdl)\bigr)^{\mdl^{(i)}}
          \!\bigl[1-\sigma\!\bigl(\MADEFN^{(i)}(\mdl)\bigr)\bigr]^{1-\mdl^{(i)}},
\qquad
\mdl\in\{0,1\}^{d},
\]
with MADE logits $\MADEFN^{(i)}(\,\cdot\,)$ and
$\sigma(\MADEFN)=(1+e^{-\MADEFN})^{-1}$.  
After an SGD proposal $\vimkp'=\vimkp-\alpha\,\nabla_\vimkp$,  
we estimate the entropy reduction
\begin{align}
\Delta\mathcal I(\alpha)
=\mathrm{H}\bigl(\vimkq\bigr)
-\mathrm{H}\bigl(q_{\vimkp'}\bigr),
\qquad
\mathrm{H}(p)=-\!\!\sum_{\mdl}p(\mdl)\log p(\mdl).
\label{eq:apdxigthreshold}
\end{align}

To reduce computation at the expense of introducing some estimation bias, we employ importance weights to re-use the current sample of model indicators in an iterative search to scale the gradient step. Draw a mini-batch
$\{\mdl^{(n)}\}_{n=1}^{N}\overset{\text{i.i.d.}}{\sim}\vimkq$
\emph{once}; no re-sampling is needed afterwards.  
Because the expectation in \eqref{eq:apdxigthreshold} switches from
$\vimkq$ to $q_{\vimkp'}$, rewrite
\begin{align}
\mathrm{H}\bigl(q_{\vimkp'}\bigr)=
-\E_{\mdl\sim \vimkq}
\!\bigl[w_{\vimkp',\vimkp}(\mdl)\,
        \log q_{\vimkp'}(\mdl)\bigr],
\quad
w_{\vimkp',\vimkp}(\mdl):=
\frac{q_{\vimkp'}(\mdl)}{\vimkq(\mdl)}.
\end{align}
For a Bernoulli product the weight factorizes:
\begin{align}
w_{\vimkp',\vimkp}(\mdl)
=\prod_{i=1}^{d}
\frac{\sigma(\MADEFNPRIME^{(i)})^{\mdl^{(i)}}[1-\sigma(\MADEFNPRIME^{(i)})]^{1-\mdl^{(i)}}}
     {\sigma(\MADEFN^{(i)} )^{\mdl^{(i)}}[1-\sigma(\MADEFN^{(i)} )]^{1-\mdl^{(i)}}}
\quad\bigl(\MADEFN^{(i)}:=\MADEFN^{(i)}(\mdl),~
      \MADEFNPRIME^{(i)}:=\MADEFNPRIME^{(i)}(\mdl)\bigr),
\end{align}
implemented stably via
$\frac{\sigma(\MADEFNPRIME^{(i)})}{\sigma(\MADEFN^{(i)})}
=\exp\bigl[\log(1+e^{-\MADEFN^{(i)}})-\log(1+e^{-\MADEFNPRIME^{(i)}})\bigr]$.

The mini-batch estimator is therefore
\begin{align}
\widehat{\mathrm{H}}_{N}(\vimkp')
=-\frac{1}{N}\sum_{n=1}^{N}
w_{\vimkp',\vimkp}\!\bigl(\mdl^{(n)}\bigr)
\log q_{\vimkp'}\!\bigl(\mdl^{(n)}\bigr),\qquad
\widehat{\mathrm{H}}_{N}(\vimkp)
=-\frac{1}{N}\sum_{n=1}^{N}\log \vimkq\!\bigl(\mdl^{(n)}\bigr).
\end{align}

Given a tolerance $\varepsilon>0$, reduce $\alpha\leftarrow0.5\,\alpha$
until
\begin{align}
\bigl|\widehat{\mathrm{H}}_{N}(\vimkp)
       -\widehat{\mathrm{H}}_{N}(\vimkp')\bigr|\le\varepsilon.
\label{eq:apdxhalvestep}
\end{align}
If no $\alpha>10^{-20}$ satisfies \eqref{eq:apdxhalvestep}, discard the update by
setting the gradient to $\vct 0$.
Otherwise, apply the accepted scaled gradient. \newpage
