\section{Example description: Bayesian inference of multi-layer-perceptron
         directed acyclic graph discovery}\label{apdx:mlpdagdescription}


\paragraph{Notation:}
\begin{align*}
\MLPDData        &\in \mathbb{R}^{\MLPDnodes\times\MLPDsamples}
             &&\text{(columns are i.i.d.\ samples)}\\
\MLPDPerm        &\in\mathcal P_{\MLPDnodes}
             &&\text{permutation matrix (node order)}\\
\MLPDEdges       &\in\{0,1\}^{\MLPDnodes\times\MLPDnodes}
             &&\text{strictly upper–triangular edge mask}\\
\MLPDAdj         &=\MLPDPerm^{\top}\MLPDEdges\MLPDPerm
             &&\text{adjacency in canonical order (code default)}\\
\MLPDparents{j}  &=\{\,i<j : \MLPDEdges_{ij}=1\,\}
             &&\text{parents of node $j$ in the sorted order.}
\end{align*}

\paragraph{Node-wise conditional mean:}
Fix hidden width $\MLPDhid$ and a model indicator $\MLPDModel=(\MLPDPerm,\MLPDEdges)$.
For each \emph{non-root} node $j=2,\dots,\MLPDnodes$ define parameters
\[
\MLPDThetaJ{j}
   =\bigl(W^{(1)}_j,b^{(1)}_j,W^{(2)}_j,b^{(2)}_j\bigr)
   \in\mathbb{R}^{(j+2)\MLPDhid + 1},
\]
with
\(
W^{(1)}_j\!\in\!\mathbb{R}^{\MLPDhid\times(j-1)},\;
b^{(1)}_j\!\in\!\mathbb{R}^{\MLPDhid},\;
W^{(2)}_j\!\in\!\mathbb{R}^{1\times\MLPDhid},\;
b^{(2)}_j\!\in\!\mathbb{R}.
\)
Let $\MLPDuvec{j}:=\MLPDEdges_{1:(j-1),\,j}$ be the \((j-1)\)-vector of active parents.  
For $\vct x=(x_1,\dots,x_{j-1})^{\!\top}$,
\[
\MLPfunc{j}(\vct x;\MLPDThetaJ{j},\MLPDEdges)
   = W^{(2)}_j\,
     \MLPDrelu\!\bigl(W^{(1)}_j(\vct x\odot\MLPDuvec{j})+b^{(1)}_j\bigr)
     +b^{(2)}_j,
\qquad
\MLPfunc{1}(\,\cdot\,)\equiv 0 .
\]

\paragraph{Gaussian likelihood:}
Let $\MLPDPermmap$ be the permutation associated with $\MLPDPerm$
(so $x_{\MLPDPermmap(j)}$ is column $j$ after sorting).  With
homoscedastic noise $\MLPDNoiseVar$,
\[
\boxed{\log p\!\bigl(\MLPDData\!\mid\!\MLPDPerm,\MLPDEdges,\MLPDParamVec\bigr)
   =-\frac{\MLPDsamples\!\MLPDnodes}{2}\log\!\bigl(2\pi\MLPDNoiseVar\bigr)
   -\frac{1}{2\MLPDNoiseVar}
     \sum_{s=1}^{\MLPDsamples}\sum_{j=1}^{\MLPDnodes}
       \Bigl(
         x_{\MLPDPermmap(j)}^{(s)}
        -\MLPfunc{j}\!\bigl(
            \vct x_{\MLPDPermmap(1:j-1)}^{(s)};
            \MLPDThetaJ{j},\MLPDEdges
          \bigr)
       \Bigr)^{2}}
\]

\paragraph{Parameter prior (masked i.i.d.\ Gaussian):}
Let $\MLPDctxmask(\MLPDModel)\subseteq\{1,\dots,\dim\MLPDParamVec\}$ be the index set
that survives the mask.  Then
\[
\boxed{\prior(\MLPDParamVec\!\mid\!\MLPDPerm,\MLPDEdges)
   =\!\!\prod_{k\in\MLPDctxmask(\MLPDModel)}
     \mathcal{N}\!\bigl(\MLPDParamVec_k;0,\MLPDPriorScale^{2}\bigr)}
\]
(parameters outside $\MLPDctxmask(\MLPDModel)$ are handled by a reference density).

\paragraph{Structural prior:}
\[
\boxed{\prior(\MLPDPerm,\MLPDEdges)\;\propto\;
  \exp\!\bigl(-\MLPDSparsityPen\,\|\MLPDEdges\|_{1}\bigr)},
  \qquad \MLPDSparsityPen\ge 0 ,
\]
with $\MLPDPerm$ a permutation matrix and $\MLPDEdges$ strictly upper triangular.

The un-normalised log-posterior is the sum of the three boxed terms above.

\subsection{Data generating process}\label{apdx:mlpdagdgp}
The data generating procedure generally follows the simulation design in \citet{Thompson2025ProDAG}.
\paragraph{Global hyper-parameters:}
\begin{align*}
\MLPDnodes :\text{ number of nodes},\quad
\MLPDhid :\text{ hidden width},\quad
\MLPDNoiseVar :\text{ noise variance},\quad\\
\MLPDEdgeProb\in(0,1):\text{ edge probability},\quad
\MLPDPriorScale>0:\text{ parameter prior scale}.
\end{align*}

\paragraph{Sample graph structure:}
\begin{align*}
\MLPDPerm &\sim \text{Uniform}\bigl(\mathcal P_{\MLPDnodes}\bigr),\\
\MLPDEdges_{ij} &\stackrel{\text{iid}}{\sim} \operatorname{Bernoulli}(\MLPDEdgeProb),
\qquad 1\le i<j\le\MLPDnodes,\\
\MLPDAdj &= \MLPDPerm^{\top}\MLPDEdges\MLPDPerm .
\end{align*}

\paragraph{Sample node parameters:}
Let the \emph{bias flag} $\MLPDBiasFlag\in\{0,1\}$
($\MLPDBiasFlag=1$ keeps both bias vectors, $\MLPDBiasFlag=0$ sets them to $0$).
For each non-root node $j=2,\dots,\MLPDnodes$ draw independently
\[
\MLPDThetaJ{j}
   =\bigl(
      W^{(1)}_j,\;\MLPDBiasFlag\,b^{(1)}_j,\;
      W^{(2)}_j,\;\MLPDBiasFlag\,b^{(2)}_j
     \bigr),
\qquad
\bigl[\MLPDThetaJ{j}\bigr]_k\stackrel{\text{iid}}{\sim}
[-0.7,-0.3]\cup[0.3,0.7],
\]
while the root node has $\MLPDThetaJ{1}=\varnothing$. Note the active parameters are drawn uniformly from a non-zero range rather than from the prior.

\paragraph{Context–to–mask map:}
For $\MLPDModel=(\MLPDPerm,\MLPDEdges)$, $\MLPDctxmask(\MLPDModel)=\MLPDctxmask(\MLPDEdges)\subseteq\{1,\ldots,\dim\MLPDParamVec\}$
keeps exactly the coordinates satisfying the conditions:
\begin{enumerate}\itemsep2pt
\item Column $i$ of $W^{(1)}_j$ is \emph{active} iff $\MLPDEdges_{ij}=1$;
\item If $\sum_{i<j}\MLPDEdges_{ij}=0$ then \emph{all} parameters in $\MLPDThetaJ{j}$ are masked.
\end{enumerate}
(The permutation $\MLPDPerm$ has no effect on the mask.)

\paragraph{Data generation (topological order):}
Let $\MLPDPermmap$ be the permutation induced by $\MLPDPerm$.
For each sample $s=1,\dots,\MLPDsamples$ generate sequentially
\begin{align*}
x_{\MLPDPermmap(1)}^{(s)} &= \MLPDNoiseStd\,\varepsilon_{1s},\\
x_{\MLPDPermmap(j)}^{(s)} &=
      \MLPfunc{j}\!\bigl(
        \vct x_{\MLPDPermmap(1:j-1)}^{(s)};
        \MLPDThetaJ{j},\MLPDEdges
      \bigr)
      +\MLPDNoiseStd\,\varepsilon_{js},
      \quad j=2,\dots,\MLPDnodes,
\end{align*}
where $\varepsilon_{js}\stackrel{\text{iid}}{\sim}\mathcal{N}(0,1)$ and
\[
\MLPfunc{j}(\vct z;\MLPDThetaJ{j},\MLPDEdges)
   = W^{(2)}_j\,
     \MLPDrelu\!\bigl(
        W^{(1)}_j(\vct z\odot\MLPDuvec{j}) + \MLPDBiasFlag\,b^{(1)}_j
     \bigr)
     +\MLPDBiasFlag\,b^{(2)}_j,
\quad
\MLPDuvec{j}:=\MLPDEdges_{1:(j-1),\,j}.
\]

Collecting the $\MLPDsamples$ draws gives
\[
\MLPDData =
\begin{bmatrix}
\vct x^{(1)}\\[-2pt]\vdots\\[-2pt]\vct x^{(\MLPDsamples)}
\end{bmatrix}
\in\mathbb{R}^{\MLPDsamples\times\MLPDnodes},
\quad
\text{stored in topological order } \bigl(
  x_{\MLPDPermmap(1)},\dots,x_{\MLPDPermmap(\MLPDnodes)}
\bigr).
\]



\subsection{Comparison metrics}\label{apdx:dagmetrics}
Given knowledge of a ``true'' adjacency matrix $A$, each experiment uses four scores for comparison with the estimated posterior: F1, structured Hamming distance (SHD), Brier score, and area under the receiver operating characteristic curve (AUROC). This follows the experiment setup in \citet{Thompson2025ProDAG}.

\subsection{Common inference setup}

For each data set in both the simulation study and real data example, VTI is run a total of 10 replicates using different random seeds, and the posterior is selected where the terminal loss is minimized. For DAGMA, the sparsity hyperparameter is swept from $\lambda^{\operatorname{min}}=10^{-3}$ to $\lambda^{\operatorname{max}}=1$ over 10 logarithmically spaced values. For the autoregressive flow, we use Affine(5,5) (see \cref{apdx:flowarchitecture}) with a context encoder designed as follows:
\[
\delta(\MLPDPerm,\MLPDEdges) = \sigma^{\lceil\times2\rceil}\circ\dots\circ\sigma^{\lceil\times2\rceil}\circ(\MLPDPerm^\top\MLPDEdges\MLPDPerm),
\]
where $\sigma^{\lceil\times2\rceil}(x):=Wx+b$ broadcasts from $|x|$ to the first power of 2 greater than or equal to $2|x|$. The final dimension of $\delta(\MLPDPerm,\MLPDEdges)$ is 4096.

\subsection{Simulation design}\label{apdx:dagsimstudy}

In the simulation study, the configuration of the MLP is as follows. We set the hidden layer width to $\MLPDhid=10$. We set the number of nodes to $\MLPDnodes=10$. We omit the bias parameters $b_j^{(1)}, b_j^{(2)}$ for all edges, i.e. set $\MLPDBiasFlag=0$. The edge inclusion probability is set to $\MLPDEdgeProb=0.5$. For VTI, the model prior $\prior(\mdl)$ is uniform (i.e. the sparsity parameter is set to $\MLPDSparsityPen=0$). 

We generate 10 i.i.d. complete data sets of length $\MLPDsamples_{\operatorname{max}}=2^{10}$ from the above process. The experiment compares data size against the metrics from \cref{apdx:dagmetrics}. The range of data sizes are $\MLPDsamples=16,32,4,128,256,512,1024$, where $\MLPDsamples<\MLPDsamples_{\operatorname{max}}$ simply takes the first $\MLPDsamples$ samples.

VTI inference was conducted on a cluster of GPU nodes with mixed Nvidia $RTX3090$ and $H100$ cards. On the former we used float32 precision for MLP architectures, the latter used float64.

\subsection{Real data example}\label{apdx:realdatadagexample}

For VTI, we chose a penalized structural model prior $\prior(\mdl)$ where $\MLPDSparsityPen=200$. We set the number of hidden nodes per edge to $\MLPDhid=5$ and include the bias terms, i.e. $\MLPDBiasFlag=1$.

For DAGMA non-linear, we use 10 hidden nodes per edge and no bias term.  

\subsection{DAG Model indicator construction: Lehmer Code Decoding}
A permutation of the ordered set
\(\{1,2,\ldots,\MLPDnodes\}\)is represented by a \emph{Lehmer code}
\(\vct c=(c_1,c_2,\ldots,c_{\MLPDnodes})\),
where
\(c_i\in\{0,1,\ldots,\MLPDnodes-i\}\).
At step \(i\,(1\le i\le\MLPDnodes)\) we choose the
\((c_i\!+\!1)\)-th \emph{unused} index in the remaining ascending list.

\smallskip
\noindent
\textit{Example.}\;
For \(\MLPDnodes=5\) and
\(\vct c=(2,1,0,0,0)\)
\[
\begin{array}{@{}l@{\quad}l@{}}
c_1=2 :& \{1,2,3,4,5\}\!\to\!3,\\
c_2=1 :& \{1,2,4,5\}\!\to\!2,\\
c_3=0 :& \{1,4,5\}\!\to\!1,\\
c_4=0 :& \{4,5\}\!\to\!4,\\
c_5=0 :& \{5\}\!\to\!5 .
\end{array}
\]

\paragraph{Permutation-matrix representation.}
The permutation \(\MLPDPermmap\) is stored as a one-hot
\(\MLPDPerm\in\{0,1\}^{\MLPDnodes\times\MLPDnodes}\) with
\(
\MLPDPerm_{r,i}=1
\)
iff row \(r\) is chosen at column \(i\).



\begin{algorithm}[H]
\caption{Vectorized Lehmer decode via leftover mask}
\label{alg:vectorised-lehmer}
\begin{algorithmic}[1]

\REQUIRE $P_{\text{code}} \in \mathbb{N}^{\MLPDbsize\times\MLPDnodes}$  \COMMENT{batch of Lehmer codes}
\ENSURE  $\MLPDPerm \in \{0,1\}^{\MLPDbsize\times\MLPDnodes\times\MLPDnodes}$

\STATE $\text{bs} \gets \MLPDbsize$
\STATE $\MLPDPerm \gets \mathbf 0_{\,\text{bs}\times\MLPDnodes\times\MLPDnodes}$

\FOR{$i = 1$ \textbf{to} $\MLPDnodes - 1$}
    \STATE $k \gets P_{\text{code}}[:,\,i]$
    \STATE $\text{OneHot} \gets \text{one\_hot}\!\bigl(k,\,\MLPDnodes - i + 1\bigr)$
           \COMMENT{shape $=\text{bs}\times(\MLPDnodes-i+1)$}
    \STATE $\text{Used} \gets \displaystyle\sum_{c=1}^{i-1}\MLPDPerm[:,:,c]$
    \STATE $\text{Mask} \gets (\text{Used}=0)$
    \STATE $\text{Idx}  \gets \operatorname{nonzero}(\text{Mask})$
    \STATE $\MLPDPerm\bigl[\text{Idx}_{[:,0]},\,\text{Idx}_{[:,1]},\,i\bigr]
           \gets \text{reshape}\!\bigl(\text{OneHot},\,{-}1\bigr)$
\ENDFOR

\STATE $\text{Used} \gets \displaystyle\sum_{c=1}^{\MLPDnodes-1}\MLPDPerm[:,:,c]$
\STATE $\text{Last} \gets \operatorname{nonzero}(\text{Used}=0)$
\STATE $\MLPDPerm\bigl[\text{Last}_{[:,0]},\,\text{Last}_{[:,1]},\,\MLPDnodes\bigr] \gets 1$

\RETURN $\MLPDPerm$

\end{algorithmic}
\end{algorithm}


Algorithm\,\ref{alg:vectorised-lehmer} decodes each column in parallel.
For column \(i\) the code
\(k\in[0,\,\MLPDnodes-i]\)specifies “pick the \((k{+}1)\)-th leftover row.”
The Boolean mask marks currently unused rows; broadcasting the
flattened one-hot vector onto the corresponding
\((\text{batch},\text{row})\) pairs writes the unit entries.
Column \(\MLPDnodes\) is filled by the single row that remains unassigned.
This implementation gives a compact \((\MLPDbsize,\MLPDnodes)\) tensor,
expanded by the decoder to
\((\MLPDbsize,\MLPDnodes,\MLPDnodes)\)
for efficient batched linear algebra in our DAG-inference pipeline.

\bigskip
%
 \subsection{Model identifier for directed acyclic graphs}
\label{apdx:dagmdl}

\newcommand{\madecatlogit}[1]{\rho^{\operatorname{cat}}_{#1}}



We encode a permutation matrix
\(\MLPDPerm \in \{0,1\}^{\MLPDnodes \times \MLPDnodes}\) using a \emph{compressed Lehmer code} consisting of
\(\MLPDnodes-1\) categorical variables                           \(\{\madecatlogit{1},\ldots,\madecatlogit{\MLPDnodes-1}\}\).
Here \(\madecatlogit{i}\) has \(\MLPDnodes-i+1\) outcomes.          

Concretely,
\(\madecatlogit{1}\in\{0,1,\ldots,\MLPDnodes-1\}\),                \(\madecatlogit{2}\in\{0,1,\ldots,\MLPDnodes-2\}\),                \(\ldots\),
\(\madecatlogit{\MLPDnodes-1}\in\{0,1\}\).                         Once the first \(\MLPDnodes-1\) columns are fixed, the last column is forced.

Each \(\madecatlogit{i}=k\) is mapped to a one-hot vector of length
\(\MLPDnodes\).  The value \(k\) selects the \((k{+}1)\)-st \emph{available}
row for the \(i\)-th column; previously taken rows remain zero, preserving the
permutation property.


Given \(\MLPDPerm\) we form an upper-triangular mask
\(\MLPDEdges\in\{0,1\}^{\MLPDnodes\times\MLPDnodes}\) with zero diagonal.  Each entry above the diagonal
(\(i<j\)) is a Bernoulli variable, so \(\MLPDEdges\) flattens to
\(\tfrac{\MLPDnodes(\MLPDnodes-1)}{2}\) bits.               The adjacency matrix is
\(\MLPDAdj=\MLPDPerm^\top\MLPDEdges\MLPDPerm\), giving a DAG.



We concatenate the \(\MLPDnodes-1\) categorical codes with the
\(\tfrac{\MLPDnodes(\MLPDnodes-1)}{2}\) Bernoulli bits,
yielding a vector \(\vct z\) of length
\((\MLPDnodes-1)+\tfrac{\MLPDnodes(\MLPDnodes-1)}{2}\).
\textsc{\madeplus} consumes \(\vct z\) together with a
\(\mathrm{multiplier\_fn}\) specifying the parameter count for each entry.

Let \(z_j\) denote the \(j\)-th component of \(\vct z\):
\[
\mathrm{multiplier\_fn}(j)=
\begin{cases}
\MLPDnodes-j, & j=1,\ldots,\MLPDnodes-1,\\ 1, & j=\MLPDnodes,\ldots,
      \MLPDnodes-1+\tfrac{\MLPDnodes(\MLPDnodes-1)}{2}.  \end{cases}
\]
The architecture yields the autoregressive factorization
\[
p(\vct z)=
\prod_{j=1}^{\,\MLPDnodes-1+\frac{\MLPDnodes(\MLPDnodes-1)}{2}}
p\bigl(z_j \mid z_{<j}\bigr).                                  \]
The identifier
\(\{\madecatlogit{1},\ldots,\madecatlogit{\MLPDnodes-1},
  \MLPDEdges_{\mathsf{binary}}\}\)                            is modelled autoregressively by a single \textsc{\madeplus}
network, yielding \(\MLPDAdj=\MLPDPerm^\top\MLPDEdges\MLPDPerm\)
upon sampling.

We employ a structural prior over the space of models with the edge-penalty term \(\gamma\):
\begin{align}
\prior(\MLPDPerm,\MLPDEdges\mid\gamma)
&=
\frac{1}{\MLPDnodes!}\;
\frac{1}{2^{\frac{\MLPDnodes(\MLPDnodes-1)}{2}}}\;
\exp\!\bigl(-\gamma\,\mathrm{nEdges}(\MLPDEdges)\bigr),\\
\mathrm{nEdges}(\MLPDEdges)
&=\sum_{i<j}\MLPDEdges_{ij},\\
\log\prior
&=-\log(\MLPDnodes!)
  -\frac{\MLPDnodes(\MLPDnodes-1)}{2}\log 2
  -\gamma\,\mathrm{nEdges}(\MLPDEdges).
\end{align}
Note that when $\gamma=0$, the prior is uniform. \subsection{Neural probability mass function for model indicators over large spaces: \madeplus}\label{apdx:madeplus}

To represent a distribution over binary strings, we use the Masked Autoencoder for Density Estimation (MADE) \citep{GermainMADE2015} implementation found in the \citet{Durkan2020Nflows} repository. To represent a more complex discrete distribution such as that required by the $\MLPDPerm,\MLPDEdges$ representation of a directed acyclic graph, we apply a simple extension to this architecture to allow us to vary the output dimension multiplier. For 
presentational clarity we call
this extension \madeplus. The key change in \madeplus is the introduction of a per-dimension output multiplier function
$\,r(i)\,$ that determines how many parameters are emitted for the $i$-th input dimension in the 
autoregressive factorization. 

In the original MADE, all features share a common multiplier $k$, yielding an output 
dimensionality of $\,k \times d\,$ when there are $\,d\,$ input features. Mathematically, 
if $\,\mathbf{x} \in \mathbb{R}^d\,$, the network outputs 
$\,(h_1, h_2, \dots, h_{kd}) \in \mathbb{R}^{kd}\,$. 

In \madeplus, a function $r: \{0, 1, \dots, d-1\} \to \mathbb{N}$ is provided, and the final output dimension is $\sum_{i=0}^{d-1} r(i)$. For each input dimension $\,x_i\,$, the network outputs $\,r(i)\,$ parameters. Concretely, 
where $\,d\,$ is the number of input features, the final output dimension becomes $\textstyle\mathrm{total\_out\_features} = \sum_{i=0}^{d-1} r(i)$. In other words, each input $\,x_i\,$ can be associated with a custom number of distributional 
parameters (e.g., to handle discrete variables of different cardinalities). The masking logic
is preserved by replicating each degree, 
$\mathrm{deg}(x_i)$, 
exactly $\,r(i)\,$ times in 
the final layer.




Below is a simplified, side-by-side pseudocode comparing MADE (left) and \madeplus (right).
Changes in \madeplus are highlighted in \textcolor{green}{green}.

\begin{minipage}[t]{0.49\textwidth}
\begin{algorithm}[H]
    \caption{Original MADE\\ (Final Layer Construction)}
    \label{alg:orig_made}
\begin{algorithmic}
\STATE \quad
\STATE out\_features = features * output\_multiplier
\STATE final\_layer = MaskedLinear(
\STATE \quad in\_degrees = prev\_out\_degrees,
\STATE \quad out\_features = out\_features,
\STATE \quad autoregressive\_features = features,
\STATE \quad is\_output = True
\STATE \quad
\STATE )
\end{algorithmic}
\end{algorithm}
\end{minipage}
\hfill
\begin{minipage}[t]{0.49\textwidth}
\begin{algorithm}[H]
    \caption{\madeplus\\ (Final Layer Construction)}
    \label{alg:madeplus}
\begin{algorithmic}
\STATE total\_out\_features = \(\sum_{i=0}^{features-1}\) \textcolor{green}{$r(i)$}
\STATE final\_layer = MaskedLinear(
\STATE \quad in\_degrees = prev\_out\_degrees,
\STATE \quad out\_features = \textcolor{green}{total\_out\_features},
\STATE \quad autoregressive\_features = features,
\STATE \quad is\_output = True,
\STATE \quad \textcolor{green}{output\_multiplier\_fn = $r(i)$}
\STATE )
\end{algorithmic}
\end{algorithm}
\end{minipage}



By allowing each input dimension $\,X_i\,$ to have its own output multiplier $\,r(i)\,$, 
the \madeplus architecture provides a more flexible autoregressive decomposition:
\[
p(\mathbf{x})
\;=\;
\prod_{i=1}^{d} p\bigl(x_i \,\bigm\vert\, x_{1}, \dots, x_{i-1}\bigr),
\]
where now the conditional distribution for $x_i$ can be parameterized by $r(i)$ parameters 
(e.g., logits for a categorical variable of size $r(i)$, or a mean/variance pair, etc.). 

Hence, one can naturally combine discrete variables of varying dimensions such as Bernoulli and categorical 
variables. For example, if $x_1$ is categorical with 10 categories and 
$x_2$ is a Bernoulli variable, one can specify $r(0) = 10$ and $r(1) = 1$, so that the overall 
conditional densities (or probability mass functions) multiply to form a richer joint model
adapting precisely to each variable's nature.


