\section{Main Proofs} \label{sec:proofs}

\subsection{Proof of \texorpdfstring{\Cref{lm:MonotoneWages}}{Lemma \ref{lm:MonotoneWages}}}   \label{sec:proof_MonotoneWages}
Define $ \tilde w_\th(x)  \; := \sup_{ y \le x } w_\th(y)$, and for the case that $X=[\ul x,\bar x]$, define additionally $\bar w_{\theta}(x)\; := \underset{\e \searrow 0}{\lim} \ \tilde w_{\theta} (x+\epsilon)$. 

First, we prove that for the non-decreasing wages  $\{ \tilde{w}_\th,  \mu_\th\}_{\theta \in \Th}$ is incentive compatible and  $ \mu_\theta \Paren{ \{x \colon  \tilde w_\th(x) \ne w_\th(x) \}} = 0$ for all $\th\in \Th$. 
Then, we show for the right-continuous modifications that  $\{ \bar{w}_\th,  \mu_\th\}_{\theta \in \Th}$ is incentive compatible and  $ \mu_\theta \Paren{ \{x \colon  \bar w_\th(x) \ne w_\th(x) \}} = 0$ for all $\th\in \Th$. 
For the first part, we apply a result from \citetalias{georgiadis2024flexible}:
\begin{lemma*}[Lemma 5, GRS:]
For every $\nu\in \D(X)$ and every  $\e >0$, a measurable function $g : X \rightarrow X$ exists such that $g(x)\leq x$ for all $x$, and $w\circ g(x) \geq [\tilde w(x)-\e] \ \nu$-almost surely.
\end{lemma*}

Define
\begin{align*}
    V(\theta,\hat{\theta}) := & \underset{\mu\in \D(X)}{\sup}\ \left\{\int u\circ w_{\hat \theta}(x)\mu(\de x)- C(\theta,\mu) \right\}, \\
        \tilde V(\theta,\hat{\theta}) := & \underset{\mu\in \D(X)}{\sup}\ \left\{\int u\circ \tilde w_{\hat \theta}(x)\mu(\de x)- C(\theta,\mu) \right\},\\
     \bar V(\theta,\hat{\theta}) := & \underset{\mu\in \D(X)}{\sup}\ \left\{\int u\circ \bar w_{\hat{\theta}}(x)\mu(\de x)- C(\theta,\mu) \right\}. 
\end{align*}

\begin{claim}\label{claim:WageTilde}
    $\tilde V(\theta,\hat{\theta}) = V(\theta,\hat{\theta})$ for all $\theta$, $\hat{\theta}$. Moreover, $\mu_\theta \Paren{ \{x \colon  \tilde w_\th(x) \ne w_\th(x) \}} = 0$ for all $\th\in \Th$ and
    \[\mu_{\theta} \in \underset{\mu\in \D(X)}{\argmax} \ \left\{\int \tilde{w}(x)\mu(\de x)- C(\mu,\theta)\right\}.\]
\end{claim}
\noindent
\begin{proof}[Proof of \Cref{claim:WageTilde}]
    As $\tilde{w}(x)\geq w(x)$ for all $x$, $\tilde V(\theta,\hat{\theta}) \geq V(\theta,\hat{\theta})$ for all $\theta$, $\hat{\theta}$. It remains to show that $\tilde V(\theta,\hat{\theta}) \leq V(\theta,\hat{\theta})$. Suppose by the way of contradiction that there exists $\theta$, $\hat{\theta}$ such that $\tilde{V}(\theta,\hat{\theta})>V(\theta,\theta)$. Then, there must exist $\nu\in\D(X)$ and $\e>0$ such that
    \begin{align*}
        \int u\circ \tilde w_{\hat{\theta}}(x) \nu (\de x) - C(\theta,\nu) > V(\theta,\hat{\theta})+\e.
    \end{align*}

    Let $g:X\rightarrow X$ be such that $g(x)\leq x$ for all $x$ and $u\circ w_{\hat{\theta}} \circ g\geq [u\circ \tilde w_{\hat{\theta}} - \e] \ \nu$-almost surely (such a $g$ exists by Lemma 5 in \citetalias{georgiadis2024flexible} and monotonicity of $u$). Define $\bar{\nu} = \nu \circ g^{-1}$, that is, $\bar{\nu} (Y) = \nu \circ g^{-1}(Y)$ for all Borel $Y$. We claim that $\bar{\nu}$ delivers the agent strictly higher utility under $w_{\hat{\theta}}$ than $V(\theta,\hat{\theta})$, thereby contradicting the definition of $V(\theta,\hat{\theta})$. This claim is implied by the following inequality chain:
    \begin{align*}
        \int u\circ w_{\hat{\theta}}(x)\bar{\nu}(\de x) - C(\bar{\nu},\th) &\geq \int [u\circ \tilde w_{\hat{\theta}}(x)-\e]\nu(\de x)-C(\bar{\nu},\theta)\\
        &\geq \int u\circ \tilde{w}_{\hat{\theta}}(x)\nu(\de x)- C(\nu,\theta)-\e >V(\theta,\hat{\theta}),
    \end{align*}
    where the first inequality comes from $u\circ w_{\hat{\theta}}\circ g\geq [u\circ\tilde w_{\hat{\theta}}-\e]$ holding $\nu$-almost surely, the second inequality from $\nu$ first-order stochastically dominating $\bar{\nu}$, and the third inequality from the contradiction assumption. Hence, $V(\theta,\hat{\theta}) = \tilde{V}(\theta,\hat{\theta})$.

    If the chain of inequalities above is taken for $\theta=\hat{\theta}$, it implies that $\mu_{\theta}$ satisfies on-path obedience under $\tilde{w}_{\theta}$, which then implies  $\mu_\theta \Paren{ \{x \colon  \tilde w_\th(x) \ne w_\th(x) \}} = 0$ for all $\th\in \Th$.
\end{proof}

If $X$ is finite, $\tilde w_\th$ is right-continuous and the proof is complete. To complete the proof of \Cref{lm:MonotoneWages} for the other case with $X=[\ul x, \bar x]$, we prove an analogous claim to \Cref{claim:WageTilde} for $\bar w$: 
\begin{claim}\label{claim:WageBar}
    $\bar V(\theta,\hat{\theta}) =\tilde  V(\theta,\hat{\theta})$ for all $\theta$, $\hat{\theta}$. Moreover, $\mu_\theta \Paren{ \{x \colon  \bar w_\th(x) \ne \tilde w_\th(x) \}} = 0$ for all $\th\in \Th$ and all 
    \[\mu_{\theta} \in \underset{\mu\in \D(X)}{\argmax} \ \left\{\int \bar{w}(x)\mu(\de x)- C(\mu,\theta)\right\}.\]
\end{claim}
\noindent
\begin{proof}[Proof of \Cref{claim:WageBar}]
First, as $\tilde{w}$ is non-decreasing, we have $\bar w_{\hat{\theta}}(x)\geq \tilde{w}_{\hat{\theta}}(x)$ for all $x$, $\theta$, $\hat{\theta}$. Hence, $\bar{V}(\theta,\hat{\theta}) \geq \tilde{V}(\theta,\hat{\theta}) $. It remains to prove  $\bar{V}(\theta,\hat{\theta}) \leq \tilde{V}(\theta,\hat{\theta}) $. Suppose to obtain a contradiction that there exists $(\theta,\hat{\th})$ such that $\bar{V}(\theta,\hat{\theta})>\tilde{V}(\theta,\hat{\theta})$. Then, there must exist $\nu$ and $\e>0$ such that
\begin{align*}
    \int u\circ \bar w_{\hat{\theta}}(x)\nu(d)- C(\theta,\nu) > \tilde{V}(\theta,\hat{\theta})+\e.
\end{align*}
Let $g:X \rightarrow X$ be a measurable function such that $g\Paren{\max X} = \max X$, and for all $x<\max X\colon$  $x<g(x)\leq x+\delta$, where $\delta>0$. Define $\nu_{\delta} = \nu \circ g^{-1}$. we claim that for a small enough $\delta$, $\nu_{\delta}$ delivers the agent strictly higher utility under $\tilde{w}_{\hat{\theta}}$ than $\tilde{V}(\theta,\hat{\theta})$, thereby reaching a contradiction. This claim is implied by the following chain of inequalities:
\begin{align*}
           \int u\circ \tilde{w}_{\hat{\theta}}(x)\nu_\delta(\de x) - C(\nu_{\delta},\th) &\geq \int u\circ \bar w_{\hat{\theta}}(x)\nu(\de x)-C(\nu_{\delta},\theta)\\
        &\geq \int u\circ \bar{w}_{\hat{\theta}}(x)\nu(\de x)- C(\nu,\theta)-\e > \tilde{V}(\theta,\hat{\theta}), 
\end{align*}
where the first inequality comes from $u\circ \tilde{w}_{\hat{\theta}}\circ g\geq u\circ\bar w_{\hat{\theta}}$, the second inequality from $\delta$ being sufficiently small and $C(\cdot,\theta)$ continuous, and the third inequality from the contradiction assumption. 

 If the chain of inequalities above is taken for $\theta=\hat{\theta}$, it implies that $\mu_{\theta}$ satisfies on-path obedience under $\bar{w}_{\theta}$, which, together with $\bar w \ge w$,  implies  $\mu_\theta \Paren{ \{x \colon  \bar w_\th(x) \ne w_\th(x) \}} = 0$ for all $\th\in \Th$.
\end{proof}


\subsection{Proof of \texorpdfstring{\Cref{thm:Characterization}}{Theorem \ref{thm:Characterization}}}   \label{sec:proof_Characterization}
First, to ensure that $\mu_{\th,\hat\th}$ is well defined for all $(\th,\hat\th)$ we show that  $\argmax_\mu U(\th, w_{\hat \th}, \mu) $ is nonempty.  Suppose that $U(\theta,w_{\hat \theta},\mu_n)$ converges to $\sup_{\nu\in\D(X)}U(\theta,w_{\hat \theta},\nu)$. By Theorem 6.4 in \citet[p. 45]{parthasarathy2005probability} the space of probability measures $\D(X)$ is compact, so there is a converging subsequence $n_k$ and $\mu\in\D(X)$ with  $\mu_{n_k} \overset{\text{weak}^*}{\longrightarrow} \mu$.
 Since $\w_{\hat\th}$ is upper-semicontinuous and $C(\th,\cdot)$ is weak$^*$-continuous, by the Portmanteau Theorem \citep[see][Theorem 2.1. and Problem 2.6.]{billingsley2013convergence}, any sequence satisfies the inequality below: $$\sup_{\nu\in D(X)}U(\th,w_{\hat \th},\nu)=\underset{k\to\infty}\limsup \Paren{\int_X w_{\hat\th}(x)\mu_{n_k}(\de x)  - C(\th, \mu_n)} \le \int_X w_{\hat\th}(x)\mu(\de x)  - C(\th, \mu) =  U(\th, w_{\hat \th}, \mu).  $$ 

Next, note that $U(\cdot , w_{\hat{\theta}},\mu )$ is absolutely continuous for all  $ (w_{\hat{\theta}},\mu)$  and $\partial U(\cdot,\mu, w_{\hat{\theta}})/ \partial \th  = - \partial C(\th, \mu )/\partial \th$, which is uniformly bounded by assumption.
Hence, by Theorem 2 of \cite{milgrom2002envelope}, any mechanism that induces truthtelling must satisfy
$$V(\theta) = V(\underline{\theta})-\int_{\underline{\theta}}^{\theta} \frac{\partial}{\partial \th} C(t, \mu_{t})\de t.$$

We have shown that item 1 is necessary for truthtelling. Now, we show that given that item 1 holds, item 2 is necessary and sufficient for truthtelling. 
Define $V(\theta, \hat \th) := \sup_{\nu \in \D(X) }U(\th, w_{\hat\th}, \nu)=U(\th, w_{\hat\th}, \mu_{\th,\hat \th})$ and $g(\theta,\hat{\theta}) := V(\theta)-V(\th ,\hat{\theta})$ as $\th$'s loss from misreporting $\hat \th$. 
 $(W,M)$ satisfies truthtelling if and only if $g(\theta,\hat \th)\geq 0$ for all $\theta,\hat{\theta}$. Note that  $g(\hat{\theta},\hat{\theta}) = V(\hat{\theta})-V(\hat{\theta},\hat{\theta})=0$. Hence, $(W,M)$ satisfies truthtelling if and only if
\begin{equation*}
    g(\th, \hat{\theta}) =  g(\th, \hat{\theta})-g(\hat{\theta},\hat{\theta}) 
    = \int_{\hat{\theta}}^{\theta}\frac{\partial g(t,\hat{\theta})}{\partial\theta}\de t 
    % = \int_{\hat{\theta}}^{\theta}\big[V^{\prime}(t)-\frac{\partial V(t,\hat \th)}{\partial \theta}\big]\de t 
    =\int_{\hat{\theta}}^{\theta}\Big[-\frac{\partial C(t, \mu_{t})}{\partial \th}+\frac{\partial C(t, \mu_{t, \hat \th })}{\partial \th }\Big]\de t \geq 0.
\end{equation*}

Items 3 and 4 follow from \citetalias{georgiadis2024flexible}. Lemma 1 in \citetalias{georgiadis2024flexible} immediately gives item 4. For item 3, the difference between the condition and the one in \citetalias{georgiadis2024flexible} is that we need to ensure that the agent of type $\th$  gets utility $V(\theta)$ instead of a minimum payment constraint. Here,  $\Big[ V(\theta)+C(\th, \mu_{\theta})-\int c_{\mu_{\theta}}(\th, x)\mu_{\theta}(\de x)\Big]$ is the constant $m$ in Proposition 2 in \citetalias{georgiadis2024flexible}, which guarantees the agent gets utility $V(\theta)$.
\qed


\section{Proofs for Applications}\label{sec:proofsApplications}

For the proofs below, we use the shorthand $\k(\mu) := K\Paren{\int_X z(x) \mu(\de x) }$. 
\subsection{Proof of \texorpdfstring{\Cref{prop:DegenerateExample}}{Proposition \ref{prop:DegenerateExample}}}   \label{sec:proof_DegenerateExample}
We can write the Principal's problem as

\begin{equation}\label{example5}
    \underset{\mu_{(\cdot),(\cdot)}, V(\cdot), w_{(\cdot)}}{max} \ \int_{\underline{\theta}}^{\overline{\theta}}\int \Big\{x-w_{\theta}(x)\Big\}\mu_{\theta}(\de x)\de F(\theta)
\end{equation}
subject to

\begin{equation}\label{obedience}\tag{Obedience}
    \mu_{\th,\hat{\theta}} \in \underset{\mu\in \D(X) }{arg \ max} \int \Big[u\big(w_{\hat{\theta}}(x))-(1-\theta)c_{\mu_{\th,\hat{\theta}}}(x)\Big]\mu(\de x)
\end{equation}
\begin{equation}\label{envelope}\tag{Envelope}
    V(\theta) =\int_{\underline{\theta}}^{\theta} \k(\mu_{t,t})\de t  \geq 0 
\end{equation}
\begin{equation}\label{monotonicity}\tag{Monotonicity}
    \int_{\hat{\theta}}^{\theta}\big[\k(\mu_{t,t})-\k(\mu_{t,\hat{\theta}})\big]\de t  \geq 0\ \text{ for all } \ \theta,\hat{\theta} \in \Th
\end{equation}

Consider any mechanism $(\mu, V, w)$ that satisfies the three constraints above. We are going to construct an alternative mechanism $(\tilde{\mu}, \tilde{V}, \tilde{w})$ with degenerate distributions that satisfies all constraints and weakly increases the principal's payoff.

Let $\tilde{x}_{\theta}$ be such that $\k(\delta_{\tilde{x}_{\theta}})= \k(\mu_{\theta})$. Then, define $\tilde{V}(\theta)=V(\theta)$,  $\tilde{\mu}_{\th,\hat{\theta}} = \delta_{\tilde{x}_{\hat \theta}}$, and $\tilde{w}_{\theta}$ be the contract that implements $\tilde{\mu}_{\theta}$ and delivers utility $V(\theta)$ to type $\theta$. By construction, and since the original mechanism satisfied all constraints, \eqref{obedience} and \eqref{envelope} are satisfied. For the feasibility of the alternative mechanism, it remains to check that \eqref{monotonicity} is also satisfied.

As the original mechanism was incentive compatible, it must be that $\k(\mu_{\theta})\geq \k(\mu_{t,t}) $ for all $\theta > t$. Then, $\tilde{x}_{\theta}\geq \tilde{x}_{t}$ for all $\theta> t$, which implies that $\tilde{\mu}$ satisfies \eqref{monotonicity}.

The final step is to show that the Principal's payoff has increased.  Note that the change has kept $\tilde{V}(\theta) = V(\theta)$ and $\k(\tilde{\mu}_{\theta}) = \k(\mu_{\theta})$. Hence,
\[u(\tilde{w}_{\theta}(\tilde{x}_{\theta})) =\int u(\tilde{w}_{\theta}(x))\tilde{\mu}_{\theta}(\de x) =    \int u(w_{\theta}(x))\mu_{\theta}(\de x)\]
As $u(\cdot)$ is concave, $\tilde{w}_{\theta}(\tilde{x}_{\theta})\leq \int w_{\theta}(x)\mu_{\theta}(\de x)$. Finally, as $z(\cdot)$ is convex
\[\k\left(\delta_{\tilde{x}_{\theta}}\right) = K\left(\int z(x)\mu_{\theta}(\de x)\right)\geq K\left(c\left(\int x\mu_{\theta}(\de x)\right)\right) = \k\left(\delta_{\int x \mu_{\theta}(\de x)}\right),\]
which implies that $\tilde{x}_{\theta}\geq \int x \mu_{\theta}(\de x)$. Hence, for all $\theta$
\[\tilde{x}_{\theta}-\tilde{w}_{\theta}(\tilde{x}_{\theta})\geq \int \Big\{x-w_{\theta}(x)\Big\}\mu_{\theta}(\de x)\],
which concludes the proof.
\qed

\subsection{Proof of \texorpdfstring{\Cref{prop:BinaryExample}}{Proposition \ref{prop:BinaryExample}}}   \label{sec:proof_BinaryExample}
We again denote a mechanism  by the triple: recommended distributions ($\mu_{\th,\hat{\theta}}$), utility levels ($V(\theta)$), and wage functions $(w_{\theta})$. Take any incentive compatible mechanism (satisfying Obedience, Envelope, and Monotonicity). We construct an alternative mechanism with $supp(\tilde{\mu}_{\theta}) \subseteq \{\underline{x},\overline{x}\}$ for all $\theta\in \Th$.

Define an alternative mechanism $\tilde{\mu}_{\th,\hat{\theta}}$, $\tilde{V}(\theta)$, and $\tilde{w}_{\theta}$ where: 
\begin{itemize}
    \item Restrict support but maintain costs: $supp(\tilde{\mu}_{\th,\hat{\theta}}) \subseteq \{\underline{x},\overline{x}\}$, with $\k(\tilde{\mu}_{\theta}) = \k(\mu_{\theta})$;
    \item Maintain same utility levels: $\tilde{V}(\theta)= V(\theta)$;
    \item Wages guarantee on-path obedience: $\tilde{w}_{\theta}$ following item 3 in Theorem 1 to implement $\tilde{\mu}_{\theta}$ for type $\theta$;
    \item Given wages, off-path guaranteed by construction: $\tilde{\mu}_{\th,\hat{\theta}} \in \underset{\mu}{argmax} \ \left\{\int u(\tilde{w}_{\hat{\theta}}(x))\mu(\de x)-(1-\theta)\k(\mu)\right\}$.
\end{itemize} 
We must show that the alternative mechanism is incentive compatible and increases the principal's payoff. 

Consider first incentive compatibility.
\paragraph{Obedience.} By construction of $\tilde w$ (on-path) and choice of $\tilde \mu_{\th, \hat\th}$ (off path).

\paragraph{Envelope constraint.} Clearly, $\k(\tilde{\mu}_{\theta}) = \k(\mu_{\theta})$ implies  $\int z(x)\tilde{\mu}_{\theta}(\de x) = \int z(x)\mu_{\theta}(\de x)$. 
Moreover, as $\tilde{V}(\theta)=V(\theta)$, the alternative mechanism inherits the Envelope constraint from the original mechanism. 

\paragraph{Monotonicity.} Recall that a sufficient condition for monotonicity is  $\k(\tilde{\mu}_{\th,\hat{\theta}})$ increasing in $\hat{\theta}$ for all $\theta$. 

When the original mechanism is in place, an agent of type $\theta$ who reports $\hat{\theta}$ and chooses $\mu$ gets a payoff:
\begin{align*}
& \int u(w_{\hat{\theta}}(x))\mu(\de x)-(1-\theta)\k(\mu) \\
= &  \int u\left(u^{-1}\left((1-\hat{\theta})K^{\prime}\left(\int z(s)\mu_{\hat \theta}(ds)\right)z(x)+V(\hat \theta)+(1-\hat{\theta})\left[\k(\mu_{\hat \theta})-\int z(s)\mu_{\hat{\theta}}(ds)\right]\right)\right)\mu(\de x)-(1-\theta)\k(\mu)\\
= & A(\hat{\theta})\int z(s)\mu(ds)+B(\hat{\theta})-(1-\theta)K\left(\int z(s)\mu(ds)\right),
\end{align*}
where $A(\theta) := (1-\theta)K^{\prime}\left(\int z(s)\mu_{\theta}(ds)\right)$, and $B(\theta) := V(\theta)+(1-\theta)\left[\k(\mu_{\theta})-\int z(s)\mu_{\theta}(ds)\right]$.

Equivalently, we can let the agent choose $\gamma:=\int z(s)\mu(ds)$. That is, 

\begin{align*}
    \gamma_{\th,\hat{\theta}} \in \underset{\gamma}{argmax} \ \left\{A(\hat{\theta})\gamma +B(\hat{\theta})-(1-\theta)K(\gamma)\right\}
\end{align*}
As the original mechanism satisfies monotonicity, it implies that $A(\cdot)$ must be increasing.

Note that under the alternative mechanism $\int z(s)\tilde{\mu}_{\theta}(ds)= \int z(s)\mu_{\theta}(ds)$ , $\k(\tilde{\mu}_{\theta})= \k(\mu_{\theta})$, and $\tilde{V}(\theta)=V(\theta)$. Hence, 
\begin{align*}
& \int u(\tilde{w}_{\hat{\theta}}(x))\mu(\de x)-(1-\theta)\k(\mu) \\
= &  \int u\left(u^{-1}\left((1-\hat{\theta})K^{\prime}\left(\int z(s)\tilde{\mu}_{\hat \theta}(ds)\right)z(x)+\tilde{V}(\hat \theta)+(1-\hat{\theta})\left[\k(\tilde{\mu}_{\hat \theta})-\int z(s)\tilde{\mu}_{\hat{\theta}}(ds)\right]\right)\right)\mu(\de x)-(1-\theta)\k(\mu)\\
= & A(\hat{\theta})\int z(s)\mu(ds)+B(\hat{\theta})-(1-\theta)K\left(\int z(s)\mu(ds)\right).
\end{align*}
Thus, as $A(\hat{\theta})$ is increasing, then $\int z(s)\tilde{\mu}_{\th,\hat{\theta}}(ds)$ in $\hat{\theta}$ and monotonicity is satisfied.
Therefore, the alternative mechanism is (IC). 
It remains to prove that it increases the principal's payoff.

\paragraph{Increasing principal's payoff.}
If an agent reports $\theta$ and chooses $\mu$, the principal's payoff is
\begin{align*}
& \int\left\{x-u^{-1}\left((1-\theta)K^{\prime}\left(\int z(s)\mu_{\theta}(ds)\right)z(x)+V(\theta)+(1-\theta)\left[\k(\mu_{\theta})-\int z(s)\mu_{\theta}(ds)\right]\right)\right\}\mu(\de x)\\
= &  \int\left\{\psi(\hat{z})-\varphi\left(A(\theta)\hat{z}+B(\theta)\right)\right\}\hat{\mu}(d\hat{z}),
\end{align*}
where  $\psi := c^{-1}$, $\varphi:=u^{-1}$, and $\hat{\mu}\in \D([z(\ul x),z(\bar x)])$ denotes the distribution over $z(x)$ generated by $\mu \in \D(X)$.
Note that the object inside the curly brackets is convex in $\hat{z}$ if its derivative is weakly positive for all $x$:
\begin{align*}
    \psi^{\prime\prime}(\hat{z}) - \varphi^{\prime\prime}\left(A(\theta)\hat{z}+B(\theta)\right)\left[A(\theta)\right]^{2}\geq 0.
\end{align*}
Note further that
$$\psi^{\prime\prime} \left(z(x)\right) = -\frac{z^{\prime\prime}(x)}{\left[z^{\prime}(x)\right]^{3}} \qquad \text{and} \qquad \varphi^{\prime\prime} \left(A z(x)+B\right) = -\frac{u^{\prime\prime}(A z(x)+B)}{\left[u^{\prime}(A z(x)+B)\right]^{3}}.$$
Hence, by \eqref{condition}, the principal's payoff is concave in $\hat{z}$. Therefore, when we replace  $\mu_{\theta}$ by $\tilde{\mu}_{\theta}$ the principal's payoff increases. Importantly, note that $B(\theta)$ is the same under $\mu_{\theta}$ and $\tilde{\mu}_{\theta}$.
\qed


