\begin{property} [refer to Lemma \ref{lem : mapping of paths in Df} in full version] \label{prop : r1}
    Let  $u,v$ be any pair of vertices mapped to different nodes $\mu$ and $\nu$ in $\mathcal{D}$. There exists an $(u,v)$-path $P$ in $G^f$ if and only if there exists a $(\mu,\nu)$-path $P_q$ in $\mathcal{D}\cup \mathcal{A}$. Moreover, path $P_q$ is a quotient path of $P$.
\end{property}
