\begin{remark}
    An immediate generalization of Theorem \ref{thm : maxflow and minimum+1 cut} would be the following. An $(s,t)$-cut $C$ is a $(\lambda+k)$ $(s,t)$-cut if and only if there are exactly $k$ edges in $E(C)$ that carry zero flow and every other edge carries flow in the direction $C$ to $\overline{C}$. %However, Figure \ref{fig: counter_example_theorem8_lemma5} shows that this generalization does not hold for $k\ge 2$. 
    However, Figure \ref{fig: counter_example_theorem8_lemma5}$(i)$ shows that 
    for $\lambda=2$, $(s,t)$-cut $C$ has capacity $k+2$ but there are $k-2$ edges in $E(C)$ carrying zero flow.
   Hence, this generalization of Theorem \ref{thm : maxflow and minimum+1 cut} is not possible for any $k\ge 2$.
\end{remark}


\subsection{Directed Weighted Graphs} \label{sec : directed weighted graph tool}
    For directed graphs, Lemma \ref{lem : maxflow and minimum+k cut}$(2)$, as well as Theorem \ref{thm : maxflow and minimum+1 cut}, does not necessarily hold. This is because there exist edges incoming to a cut in directed graphs, and hence, Equation \ref{equation : undirected graphs} fails to satisfy. %{\color{red}is not true}. %for directed unweighted graphs 
    (refer to Figure \ref{fig: counter_example_theorem8_lemma5}$(ii)$). 
    Observe that the following lemma immediately follows from the Theorem \ref{thm : maxflow mincut theorem} (Maxflow-Mincut Theorem).
    \begin{lemma} \label{lem : alternative maxflow mincut}
        For any maximum $(s,t)$-flow $f$, %the capacity of an $(s,t)$-cut $C$ is $\lambda$ in $G$
    an $(s,t)$-cut $C$ is an $(s,t)$-mincut if and only if the capacity of $C$ is $0$ in the corresponding residual graph $G^f$.
    \end{lemma}
     Interestingly, for directed weighted graphs, the result in Lemma \ref{lem : alternative maxflow mincut} can be extended to $(\lambda+\Delta)$ $(s,t)$-cuts, where $\Delta \ge 0$ as shown in the following theorem. %(the proof is provided in Appendix \ref{sec : ommited proof of maxflow min+k}). %{\color{red}discuss the wording--$>$}
     %This theorem can be established using the conservation of flow and the construction of the residual graph (the proof is provided in Appendix \ref{sec : ommited proof of maxflow min+k}). %{\color{red} (place the appropriate link for Appendix here)}. 
     % {\color{brown}      It also plays a key role in establishing our main results in the following sections.  }

\begin{theorem}[\text{Maxflow (Min+$\Delta$)-cut Theorem}] \label{thm : min+k in residual graph} 
    Let $G=(V,E)$ be a directed weighted graph %with positive edge weights %$w:E \rightarrow \mathbb{R}^{+}$
    with a designated source vertex $s$ and a designated sink vertex $t$.
    Let $f$ be any maximum $(s,t)$-flow in $G$ and $G^f$ be the corresponding residual graph. Let $C$ be an $(s,t)$-cut in $G$. The capacity of $C$ in $G$ is $(\lambda+\Delta)$ if and only if the capacity of $C$ in $G^f$ is $\Delta$, where $\Delta\ge 0$.    
\end{theorem}
\begin{proof}
    Let $E_{out}(A,H)$ (likewise $E_{in}(A,H)$) denote the set of outgoing edges (likewise the set of incoming edges) of a cut $A$ in a graph $H$.
    For any edge $e$ in $G$, let $r(e)$ be the residual capacity, that is, $r(e)=w(e)-f(e)$.
    For any edge $e$ in graph $G^f$, let $w'(e)$ denote the capacity of edge $e$.
    By construction of $G^f$, for each edge $e=(u,v) \in E_{out}(C,G)$ with $r(e)\neq 0$, there exists a forward edge $(u,v) \in E_{out}(C,G^f)$ with $w'(u,v)=r(e)$. Similarly, for each edge $e=(u,v) \in E_{in}(C,G)$ with $f(e)\ne 0$, there exists a backward edge $(v,u) \in E_{out}(C,G^f)$ with $w'(v,u)=f(e)$.
    This provides us with the following equality. 
   \begin{align}\label{eq : 3}
        \begin{split}
         \sum_{e'\in E_{out}(C,G^f)} w'(e')&=\sum_{e\in E_{out}(C,G)}r(e)+ \sum_{e\in E_{in}(C,G)}f(e)\\ 
         &=\sum_{e\in E_{out}(C,G)}(w(e)-f(e))+ \sum_{e\in E_{in}(C,G)}f(e)\\
         &=\sum_{e\in E_{out}(C,G)}w(e)-\sum_{e\in E_{out}(C,G)}f(e) + \sum_{e\in E_{in}(C,G)}f(e)\\
         %&=c(C)-f_{out}(C)+f_{in}(C)\\
         &=c(C)-(f_{out}(C)-f_{in}(C))\\
         &=c(C)-\lambda \quad\quad \text{ Using Lemma \ref{lem : flow conservation}}
       \end{split}
    \end{align}
Equation \ref{eq : 3} completes the proof.
\end{proof}

\section{Limitation of the Existing Algorithm for Second (s,t)-mincut} \label{sec : limitation}
 We state here a limitation of the existing  %giving a brief overview of the previous 
algorithm given by Vazirani and Yannakakis \cite{vazirani1992suboptimal} to compute a second $(s,t)$-mincut. 
The algorithm for computing an $(s,t)$-cut of $k^{th}$ minimum capacity by \cite{vazirani1992suboptimal} uses ${\mathcal O}(n^{2(k-1)})$ maximum $(s,t)$-flows. So, for $k=2$, the algorithm uses ${\mathcal O}(n^2)$ maximum $(s,t)$-flow computations. In the same article \cite{vazirani1992suboptimal}, they stated the following property. 
 \begin{lemma}[Lemma 3.2(1) in \cite{vazirani1992suboptimal}] 
   Let $G^f$ be the residual graph corresponding to a maximum $(s,t)$-flow $f$ in $G$. Let $H$ be an SCC in $G^f$ and $u,v$ be a pair of vertices in $H$. If the capacity of the least capacity cut separating $\{u\}$ and $\{v\}$ is $k$ in $H$, then the least capacity cut separating $\{s,u\}$ and $\{v,t\}$ has capacity $\lambda+k$ in $G$.
\label{lem: vazirani wrong lemma}
\end{lemma}
\begin{figure}[ht]
 \centering  \includegraphics[width=0.8\textwidth]{Lemma_3.2_of_VY_is_wrong.png} 
  \caption{A counter example for Lemma 3.2(1) in \cite{vazirani1992suboptimal}
  $(i)$ A graph $G$. $V\setminus \{t\}$ is the $(s,t)$-mincut in $G$ with capacity $1$ and $c(A)$=22. $(ii)$ $H$ is an  SCC in $G^f$ and $c(B,H)=2$ 
 }
    \label{fig: counter_examples_VY92}
\end{figure}
 Vazirani and Yannakakis \cite{vazirani1992suboptimal} used Lemma \ref{lem: vazirani wrong lemma} to design an algorithm that computes second $(s,t)$-mincut using ${\mathcal O}(n)$ maximum $(s,t)$-flow computations (the algorithm preceding Theorem 3.3 in \cite{vazirani1992suboptimal}). 
Unfortunately,  Lemma \ref{lem: vazirani wrong lemma} (or Lemma 3.2(1) in \cite{vazirani1992suboptimal}) is not correct as shown in Figure \ref{fig: counter_examples_VY92}$(ii)$. $H$ is the SCC in $G^f$ containing vertices $u$ and $v$. The least capacity cut $B$ separating $\{u\}$ and $\{v\}$ has capacity $2$ in $H$. 
By Lemma \ref{lem: vazirani wrong lemma}, the least capacity cut separating $\{s,u\}$ and $\{v,t\}$ must have capacity $2+1=3$ in $G$. 
However, as it can be verified easily using Figure \ref{fig: counter_examples_VY92}$(i)$, $A$ is a least capacity cut separating $\{s,u\}$ and $\{v,t\}$ in $G$ and its capacity is $22$.
Therefore, the algorithm stated above Theorem 3.3 in \cite{vazirani1992suboptimal}, fails to correctly output a second $(s,t)$-mincut. 
