\begin{lemma} \label{lem : unique anchor edge}
    Given any maximum $(s,t)$-flow in $G$, for every $(\lambda+1)$ $(s,t)$-cut $C$, there is exactly one anchor edge that contributes to $C$.
\end{lemma}
