\section{Handling Dual Edge Insertions} \label{sec: handling dual edge insertion}
%
%We consider $G$ to be an undirected multi-graph
Suppose the two query edges to be inserted into simple graph $G$ are 
%Suppose the two inserted edges are 
$e_1=(x_1,y_1)$ and $e_2=(x_2,y_2)$. 
% Firstly, we state an existing result for residual graph $G^f$ 
% which is immediate from Lemma \ref{lem : ford fulkerson augmenting paths}.
For any directed graph $H_d$ and an undirected edge $e=(a,b)$, let $H_d\cup \{e\}$ denote the graph obtained from $H_d$ after insertion of pair of directed edges $(a,b)$ and $(b,a)$. We first state the following immediate corollary of Lemma \ref{lem : ford fulkerson augmenting paths}.
\begin{lemma} [\cite{ford_fulkerson_1956}] \label{lem : insertion in Gf}
    Upon insertion of an edge $e$ in $G$, the value of maximum $(s,t)$-flow can increase in $G\cup \{e\}$ if and only if there is an $(s,t)$-path in $(G^f \cup \{e\})$. 
\end{lemma}

The following lemma shows that $\mathcal{D}_{PQ}(G)$ can be used to report an $(s,t)$-mincut after the insertion of a single edge in $\mathcal{O}(n)$ time.
\begin{lemma} [\cite{DBLP:journals/mp/PicardQ80} and Lemma 4.4 in \cite{baswana2023minimum+}] \label{lem : single edge insertion}
     For any undirected multi-graph $\mathcal{G}$, upon the insertion of any edge $e=(u,v)$, the capacity of $(s,t)$-mincut increases by $1$ if and only if $u$ is mapped to sink $\mathbb{S}$ and $v$ is mapped to source $\mathbb{T}$ or vice-versa in ${\mathcal D}_{PQ}(\mathcal{G})$. Moreover, %if the capacity of $(s,t)$-mincut increases,
     the set of vertices mapped to $\mathbb{S}$ defines an $(s,t)$-mincut in $\mathcal{G}\cup \{e\}$.
\end{lemma}
%D and e
Similar to handling the failure of edges in Appendix \ref{sec : handling dual edge in subquadratic space}, our main objective is to construct $\mathcal{D}_{PQ}(G\cup \{e_1\})$ by only using DAG $\mathcal{D}(\mathcal{A})$ and set of edges $\mathcal{A}$ from Theorem \ref{thm: structure for min+1}.
% For simplicity of exposition, we use $D_\mathcal{A}$ to denote the graph $\mathcal{D}(\mathcal{A})\cup \mathcal{A}$.
Using the fact $\mathcal{D}(\mathcal{A})\cup \mathcal{A}$ is a quotient graph of $G^f$, along a similar lines to the proof of Lemma \ref{lem : mapping of paths in Df}, we can establish the followin lemma.

\begin{lemma} \label{lem : path in Gf and Df for insertion}
    Upon the insertion of any edge $e$ in $G^f$, there exists an $(s,t)$-path $P_r$ in $G^f\cup \{e\}$ if and only if there exists an $(s,t)$-path $P$ in  $(\mathcal{D}(\mathcal{A})\cup \mathcal{A})\cup \{e\}$. Moreover, $P$ is a quotient path of $P_r$.
    \label{lem : equivalence between D(F) and Gf}
\end{lemma}

We now use $(\mathcal{D}(\mathcal{A})\cup \mathcal{A}) \cup \{e_1\}$ to determine whether flow $f$ is also a maximum $(s,t)$-flow in $G \cup \{e_1\}$ or whether its value can increase by $1$.
We verify whether there exists an $(s,t)$-path $P$ in graph $(\mathcal{D}(\mathcal{A})\cup \mathcal{A}) \cup \{e_1\}$. Suppose path $P$ exists.
%
It follows from Lemma \ref{lem : path in Gf and Df for insertion} that there is an $(s,t)$-path $P_r$ in $G^f$ such that $P$ is a quotient path of $P_r$.
So, by Lemma \ref{lem : insertion in Gf}, the capacity of $(s,t)$-mincut is $\lambda+1$ in $G\cup \{e_1\}$.
Upon updating path $P_r$ in $G^{f}$ by following the construction of residual graph, let $f_2$ be the maximum $(s,t)$-flow of value $\lambda+1$ obtained in $G\cup\{ e_1\}$ and let $G^{f_2}$ be the corresponding residual graph.
Since $\mathcal{D}(\mathcal{A})\cup \mathcal{A}$ is a quotient graph of $G^f$, instead of updating $P_r$, we update path $P$ in $(\mathcal{D}(\mathcal{A})\cup \mathcal{A}) \cup \{e_1\}$ by following the construction of residual graph (refer to Section \ref{sec : preliminaries}) to obtain graph $D_2$. 
The above steps can be executed in ${\mathcal O}(\min\{m,n\sqrt{\lambda}\})$ time.
%
If there exists no $(s,t)$-path in $(\mathcal{D}(\mathcal{A})\cup \mathcal{A}) \cup \{e_1\}$, then $D_2$ is the same as $(\mathcal{D}(\mathcal{A})\cup \mathcal{A}) \cup \{e_1\}$, $G^{f_2}=G^f$, and the capacity of $(s,t)$-mincut is $\lambda$ in $G\cup \{e_1\}$. We now establish the following relation between graph $D_2$ and $G^{f_2}$.

% Since, the insertion of an edge can only increase the capacity of a cut.
\begin{lemma} \label{lem : property of D2 for insertion}
    Graph $D_2$ satisfies the following three properties. 
    \begin{enumerate}
        \item $D_2$ is a quotient graph of $G^{f_2}$, where $f_2$ is a maximum $(s,t)$-flow in $G\cup \{e_1\}$.
        \item A pair of vertices $u,v$ are mapped to the same node in ${\mathcal D}({\mathcal A})$ if and only if $u,v$ are mapped to the same node in $D_2$.
         \item If a pair of vertices $u,v$ is mapped to a node in $D_2$ then $u,v$ belong to the same SCC in $G^{f_2}$.
    \end{enumerate}
\end{lemma}
\begin{proof}
    The proof of properties (1) and (2) follows directly from the construction of $D_2$. We now establish the property (3) of $D_2$. 
    Suppose $u,v$ are a pair of vertices that are mapped to the same node in $D_2$. It follows from Theorem \ref{thm: structure for min+1} that any $(s,t)$-cut that separates $u,v$ has capacity at least $\lambda+2$ in $G$. Insertion of edge $e_1$ can only increase the capacity of any $(s,t)$-cut. Therefore, by property (2), the least capacity $(s,t)$-cut in $G\cup \{e_1\}$ that separates vertices $u,v$ has capacity at least $\lambda+2$. Moreover, the capacity of $(s,t)$-mincut in $G\cup \{e_1\}$ is at most $\lambda+1$. Therefore, by Lemma \ref{lem :mapping of nodes in Dpq}, $u,v$ are mapped to the same node in $\mathcal{D}_{PQ}(G\cup \{e_1\})$. By construction of $\mathcal{D}_{PQ}(G\cup \{e_1\})$, $u,v$ belong to the same SCC in $G^{f_2}$.
 \end{proof} 
 % change the $\mathbb{D}$ to $\mathcal{R}$ in failure}
% \begin{proof}
%     The proof of properties (1) and (2) follows directly from the construction of $D_2$. We now establish the property (3) of $D_2$. It follows from Theorem \ref{thm : minimum+1 (s,t)-cut} that any $(s,t)$-cut that separates any pair of vertices mapped to the same node in ${\mathcal D}({\mathcal A})$ has capacity at least $\lambda+2$ in $G$. Insertion of edge $e_1$ can only increase the capacity of any $(s,t)$-cut. Therefore, by property (2), the least capacity $(s,t)$-cut in $G\cup \{e_1\}$ that separates any pair of vertices $u,v$ mapped to the same node in $D_2$ has capacity at least $\lambda+2$. Moreover, the capacity of $(s,t)$-mincut in $G\cup \{e_1\}$ is at most $\lambda+1$. Therefore, by Lemma \ref{lem :mapping of nodes in Dpq}, $u,v$ belong to the same SCC in $G^{f_2}$.
% \end{proof}
We now obtain DAG ${\mathcal D}_{PQ}(G\cup \{e_1\})$ from graph $D_2$. Let ${\mathcal I}$ be the graph obtained by contracting every SCC of $D_2$. The following relation between ${\mathcal D}_{PQ}(G\cup \{e_1\})$ and ${\mathcal I}$ can be established along similar lines to Lemma \ref{lem : mapping of node in Dpq and D} using Lemma \ref{lem : property of D2 for insertion}.

\begin{lemma} \label{lem : mapping of node in Dpq and I}
     A pair of vertices $u,v$ are mapped to the same node in ${\mathcal I}$ if and only if $u,v$ are mapped to the same node in ${\mathcal D}_{PQ}(G\cup \{e_1\})$.  
\end{lemma}
% We now contract each SCC of $D_2$ 
