%     Suppose there is a pair of vertices $u,v$ that are mapped to the same node in ${\mathcal I}$. It follows from the construction of ${\mathcal I}$ that $u,v$ are either mapped to the same node in $D_2$ or belong to an SCC in $D_2$. In the former case, by Lemma \ref{lem : property of D2}(3), $u,v$ belong to the same SCC in $G^{f_2}$. We now consider the latter case. It follows from Lemma \ref{lem : property of D2}(1) and (3) that a pair of vertices belonging to an SCC in $D_2$ also belongs to an SCC in $G^{f_2}$. Hence, by construction, $u,v$ are mapped to the same node in ${\mathcal D}_{PQ}(G\cup \{e_1\})$.

%     We now prove the converse part. Suppose $u$ and $v$ are mapped to the same node of ${\mathcal D}_{PQ}(G\cup \{e_1\})$. It implies from the construction of ${\mathcal D}_{PQ}(G\cup \{e_1\})$ that $u$ and $v$ belong to the same SCC in the residual graph $G^{f_2}$ for maximum $(s,t)$-flow $f_2$ in $G\cup \{e_1\}$. Therefore, by Lemma \ref{lem : property of D2}(1), $u$ and $v$ are either belong to the same node in $D_2$ or in an SCC in $D_2$. Hence, by construction, $u$ and $v$ are mapped to the same node in ${\mathcal I}$. 
% \end{proof}
It follows from Lemma \ref{lem : property of D2 for insertion}(1) and Lemma \ref{lem : mapping of node in Dpq and I} that the set of edges in $\mathcal{I}$ is the same as the set of edges in ${\mathcal D}_{PQ}(G\cup \{e_1\})$. Therefore, the following lemma is immediate.

\begin{lemma} \label{lem : Dpq same as D2 for insertion}
    Graph ${\mathcal I}$ is the graph $\mathcal{D}_{PQ}(G\cup \{e_1\})$.
\end{lemma}

It follows from Lemma \ref{lem : Dpq same as D2 for insertion} that given ${\mathcal D}({\mathcal A})$ and set of edges ${\mathcal A}$, there is an algorithm that, %{\color{brown}repeated also it is only $O(n)$ so it has tobe broekn} 
using ${\mathcal O}(\min\{{m,n\sqrt{\lambda}}\})$ space, can compute graph ${\mathcal D}_{PQ}(G\cup \{e_1\})$ in ${\mathcal O}(\min\{{m,n\sqrt{\lambda}}\})$ time.
Hence, we can use Lemma \ref{lem : single edge insertion} to check whether the insertion of edge $e_2$ in $G \cup \{e_1\}$ increases the capacity of $(s,t)$-mincut.
Suppose $e_2$ satisfies the condition stated in Lemma \ref{lem : single edge insertion} for $\mathcal{D}_{PQ}(G\cup \{e_1\})$. If the $(s,t)$-mincut capacity in $G\cup \{e_1\}$ is $\lambda+1$ (likewise $\lambda$), then after the insertion of two edges $e_1,e_2$, the capacity of $(s,t)$-mincut in $G$ is $\lambda+2$ (likewise $\lambda+1$). 
%Similarly, if the $(s,t)$-mincut capacity in $G\cup \{e_1\}$ is $\lambda$, then after the insertion of two edges $e_1,e_2$, the capacity of $(s,t)$-mincut in $G$ is $\lambda+1$.
% In a similar way, we can determine the capacity of $(s,t)$-mincut in $G$ after the insertion of two edges $e_1,e_2$ if $e_2$ does not satisfy Lemma \ref{lem : single edge insertion}.
If $e_2$ fails to satisfy the condition stated in Lemma \ref{lem : single edge insertion} for ${\mathcal D}_{PQ}(G\cup \{e_1\})$, the capacity of $(s,t)$-mincut in $G$ after the insertion of edges $e_1,e_2$ is the same as the capacity of $(s,t)$-mincut in $G\cup \{e_1\}$.
 % Moreover, again by Lemma \ref{lem : single edge failure}, reporting an $(s,t)$-mincut in $G\setminus \{e_1\}$ after the failure of edge $e_2$ requires ${\mathcal O}(m)$ time. 
Moreover, the reported $(s,t)$-mincut using Lemma \ref{lem : single edge insertion} in $\mathcal{D}_{PQ}(G\cup \{e_1\})$ is also an $(s,t)$-mincut in $G$ after the insertion of two edges $e_1,e_2$.
Therefore, overall ${\mathcal O}(\min\{{m,n\sqrt{\lambda}}\})$ time  is required to report an $(s,t)$-mincut and its capacity after the insertion of edges $e_1,e_2$ in graph $G$. This leads to the following theorem. 
\begin{theorem} [Dual Edge Insertions for Simple Graphs] \label{thm : insertion for multi-graphs}
    Let $G$ be an simple graph on $n$ vertices and $m$ edges with designated source and sink vertices $s$ and $t$ respectively. There exists a data structure occupying ${\mathcal O}(\min \{m,n\sqrt{\lambda}\})$ space that can report an $(s,t)$-mincut in ${\mathcal O}(\min \{m,n\sqrt{\lambda}\})$ time after the insertion of any pair of given query edges in $G$.
\end{theorem}




