It follows from Lemma \ref{lem : edge disjoint paths and min+1} that we only need to efficiently find a vertex $x$ such that there is exactly one  edge disjoint path from $s$ to $x$ in $G^f$.
We use the concept of \textit{dominance} with respect to vertex $s$ to achieve this goal as follows.
A vertex $v$ is called a \textit{dominator} of a vertex $u$ if every $(s,u)$-path contains vertex $v$.
A dominator tree of a graph %with a root vertex $s$ 
is defined as follows. %has the following property.

\begin{theorem}[Dominator Tree \cite{tarzandominator1979}]\label{thm : dominator}
     Let $\mathcal{G}$ be any directed multi-graph. Let $T_{\mathcal{G}}$ denote the dominator tree of $\mathcal{G}$ on vertex set $V$ with root vertex $s$. $T_{\mathcal{G}}$ is a directed tree rooted at $s$ such that the following property holds. For any pair of vertices $u,v \in V$, $v$ is an ancestor of $u$ in $T_\mathcal{G}$ if and only if $v$ is a dominator of $u$ in $\mathcal{G}$. 
\end{theorem}
Observe that in graph $G^f$, there is exactly one edge-disjoint path from $s$ to $x$ if and only if there exists an edge $e'$ such that every $(s,x)$-path contains $e'$. However, for any vertex $u$, even if $v$ is a dominator of a vertex $u$, it is quite possible that there are more than one edge-disjoint $(s,u)$-paths in $G^f$. So, a dominator tree for $G$ does not immediately help in determining whether there is exactly one edge-disjoint $(s,u)$-path in $G^f$. We now construct a graph $\mathcal{H}$ from $G^f$ whose dominator tree helps in achieving our objective.

\paragraph*{Construction of $\mathcal{H}=(V',E')$:} 
For each edge $(u,v)$ in $G^f$, split edge $(u,v)$ into two edges $(u,w)$ and $(w,v)$ using a new vertex $w$. It follows that the number of vertices, as well as edges, in $\mathcal{H}$ is $\mathcal{O}(m)$.

To design our algorithm, we begin by classifying the vertices in $\mathcal{H}$ as follows. A vertex $v \in V'$ is said to be \textit{marked} if $v \notin V$, otherwise, it is said to be \textit{unmarked}. 
It follows from the construction of ${\mathcal H}$ that there exists a marked vertex $v$ in $\mathcal{H}$ corresponding to every edge $e'$ in $G^f$ and vice versa. Let $T_\mathcal{H}$ be the dominator tree of $\mathcal{H}$ with root vertex $s$. We now establish the following relation between $T_\mathcal{H}$ and graph $G^f$.

\begin{lemma}\label{lem : dominator in modified graph}
    Let $v$ be a marked vertex in $\mathcal{H}$ corresponding to an edge $e'$ in $G^f$. $v$ is an ancestor of an unmarked vertex $u$ in $T_\mathcal{H}$ if and only if every $(s,u)$-path contains $e'$ in $G^f$.
\end{lemma}
\begin{proof}
    Suppose marked vertex $v$ is an ancestor of an unmarked vertex $u$ in $T_\mathcal{H}$. It follows from Theorem \ref{thm : dominator} that each $(s,u)$-path in $\mathcal{H}$ contains $v$. It follows from the construction of $\mathcal{H}$ that each $(s,u)$-path contains the edge $e'$ (corresponding to $v$) in $G^f$. 

    Suppose $u$ is an unmarked vertex and every $(s,u)$-path contains edge $e'$ in $G^f$. 
    %Let the edge $e'=(w,u)$.
    By construction of $\mathcal{H}$, every $(s,u)$-path contains marked vertex $v$ (corresponding to edge $e'$ in $G^f$) in $\mathcal{H}$.
    By Theorem \ref{thm : dominator}, $v$ is ancestor of $u$ in $T_\mathcal{H}$. %Therefore, $u$ is an unmarked vertex that appears in the subtree rooted at $v$ in $\mathcal{H}$.    
\end{proof}    
We now use Lemma \ref{lem : dominator in modified graph} to establish a relation between the dominator tree $T_\mathcal{H}$ and $(\lambda+1)$ $(s,t)$-cuts in graph $G$.

\begin{lemma} \label{lem : dominator with min+1 st cut}
    Let $v$ be a marked vertex in $\mathcal{H}$ and let the edge in $G^f$ corresponding to $v$ be $e'=(w,u)$.
    $v$ is an internal vertex in $T_\mathcal{H}$ with child $u$ if and only if there exists a $(\lambda+1)$ $(s,t)$-cut $C$ in $G$ such that the only edge outgoing from $C$ in $G^f$ is edge $e'$.
\end{lemma}
\begin{proof}
    Suppose $v$ is an internal marked vertex in $T_\mathcal{H}$ with child $u$.
    By construction of $\mathcal{H}$, $u$ is an unmarked vertex, since $e'=(w,u)$ in $G^f$.
    By Lemma \ref{lem : dominator in modified graph}, every $(s,u)$-path contains edge $(w,u)$ in $G^f$. 
    Therefore, it is easy to show that the least capacity $(s,t)$-cut in $G^f$ that separates $\{s,w\}$ from $\{u,t\}$ has capacity one, since $t$ has indegree $0$.
    By Theorem \ref{thm : min+k in residual graph}, $C$ is a $(\lambda+1)$ $(s,t)$-cut in $G$ with $u \in \overline{C}$ such that only $e'$ contributes to $C$ in $G^f$.
    % Hence, there exists exactly one edge-disjoint $(s,u)$-path in $G^f$.
    % % By Lemma \ref{lem : edge disjoint paths and min+1}, there exists a $(\lambda+1)$ $(s,t)$-cut $C$ in $G$ with $u \in \overline{C}$. Moreover, it can be established using Theorem \ref{thm : dominator} that there exists an $(s,t)$-cut $C$ such that only $e'$ contributes to $C$ in $G^f$.
    % Moreover, since $t$ has indegree zero, it follows that there exists a $(\{s,w\},\{u,t\})$-cut $C$ such that exactly edge $(w,u)$ contributes to $C$ in $G^f$. By Theorem \ref{thm : min+k in residual graph}, $C$ is a $(\lambda+1)$ $(s,t)$-cut in $G$ with $u \in \overline{C}$ such that only $e'$ contributes to $C$ in $G^f$.

    Suppose there exists a $(\lambda+1)$ $(s,t)$-cut $C$ in $G$ such that the only edge outgoing from $C$ in $G^f$ is edge $e'$. 
    Since $u \in \overline{C}$, it follows that every $(s,u)$-path must contain edge $e'$ in $G^f$. By Lemma \ref{lem : dominator in modified graph}, $v$ is an ancestor of $u$ (unmarked vertex) in $T_\mathcal{H}$.     
    By construction of $\mathcal{H}$, $(v,u)$ is an edge in $\mathcal{H}$. Hence, $v$ is the parent of $u$ in $T_\mathcal{H}$. 
\end{proof}

Now, we state the algorithm for computing a $(\lambda+1)$ $(s,t)$-cut in $G$.
\paragraph*{Algorithm:}
The algorithm begins by computing $G^f$ and graph $\mathcal{H}$ using maximum $(s,t)$-flow $f$ in $G$.
Compute the dominator tree $T_\mathcal{H}$ from $\mathcal{H}$ using the ${\mathcal O}(m)$ time algorithm given in \cite{dominator/alstrup1999dominators}. 
% This takes $\mathcal{O}(m)$ time.
To determine the existence of a $(\lambda+1)$ $(s,t)$-cut in $G$, find a marked internal vertex in $T_\mathcal{H}$.
If there does not exist any marked internal vertex in $T_\mathcal{H}$, by Lemma \ref{lem : dominator with min+1 st cut}, there exists no $(\lambda+1)$ $(s,t)$-cut in $G$ and the algorithm terminates.
Suppose there exists an internal marked vertex $v$ in $T_\mathcal{H}$ with child $u$. 
By Lemma \ref{lem : dominator with min+1 st cut}, there is a $(\lambda+1)$ $(s,t)$-cut $C$ in $G$ such that $u \in \overline{C}$. Obtain graph $G_u$ from graph $G^f$ by adding a pair of edges between $u$ and $t$. Compute a maximum $(s,t)$-flow in graph $G_u$ using the algorithm of Ford and Fulkerson \cite{ford_fulkerson_1956}. This completes the proof of the following lemma.
\begin{lemma}\label{lem : computing min+1 in a rgaph with one st mincut}
    Let $G$ be a graph with exactly one $(s,t)$-mincut $V\setminus \{t\}$ $($or $\{s\})$. There is an algorithm that, given a maximum $(s,t)$-flow, computes a $(\lambda+1)$ $(s,t)$-cut in $G$ in $\mathcal{O}(m)$ time.
\end{lemma}

\subsection{Graphs with Exactly two (s,t)-mincuts} \label{sec : min+1 using covering}
%Observe that the algorithm stated in Lemma \ref{lem : computing min+1 in a rgaph with one st mincut} computes a $(\lambda+1)$ $(s,t)$-cut by crucially using Lemma \ref{lem : edge disjoint paths and min+1}. However,
Lemma \ref{lem : edge disjoint paths and min+1} fails to hold when $G$ has exactly $2$ $(s,t)$-mincuts: $\{s\}$ and $V \setminus\{t\}$. This is because $s$ has outdegree $0$ in the residual graph $G^f$ and there is no path from $s$ to any vertex. 
Similar to the proof of Lemma \ref{lem : n maxflow}, we can address this problem by constructing the pair of graphs $G^I$ and $G^U$ (as constructed in the algorithm for second $(s,t)$-mincut stated in Lemma \ref{lem : n maxflow}) using the covering technique of \cite{baswana2023minimum+}.
% Let $x$ be any arbitrary vertex other than $s,t$.
% We obtain two graphs $G^I$ (likewise $G^U$) are obtained from $G^f$ by adding  two edges from $s$ to $x$ (likewise $x$ to $t$), such that the following property holds.
% % We obtain two graphs $G^I$ and $G^U$ by adding  such that the following property holds.
% $V\setminus\{t\}$ is the only $(s,t)$-mincut in $G^I$ and $\{s\}$ is the only $(s,t)$-mincut in $G^U$. 
% Moreover, every $(\lambda+1)$ $(s,t)$-cut in $G$ appears in exactly one of the graphs $G^I,G^U$.
It follows that Lemma \ref{lem : computing min+1 in a rgaph with one st mincut} is satisfied in both the graphs $G^I$ and $G^U$. This leads to the following lemma. 

\begin{lemma}\label{lem : computing min+1 in a rgaph with two st mincut}
    Let $G$ be any graph with exactly two $(s,t)$-mincuts $\{s\}$ and $V\setminus \{t\}$. There is an algorithm that, given a maximum $(s,t)$-flow, computes a $(\lambda+1)$ $(s,t)$-cut in $G$ in  $\mathcal{O}(m)$ time.
\end{lemma}
Using Lemma \ref{lem : computing min+1 in a rgaph with one st mincut} and Lemma \ref{lem : computing min+1 in a rgaph with two st mincut}, we can compute a $(\lambda+1)$ $(s,t)$-cut in general graphs as shown in Appendix \ref{sec : extension to egenral graphs} with the following slight modification. Instead of working with each SCC $H$, here we compute $(\lambda+1)$ $(s,t)$-cuts in the graph $G_\mu$ constructed for the node $\mu$ of ${\mathcal D}_{PQ}(G)$ corresponding to $H$ (refer to Appendix \ref{sec : extension to egenral graphs}).
Observe that each edge $(\mu_1,\mu_2)$ in $\mathcal{D}_{PQ}(G)$ appears in exactly two graphs -- $G_{\mu_1}$ and $G_{\mu_2}$. Moreover, due to the use of Covering Technique \cite{baswana2023minimum+}, each edge and vertex in $G_\mu$ is counted at most twice. Hence, the total number of vertices and edges across all graphs $G_\mu$ are $\mathcal{O}(n)$ and $\mathcal{O}(m)$ respectively. This completes the proof of Theorem \ref{thm : minimum+1 (s,t)-cut}.

