\section{Space Occupied by $\mathcal{D}(G\setminus \mathcal{A})$ in Undirected Multi-graphs}\label{sec : size of Dpq}
% To analyze the space required by our compact structure $\mathcal{D}_{PQ}(G\setminus \mathcal{A})$, 
In this section, we establish an upper bound on the space required by $\mathcal{D}_{PQ}$ for undirected multi-graphs using only existing results. %immediate from existing results. 
We first state the following property for $\mathcal{D}_{PQ}$ which holds for undirected graphs.
\begin{lemma}[\cite{DBLP:journals/mp/PicardQ80,ford_fulkerson_1956}] \label{lem : every edge has flow in Dpq}
    Let $f$ be any maximum $(s,t)$-flow in any undirected graph ${G}$.
    For any edge $e=(x,y)$ in ${\mathcal D}_{PQ}({G})$, the corresponding undirected edge $e$ in ${ G}$ satisfies
    $f(e)=w(e)$ and $e$ carries flow in the direction $y$ to $x$. 
\end{lemma}
% By Lemma \ref{lem : every edge has flow in Dpq}, to bound the number of edges in ${\mathcal D}_{PQ}$, it suffices to bound the number of edges carrying flow.
%Note that the number of edges carrying flow in any arbitrary $(s,t)$-maxflow  might be $\Omega(n^2)$. 
An $(s,t)$-flow is said to be acyclic if there is no directed cycle in which every edge carries flow in the direction of the cycle.
For any integral acyclic maximum $(s,t)$-flow in an undirected integer-weighted graph,
the number of edges carrying flow is bounded by the following lemma.
\begin{lemma}[\cite{shortlengthversionofmengerstheorem} and Lemma 12 in \cite{henzingericalp2023}] \label{lem : cardinality of set flow}
    Let ${G}$ be any undirected integer-weighted graph with no parallel edges and $(s,t)$-mincut capacity $\lambda$. For any integral acyclic maximum $(s,t)$-flow in ${G}$, the number of edges carrying flow in ${G}$ is $\mathcal{O}(\min \{m,n \sqrt{\lambda}\})$.
\end{lemma}
% Since, $\mathcal{D}_{PQ}$ is a DAG, by Lemma \ref{lem : every edge has flow in Dpq}, the following lemma is immediate.
% By the Maxflow-Mincut Theorem, every edge in the edge-set of an $(s,t)$-mincut carries flow in an undirected multi-graph. By Theorem \ref{thm : dag for st mincut and characterization}, an edge $e$ belongs to $\mathcal{D}_{PQ}(\mathcal{G})$  if and only if $e$ contributes to an $(s,t)$-mincut in $\mathcal{G}$. 
It follows from Lemma \ref{lem : every edge has flow in Dpq} that for every edge $e$ of ${\mathcal D}_{PQ}({\mathcal G})$, the corresponding undirected edge $e$ carries flow in any maximum $(s,t)$-flow in ${\mathcal G}$. As a result, they also carry flow in any integral acyclic maximum $(s,t)$-flow. Therefore, the following lemma is immediate from Lemma \ref{lem : cardinality of set flow}. 
\begin{lemma}\label{lem : size of Dpq in integer weighted}
    For any undirected integer-weighted graph ${G}$ with $(s,t)$-mincut capacity $\lambda$, the space occupied by DAG $\mathcal{D}_{PQ}({G})$ is $\mathcal{O}(\min\{m,n\sqrt{\lambda}\})$. 
\end{lemma}
% For any undirected integer-weighted graph, using the result of \cite{shortlengthversionofmengerstheorem}, it is easy to show that $\mathcal{D}_{PQ}(G)$ occupies $\mathcal{O}(\min\{m,n\sqrt{\lambda}\})$ space (the proof is given in Appendix \ref{sec : size of Dpq} for completeness). 
We can easily transform any undirected multi-graph $G$ to an undirected integer-weighted graph $G'$ with no parallel edges as follows. For any pair $u,v$, if there are $q$ edges, $q >0$, between $u$ and $v$, then replace all these edges with a single edge $(u,v)$ of capacity $q$. %Let $G'$ be the resulting graph. 
Observe that for each cut $C$, $C$ has capacity $\lambda'$ in $G$ if and only if $C$ has capacity $\lambda'$ in $G'$. Hence, for any undirected multigraph $G$, we can use $\mathcal{D}_{PQ}(G')$ to store and characterize all $(s,t)$-mincuts in $G$. This, along with Lemma \ref{lem : size of Dpq in integer weighted}, gives us the following result.

\begin{lemma}\label{lem : size of Dpq}
    For any undirected multi-graph ${G}$ with $(s,t)$-mincut capacity $\lambda$, there is an undirected integer-weighted graph ${ G'}$ with no parallel edges such that 
    \begin{enumerate}
        \item the capacity of each cut in $G$ remains the same in $G'$ and 
        %any cut $C$ has capacity $\lambda'$, $\lambda'\ge 0$ in ${ G}$ if and only if $C$ has capacity $\lambda'$ in ${G'}$ and

        \item DAG $\mathcal{D}_{PQ}(G')$ occupies $\mathcal{O}(\min\{m,n\sqrt{\lambda}\})$ space.
    \end{enumerate}
\end{lemma}



