\begin{lemma}\label{lm2}
	Let $\psi(w)=\eta w$ with $\eta\in\mathbb T$ and $w\in\mathbb D$. Then $\Im\{\textbf{Ber}(C_{\psi})\}=0$ if and only if $\Im\{\eta\}=0$.
\end{lemma}


\begin{proof}
	Let $w=re^{i\theta}$ with $r\in[0, 1).$ Then 
	\begin{equation*}
		\widetilde{C_{\psi}}(re^{i\theta})=\left(\frac{1-r^2}{1-\eta r^2}\right)^{\gamma+2}.
	\end{equation*}
	Suppose that $\Im\{\textbf{Ber}(C_{\psi})\}=0$. Then 
	$\frac{1-r^2}{1-\eta r^2}\in\mathbb R$ for all $r\in[0, 1).$ Let $\frac{1-r^2}{1-\eta r^2}=k_r,$ where $k_r\in\mathbb R.$ By taking logarithm both side, we have
	\begin{eqnarray*}
		&&\log (1-r^2)-\log(1-\eta r^2)=\log k_r\\
		&\implies& \log(1-\eta r^2)=\log\left(\frac{1-r^2}{k_r}\right)\\
		&\implies& 1-\eta r^2=\frac{1-r^2}{k_r}\\
		&\implies& \eta=\frac{1}{r^2}-\frac{1-r^2}{k_r r^2}\in\mathbb R.
	\end{eqnarray*}

	Thus $\Im\{\eta\}=0.$ Conversely, let $\Im\{\eta\}=0.$ It is easy to observe that $\Im\{\textbf{Ber}(C_{\psi})\}=0$.

\end{proof}
\begin{lemma}\label{lm1}
	If $\psi(w)=\eta w$ with $\eta\in\mathbb T$ and $w\in\mathbb D$ then the Berezin range of $C_\psi$ acting on $A^2_{\gamma}(\mathbb{D})$ is a point if and only if $\eta=1$.
\end{lemma}


\begin{proof}
	As the sufficient part is obvious, we only prove the necessary part.
	Let $w=re^{i\theta}$ with $r\in[0, 1).$ Then 
	\begin{equation*}
		\widetilde{C_{\psi}}(re^{i\theta})=\left(\frac{1-r^2}{1-\eta r^2}\right)^{\gamma+2}.
	\end{equation*}
	Suppose that $\textbf{Ber}(C_{\psi})$ is a point. As $\widetilde{C_{\psi}}(0)=1,$ so $\textbf{Ber}(C_{\psi})=\{1\}.$
	Thus, $\left(\frac{1-r^2}{1-\eta r^2}\right)^{\gamma+2}=1$ for all $r\in[0, 1).$
	This implies that 
	\begin{equation}\label{eq2}
		\left|\frac{1-r^2}{1-\eta r^2}\right|=1\implies 1-r^2=|1-\eta r^2|.
	\end{equation}
	Now consider $\eta=e^{i\phi}$ in \eqref{eq2}, then
	\begin{equation*}
		1-r^2=|1- e^{i\phi}r^2|=|1- (\cos\phi+i~sin \phi)r^2|=|(1-r^2\cos \phi)-i~r^2 sin \phi|.
	\end{equation*}
	This implies that 
	\begin{equation*}
		2r^2(\cos^2 \phi-1)=0\implies \cos\phi=\pm 1\implies sin \phi=0.
	\end{equation*}
	Therefore, $\eta=\cos\phi+i sin\phi= 1,$ as $\eta=-1$ does not satisfy the equation \eqref{eq2} for all $r\in[0, 1).$ 

\end{proof}






