	\begin{theorem}
		If $\phi$ is in $L^{\infty}(\mathbb{T})$, then $\textbf{Ber}(T_{\phi})=P[\phi](\mathbb{D})$.
	\end{theorem}
	\begin{proof}
		Let $\hat{k}_{w}$ be the normalized reproducing kernel at $w \in \mathbb{D}.$ Then from the definition of the Berezin transform we have
		\begin{align*}
			\widetilde{T_{\phi}}(w)=\langle T_{\phi}\hat{k}_{w},\hat{k}_{w}\rangle
			=\langle P_{+}(\phi\hat{k}_{w}),\hat{k}_{w}\rangle
			=\langle \phi\hat{k}_{w},P_{+}\hat{k}_{w}\rangle
			=\langle \phi\hat{k}_{w},\hat{k}_{w}\rangle.
		\end{align*}
		This implies that
		\begin{align*}
			\widetilde{T_{\phi}}(w) =\frac{1}{2\pi}\int_{0}^{2\pi}\phi(e^{i\theta})|\hat{k}_{w}(e^{i\theta})|d\theta
			=\frac{1}{2\pi}\int_{0}^{2\pi}\phi(e^{i\theta})\frac{1-|w|^2}{|1-\bar{w}e^{i\theta}|^2}d\theta
			=P[\phi](w).
		\end{align*}
		Therefore, we get $\textbf{Ber}(T_{\phi})=P[\phi](\mathbb{D}).$
	\end{proof}

	\begin{proposition}
		For $\phi \in L^{\infty}(\mathbb{T})$, the Berezin range of $T_{\phi}$ is convex if and only if $P[\phi](\mathbb{D})$ is convex.
	\end{proposition}



