\section{Preliminaries and first results}
%\subsection{Some Linear Functional Analysis facts}
Let $H$ be a real Hilbert space and let $A$ be a self-adjoint bounded linear operator on $H$. More details on these operators can be found, for example, in \cite{KaAk,BauCom}. 

Let us recall that $A$ is \emph{strongly positive} if there exists $\gamma>0$ such that for all $x\in H$:
\begin{equation}\label{StrPosEq}
\langle Ax,x\rangle \ge \gamma\|x\|^2
\end{equation}

The following lemma will be used in the sequel. For the sake of completeness, we prove it here.

\begin{lemma} \label{I-minus-alpha-A-lemma}
Let $A$ be strongly positive.
For any $\alpha \in [0, \|A\|^{-1}]$:
\begin{equation}
\|I-\alpha A\|\le 1-\alpha\gamma
\end{equation}
\end{lemma}
\begin{proof}
We clearly have $\|A\| > 0$. We have that, given $\alpha \in [0, \|A\|^{-1}]$, for any $x\in H$:%$I-\alpha A$ is positive (see \cite{}). 
\[\langle (I-\alpha A)x,x \rangle=\|x\|^2-\alpha \langle Ax,x \rangle \ge \|x\|^2-\|A\|^{-1}\|A\|\|x\|^2=0\]
Thus
\[\sup_{\|x\|=1} |\langle (I-\alpha A)x,x \rangle|=\sup_{\|x\|=1} \langle (I-\alpha A)x,x \rangle\]
As
\begin{equation*}
\sup_{\|x\|=1} |\langle Ax,x\rangle|=\|A\|
\end{equation*}
we have
\begin{equation*}
\|I-\alpha A\| = \sup_{\|x\|=1} \langle (I-\alpha A)x,x \rangle=\sup_{\|x\|=1}(\|x\|^2-\alpha \langle Ax,x \rangle) \le 1-\alpha\gamma
\end{equation*}
\end{proof}

Furthermore, we shall use the following well known inequality in real Hilbert spaces: for all $x,y\in H$,
\begin{equation} \label{lem2.4eq}
\|x+y\|^2 \le \|x\|^2+2\langle y,x+y\rangle
\end{equation}

\subsection{Quantitative definitions and lemmas}

\begin{dfn}
Let $(x_n)$ be a sequence in $H$.
\begin{enumerate}[(i)]
\item Let $x\in H$. We say $\phi:\N\to\N$ is a \emph{rate of convergence} of $(x_n)$ (to $x$) if
\[\forall k\in\N \forall n\ge\phi(k) \left(\|x_n-x\|\le\frac{1}{k+1}\right)\]
\item We say $\phi:\N\to\N$ is a \emph{Cauchy modulus} of $(x_n)$ if
\[\forall k\in\N \forall n,m\ge\phi(k) \left(\|x_n-x_m\|\le\frac{1}{k+1}\right)\]

%\end{dfn}
%\begin{dfn}
%\begin{dfn}
\item A function $\phi:\N \times \N^\N \to \N$ is a \emph{rate of metastability} of a sequence $(x_n) \subseteq H$ if
\[\forall k\in\N \forall f\in \N^\N \exists n \le \phi(k,f) \forall i,j \in [n,f(n)] \left(\|x_i-x_j\|\le\frac{1}{k+1}\right)\]
\end{enumerate}
%\end{dfn}
%\begin{dfn}
If $(a_n)$ is a sequence of non-negative real numbers such that $\sum_{n=0}^{+\infty} a_n=+\infty$ then $\theta:\N\to\N$ is a \emph{rate of divergence} of $(a_n)$ if $\sum_{n=0}^{\theta(k)}a_n \ge k$ for all $k\in\N$.
%\end{dfn}
%\begin{dfn}
\begin{lemma}\label{div-rate-k-1} 
Assume that $a_n \le 1$ for all $n\in\N$ and that $\theta$ is a rate of divergence of $(a_n)$. Then $\theta(k) \ge k-1$ for all $k\in\N$.
\end{lemma}
\begin{proof}
Assume that for some $k\in\N$, we have that $\theta(k)<k-1$, hence $\theta(k)\leq k-2$.
Then $\sum\limits_{i=0}^{\theta(k)} a_i \le \sum\limits_{i=0}^{k-2} a_i \le k-1<k$, which is a contradiction.
\end{proof}

If $(b_n)$ is a sequence of real numbers such that $\limsup b_n \le 0$, then $\psi:\N\to\N$ is a \emph{$\limsup$-rate} of $(b_n)$ if
\[\forall k\in\N\forall n\ge\psi(k)\left(b_n \le \frac{1}{k+1}\right)\]
\end{dfn}



\subsubsection{Xu's Lemma}

In his paper \cite{Xu03}, Xu uses a lemma regarding the convergence of a sequence of non-negative real numbers. This result would become well known in fixed point theory and is often referred as Xu's lemma.
\begin{prop}[Xu's Lemma]\label{lem-Xu}\cite{Xu03}
Let $(a_n)$ be a sequence in $[0,1]$,
$(b_n)$ and $(c_n)$ sequences of reals and 
$(s_n)$ a sequence of nonnegative reals such that for all $n\in\N$,  
\begin{equation*}
s_{n+1}\leq (1-a_n)s_n + a_nb_n+c_n
\end{equation*}
and $\sum\limits_{n=0}^\infty a_n=+\infty,\ \limsup_n b_n \le 0,\ \sum\limits_{n=0}^\infty c_n < +\infty$.
%\end{equation*}
%\end{enumerate}

Then $\lim_n s_n=0$.
\end{prop}
As a part of proof mining research, quantitative versions of this lemma were deduced (see \cite{Pin23} for an overview). In this paper, we use a version corresponding to the particular case of the lemma with $(c_n)\equiv 0$, whose proof can be found in \cite[Proposition 4]{LeuPin21}.

\begin{prop}\label{quant-lem-Xu02-cn-0}
Let $(a_n)$ be a sequence in $[0,1]$,
$(b_n)$ a sequence of reals and 
$(s_n)$ sequence of nonnegative reals such that for all $n\in\N$,  
\begin{equation}
s_{n+1}\leq (1-a_n)s_n + a_nb_n
\end{equation}
Assume that $L\in\N^*$ is an upper bound on $(s_n)$, $\sum\limits_{n=0}^\infty a_n$ diverges with rate of divergence $\theta$ and $\limsup_n b_n \le 0$ with $\limsup$-rate $\psi$.

Then $\lim_n s_n=0$ with rate of convergence $\Sigma_0$ defined by 
\begin{equation}
\Sigma_0(k)=\theta\left(\psi(2k+1)+\lceil \ln(2L(k+1))\rceil\right)+1.
\end{equation}
\end{prop}

The condition $\sum\limits_{n=0}^\infty a_n = \infty$ is equivalent to
\[\prod_{n=0}^\infty (1-a_n)=0.\]
As such, we may also consider this condition:
\begin{equation}\label{q2'}
\begin{gathered}
{\rm A'}:\N\times \N\to\N \text{ is a monotone function satisfying}\\
\forall k, m\in \N\, \left( \prod_{i=m}^{{\rm A'}(m,k)}(1-a_i)\leq \frac{1}{k+1}\right),
\end{gathered}
\end{equation}
implying that for each $m\in\N$, $A'(m, \cdot)$ is a rate of convergence towards zero for the sequence $\left(\prod_{i=m}^{n}(1-a_i)\right)_n$. By saying that ${\rm A'}$ is monotone we mean that it is monotone in both variables,
\[
\forall k, k', m, m' \in \N\, \left( k\leq k' \land m\leq m' \to {\rm A'}(m, k)\leq {\rm A'}(m', k')\right).
\]

We have this quantitative result involving this condition. For the proof, follow \cite[Lemma 3.4]{Pin23}, replacing $\varepsilon$ with $\frac{1}{k+1}$ (see also \cite[Lemma 13]{Pin21}).

\begin{lemma}\label{Xu-lem-C2q**}
	Let $(s_n)$ be a bounded sequence of non-negative real numbers and $D\in\N$ a positive upper bound on $(s_n)$. Consider sequences of real numbers $(a_n)\subset\, [0,1]$ and $(r_n)\subset \R$ and assume the existence of monotone functions ${\rm A'}: \N\times \N \to \N$ and ${\rm R}:\N \to \N$ such that
	\begin{enumerate}[{\rm (i)}]
		\item ${\rm A'}$ satisfies \eqref{q2'},
		\item ${\rm R}$ is such that $\forall k\in \N \, \forall n\geq {\rm R}(k) \, \left( r_n \leq \frac{1}{k+1} \right)$,
	\end{enumerate}
	 If for all $n\in \N$, $s_{n+1}\leq (1-a_n)s_n+a_nr_n$,	then $(s_n)$ converges to zero and
	\begin{equation*}
	\forall k \in \N \,\forall n\geq \Sigma^*_0(k) \, \left(s_n\leq \dfrac{1}{k+1}\right),
	\end{equation*}
	\noindent where $\Sigma^*_0(k):={\rm A'}({\rm R}(2k+1), 2D(k+1)-1)+1$.
\end{lemma}

The following is another quantitative version of Xu's lemma. This has a weaker conclusion than the previous result, in that it only gives information regarding finite terms of the sequence $(s_n)$. This is useful for obtaining rates of metastability. A proof can be seen in \cite[Lemma 2.11]{DinPin23}.
\begin{prop} \label{XuMeta}
Let $(a_n)$ be a sequence in $[0,1]$,
$(b_n), (c_n)$ sequences of real numbers and 
$(s_n)$ sequence of nonnegative real numbers such that for all $n\in\N$,  
\begin{equation}
s_{n+1}\leq (1-a_n)s_n + a_nb_n+c_n
\end{equation}
Assume that $L\in\N^*$ is an upper bound on $(s_n)$, that $\sum\limits_{n=0}^\infty a_n$ diverges with rate of 
divergence $\theta$ and that, for $k,n,q\in\N$ and for all $i\in [n,q]$:
\[c_i \le \frac{1}{3(k+1)(q+1)} \quad\text{and}\quad b_i \le \frac{1}{3(k+1)}. \]
Then
\[\forall i\in[\sigma(k,n),q]\left(s_i \le \frac{1}{k+1}\right)\]
with
\[\sigma(k,n):=\theta(n+\lceil \ln(3L(k+1))\rceil)+1.\]
\end{prop}

%{\color{red} Add quantitative Xu's lemma where you use the condition with convergent product: \cite[Proposition 4]{LeuPin21} and \cite{}}


We also have the corresponding result with ${\rm A'}$ satisfying \eqref{q2'}. See \cite[Lemma 2.12]{DinPin23}.

\begin{prop}\label{XuMeta-C2q**}
	Let $(s_n)$ be a bounded sequence of non-negative real numbers and $D\in\N^*$ an upper bound on $(s_n)$. Consider sequences of real numbers $(a_n)\subset\, [0,1]$, $(r_n)\subset \R$ and assume that $\sum a_n=\infty$ with a function ${\rm A'}$ satisfying \eqref{q2'}. Let $k,n, q\in \N$ be given. If for all $i\in [n,q]$
	\begin{equation*}
		(i)\  s_{i+1}\leq (1-a_i)s_i+a_ib_i+c_i\,,\quad (ii)\  b_i\leq \frac{1}{3(k+1)}\,,\quad (iii)\ c_i\leq \frac{1}{3(k+1)(q+1)}, 
	\end{equation*}
	then 
	\[\forall i \in [\sigma(k,n), q] \left( s_i\leq \frac{1}{k+1}\right),\]
	where 
	\begin{equation*}
		\sigma(k,n):={\rm A'}\left(n, 3D(k+1)-1\right)+1.
	\end{equation*}
\end{prop}
