\subsection{Xu's iteration}\label{iterPrelim}

Let $H$ be a Hilbert space. Given $l\in\N$, let $T_0,\ldots, T_{l-1}$ be nonexpansive mappings on $H$. We define $T_n$ for $n \ge l$ as $T_{n \bmod l}$. Define
\begin{equation}
F:= \bigcap_{i=0}^{l-1} \Fix(T_i)
\end{equation}

We assume that $F \neq \emptyset$.

Let $u\in H$. Let $A$ be a self-adjoint bounded linear operator on $H$ satisfying \eqref{StrPosEq} for some $0<\gamma \le 1$ and for all $x\in H$.

Xu's iteration $(x_n)$ is defined by
\begin{equation}\label{iter}
x_0\in H,\quad x_{n+1}=(I-\alpha_{n+1}A)T_{n+1}x_n+\alpha_{n+1}u
\end{equation}
where $(\alpha_n) \subset (0,1]$.

In the sequel we prove some useful properties of Xu's iteration.

For the rest of the section, we take $p\in F$ and assume that
\begin{center}
there is $N_0\in\N$ such that $\alpha_{n+1} \le \|A\|^{-1}$ for every $n\ge N_0$,
\end{center}
\begin{lemma}\label{bound-ineq}
For every $n\ge N_0$:
\begin{align}
\|x_{n+1}-p\| &\le(1-\gamma\alpha_{n+1})\|x_n-p\|+\alpha_{n+1}\|u-Ap\|,\label{bound-ineq1}\\
\|x_n - p\| &\leq K_0, \label{bound-ineq2}
\end{align}
where $K_0\in\N^*$ is such that:
\begin{equation} \label{def-K0}
K_0 \ge \max\left\{\|x_{N_0}-p\|,\frac{\|u-Ap\|}{\gamma}\right\}.
\end{equation}

\end{lemma}
\begin{proof}
We get that for all $n\ge N_0$:
\begin{eqnarray*}
\|x_{n+1}-p\| &=&\|(I-\alpha_{n+1}A)T_{n+1}x_n+\alpha_{n+1}u-p+\alpha_{n+1}Ap- \alpha_{n+1}Ap\|\\
&=& \|(I-\alpha_{n+1}A)(T_{n+1}x_n-p)+\alpha_{n+1}(u-Ap)\|\\
&\le& (1-\gamma\alpha_{n+1})\|T_{n+1}x_n-p\|+\alpha_{n+1}\|u-Ap\|\quad\text{by Lemma \ref{I-minus-alpha-A-lemma}}\\
&\le&(1-\gamma\alpha_{n+1})\|x_n-p\|+\alpha_{n+1}\|u-Ap\|
\end{eqnarray*}
Thus, \eqref{bound-ineq1} holds.

We prove \eqref{bound-ineq2} by induction. The case $n=N_0$ is obvious. Assume that $\|x_n-p\| \le K_0$. It follows from \eqref{bound-ineq1} that:
\begin{equation*}
\|x_{n+1}-p\| \le (1-\gamma\alpha_{n+1})K_0+\alpha_{n+1}\gamma K_0=K_0
\end{equation*}
Thus, $\|x_n-p\| \le K_0$ for every $n\ge N_0$.
\end{proof}





\begin{lemma}
Let $b_A\in\N^*$ be such that $b_A\ge \|A\|$. For every $n\ge N_0,m\in\N$ and $x\in H$:
\begin{align}
\|u-AT_{n+1}x_n\| 
&\le (b_A+1)K_0,\label{uATx-bound}\\
\begin{split}
\|x_{n+l+1}-x_{n+1}\|
&\le (1-\alpha_{n+l+1}\gamma)\|x_{n+l}-x_n\|\\
&\ \ + (b_A+1)K_0|\alpha_{n+l+1}-\alpha_{n+1}|,\label{xnl1-xn1-ineq}
\end{split}\\
\begin{split}
\|x_{n+l+m}-x_{n+m}\|
&\le \|x_{n+l}-x_n\|\prod_{i=n+1}^{n+m}(1-\alpha_{i+l}\gamma)\\
&\ \ + (b_A+1)K_0\sum_{i=n+1}^{n+m}|\alpha_{i+l}-\alpha_i|,\label{xnl1-xn1-ineq2}
\end{split}\\
\begin{split}
\|x_{n+1}-x\|^2 
&\le (1-\alpha_{n+1}\gamma)\|x_n-x\|^2+2\|x_n-x\|\|T_{n+1}x-x\|\\
&\ \ +\|T_{n+1}x-x\|^2+2\alpha_{n+1}\langle u-Ax,x_{n+1}-x\rangle.\label{xn1-x-sq-ineq}
\end{split}
\end{align}
\end{lemma}
\begin{proof}
Let $n\ge N_0$ and $x\in H$. By \eqref{bound-ineq2},
\begin{align*}
\|u-AT_{n+1}x_n\| &\le \|u-Ap\|+\|A\|\|p-T_{n+1}x_n\| \le \|u-Ap\|+\|A\|\|p-x_n\| \\
&\le \gamma K_0 +\|A\| K_0 \le (b_A+1)K_0.
\end{align*}


\begin{eqnarray*}
&&\|x_{n+l+1}-x_{n+1}\|\\
 &=& \|(I-\alpha_{n+l+1}A)T_{n+l+1}x_{n+l}+\alpha_{n+l+1}u-((I-\alpha_{n+1}A)T_{n+1}x_n+\alpha_{n+1}u)\|\\
&=& \|(I-\alpha_{n+l+1}A)(T_{n+l+1}x_{n+l}-T_{n+1}x_n)+(\alpha_{n+l+1}-\alpha_{n+1})(u-AT_{n+1}x_n)\|\\
&\le& (1-\alpha_{n+l+1}\gamma)\|T_{n+l+1}x_{n+l}-T_{n+1}x_n\|+(b_A+1)K_0|\alpha_{n+l+1}-\alpha_{n+1}|\\
&&\text{by Lemma \ref{I-minus-alpha-A-lemma} and \eqref{uATx-bound}}\\
&\le& (1-\alpha_{n+l+1}\gamma)\|x_{n+l}-x_n\|+ (b_A+1)K_0|\alpha_{n+l+1}-\alpha_{n+1}|\quad\text{since $T_{n+l}=T_n$}.
\end{eqnarray*}

By induction, from \eqref{xnl1-xn1-ineq} we get \eqref{xnl1-xn1-ineq2}.

\begin{eqnarray*}
\|x_{n+1}-x\|^2 &=& \|(I-\alpha_{n+1}A)(T_{n+1}x_n-x)+\alpha_{n+1}(u-Ax)\|^2\\
&\le& \|(I-\alpha_{n+1}A)(T_{n+1}x_n-x)\|^2+2\alpha_{n+1}\langle u-Ax,x_{n+1}-x\rangle\\
&& \text{by } \eqref{lem2.4eq}\\
&\le& (1-\alpha_{n+1}\gamma)\|T_{n+1}x_n-x\|^2+2\alpha_{n+1}\langle u-Ax,x_{n+1}-x\rangle\\
&&\text{by Lemma \ref{I-minus-alpha-A-lemma}}\\
&\le& (1-\alpha_{n+1}\gamma)(\|T_{n+1}x_n-T_{n+1}x\|+\|T_{n+1}x-x\| )^2\\
&&+2\alpha_{n+1}\langle u-Ax,x_{n+1}-x\rangle\\
&\le& (1-\alpha_{n+1}\gamma)\|x_n-x\|^2+2\|x_n-x\|\|T_{n+1}x-x\|\\
&&+\|T_{n+1}x-x\|^2+2\alpha_{n+1}\langle u-Ax,x_{n+1}-x\rangle.
\end{eqnarray*}

\end{proof}

\subsection{Quantitative hypotheses}


%Consider the following conditions:
Xu used the following hypotheses on the parameter sequences $(\alpha_n)$:
\begin{align*}
\text{(C1)} \quad & \lim_n \alpha_n=0&\quad\text{(C2)} \quad & \sum_{n=0}^{+\infty} \alpha_n = +\infty\\
\text{(C3)} \quad & \lim_n \frac{\alpha_n}{\alpha_{n+l}}=1&\quad\text{(C4)} \quad & \sum_{n=0}^{+\infty} |\alpha_n - \alpha_{n+l}| <+\infty
\end{align*}

As we prove quantitative versions of the results in our paper, we use quantitative conditions:
\begin{eqnarray*}
\text{(C1q)} \quad & \lim_n \alpha_n=0 \text{ with convergence rate } \sigma_1\\
\text{(C2q)} \quad & \sum_{n=0}^{+\infty} \alpha_n = +\infty \text{ with divergence rate } \sigma_2\\
%\text{(C2q*)} \quad & \alpha_n < 1 \text{ and } \prod_{n=0}^{+\infty} (1-\gamma\alpha_n) = 0 \text{ with rate of convergence } \sigma_2^*\\
\text{(C2q*)} \quad &\prod_{n=m}^{+\infty} (1-\gamma\alpha_n) = 0 \text{ with rate of convergence } \sigma_2^*(m,\cdot) \text{ for } m\in\N\\
\text{(C3q)} \quad & \lim_n \frac{\alpha_n}{\alpha_{n+l}}=1 \text{ with convergence rate } \sigma_3\\
\text{(C4q)} \quad & \sum_{n=0}^{+\infty} |\alpha_n - \alpha_{n+l}| <+\infty \text{ with Cauchy modulus } \sigma_4
\end{eqnarray*}
We make natural monotonicity assumptions on the rates, i.e., that the $\sigma_i$ and $\sigma_2^*$ are increasing.

\begin{lemma}\label{lem-nalpha}
Assume that (C1q) holds. Let:
\[\nalpha:=\max\{\sigma_1(b_A-1)-1,0\}.\]
Then for every $n \ge \nalpha$ we have:
\[\alpha_{n+1} \le\|A\|^{-1}\]
\end{lemma}

\begin{proof}
Take $n \ge \nalpha$. Then:
\[\alpha_{n+1} \le \frac{1}{b_A-1+1} \le \|A\|^{-1}\]
\end{proof}

\begin{lemma}\label{bound-lem}
Assume that (C1q) holds. Let $p\in F$ and $K\in\N^*$ be such that
\begin{equation} \label{def-K}
K \ge \max\left\{\|x_{\nalpha}-p\|,\frac{\|u-Ap\|}{\gamma}\right\}.
\end{equation}
Then $\|x_n-p\| \le K$ for all $n \ge \nalpha$.
\end{lemma}
\begin{proof}
By Lemma \ref{lem-nalpha}, we have $\alpha_{n+1} \le\|A\|^{-1}$ for every $n \ge \nalpha$. We may thus apply \eqref{bound-ineq2}, taking $N_0=\nalpha$ and $K_0=K$.
\end{proof}

If (C1q) holds, we may, analogously, use any inequality from Section \ref{iterPrelim}, taking $N_0=\nalpha$ and $K_0=K$.



\section{Connection with Körnlein's results}% \cite{Kor} for $\|A\|<2$}

In the following, we show that for $\|A\|< 2$, Xu’s iteration is a particular case of an iteration due to Yamada. Körnlein \cite{Kor,KorTh} computed rates of metastability for Yamada’s iteration. Hence, for $\|A\|< 2$, these rates are also rates for Xu’s iteration.

We also show that Xu's iteration is not necessarily a particular case of Yamada's iteration if $\|A\| \ge 2$, therefore Yamada's and Körnlein's results are not applicable in this case.

The quadratic minimization problem (P) associated to the operator $A$ is given by \eqref{Prob}.
As pointed out by Xu, the problem (P) has a unique solution $x^*$ and, furthermore, (P) has the following variational characterization (\cite[Lemma 2.3.]{Xu03}):

\begin{equation} \label{VIP}
\langle u-Ax^*, y-x^*\rangle \le 0\quad\text{for all $y\in F$}.
\end{equation}

We consider the variational inequality problem (VIP) consisting in finding $x^*\in F$ such that,
\[\forall y\in F\ \langle \mathcal{F}x^*, y-x^*\rangle \ge 0\]
for some mapping $\mathcal{F}$ in $H$.

The following iteration was considered by Yamada \cite{Yam} in connection with the VIP: 
\begin{equation}\label{iterYam}
v_0\in H,\quad v_{n+1}=(1-\alpha_{n+1})T_{n+1}v_n+\alpha_{n+1}f(T_{n+1}v_n)
\end{equation}
where $f:H\to H$ is a contraction.

%Körnlein applied proof mining methods to obtain quantitative results of the strong convergence of this iteration, consisting in rates of metastability.

\begin{lemma}
%\begin{enumerate}
If $\|I-A\|<1$, Xu's iteration is a particular case of Yamada's iteration \eqref{iterYam}.
%\end{enumerate}
\end{lemma}

\begin{proof}
Let $f(x):=(I-  A)x+  u$. Then, for all $x,y\in H$, $\|f(x)-f(y)\|=\|(I-  A)x+  u-(I-  A)y-  u  \|=\|(I-A)(x-y)\| \le \|I-A\|\|x-y\|$. As $\|I-A\|<1$, we have that $f$ is a contraction.
It follows that, for all $n\in\N$,
\begin{align*}
v_{n+1}&=(1-\alpha_{n+1})T_{n+1}v_n+\alpha_{n+1}((I-  A)T_{n+1}v_n+  u)\\
&=T_{n+1}v_n-\alpha_{n+1}T_{n+1}v_n+\alpha_{n+1}T_{n+1}v_n-\alpha_{n+1}  AT_{n+1}v_n+\alpha_{n+1}  u\\
&=T_{n+1}v_n-\alpha_{n+1}  (AT_{n+1}v_n-u)\\
&=(I-\alpha_{n+1}  A)T_{n+1}v_n+\alpha_{n+1} u
\end{align*}
\end{proof}



\begin{obs}

We then show that Xu's iteration is not necessarily a particular case of Yamada's iteration if $\|A\| \ge 2$.



From the above equalities we get that, if Xu's iteration is a particular case of Yamada's iteration, then $f$ is such that, for all $n\in\N$,
