We now show how to apply Yamada's approach to the problem (P), introducing a particular case of Yamada's iteration, which turns out to be also a particular case of  Xu's iteration. %We also show that the reciprocal is not true: for $\|A\|\ge 2$, Xu’s iteration does not overlap(?) with the particular case of Yamada's iteration, therefore Yamada's and Körnlein's results do not apply to Xu's iteration(?).

We first note that (P) is a particular case of the problem
\[\min_{x\in F} \theta(x)\]
for some convex function $\theta: H\to \R$ twice differentiable on $H$ such that there exists $m,M>0$ such that, for all $x,v\in H$:
\[m\|v\|^2 \le \langle \theta''(x)v,v\rangle \le M\|v\|^2.\]
This, in turn, is a particular case of the VIP \cite{DeuYam}.
Deutsch and Yamada \cite{DeuYam} had introduced an iteration for this problem (also used by Xu \cite{Xu03}):
\begin{equation}\label{iterConv}
v_0\in H,\quad v_{n+1}=T_{n+1}v_n-\alpha_{n+1}\mu \theta'(T_{n+1}v_n)
\end{equation}
where $0<\mu<\frac{2}{M}$.
\begin{prop}
The iteration \eqref{iterConv} is a particular case of \eqref{iterYam}.
\end{prop}
\begin{proof}
We define $\psi(x):= \mu \theta(x)-\frac{1}{2}\|x\|^2$. Then $\psi'(x)=\mu\theta'(x)-x$. It is known \cite[Lemma 3.5]{DeuYam} that $\psi'$ is a contraction for $0<\mu<\frac{2}{M}$. We can thus take $f:=-\psi'$ in \eqref{iterYam}:% obtaining \eqref{iterConv}.
\begin{align*}
v_{n+1}&=(1-\alpha_{n+1})T_{n+1}v_n-\alpha_{n+1}\psi'(T_{n+1}v_n)\\
&=(1-\alpha_{n+1})T_{n+1}v_n-\alpha_{n+1}(\mu\theta'(T_{n+1}v_n)-T_{n+1}v_n)\\
&=(1-\alpha_{n+1})T_{n+1}v_n-\alpha_{n+1}\mu\theta'(T_{n+1}v_n)+\alpha_{n+1}T_{n+1}v_n\\
&=T_{n+1}v_n-\alpha_{n+1}\mu\theta'(T_{n+1}v_n)
\end{align*}
\end{proof}
We can thus apply Yamada's approach to the problem (P) by taking $\theta(x):=\frac{1}{2}\langle Ax,x\rangle-\langle x,u\rangle$ in \eqref{iterConv}.

\begin{prop}
Taking $\theta(x):=\frac{1}{2}\langle Ax,x\rangle-\langle x,u\rangle$ in \eqref{iterConv} we obtain:
\begin{equation}\label{iterYamQuad}
v_0\in H,\quad v_{n+1}=(I-\alpha_{n+1}\mu A)T_{n+1}v_n+\alpha_{n+1}\mu u
%v_0\in H,\quad v_{n+1}=T_{n+1}v_n-\alpha_{n+1}\mu (A(T_{n+1}v_n)-u)
\end{equation}
with $0<\mu<\frac{2}{\|A\|}$.

%This is identical to \eqref{iterYam} with $f(x):=(I-\mu A)x+\mu u$.
\end{prop}
\begin{proof}
We have $\theta'(x)=Ax-u$. Thus from \eqref{iterConv} we get
\begin{align*}
v_{n+1}&=T_{n+1}v_n-\alpha_{n+1}\mu (AT_{n+1}v_n-u)\\
&=T_{n+1}v_n-\alpha_{n+1}\mu AT_{n+1}v_n+\alpha_{n+1}\mu u\\
&=(I-\alpha_{n+1}\mu A)T_{n+1}v_n+\alpha_{n+1}\mu u
\end{align*}
 %Thus we obtain \eqref{iterYamQuad}.
We take $M=\|A\|$ since $\theta''(x)=A$ and, for every $v\in H$,
\[\langle Av,v\rangle \le \|A\|\|v\|^2.\]
\end{proof}

\begin{obs}
The iteration \eqref{iterYamQuad} is identical to Xu's iteration \eqref{iter} with $\mu A$ in place of $A$ and $\mu u$ in place of $u$. That is, we take $f(x):=(I- \mu A)x+  \mu u$ in \eqref{iterYam}.


\end{obs}

If $\|A\| < 2$, then $A=\mu A_0$ for some strongly positive self-adjoint bounded linear operator $A_0$ and some $0<\mu<\frac{2}{\|A_0\|}$. 
We thus have that, if $\|A\| < 2$, Xu's iteration \eqref{iter} is a particular case of Yamada's iteration \eqref{iterYam}.

We also have that, if $\|A\| \ge 2$, Xu's iteration \eqref{iter} is not a particular case of the iteration \eqref{iterYamQuad}.


