\section{Main results}

The main results of this paper are quantitative versions of Theorem \ref{teor3.1} providing uniform effective rates of metastability of Xu's iteration. These results are obtained by applying proof mining methods to Xu's strong convergence proof.

In the following, $H$ is a Hilbert space and $A$ is a self-adjoint bounded linear operator on $H$ satisfying \eqref{StrPosEq} for some $0<\gamma \le 1$ and for all $x\in H$. Furthermore, $l\in\N$ and $T_0,\ldots, T_{l-1}$ are nonexpansive mappings on $H$ such that $F:= \bigcap_{i=0}^{l-1} \Fix(T_i)$ is a nonempty set. Xu's iteration $(x_n)$ is given by \eqref{iter}, 
where $u\in H$, $(\alpha_n) \subset (0,1]$ and $T_n=T_{n \bmod l}$ for $n \ge l$.

For every $i\in\N$, denote
\[\tilde{T}_i:= T_{i+l} \cdots T_{i+1}.\]

We take $p\in F$ and $b_A,b_U,b_p\in\N^*$ are such that
$$b_A\ge\|A\|,\quad b_U\ge\|u\|,\quad b_p \ge \|p\|.$$

\begin{teor}\label{main}
Assume (C1q), (C2q), (C3q) hold. Let $K\in\N^*$ be such that%as in \eqref{def-K} and
\begin{equation*}
K \ge \max\left\{\|x_{\nalpha}-p\|,\frac{\|u-Ap\|}{\gamma}\right\}, \quad \text{where}\quad \nalpha=\max\{\sigma_1(b_A-1)-1,0\}.
\end{equation*}
Suppose $\tau:\N\to\N$ is a monotone function satisfying, for all $k,m\in\N$ and $x\in \overline{B}_K(p)$: %Then :$(x_n)$ is Cauchy with rate of metastability $\Omega$ defined by:
\begin{equation}\label{tau-cond}
\|x-\tilde{T}_mx\| \le \frac{1}{\tau(k)+1} \quad\text{implies}\quad \forall i<l \left(\|x-T_ix\|<\frac{1}{k+1}\right).
\end{equation}

Then, for every $k\in\N$ and $f:\N\to\N$:
\[\exists N \le \Omega(k,f) \forall i,j\in[N,\tilde{f}(N)] \left(\|x_i-x_j\| \le \frac{1}{k+1}\right),\]
where
\begin{equation}\label{def-meta}
\Omega(k,f)=\sigma(k_0,\tilde{\phi}(24K(h_{k,f}^{(\dd)}(0)+1)^2))+\nalpha,
\end{equation}
with 


\begin{align*}
\sigma(k,n)&= \sigma_2 \left (\left \lceil \frac{n+\lceil \ln(12K^2(k+1))\rceil}{\gamma} \right\rceil +\nalpha+1\right)-\nalpha,\\
k_0&=4(k+1)^2-1,\\[2mm]
\tilde{\phi}(k)&=\Phi(\tau(k)),\\
\Phi(k)&=\max\{\Sigma((l+1)(k+1)-1),\Psi((l+1)(k+1)-1)\},\\
\Sigma(k)&=\sigma_2 \left (\left \lceil \frac{\psi(2k+1)+\lceil \ln(4K(k+1))\rceil}{\gamma} \right\rceil +\nalpha+l+1\right)-l,\\
