\Psi(k)&=\max\{\sigma_1((b_A+1)K(k+1)-1)-1,0\},\\[2mm]
\dd&=2^83^3b_A K^2\left(\left\lceil\frac{1}{2}b_A\kone^2\right\rceil +2b_U\kone\right)\left\lceil\frac{1}{\gamma}\right\rceil^2 (k+1)^4,\\
\kone&=K+b_p,\\[2mm]
h_{k,f}(m)&=\max\{\eta(k_0,\tilde{\phi}(K_m),\tilde{f}),\tilde{f}(\sigma(k_0,\tilde{\phi}(K_m))),K_m\}+1,\\
