\section{Proofs of our main results}
In the following, we shall present the proofs of our main quantitative results, Theorems \ref{main}, \ref{main-C2q**}, \ref{main-C4q} and \ref{main-C4q-C2q**}. We use all the notations and definitions from the previous sections.

In the sequel we present the main steps of Xu's proof.

\begin{enumerate}
\item[Step 1:] $(x_n)$ is bounded.
\item[Step 2:] $(x_n)$ is $(\tilde{T}_n)$-asymptotically regular.
\item[Step 3:] $\limsup_n \langle u-Ax^*, x_n-x^*\rangle \le 0$ where $x^*$ is the unique solution of the problem (P). The proof uses \eqref{VIP} and the Demiclosedness Principle (see for example \cite[Lemma 2.2]{Xu03}). Hence weak sequential compactness is used in this step.
\item[Step 4:] $(x_n)$ converges strongly to $x^*$. This is proved by applying Step 3, \eqref{xn1-x-sq-ineq} and Xu's lemma (Proposition \ref{lem-Xu}).
\end{enumerate}

The proofs of the main Theorems will be obtained by giving quantitative versions of each of the steps of Xu's proof. %We have already computed an upper bound for $(x_n)$ in \eqref{}.


\subsection{Rates of asymptotic regularity}

A quantitative version of Step 2 in Xu's proof consists in giving rates of $(\tilde{T}_n)$-asymptotic regularity. Additionally, as a consequence of the quantitative hypothesis \eqref{tau-cond} on $\tau$, we obtain a simultaneous rate of $T_i$-asymptotic regularity of $(x_n)$ for all $0 \le i \le l-1$.

Let $U$ be a mapping on $H$. We say $\phi:\N\to\N$ is a \emph{rate of $U$-asymptotic regularity} of a sequence $(x_n) \subseteq H$ if
\[\forall k\in\N \forall n\ge\phi(k) \left(\|x_n-Ux_n\|\le\frac{1}{k+1}\right)\]
%\end{dfn}
%\begin{dfn}
Let $(U_n)_{n\in\N}$ be a family of mappings on $H$. We say $\phi:\N\to\N$ is a \emph{rate of $(U_n)$-asymptotic regularity} of a sequence $(x_n) \subseteq H$ if
\[\forall k\in\N \forall n\ge\phi(k) \left(\|x_n-U_nx_n\|\le\frac{1}{k+1}\right)\]
%\end{dfn}




%Xu's proof continues by showing the $T_i$-asymptotic regularity of $(x_n)$ for all $i$. We give the respective rate. %given the above condition.

\begin{prop}\label{tildeTn-as-reg}
Let (C1q), (C2q) and (C3q) hold. Then $(x_n)$ is $(\tilde{T}_n)$-asymptotically regular with rate $\Phi$ defined in Theorem \ref{main}.
\end{prop}
\begin{proof}$\ $\\
\noindent \textbf{Claim 1:} $\Psi(k)=\max\{\sigma_1((b_A+1)K(k+1)-1)-1,0\}$ is a rate of convergence of $\|x_{n+1}-T_{n+1}x_n\|$ to $0$.\\ 
\textbf{Proof of claim:} 


We note that, since $\sigma_1$ is increasing, we have that $\nalpha=\max\{\sigma_1(b_A-1)-1,0\} \le \Psi(k)$ for every $k\in\N$.


By \eqref{uATx-bound}, we have $\|u-AT_{n+1}x_n\| \le (b_A+1)K$ for $n\ge \nalpha$.

Taking $n\ge \Psi(k)$: %{\color{red} new equality in Preliminaries?}
\begin{multline*} 
\|x_{n+1}-T_{n+1}x_n\|=\|(I-\alpha_{n+1}A)T_{n+1}x_n+\alpha_{n+1}u-T_{n+1}x_n\|\\=\|-\alpha_{n+1}AT_{n+1}x_n+\alpha_{n+1}u\|=\alpha_{n+1}\|u-AT_{n+1}x_n\| \\\le \frac{1}{(b_A+1)K(k+1)}(b_A+1)K=\frac{1}{k+1}
\end{multline*}
that is, $\Psi$ is a rate of convergence of $\|x_{n+1}-T_{n+1}x_n\|$ to $0$. \hfill $\blacksquare$

\vspace{10pt}

\noindent \textbf{Claim 2:} $\Sigma(k)=\sigma_2 \left (\left \lceil \frac{\psi(2k+1)+\lceil \ln(4K(k+1))\rceil}{\gamma} \right\rceil +\nalpha+l+1\right)-l$ is a rate of convergence of $\|x_{n+l}-x_n\|$ to $0$.\\
\textbf{Proof of claim:} 
We have, by Lemma \ref{xnl1-xn1-ineq}, for $n\ge \nalpha$:
\begin{equation*}
\|x_{n+l+1}-x_{n+1}\| \le (1-\alpha_{n+l+1}\gamma)\|x_{n+l}-x_n\|+\alpha_{n+l+1}\gamma \frac{(b_A+1)K|\alpha_{n+l+1}-\alpha_{n+1}|}{\alpha_{n+l+1}\gamma}
\end{equation*}

We will apply Proposition \ref{quant-lem-Xu02-cn-0} with $s_n:=\|x_{n+\nalpha+l}-x_{n+\nalpha}\|,a_n:=\alpha_{n+\nalpha+l+1}\gamma$ and
\[b_n:=\frac{(b_A+1)K|\alpha_{n+\nalpha+l+1}-\alpha_{n+\nalpha+1}|}{\alpha_{n+\nalpha+l+1}\gamma}\]

We have that $\|x_{n+\nalpha+l}-x_{n+\nalpha}\| \le \|x_{n+\nalpha+l}-p\|+\|p-x_{n+\nalpha}\| \le 2K$.

By (C3q), if $n\ge\psi(k)=\max\left\{\sigma_3\left(\left\lceil\frac{(b_A+1)K}{\gamma}\right\rceil(k+1)-1\right)-\nalpha-1,0\right\}$:

\[\frac{(b_A+1)K|\alpha_{n+\nalpha+l+1}-\alpha_{n+\nalpha+1}|}{\alpha_{n+\nalpha+l+1}\gamma} \le \frac{(b_A+1)K}{\gamma}\cdot\frac{1}{\left\lceil\frac{(b_A+1)K}{\gamma}\right\rceil(k+1)-1+1} \le \frac{1}{k+1}\]
that is, $\psi$ is a convergence rate of $b_n$ to $0$, and thus a $\limsup$-rate of $(b_n)$.

Define $\Theta(k)=\max\left\{\sigma_2 \left (\left \lceil \frac{k}{\gamma} \right\rceil +\nalpha+l+1\right)-\nalpha-l-1,0\right\}$. 
Then
\begin{eqnarray*}
\sum\limits_{n=0}^{\Theta(k)} a_n & = & \gamma\sum\limits_{n=0}^{\Theta(k)} \alpha_{n+\nalpha+l+1} = \gamma\sum\limits_{n=\nalpha+l+1}^{\Theta(k)+\nalpha+l+1} \alpha_n =\gamma
\left(\sum\limits_{n=0}^{\Theta(k)+\nalpha+l+1}\alpha_n - \sum\limits_{n=0}^{\nalpha+l}\alpha_n\right)\\
& \geq &\gamma
\left(\sum\limits_{n=0}^{\sigma_2 \left (\left \lceil \frac{k}{\gamma} \right\rceil +\nalpha+l+1\right)}\alpha_n-\sum\limits_{n=0}^{\nalpha+l}\alpha_n\right)\\
& \geq & \gamma\left(\left\lceil \frac{k}{\gamma} \right\rceil +\nalpha+l+1-\sum\limits_{n=0}^{\nalpha+l}\alpha_n\right) \quad \text{by~} (C2q)\\
& \geq & \gamma\left\lceil \frac{k}{\gamma}\right\rceil \quad \text{as~}\sum\limits_{n=0}^{\nalpha+l}\alpha_n\leq \nalpha+l+1\\
& \geq & k.
\end{eqnarray*}
Thus, $\Theta$ is a rate of divergence for $\sum\limits_{n=0}^\infty a_n$.

We now apply Proposition \ref{quant-lem-Xu02-cn-0}, concluding that $\|x_{n+\nalpha+l}-x_{n+\nalpha}\| \to 0$ with rate of convergence
\begin{equation}
k \mapsto \Theta\left(\psi(2k+1)+\lceil \ln(4K(k+1))\rceil\right)+1
\end{equation}
that is, $\|x_{n+l}-x_n\| \to 0$ with rate of convergence
\begin{align*}
\Sigma(k)&=\Theta\left(\psi(2k+1)+\lceil \ln(4K(k+1))\rceil\right)+\nalpha+1\\
&=\max\left\{\sigma_2 \left (\left \lceil \frac{\psi(2k+1)+\lceil \ln(4K(k+1))\rceil}{\gamma} \right\rceil +\nalpha+l+1\right)-\nalpha-l-1,0\right\}\\
&\ \ +\nalpha+1
\end{align*}
By Lemma \ref{div-rate-k-1}, we have that
\begin{align*}
&\sigma_2 \left (\left \lceil \frac{\psi(2k+1)+\lceil \ln(4K(k+1))\rceil}{\gamma} \right\rceil +\nalpha+l+1\right)\\
\ge& \left \lceil \frac{\psi(2k+1)+\lceil \ln(4K(k+1))\rceil}{\gamma} \right\rceil +\nalpha+l\ge \nalpha+l+1
\end{align*}
Thus
\[\Sigma(k)=\sigma_2 \left (\left \lceil \frac{\psi(2k+1)+\lceil \ln(4K(k+1))\rceil}{\gamma} \right\rceil +\nalpha+l+1\right)-l\]
$\ $ \hfill $\blacksquare$

Taking $n\ge \Sigma((l+1)(k+1)-1)$ we get:
\[\|x_{n+l}-x_n\| \le \frac{1}{(l+1)(k+1)}\]
Taking $n\ge \Psi((l+1)(k+1)-1)$ we get:
\begin{align*}
\|x_{n+l}-T_{n+l}x_{n+l-1}\| &\le \frac{1}{(l+1)(k+1)}\\
\|T_{n+l}x_{n+l-1}-T_{n+l}T_{n+l-1}x_{n+l-2}\| &\le \frac{1}{(l+1)(k+1)}\\
&\vdots\\
\|T_{n+l}\cdots T_{n+2}x_{n+1}-T_{n+l}\cdots T_{n+1}x_n\| &\le \frac{1}{(l+1)(k+1)}
\end{align*}
%Define $\Phi(k):=\max\{\Sigma((l+1)(k+1)-1),\Psi((l+1)(k+1)-1)\}$.
Take $n\ge \Phi(k)=\max\{\Sigma((l+1)(k+1)-1),\Psi((l+1)(k+1)-1)\}$. 
Adding up the above and applying the triangle inequality, we get:
\[\|x_n-T_{n+l}\cdots T_{n+1}x_n\| \le \frac{1}{k+1}\]
that is, $\Phi$ is a rate of $(\tilde{T}_n)$-asymptotic regularity of $(x_n)$.
\end{proof}

\begin{prop}\label{C2q**-tildeTn-as-reg}
Assume that (C1q), (C2q*) and (C3q) hold. Then $(x_n)$ is $(\tilde{T}_n)$-asymptotically regular with rate $\Phi^*$, defined as $\Phi$ from Theorem \ref{main} but with $\Sigma$ replaced by
\[\Sigma^*(k)=\max\{\sigma_2^*(\psi(2k+1), 4K(k+1)-1)-l,\nalpha+1\}\]
\end{prop}

\begin{proof}
Claim 1 of Proposition \ref{tildeTn-as-reg} can be applied here.

We will apply Proposition \ref{Xu-lem-C2q**} with $s_n:=\|x_{n+\nalpha+l}-x_{n+\nalpha}\|,a_n:=\alpha_{n+\nalpha+l+1}\gamma$ and
\[b_n:=\frac{(b_A+1)K|\alpha_{n+\nalpha+l+1}-\alpha_{n+\nalpha+1}|}{\alpha_{n+\nalpha+l+1}\gamma}\]

We already have, as in Claim 2 of Proposition \ref{tildeTn-as-reg}, that \\$\psi(k)=\max\left\{\sigma_3\left(\left\lceil\frac{(b_A+1)K}{\gamma}\right\rceil(k+1)-1\right)-\nalpha-1,0\right\}$ is a $\limsup$-rate of $(b_n)$.

We define
\begin{equation}\label{def-theta*}
\Theta^*(m,k)=\max\{\sigma_2^*(m,k)-\nalpha-l-1,0\}.
\end{equation}
Then, given $m\in\N$, we have that $\Theta^*(m,\cdot)$ is a rate of convergence of $\prod\limits_{n=m}^\infty (1-a_n)$ to $0$.

We now apply Proposition \ref{Xu-lem-C2q**}, concluding that $\|x_{n+\nalpha+l}-x_{n+\nalpha}\| \to 0$ with rate of convergence
\[k\mapsto \Theta^*(\psi(2k+1), 4K(k+1)-1)+1\]
that is, $\|x_{n+l}-x_n\| \to 0$ with rate of convergence
\begin{align*}
\Sigma^*(k)&=\Theta^*(\psi(2k+1), 4K(k+1)-1)+\nalpha+1\\
&=\max\{\sigma_2^*(\psi(2k+1), 4K(k+1)-1)-\nalpha-l-1,0\}+\nalpha+1\\
&=\max\{\sigma_2^*(\psi(2k+1), 4K(k+1)-1)-l,\nalpha+1\}
\end{align*}
\end{proof}

\begin{prop}\label{C4q-tildeTn-as-reg}
Assume that (C1q), (C2q) and (C4q) hold. Then $(x_n)$ is $(\tilde{T}_n)$-asymptotically regular with rate $\tilde{\Phi}$, defined as $\Phi$ from Theorem \ref{main} but with $\Sigma$ replaced by
\[\hat{\Sigma}(k)=\sigma_2\left(\Ns+l+1+\left\lceil\frac{\ln(4K(k+1))}{\gamma}\right\rceil\right)\]
where $\Ns:=\sigma_4(2(b_A+1)K(k+1)-1)$.
\end{prop}

\begin{proof}
Claim 1 of Proposition \ref{tildeTn-as-reg} can be applied here.

We show that $\hat{\Sigma}$ is a rate of convergence of $\|x_{n+l}-x_n\|$ to $0$. The following argument is similar to \cite[Lemma 6.6.(ii)]{FerLeuPin}.

We apply \eqref{xnl1-xn1-ineq2} with $n=\Ns$. Then, noting that $1-x \le e^{-x}$ for $x \ge 0$, we get, for all $m\in\N$:
\begin{equation}\label{C4q-as-reg-eq1}
\|x_{\Ns+l+m}-x_{\Ns+m}\|
%&\le \|x_{n+l}-x_n\|\prod_{i=n+1}^{n+m}(1-\alpha_{i+l}\gamma)\\
%&\ \ + (b_A+1)K_0\sum_{i=n+1}^{n+m}|\alpha_{i+l}-\alpha_i|\\
\le 2K\exp\left(-\gamma \sum_{i=\Ns+1}^{\Ns+m} \alpha_{i+l}\right)+ (b_A+1)K\sum_{i=\Ns+1}^{\Ns+m}|\alpha_{i+l}-\alpha_i|
\end{equation}

By (C4q), we have that
\begin{equation}\label{C4q-as-reg-eq2}
(b_A+1)K\sum_{i=\Ns+1}^{\Ns+m}|\alpha_{i+l}-\alpha_i| \le \frac{1}{2(k+1)}
\end{equation}

Let $M=\hat{\Sigma}(k)-\Ns=\sigma_2\left(\Ns+l+1+\left\lceil\frac{\ln(4K(k+1))}{\gamma}\right\rceil\right)-\Ns$. Note that, by Lemma \ref{div-rate-k-1}, $\sigma_2(k) \ge k-1$ for all $k\in\N$, thus $M\in\N$. By (C2q), it follows that, for all $m\ge M$:
\[\sum_{i=0}^{\Ns+m+l} \alpha_i \ge \sum_{i=0}^{\Ns+M} \alpha_i \ge \Ns+l+1+\left\lceil\frac{\ln(4K(k+1))}{\gamma}\right\rceil \ge \sum_{i=0}^{\Ns+l} \alpha_i + \left\lceil\frac{\ln(4K(k+1))}{\gamma}\right\rceil\]

Thus $\sum_{i=\Ns+1}^{\Ns+m} \alpha_{i+l} = \sum_{i=\Ns+l+1}^{\Ns+m+l} \alpha_i \ge \left\lceil\frac{\ln(4K(k+1))}{\gamma}\right\rceil$, therefore:
\begin{equation}\label{C4q-as-reg-eq3}
2K\exp\left(-\gamma \sum_{i=\Ns+1}^{\Ns+m} \alpha_{i+l}\right) \le 2K\exp(-\ln(4K(k+1)))= \frac{1}{2(k+1)}
\end{equation}
By \eqref{C4q-as-reg-eq1}, \eqref{C4q-as-reg-eq2} and \eqref{C4q-as-reg-eq3} we get that $\|x_{\Ns+l+m}-x_{\Ns+m}\| \le \frac{1}{k+1}$ for $m\ge M$, thus $\|x_{n+l}-x_n\| \le \frac{1}{k+1}$ for $n\ge \Ns+M=\hat{\Sigma}(k)$.

The proof concludes analogously to Proposition \ref{tildeTn-as-reg}.
\end{proof}

\begin{prop}\label{C2q**-C4q-tildeTn-as-reg}
Assume that (C1q), (C2q*) and (C4q) hold. Then $(x_n)$ is $(\tilde{T}_n)$-asymptotically regular with rate $\tilde{\Phi}^*$, defined as $\Phi$ from Theorem \ref{main} but with $\Sigma$ replaced by
\[\hat{\Sigma}^*(k)=\sigma_2^*(\Ns+1,4K(k+1)-1)\]
where $\Ns$ is as in Proposition \ref{C4q-tildeTn-as-reg}.
\end{prop}

\begin{proof}
Claim 1 of Proposition \ref{tildeTn-as-reg} can be applied here.

We show that $\hat{\Sigma}^*$ is a rate of convergence of $\|x_{n+l}-x_n\|$ to $0$.

Note that, by (C2q*), we have that $\sigma_2^*(m,k)\ge m$ for all $k\in\N^*$ and $m\in \N$.

We apply \eqref{xnl1-xn1-ineq2} with $n=\Ns$, obtaining for all $m\in\N$:
\begin{equation}\label{C4q-C2q**-as-reg-eq1}
\|x_{\Ns+l+m}-x_{\Ns+m}\|
%&\le \|x_{n+l}-x_n\|\prod_{i=n+1}^{n+m}(1-\alpha_{i+l}\gamma)\\
%&\ \ + (b_A+1)K_0\sum_{i=n+1}^{n+m}|\alpha_{i+l}-\alpha_i|\\
\le 2K\prod_{i=\Ns+1}^{\Ns+m} (1-\alpha_{i+l}\gamma)+ (b_A+1)K\sum_{i=\Ns+1}^{\Ns+m}|\alpha_{i+l}-\alpha_i|
\end{equation}

%By (C4q), we have \eqref{}.

Let $M:=\hat{\Sigma}^*(k)-\Ns=\sigma_2^*(\Ns+1,4K(k+1)-1)-\Ns \in \N$.

By (C2q*), we have, for $m\ge M$:
\begin{equation}\label{C4q-C2q**-as-reg-eq}
\prod_{i=\Ns+1}^{\Ns+m} (1-\alpha_{i+l}\gamma) \le \frac1{ 4K(k+1)}
\end{equation}

By \eqref{C4q-C2q**-as-reg-eq1},\eqref{C4q-as-reg-eq2} and \eqref{C4q-C2q**-as-reg-eq}, we get $\|x_{\Ns+l+m}-x_{\Ns+m}\| \le \frac{1}{k+1}$ for $m\ge M$, thus $\|x_{n+l}-x_n\| \le \frac{1}{k+1}$ for $n\ge \Ns+M=\hat{\Sigma}^*(k)$.
\end{proof}

\begin{teor}
Assume that $(x_n)$ is $(\tilde{T}_n)$-asymptotically regular with rate $\Phi$ such that $\Phi(k) \ge \nalpha$ for all $k\in\N$ and that $\tau:\N\to\N$ is as in Theorem \ref{main}. Then $(x_n)$ is $T_i$-asymptotically regular for all $0 \le i \le l-1$ with rate $\tilde{\phi}(k)=\Phi(\tau(k))$.
\end{teor}


\begin{proof}
Taking $n \ge \tilde{\phi}(k)=\Phi(\tau(k))$ we get:
\[\|x_n-\tilde{T}_nx_n\| \le \frac{1}{\tau(k)+1}\]
We have $n\ge \nalpha$, thus, by Lemma \ref{bound-lem}, we have that $x_n \in \overline{B}_K(p)$. Thus, by the hypothesis on $\tau$:
\begin{equation*}
\forall i<l \left(\|x_n-T_ix_n\|<\frac{1}{k+1}\right)
\end{equation*}
\end{proof}

\subsubsection{An example}

We obtain quadratic rates of $(\tilde{T}_n)$-asymptotic regularity for $(x_n)$ for a particular sequence $(\alpha_n)$.

\begin{prop}
Let $\alpha_n:=\frac{1}{\gamma(n+J)}$ with $J:=\left\lceil\frac{1}{\gamma}\right\rceil$.

Then Proposition \ref{C2q**-tildeTn-as-reg} gives us the following rate of $(\tilde{T}_n)$-asymptotic regularity for $(x_n)$:
\begin{multline*}
\Phi^*(k)=\max\{4K(l+1)(k+1)(\psi(2(l+1)(k+1)-1)+J-1)-J-l,\\
J((b_A+1)K(l+1)(k+1)-1)-1,\nalpha+1\}
\end{multline*}
with $\psi(k)=\max\left\{l\left\lceil\frac{(b_A+1)K}{\gamma}\right\rceil(k+1)-J-\nalpha-1,0\right\}$ and $\nalpha=\max\{J(b_A-1)-1,0\}$.

Proposition \ref{C2q**-C4q-tildeTn-as-reg} gives us, likewise:
\[\tilde{\Phi}^*(k)=4K(2lJ(b_A+1)K(l+1)(k+1)-1)(l+1)(k+1)-J.\]
\end{prop}


\begin{proof}
We have, for $n\in\N$, that $\gamma(n+J) \ge \gamma J\ge 1$ and thus $\alpha_n \le 1$.

In the following, take $k\in\N$.

\noindent \textbf{Claim 1:}
(C1q) holds with $\sigma_1(k)=Jk$.\\
\textbf{Proof of claim:}
We have that if $n \ge Jk$ then:
\begin{align*}
&n+\left\lceil\frac{1}{\gamma}\right\rceil\ge \left\lceil\frac{1}{\gamma}\right\rceil (k+1)\\
\Rightarrow\ &\gamma\left(n+\left\lceil\frac{1}{\gamma}\right\rceil\right)\ge k+1\\
\Rightarrow\ &\frac{1}{\gamma(n+J)} \le \frac{1}{k+1}.
\end{align*}
\hfill $\blacksquare$

\vspace{10pt}

\noindent \textbf{Claim 2:}
(C2q*) holds with $\sigma_2^*(m,k)=\max\{(m+J-1)(k+1)-J,0\}$.\\
\textbf{Proof of claim:}
\begin{equation*}
\prod_{i=m}^n \left(1-\gamma\frac{1}{\gamma(i+J)}\right)=\prod_{i=m}^n \frac{i+J-1}{i+J}=\frac{m+J-1}{m+J}\cdots \frac{n+J-1}{n+J}=\frac{m+J-1}{n+J}.
\end{equation*}
Taking $n\ge (m+J-1)(k+1)-J$, we get $\frac{m+J-1}{n+J} \le \frac{1}{k+1}$.

\hfill $\blacksquare$

\vspace{10pt}
\noindent \textbf{Claim 3:}
(C3q) holds with $\sigma_3(k)=\max\{l(k+1)-J,0\}$.\\
\textbf{Proof of claim:}
\begin{equation*}
\frac{\alpha_n}{\alpha_{n+l}} = \frac{\frac{1}{\gamma(n+J)}}{\frac{1}{\gamma(n+l+J)}}=\frac{n+l+J}{n+J}=1+\frac{l}{n+J}.
\end{equation*}
Taking $n\ge l(k+1)-J$, we get
\[\left|\frac{\alpha_n}{\alpha_{n+l}}-1\right| = \frac{l}{n+J} \le \frac{1}{k+1}.\]
\hfill $\blacksquare$

\vspace{10pt}

\noindent \textbf{Claim 4:}
(C4q) holds with $\sigma_4(k)=\max\{lJ(k+1)-J-1,0\}$.\\
\textbf{Proof of claim:}


Take $m\ge \sigma_4(k)+1$. Then:
\[
\sum_{i=m}^n |\alpha_{i+l}-\alpha_i| = \sum_{i=m}^n\left|\frac{1}{\gamma(i+l+J)}-\frac{1}{\gamma(i+J)}\right|=\frac{1}{\gamma}\sum_{i=m}^n \left(\frac{1}{i+J}-\frac{1}{i+l+J}\right).
\]
If $n\ge m+l$,
\begin{multline*}
\frac{1}{\gamma}\sum_{i=m}^n \left(\frac{1}{i+J}-\frac{1}{i+l+J}\right)=\\\frac{1}{\gamma}\left(\frac{1}{m+J}+\ldots+\frac{1}{m+l+J-1}-\frac{1}{n+J+1}-\ldots-\frac{1}{n+J+l}\right).\end{multline*}
%if $m\le n < m+l$,
%\[\frac{1}{\gamma}\sum_{i=m}^n \left(\frac{1}{i+J}-\frac{1}{i+l+J}\right)=\frac{1}{\gamma}\left(\frac{1}{m+J}+\ldots+\frac{1}{n+J}-\frac{1}{m+l+J}-\ldots-\frac{1}{n+l+J}\right).\]
Thus, for any $n\in\N$, we get
\[
\sum_{i=m}^n |\alpha_{i+l}-\alpha_i| \le \frac{l}{\gamma(m+J)} \le\frac{l}{\gamma(\sigma_4(k)+J+1)}\le \frac{l}{\gamma lJ(k+1)} \le\frac{1}{k+1}
.\]
\hfill $\blacksquare$

\vspace{10pt}

We thus apply Proposition \ref{C2q**-tildeTn-as-reg} and compute the rate:
\begin{align*}
\Psi(k)&=\max\{\sigma_1((b_A+1)K(k+1)-1)-1,0\}\\
&=\max\{J((b_A+1)K(k+1)-1)-1,0\}\\
&=J((b_A+1)K(k+1)-1)-1,
\end{align*}

\[\nalpha=\max\{\sigma_1(b_A-1)-1,0\}=\max\{J(b_A-1)-1,0\},\]

\begin{align*}
\psi(k)&=\max\left\{\sigma_3\left(\left\lceil\frac{(b_A+1)K}{\gamma}\right\rceil(k+1)-1\right)-\nalpha-1,0\right\}\\
&=\max\left\{\max\left\{l\left(\left\lceil\frac{(b_A+1)K}{\gamma}\right\rceil(k+1)\right)-J,0\right\}-\nalpha-1,0\right\}\\
&=\max\left\{l\left(\left\lceil\frac{(b_A+1)K}{\gamma}\right\rceil(k+1)\right)-J-\nalpha-1,0\right\},
\end{align*}
\begin{align*}
\Sigma^*(k)&=\max\{\sigma_2^*(\psi(2k+1), 4K(k+1)-1)-l,\nalpha+1\}\\
&=\max\{\max\{4K(k+1)(\psi(2k+1)+J-1)-J,0\}-l,\nalpha+1\}\\
&=\max\{4K(k+1)(\psi(2k+1)+J-1)-J-l,\nalpha+1\}.
\end{align*}

Thus:
\begin{align*}
\Phi^*(k)&=\max\{\Sigma^*((l+1)(k+1)-1),\Psi((l+1)(k+1)-1)\}\\
&=\max\{\max\{4K(l+1)(k+1)(\psi(2(l+1)(k+1)-1)+J-1)-J-l,\\
&\ \ \nalpha+1\},J((b_A+1)K(l+1)(k+1)-1)-1\}\\
&=\max\{4K(l+1)(k+1)(\psi(2(l+1)(k+1)-1)+J-1)-J-l,\\
&\ \ J((b_A+1)K(l+1)(k+1)-1)-1,\nalpha+1\}.
\end{align*}

We now apply Proposition \ref{C2q**-C4q-tildeTn-as-reg}:
\begin{align*}
\Ns&:=\sigma_4(2(b_A+1)K(k+1)-1)=\max\{2lJ(b_A+1)K(k+1)-J-1,0\}\\&=2lJ(b_A+1)K(k+1)-J-1,
\end{align*}
\begin{align*}
\hat{\Sigma}^*(k)&=\sigma_2^*(\Ns+1,4K(k+1)-1)\\
&=\max\{4K(2lJ(b_A+1)K(k+1)-1)(k+1)-J,0\}\\
&=4K(2lJ(b_A+1)K(k+1)-1)(k+1)-J.
\end{align*}
Thus:
\begin{align*}
\tilde{\Phi}^*(k)&=\max\{\hat{\Sigma}^*((l+1)(k+1)-1),\Psi((l+1)(k+1)-1)\}\\
&=\max\{4K(2lJ(b_A+1)K(l+1)(k+1)-1)(l+1)(k+1)-J,\\
&\ \ J((b_A+1)K(l+1)(k+1)-1)-1\}\\
&=4K(2lJ(b_A+1)K(l+1)(k+1)-1)(l+1)(k+1)-J,
\end{align*}
since
\begin{align*}
&(8lJ(b_A+1)K^2(l+1)(k+1)-4K)(l+1)(k+1)-J\\
 &\ge (16lJ(b_A+1)K^2-4K)(l+1)(k+1)-J\\
 &\ge (16lJ(b_A+1)-4)K^2(l+1)(k+1)-J\\
  &\ge 14lJ(b_A+1)K^2(l+1)(k+1)-J\\
   &\ge J(b_A+1)K(l+1)(k+1)-J-1.
\end{align*}
\end{proof}



