\subsection{General quantitative results on finite families of mappings}

In this subsection, we present general quantitative results that will be used to get quantitative versions of the next steps in Xu's proof. These results are adaptations to our settings of similar results from \cite{FerLeuPin, Koh11}.

\subsubsection{A general principle}

The following is a slight generalization of \cite[Proposition 6.4.]{FerLeuPin} and is proved analogously. We use this principle in order to, following the previous two results, compute a metastability rate for $(x_n)$.

\begin{prop} \label{FLPres}
Let $(X,d)$ be a metric space and let $D$ be a subset of $X$. Let $(u_n)$ be a sequence in $X$ and let $P\in\N$. Let $U_0,\ldots,U_{l-1}$ be mappings from $X$ to $X$ and $\phi_0,\ldots,\phi_{l-1}$ be mappings from $X\times X$ to $\R$.

Assume there are monotone functions $\bar{\delta},\bar{\psi},\bar{\gamma},\bar{\eta},\bar{\sigma}$ such that:
\begin{enumerate}[(i)]
\item %\begin{equation*}
$\forall k \in \N \forall f\in \N^\N \exists N \le \bar{\psi}(k,\tilde{f}) \exists x\in D \left[\forall i<l \left(d(U_i(x),x)< \frac{1}{\tilde{f}(N)+1}\right)  \right.\\\left. \land\forall n \in [N+P,\tilde{f}(N)+P] \forall i<l \left(\phi_i(x,x)<\phi_i(x,u_n) + \frac{1}{k+1}\right)\right]$
%\end{equation*}
\item %\begin{equation*}
$\forall k,n \in \N \forall f\in \N^\N \forall x\in D \left[\forall i<l \left(d(U_i(x),x) \le \frac{1}{\bar{\gamma}(k,n,\tilde{f})+1}\right)  \right.\\\left. \land\forall j \in [n+P,\bar{\eta}(k,n,\tilde{f})+P] \forall i<l \left(\phi_i(x,x)\le\phi_i(x,u_j) + \frac{1}{\bar{\delta}(k)+1}\right) \right.\\\left. \to\exists M \le \bar{\sigma}(k,n,\tilde{f}) \forall m \in [M,\tilde{f}(M)] \left(d(u_m,x) \le \frac{1}{k+1}\right)\right]$
%\end{equation*}
\end{enumerate}
Then:
\begin{equation*}
\forall k\in \N \forall f\in \N^\N \exists M \le \phi(k,\tilde{f}) \forall m,n \in [M,\tilde{f}(M)] \left(d(u_m,u_n) \le \frac{1}{k+1}\right)
\end{equation*}
where $\phi(k,f):= \bar{\sigma}(2k+1,\bar{\psi}(\bar{\delta}(2k+1),\bar{f}),f)$ and $\bar{f}(m) := \max\{\bar{\gamma}(2k+1,m,f),\\\bar{\eta}(2k+1,m,f)\}$.
\end{prop}


\subsubsection{Quantitative projection arguments}

Let $H$ be a Hilbert space, $D$ a bounded subset of $H$ and $b\in\N^*$ an upper bound for the diameter of $D$. Let $l\in\N$ and let $T_0,\ldots,T_{l-1}$ be nonexpansive mappings on $H$.

In \cite[Proposition 3.1]{FerLeuPin}, proof mining was applied to a weakening of a projection argument (namely, the existence of a projection of a point on a bounded closed convex set) used by Browder. The resulting quantitative statement can in fact be generalized, under a certain condition for the given bounded set, to any bounded function rather than just the squared distance to a point.

\begin{prop}\label{quant-min-gen}
Assume that for any $k\in\N$ there is $x\in D$ such that
\[\forall i<l\left(\|T_ix-x\| <\frac{1}{k+1}\right)\]
Let $\phi:D\to\R$ be a function such that there are $m_\phi,M_\phi\in\N$ satisfying $-m_\phi \le \phi(x) \le M_\phi$ for $x\in D$.

Then for any $k\in\N$ and $f:\N\to\N$ there is $N\in\N$ such that $N \le (\tilde{f}+1)^{(r)}(0)$ and
\begin{multline}
\exists x\in D \left(\forall i<l\left(\|T_ix-x\| <\frac{1}{\tilde{f}(N)+1}\right) \right.\\ \left. \land \forall z\in D\left(\forall i<l\left( \|T_iz-z\| \le \frac{1}{N+1}\right)\to \phi(x)<\phi(z) + \frac{1}{k+1}\right)\right)
\end{multline}
where $r:=(m_\phi+M_\phi)(k+1)$.
\end{prop}

\begin{proof}
We prove the following: for any $k\in\N$ and $f:\N\to\N$ there is $N\in\N$ such that $N \le \tilde{f}^{(r)}(0)$ and
\begin{multline}
\exists x\in D \left(\forall i<l\left(\|T_ix-x\| \le\frac{1}{\tilde{f}(N)+1}\right) \right.\\ \left. \land \forall z\in D\left(\forall i<l\left( \|T_iz-z\| \le \frac{1}{N+1}\right)\to \phi(x)<\phi(z) + \frac{1}{k+1}\right)\right)
\end{multline}
Applying this to $f+1$ gives the proposition.

Assume the above result is not true, that is, there are $k\in\N$ and $f:\N\to\N$ such that for all $N\in\N$ with $N \le \tilde{f}^{(r)}(0)$
\begin{multline}\label{contpos}
\forall x\in D \left(\forall i<l\left(\|T_ix-x\| \le\frac{1}{\tilde{f}(N)+1}\right)  \right.\\ \left. \to\exists z\in D\left(\forall i<l\left( \|T_iz-z\| \le \frac{1}{N+1}\right)\land \phi(z)\le\phi(x) - \frac{1}{k+1}\right)\right)
\end{multline}

Note that, since $\tilde{f}$ is monotone, the sequence $(\tilde{f}^{(j)}(0))_{j\in\N}$ is monotone.

We define $x_0,\ldots,x_{r+1}\in D$ as follows:
\begin{enumerate}[(i)]
\item By hypothesis, take $x_0$ such that
\[\forall i<l\left( \|T_ix_0-x_0\| \le \frac{1}{\tilde{f}^{(r+1)}(0)+1}\right)\]
\item Now we define $x_{j+1}$ for $j\le r$. Assume $x_j$ is such that
\[\forall i<l\left( \|T_ix_j-x_j\| \le \frac{1}{\tilde{f}^{(r-j+1)}(0)+1}\right)\]
By \eqref{contpos} with $x=x_j$ and $N=\tilde{f}^{(r-j)}(0)$, we can take $z\in D$ such that
\[\forall i<l\left( \|T_iz-z\| \le \frac{1}{\tilde{f}^{(r-j)}(0)+1}\right)\land \phi(z)\le\phi(x_j) - \frac{1}{k+1}\]

Let $x_{j+1}$ be one such $z$.
\end{enumerate}

We have, thus, for all $j\le r$,
\[\phi(x_{j+1})\le\phi(x_j) - \frac{1}{k+1}\]
which implies
\[\phi(x_{r+1}) \le \phi(x_0) - \frac{r+1}{k+1} \le M_\phi -\frac{(m_\phi+M_\phi)(k+1)+1}{k+1} = -m_\phi-\frac{1}{k+1}<-m_\phi\]
This is a contradiction.
\end{proof}


We denote, for all $x,y\in H$ and $\lambda \in [0,1]$,
\[w_\lambda(x,y):=(1-\lambda)x+\lambda y.\]

The following result is an immediate extension to a finite famiy of mappings of \cite[Lemma 2.3.]{Koh11}.
\begin{lemma}  \label{conv-quant}
Assume furthermore that $D$ is convex.

For all $k\in\N$ and $y_1,y_2\in D$,
\begin{multline}
\forall j\in\{1,2\} \forall i<l\left(\|T_iy_j-y_j\| \le \frac{1}{12b(k+1)^2}\right)\\
\to \forall \lambda\in[0,1]\forall i<l\left(\|T_iw_\lambda(y_1,y_2)-w_\lambda(y_1,y_2)\| <\frac{1}{k+1}\right)
\end{multline}
\end{lemma}

The following result is similar to \cite[Corollary 3.5.]{FerLeuPin}.

\begin{prop}\label{quant-min-gamma-gen}
Assume that $D$ and $\phi: D\to\R$ satisfy the hypotheses in Proposition \ref{quant-min-gen} and that $D$ is convex.



For any $k\in \N$ and $f:\N \to\N$ there is $N\in\N$ such that $N \le 12b((\check{f}+1)^{(r)}(0)+1)^2$ with $r:=(m_\phi+M_\phi)(k+1)$ and $\check{f}(m):=\max\{\tilde{f}(12b(m+1)^2),12b(m+1)^2\}$ and there is $x\in D$ for which the following two properties hold:
\[\forall i<l \left(\|T_ix-x\| < \frac{1}{\tilde{f}(N)+1}\right)\]
\begin{multline*}
\forall y\in D \left(\forall i<l \left(\|T_iy-y\|\le\frac{1}{N+1}\right) \to \forall \lambda\in [0,1] \left(\phi(x) < \phi(w_\lambda(x,y)) + \frac{1}{k+1}\right)\right)
\end{multline*}
\end{prop}

\begin{proof}
By Proposition \ref{quant-min-gen}, there are $x\in D$ and $N'\in\N$ such that $N' \le (\check{f}+1)^{(r)}(0)$ and
\begin{multline}\label{eq-min}
\left(\forall i<l\left(\|T_ix-x\| <\frac{1}{\check{f}(N')+1}\right) \right.\\ \left. \land \forall z\in D\left(\forall i<l\left( \|T_iz-z\| \le \frac{1}{N'+1}\right)\to \phi(x)<\phi(z) + \frac{1}{k+1}\right)\right)
\end{multline}

Let $N:=12b(N'+1)^2$. Then $N\le 12b((\check{f}+1)^{(r)}(0)+1)^2$. Furthermore, $\tilde{f}(N) \le \check{f}(N')$, thus
\[\forall i<l\left(\|T_ix-x\| <\frac{1}{\tilde{f}(N)+1}\right)\]

Now let $y\in D$ such that $\forall i<l \left(\|T_iy-y\|\le\frac{1}{N+1}\right)$. Then we have $\forall i<l \left(\|T_iy-y\|<\frac{1}{12b(N'+1)^2}\right)$. Furthermore, we have:
\[\forall i<l\left(\|T_ix-x\| <\frac{1}{12b(N'+1)^2}\right)\]

By Lemma \ref{conv-quant}, we get
\[\forall i<l\left(\|T_iw_\lambda(x,y)-w_\lambda(x,y)\| <\frac{1}{N'+1}\right)\]

By \eqref{eq-min}, we get the result.
\end{proof}



\subsection{A quantitative version of the variational formulation of the problem}

In Step 3 of Xu's proof, the variational characterization \eqref{VIP} of the quadratic optimization problem (P) is used. In the following we give a quantitative version of \eqref{VIP}.

This quantitative result corresponds to the existence of a solution of (P).
\begin{prop}\label{quant-min-P}
Take $D=\overline{B}_K(p)$. For any $k\in\N$ and $f:\N\to\N$ there is $N\in\N$ such that $N \le (\tilde{f}+1)^{(r)}(0)$ and
\begin{multline*}
\exists x\in D \left(\forall i<l\left(\|T_ix-x\| <\frac{1}{\tilde{f}(N)+1}\right) \land \forall z\in D\right.\\\left. \left(\forall i<l\left( \|T_iz-z\| \le \frac{1}{N+1}\right)\to \frac{1}{2}\langle Ax,x\rangle-\langle x,u\rangle<\frac{1}{2}\langle Az,z\rangle-\langle z,u\rangle + \frac{1}{k+1}\right)\right)
\end{multline*}
where $r:=\left(\left\lceil\frac{1}{2}b_A\kone^2\right\rceil +2b_U\kone\right)(k+1)$ where $\kone:=K+b_p$ with $b_p\in\N^*$ such that $b_p \ge \|p\|$ and $b_U\in\N^*$ is such that $b_U\ge\|u\|$.
\end{prop}

\begin{proof}
We apply Proposition \ref{quant-min-gen} with $\phi(x)=\frac{1}{2}\langle Ax,x\rangle-\langle x,u\rangle$.

The required condition for $D$ is clearly satisfied.

Take $x\in D$. Note that $\|x\| \le \kone$. Thus we have:
\[\phi(x) \le \frac{1}{2}\|A\|\|x\|^2+\|x\|\|u\| \le \left\lceil\frac{1}{2}b_A\kone^2\right\rceil +b_U\kone\]
and
\[\phi(x) \ge \frac{1}{2}\gamma\|x\|^2-\|x\|\|u\| \ge -b_U\kone\]
\end{proof}


\begin{prop}\label{quant-min-gamma-P}
Take $D=\overline{B}_K(p)$.

For any $k\in \N$ and $f:\N \to\N$ there is $N\in\N$ such that $N \le 24K((\check{f}+1)^{(r)}(0)+1)^2$ with $r:=\left(\left\lceil\frac{1}{2}b_A\kone^2\right\rceil +2b_U\kone\right)(k+1)$ and $\check{f}(m):=\max\{\tilde{f}(24K(m+1)^2),24K(m+1)^2\}$ and there is $x\in D$ for which the following two properties hold:
\[\forall i<l \left(\|T_ix-x\| < \frac{1}{\tilde{f}(N)+1}\right)\]
\begin{multline*}
\forall y\in D \left(\forall i<l \left(\|T_iy-y\|\le\frac{1}{N+1}\right) \right.\to\\ \left.\forall \lambda\in [0,1] \left(\frac{1}{2}\langle Ax,x\rangle-\langle x,u\rangle < \frac{1}{2}\langle Aw_\lambda(x,y),w_\lambda(x,y)\rangle-\langle w_\lambda(x,y),u\rangle + \frac{1}{k+1}\right)\right)
\end{multline*}
\end{prop}

\begin{proof}
We apply Proposition \ref{quant-min-gamma-gen} with $\phi(x)=\frac{1}{2}\langle Ax,x\rangle-\langle x,u\rangle$, $M_\phi=\left\lceil\frac{1}{2}b_A\kone^2\right\rceil +b_U\kone, m_\phi=b_U\kone$  (see proof of Corollary \ref{quant-min-P}) and $b=2K$.
\end{proof}

The following result is similar to \cite[Lemma 2.7.]{Koh11}, but constitutes one of the places where the difference between Xu's result and Bauschke's theorem is illustrated - the role of the linear operator $A$.

\begin{prop}\label{propkey}
Let $x,y\in H$ and $b\in\N^*$ such that $\|x-y\| \le b$. Then, for any $k\in\N$:
\begin{multline}
\frac{1}{2}\langle Ax,x\rangle-\langle x,u\rangle \le \frac{1}{2}\langle Aw_{\lambda_k}(x,y),w_{\lambda_k}(x,y)\rangle-\langle w_{\lambda_k}(x,y),u\rangle + \frac{1}{3b_A b^2(k+1)^2} \\\to \langle u-Ax,y-x \rangle < \frac{1}{k+1}
\end{multline}
where $\lambda_k:=\frac{1}{2b_Ab^2(k+1)}$.

In particular, we get:
\begin{multline}
\forall \lambda \in[0,1] \left(\frac{1}{2}\langle Ax,x\rangle-\langle x,u\rangle \right.\\
\left.\le \frac{1}{2}\langle Aw_\lambda(x,y),w_\lambda(x,y)\rangle-\langle w_\lambda(x,y),u\rangle + \frac{1}{3b_A b^2(k+1)^2}\right) \\\to \langle u-Ax,y-x \rangle < \frac{1}{k+1}
\end{multline}
\end{prop}

\begin{proof}
First we observe that, since $A$ is linear:
\begin{eqnarray*}
&\frac{1}{2}\langle Aw_{\lambda_k}(x,y),w_{\lambda_k}(x,y)\rangle-\langle w_{\lambda_k}(x,y),u\rangle\\
=&\frac{1}{2}\langle A(x+\lambda_k(y-x)),x+\lambda_k(y-x)\rangle-\langle x+\lambda_k(y-x),u\rangle\\
=&\frac{1}{2}(\langle Ax,x\rangle + \lambda_k\langle Ax,y-x\rangle +\lambda_k\langle A(y-x),x+\lambda_k(y-x)\rangle)-\langle x,u\rangle-\lambda_k\langle y-x,u\rangle
\end{eqnarray*}

We now assume that
\[\frac{1}{2}\langle Aw_{\lambda_k}(x,y),w_{\lambda_k}(x,y)\rangle-\langle w_{\lambda_k}(x,y),u\rangle -\left(\frac{1}{2}\langle Ax,x\rangle-\langle x,u\rangle\right)\ge - \frac{1}{3b_A b^2(k+1)^2}\]
that is,
\begin{multline*}
\frac{\lambda_k}{2}\langle Ax,y-x\rangle+\frac{\lambda_k}{2}\langle Ay-Ax, x+\lambda_k(y-x)\rangle-\lambda_k\langle y-x,u\rangle \ge -\frac{1}{3b_A b^2(k+1)^2}
\end{multline*}
thus we get
\begin{multline*}
\frac{1}{2}\langle Ax,y-x\rangle+\frac{1}{2}\langle Ay, x\rangle-\frac{1}{2}\langle Ax, x\rangle+\frac{1}{2}\langle Ay-Ax,\lambda_k(y-x)\rangle-\langle y-x,u\rangle \\\ge -\frac{1}{3b_A b^2(k+1)^2\lambda_k}
\end{multline*}

We now note that $\frac{1}{3b_A b^2(k+1)^2\lambda_k}=\frac{2}{3(k+1)}$. We then recall that $\langle Ay,x\rangle =\langle y,Ax\rangle$ to deduce:

\begin{equation*}
\langle Ax,y-x\rangle+\frac{\lambda_k}{2}\langle A(y-x),y-x\rangle-\langle y-x,u\rangle \ge -\frac{2}{3(k+1)}
\end{equation*}
that is,
\begin{equation*}
\langle Ax-u,y-x\rangle+\frac{\lambda_k}{2}\langle A(y-x),y-x\rangle \ge -\frac{2}{3(k+1)}
\end{equation*}
then, by Cauchy-Schwarz:
\begin{equation*}
\langle Ax-u,y-x\rangle+\frac{\lambda_k}{2}b_Ab^2 \ge -\frac{2}{3(k+1)}
\end{equation*}

Now, noting that $\frac{\lambda_k}{2}b_Ab^2=\frac{1}{4(k+1)}$:
\begin{equation*}
\langle Ax-u,y-x\rangle \ge -\frac{2}{3(k+1)}-\frac{1}{4(k+1)} > -\frac{1}{k+1}
\end{equation*}
\end{proof}

We thus deduce the quantitative version of \eqref{VIP}.

\begin{prop}\label{quant-lem2.3}
Take $D=\overline{B}_K(p)$.

For any $k\in \N$ and $f:\N \to\N$ there is $N\in\N$ such that $N \le 24K((\check{f}+1)^{(R)}(0)+1)^2$ with $R:=12b_A K^2\left(\left\lceil\frac{1}{2}b_A\kone^2\right\rceil +2b_U\kone\right)(k+1)^2$ and $\check{f}$ as in Proposition \ref{quant-min-gamma-P} and there is $x\in D$ for which the following two properties hold:
\[\forall i<l \left(\|T_ix-x\| < \frac{1}{\tilde{f}(N)+1}\right)\]
\begin{equation*}
\forall y\in D \left(\forall i<l \left(\|T_iy-y\|\le\frac{1}{N+1}\right) \to \langle u-Ax,y-x \rangle < \frac{1}{k+1}\right)
\end{equation*}
\end{prop}

\begin{proof}
We apply Proposition \ref{quant-min-gamma-P} with $12b_A K^2(k+1)^2-1$ in place of $k$ and then Proposition \ref{propkey} (with $b:=2K$).
\end{proof}


\subsection{The compactness argument adapted to Xu's iteration}\label{XuProof}
%\emph{(The following is an abstract proof using the Heine-Borel compactness principle.)}

Now we expose, in accordance with the paper \cite{FerLeuPin} by Ferreira, Leu\c{s}tean and Pinto, a modification of Step 3 of Xu's proof, where the argument involving weak sequential compactness is replaced by a Heine-Borel compactness principle. This modified proof illustrates how we may use the method from the aforementioned paper in order to compute a metastability rate.

\vspace{10pt}

Let $x^*$ be the unique solution of Problem (P). Take $D=\overline{B}_K(p)$.




By \eqref{VIP} we thus get, for all $k\in\N$:
\begin{equation}
\forall y \in D \left(\forall i<l (T_iy=y) \to \langle u-Ax^*, y-x^*\rangle < \frac{1}{k+1}\right)
\end{equation}
Define, for $m\in\N$:
\begin{equation}
\Omega_m:=\bigcup_{i<l}\left\{y\in H: \|T_iy-y\| > \frac{1}{m+1}\right\}\cup\left\{y\in H: \langle u-Ax^*, y-x^*\rangle < \frac{1}{k+1}\right\}
\end{equation}
Then $D \subseteq \bigcup_{m\in\N} \Omega_m$. Then by the principle of Heine-Borel compactness, we have an $N\in\N$ such that $D \subseteq \Omega_N$ (note how the sequence $(\Omega_m)$ is increasing). Thus:
\begin{equation} \label{a}
\forall y \in D \left(\forall i<l\left( \|T_iy-y\| \le \frac{1}{N+1}\right) \to \langle u-Ax^*, y-x^*\rangle < \frac{1}{k+1}\right)
\end{equation}

The above reasoning is made quantitative by Proposition \ref{quant-lem2.3}.

As $(x_n)$ is $T_i$-asymptotically regular for $0 \le i \le l-1$, we apply \eqref{a}, deducing that $\limsup_n \langle u-Ax^*, x_n-x^*\rangle \le 0$.
%The following result is a quantitative version of this step.
%\begin{equation*}
%\exists j\in\N \forall n\ge j \left(\langle u-Ax^*, x_n-x^*\rangle < \frac{1}{k+1}\right)
%\end{equation*}
%that is, $\tilde{\Phi}$ is a $\limsup$-rate of $(\langle u-Ax^*, x_n-x^*\rangle)$.

The quantitative result that expresses this modification is given in the sequel.





%We now apply the above to $(x_n)$, given its $T_i$-asymptotic regularity for $i<l$. This corresponds to step (ii) in the compactness argument. %(this corresponds to applying the general principle from Section 4 of \cite{FerLeuPin}).
\begin{prop}\label{cond-innerprod-xn}
Assume (C1q) holds. Take $D=\overline{B}_K(p)$. Let $\tilde{\phi}$ be a monotone simultaneous rate of $T_i$-asymptotic regularity of $(x_n)$ for all $0\le i \le l-1$ such that $\tilde{\phi}(k) \ge \nalpha$ for all $k\in\N$.

For any $k\in \N$ and $f:\N \to\N$ there is $N'\in\N$ and $x\in D$ such that $N' \le \tilde{\phi}(24K((\mathring{f}+1)^{(R)}(0)+1)^2)$ with $\mathring{f}(m):=\max\{\tilde{f}(\tilde{\phi}(24K(m+1)^2)),24K(m+1)^2\}$ and $R$ as before, for which the following two properties hold:
\[\forall i<l \left(\|T_ix-x\| < \frac{1}{\tilde{f}(N')+1}\right)\]
\[\forall n\ge N' \left(\langle u-Ax,x_n-x \rangle < \frac{1}{k+1}\right)\]
In particular:
\[\forall n\in[N',f(N')] \left(\langle u-Ax,x_n-x \rangle < \frac{1}{k+1}\right)\]
\end{prop}
\begin{proof}
We apply Proposition \ref{quant-lem2.3} with $g(n):=\tilde{f}(\tilde{\phi}(n))$ in place of $f$. We get $N\in\N$ such that $N \le 24K((\mathring{f}+1)^{(R)}(0)+1)^2$ with $R:=12b_A K^2\left(\left\lceil\frac{1}{2}b_A\kone^2\right\rceil +2b_U\kone\right)\\(k+1)^2$ and $\mathring{f}(m):=\check{g}(m)=\max\{\tilde{f}(\tilde{\phi}(24K(m+1)^2)),24K(m+1)^2\}$ and we get $x\in D$ for which the following two properties hold:
\[\forall i<l \left(\|T_ix-x\| < \frac{1}{\tilde{f}(\tilde{\phi}(N))+1}\right)\]
\begin{equation*}
\forall y\in D \left(\forall i<l \left(\|T_iy-y\|\le\frac{1}{N+1}\right) \to \langle u-Ax,y-x \rangle < \frac{1}{k+1}\right)
\end{equation*}

We have that
\[\forall n\ge \tilde{\phi}(N)\forall i<l \left(\|T_ix_n-x_n\|\le\frac{1}{N+1}\right)\]
Since $\tilde{\phi}(N) \ge \nalpha$, by Lemma \ref{bound-lem} we get that $x_n\in D$ for $n\ge \tilde{\phi}(N)$, thus
\[\forall n\ge \tilde{\phi}(N) \left(\langle u-Ax,x_n-x \rangle < \frac{1}{k+1}\right)\]
Take $N':=\tilde{\phi}(N)$. Since $\tilde{\phi}$ is monotone, we have $N' \le \tilde{\phi}(24K((\mathring{f}+1)^{(R)}(0)+1)^2)$. Furthermore,
\[\forall i<l \left(\|T_ix-x\| < \frac{1}{\tilde{f}(N')+1}\right)\]
\end{proof}

\subsection{Rates of metastability}

The following two results correspond to the last step of Xu's proof.

\begin{prop} \label{step7}
Assume (C1q) and (C2q) hold. Let $k,n\in\N,x\in \overline{B}_K(p)$ and let $f:\N \to \N$ be a monotone function. If
\[\forall i<l \left(\|T_ix-x\| \le \frac{1}{\eta(k,n,f)+1}\right)\]
and
\[\forall j \in [n+\nalpha+1,f(\sigma(k,n))+\nalpha+1] \left(\langle u-Ax,x_j-x\rangle \le \frac{\gamma}{6(k+1)}\right)\]
with $\sigma(k,n)= \sigma_2 \left (\left \lceil \frac{n+\lceil \ln(12K^2(k+1))\rceil}{\gamma} \right\rceil +\nalpha+1\right)-\nalpha$, then
\[\forall j\in [\sigma(k,n)+\nalpha,f(\sigma(k,n)+\nalpha)]\left(\|x_j-x\|^2 \le \frac{1}{k+1}\right)\]
%where $\nalpha:=\sigma_1(b_A-1)$.
\end{prop}


\begin{proof}
For $n\ge \nalpha$, by \eqref{xn1-x-sq-ineq}:
\begin{eqnarray*}
\|x_{n+1}-x\|^2 &\le& (1-\alpha_{n+1}\gamma)\|x_n-x\|^2+2\|x_n-x\|\|T_{n+1}x-x\|\\
&&+\|T_{n+1}x-x\|^2+\alpha_{n+1}\gamma\frac{2}{\gamma}\langle u-Ax,x_{n+1}-x\rangle
\end{eqnarray*}
We show that we can apply Proposition \ref{XuMeta} with
$s_n:=\|x_{n+\nalpha}-x\|^2,\quad a_n:=\alpha_{n+\nalpha+1}\gamma,\quad b_n:=\frac{2}{\gamma}\langle u-Ax,x_{n+\nalpha+1}-x\rangle, \quad c_n:=2\|x_{n+\nalpha}-x\|\|T_{n+\nalpha+1}x-x\|+\|T_{n+\nalpha+1}x-x\|^2$ and $q:=f(\sigma(k,n))$ for arbitrary $k,n\in\N$.

Analogously to what was done in Claim 2 of Proposition \ref{tildeTn-as-reg}, we have that $\tilde{\Theta}(k) = \max\left\{\sigma_2 \left (\left \lceil \frac{k}{\gamma} \right\rceil +\nalpha+1\right)-\nalpha-1,0\right\}$ is a rate of divergence for $\sum\limits_{n=0}^{+\infty} a_n$.


Given $p\in F$, we have that $\|x_{n+\nalpha}-x\|^2 \le (\|x_{n+\nalpha}-p\|+\|p-x\|)^2 \le 4K^2$.

We have, for $j\in\N$: %for $n\ge\sigma_1(b_A-1)$:
\begin{eqnarray*}
c_j &=&2\|x_{j+\nalpha}-x\|\|T_{j+\nalpha+1}x-x\|+\|T_{j+\nalpha+1}x-x\|^2\\
&\le& 4K\frac{1}{\eta(k,n,f)+1}+\frac{1}{(\eta(k,n,f)+1)^2}\\
&\le& 4K\frac{1}{24K(k+1)(f(\sigma(k,n))+1)+1}+\frac{1}{(\max\{f(\sigma(k,n)),6k+5\}+1)^2}\\
&\le& \frac{1}{6(k+1)(f(\sigma(k,n))+1)} +\frac{1}{6(k+1)(f(\sigma(k,n))+1)}\\
&=&\frac{1}{3(k+1)(f(\sigma(k,n))+1)}=\frac{1}{3(k+1)(q+1)}
\end{eqnarray*}

By hypothesis we get
\[\forall j \in [n,q] \left(b_j \le \frac{1}{3(k+1)}\right)\]
Thus, Proposition \ref{XuMeta} gives us
\[\forall j\in [\sigma(k,n),f(\sigma(k,n))]\left(\|x_{j+\nalpha}-x\|^2 \le \frac{1}{k+1}\right)\]
that is,
\[\forall j\in [\sigma(k,n)+\nalpha,f(\sigma(k,n))+\nalpha]\left(\|x_j-x\|^2 \le \frac{1}{k+1}\right)\]

with
\begin{align*}
\sigma(k,n)&=\theta(n+\lceil \ln(3L(k+1))\rceil)+1\\
&=\tilde{\Theta}(n+\lceil \ln(12K^2(k+1))\rceil)+1\\
&=\max\left\{\sigma_2 \left (\left \lceil \frac{n+\lceil \ln(12K^2(k+1))\rceil}{\gamma} \right\rceil +\nalpha+1\right)-\nalpha-1,0\right\}+1\\
&=\max\left\{\sigma_2 \left (\left \lceil \frac{n+\lceil \ln(12K^2(k+1))\rceil}{\gamma} \right\rceil +\nalpha+1\right)-\nalpha,1\right\}
\end{align*}
Note that, by Lemma \ref{div-rate-k-1}, we have that
\begin{equation*}
\sigma_2 \left (\left \lceil \frac{n+\lceil \ln(12K^2(k+1))\rceil}{\gamma} \right\rceil +\nalpha+1\right)
\ge\left \lceil \frac{n+\lceil \ln(12K^2(k+1))\rceil}{\gamma} \right\rceil +\nalpha
\ge\nalpha+1
\end{equation*}
thus
\[\sigma(k,n)=\sigma_2 \left (\left \lceil \frac{n+\lceil \ln(12K^2(k+1))\rceil}{\gamma} \right\rceil +\nalpha+1\right)-\nalpha\]


Now, given $g:\N\to\N$ monotone, take $f:\N\to\N$ with $f(j):=g(j+\nalpha)$ for all $j\in\N$. Then $f$ is monotone and $g(j+\nalpha) \le f(j)+\nalpha$ for all $j\in\N$. From the above we get
\[\forall j\in [\sigma(k,n)+\nalpha,g(\sigma(k,n)+\nalpha)]\left(\|x_j-x\|^2 \le \frac{1}{k+1}\right)\]
\end{proof}

\begin{prop} \label{step7-C2q**}
Assume (C1q) and (C2q*) hold. Let $k,n\in\N,x\in \overline{B}_K(p)$ and let $f:\N \to \N$ be a monotone function. If
\[\forall i<l \left(\|T_ix-x\| \le \frac{1}{\eta(k,n,f)+1}\right)\]
and
\[\forall j \in [n+\nalpha+1,f(\sigma^*(k,n))+\nalpha+1] \left(\langle u-Ax,x_j-x\rangle \le \frac{\gamma}{6(k+1)}\right)\]
with $\sigma^*(k,n)=\max\left\{\sigma_2^*\left(n, \frac{1}{12K^2(k+1)}\right)-\nalpha-l,1\right\}$, then
\[\forall j\in [\sigma^*(k,n)+\nalpha,f(\sigma^*(k,n)+\nalpha)]\left(\|x_j-x\|^2 \le \frac{1}{k+1}\right)\]
%where $\nalpha:=\sigma_1(b_A-1)$.
\end{prop}

\begin{proof}
We have \eqref{xn1-x-sq-ineq} for $n\ge \nalpha$. We show that we can apply Proposition \ref{XuMeta-C2q**} with
$s_n:=\|x_{n+\nalpha}-x\|^2,\quad a_n:=\alpha_{n+\nalpha+1}\gamma,\quad b_n:=\frac{2}{\gamma}\langle u-Ax,x_{n+\nalpha+1}-x\rangle, \quad c_n:=2\|x_{n+\nalpha}-x\|\|T_{n+\nalpha+1}x-x\|+\|T_{n+\nalpha+1}x-x\|^2$ and $q:=f(\sigma^*(k,n))$ for arbitrary $k,n\in\N$.

We know that, given $m\in\N$ and defining $\Theta^*$ as in \eqref{def-theta*}, $\Theta^*(m,\cdot)$ is a rate of convergence of $\prod\limits_{n=m}^\infty (1-a_n)$ to $0$.

We know from the proof of Proposition \ref{step7} that the conditions on $b_n$ and $c_n$ are satisfied.

Thus, Proposition \ref{XuMeta-C2q**} gives us
\[\forall j\in [\sigma^*(k,n),f(\sigma^*(k,n))]\left(\|x_{j+\nalpha}-x\|^2 \le \frac{1}{k+1}\right)\]
that is,
\[\forall j\in [\sigma^*(k,n)+\nalpha,f(\sigma^*(k,n))+\nalpha]\left(\|x_j-x\|^2 \le \frac{1}{k+1}\right)\]

with

\begin{align*}
\sigma^*(k,n)&={\rm A'}\left(n, \frac{1}{3D(k+1)}\right)+1\\
&=\Theta^*\left(n, \frac{1}{12K^2(k+1)}\right)+1\\
&=\max\left\{\sigma_2^*\left(n, \frac{1}{12K^2(k+1)}\right)-\nalpha-l-1,0\right\}+1\\
&=\max\left\{\sigma_2^*\left(n, \frac{1}{12K^2(k+1)}\right)-\nalpha-l,1\right\}.
\end{align*}

The proof concludes as in Proposition \ref{step7}.
\end{proof}

