\title{Deep learning for classifying dynamical states from time series via recurrence plots}
%\title{Deep learning-based classification of dynamical states using recurrence plots}

\author{Athul Mohan${}^{1,2}$, G. Ambika${}^{2}$, Chandrakala Meena${}^{1,2}$}
