\appendix
\section{Numerical methods}
In this work we consider two different continuum models.  For problems involving one population we generate numerical solutions of Equation~\eqref{eq:cont_1p}, $c_{1}(x,t)$. For problems involving two subpopulations we generate numerical solutions of Equation~\eqref{eq:cont_2p},  $c_{1}(x,t)$ and $c_{2}(x,t)$.  We will now describe how we obtain these numerical solutions.  In brief we use a method-of-lines approach where we spatially discretize the PDE models using standard finite difference approximations for the spatial terms and then solve the resulting system of coupled ordinary differential equations (ODE) in time using the DifferentialEquations.jl package by taking advantage of automatic time stepping and temporal truncation error control~\cite{rackauckas2017}.

To solve Equation~\eqref{eq:cont_1p} on $0 < x < L$ we discretize the spatial terms on a uniform grid with grid spacing $\delta > 0$, such that $c_{1}(x_n,t)=c_{1,n}$ for $ n = 1,2,3, \ldots, N$, where $x_n = (n-1)\delta$. At $x=0$ and $x=L$, corresponding to mesh points $x_1$ and $x_N$, respectively, we impose a zero flux boundary conditions $\mathcal{J}_1 = \mathcal{J}_N= 0$ to give
\begin{align}
\dfrac{\text{d}c_{1,1}}{\text{d}t} &= \dfrac{D_{1}}{\delta^2}\left(c_{1,2}-c_{1,1}\right) - \dfrac{ v_{1}}{\delta} \left[c_{1,2}\left(1-c_{1,2}\right)\right],\label{eq:A1} \\
\dfrac{\text{d} c_{1,n}}{\text{d} t}&= \dfrac{D_{1}}{\delta^2}\left(c_{1,n+1} - 2c_{1,n} + c_{1,n-1}\right) \notag \\
&- \dfrac{v_{1}}{2\delta}\left[c_{1,n+1}(1-c_{1,n+1}) - c_{1,n-1}(1-c_{1,n-1})\right], \quad \text{for }  n=2,3,4,\ldots, N-1, \label{eq:A2}\\
\frac{\text{d}c_{1,N}}{\text{d}t} &= -\dfrac{D_{1}}{\delta^2}\left(c_{1,N}-c_{1,N-1}\right) + \dfrac{v_{1}}{\delta} \left[c_{1,N-1}\left(1-c_{1,N-1}\right)\right].\label{eq:A3}
\end{align}
We solve the system of ODEs given by Equations~\eqref{eq:A1}--\eqref{eq:A3} using Heun's method with adaptive time-stepping~\cite{rackauckas2017}. All results presented in this work correspond to $\delta = 0.5$.  To ensure our results are grid independent we considered a number of test cases and checked that numerical results with $\delta=0.5$ were indistinguishable from results with $\delta = 0.1$.

To solve Equation~\eqref{eq:cont_2p} on $0 < x < L$ we discretize the spatial terms on a uniform grid with grid spacing $\delta > 0$, such that $c_1(x_n,t)=c_{1,n}$ and $c_2(x_n,t)=c_{1,n}$ for $ n = 1,2,3, \ldots, N$. No flux boundary conditions are imposed at $x=0$ and $x=L$, leading to
\begin{align}
\dfrac{\text{d}c_{1,1}}{\text{d}t} &= \dfrac{D_{1}}{\delta^2}\left[\left(1-c_{1,2}-c_{2,2}\right)\left(c_{1,2}-c_{1,1}\right) + c_{1,2}\left(c_{1,2}+c_{2,2}-c_{1,1}-c_{2,1} \right)\right] \notag\\ 
 &-\dfrac{v_{1}}{\delta}\left[c_{1,2}\left(1-c_{1,2}-c_{2,2}\right)\right], \notag\\
\dfrac{\text{d}c_{2,1}}{\text{d}t} &= \dfrac{D_{2}}{\delta^2}\left[\left(1-c_{1,2}-c_{2,2}\right)\left(c_{2,2}-c_{2,1}\right) + c_{2,2}\left(c_{1,2}+c_{2,2}-c_{1,1}-c_{2,1} \right)\right] \notag\\
&- \dfrac{v_{2}}{\delta}\left[ c_{2,2}\left(1-c_{1,2}-c_{2,2}\right)\right] , \label{eq:A4}\\
\dfrac{\text{d}c_{1,n}}{\text{d}t} &= \dfrac{D_{1}}{2\delta^2}\left[\left(2-c_{1,n+1}-c_{2,n+1}-c_{1,n}-c_{2,n}\right)\left(c_{1,n+1}-c_{1,n}\right)\right] \notag\\
&+\dfrac{D_{1}}{2\delta^2}\left[\left(c_{1,n+1}+c_{1,n}\right)\left(c_{1,n+1}+c_{2,n+1}-c_{1,n}-c_{2,n}\right)\right] \notag\\
&-\dfrac{D_{1}}{2\delta^2}\left[\left(2-c_{1,n}-c_{2,n}-c_{1,n-1}-c_{2,n-1}\right)\left(c_{1,n}-c_{1,n-1}\right)\right]\notag\\
&- \dfrac{D_{1}}{2\delta^2}\left[\left(c_{1,n}+c_{1,n-1}\right)\left(c_{1,n}+c_{2,n}-c_{1,n-1}-c_{2,n-1}\right)\right] \notag\\ 
&-\dfrac{v_{1}}{2\delta}\left[c_{1,n+1}\left(1-c_{1,n+1}-c_{2,n+1}\right) - c_{1,n-1}\left(1-c_{1,n-1}-c_{2,n-1}\right)\right] \notag\\
\dfrac{\text{d}c_{2,n}}{\text{d}t} &= \dfrac{D_{2}}{2\delta^2}\left[\left(2-c_{1,n+1}-c_{2,n+1}-c_{1,n}-c_{2,n}\right)\left(c_{2,n+1}-c_{2,n}\right)\right]\notag\\
&+ \dfrac{D_{2}}{2\delta^2}\left[\left(c_{2,n+1}+c_{2,n}\right)\left(c_{1,n+1}+c_{2,n+1}-c_{1,n}-c_{2,n}\right)\right] \notag\\
&-\dfrac{D_{2}}{2\delta^2}\left[\left(2-c_{1,n}-c_{2,n}-c_{1,n-1}-c_{2,n-1}\right)\left(c_{2,n}-c_{2,n-1}\right)\right]\notag\\
&-\dfrac{D_{2}}{2\delta^2}\left[\left(c_{2,n}+c_{2,n-1}\right)\left(c_{1,n}+c_{2,n}-c_{1,n-1}-c_{2,n-1}\right)\right] \notag\\ 
&-\dfrac{v_{2}}{2\delta}\left[c_{2,n+1}\left(1-c_{1,n+1}-c_{2,n+1}\right) - c_{2,n-1}\left(1-c_{1,n-1}-c_{2,n-1}\right)\right], \notag\\
&\text{for } n=2,3,4,\ldots, N-1, \label{eq:A5}\\
\dfrac{\text{d}c_{1,N}}{\text{d}t} &= -\dfrac{D_{1}}{\delta^2}\left[\left(1-c_{1,N-1}-c_{2,N-1}\right)\left(c_{1,N}-c_{1,N-1}\right)\right]\notag\\
&-\dfrac{D_{1}}{\delta^2}\left[c_{1,N-1}\left(c_{1,N}+c_{2,N}-c_{1,N-1}-c_{2,N-1}\right)\right]\notag\\
&+ \dfrac{v_{1}}{\delta}\left[c_{1,N-1}\left(1-c_{1,N-1}-c_{2,N-1}\right)\right], \notag\\ 
\dfrac{\text{d}c_{2,N}}{\text{d}t} &= -\dfrac{D_{2}}{\delta^2}\left[\left(1-c_{1,N-1}-c_{2,N-1}\right)\left(c_{2,N}-c_{2,N-1}\right)\right]\notag\\
&-\dfrac{D_{2}}{\delta^2}\left[c_{2,N-1}\left(c_{1,N}+c_{2,N}-c_{1,N-1}-c_{2,N-1}\right)\right]\notag\\
&+ \dfrac{v_{2}}{\delta}\left[ c_{2,N-1}\left(1-c_{1,N-1}-c_{2,N-1}\right)\right] \label{eq:A6}.
\end{align}

We solve the system of ODEs given by Equations~\eqref{eq:A4}--\eqref{eq:A6} using Heun's method with adaptive time-stepping~\cite{rackauckas2017} with $\delta = 0.5$.  Again, we tested these results to ensure they are grid independent. 

