		\langle F(x), x - x' \rangle = \sum_i \langle F_i(x), x_i \rangle - \langle F_i(x), x'_i \rangle = \sum_{i = 1}^{n} \left(u_i(x) - u_i(x_i', x_{-i})\right).
	\end{equation*}
	% The last equivalence follows from the tensor-product definition of the reward for mixed-extension games:
	% \begin{equation*}
 %    \begin{aligned}
	% 	& && u_i(x) = \sum_{a \in \Acal} x_i(a_i) \cdot x_{-i}(a_{-i}) \cdot u_i(a_i, a_{-i}) \\
 %        &\implies && F_{i}^k(x) = \nabla_{x_i^k} u_i(x) = \sum_{a_{-i} \in \Acal_{-i}} x_{-i}(a_{-i}) \cdot u_i(a_i^k, a_{-i}) \\
 %        &\implies && u_i(x) = \langle F_i(x), x_i \rangle
 %    \end{aligned}
	% \end{equation*}
	The "implies" direction of our theorem simply follows by the fact that all pure strategies are also mixed strategies. If the variational stability condition holds for the latter, it must also hold for the former.\\
	Next, let us show the "implied by" direction of our theorem. To that end, assume that $\langle F(x), x - x^* \rangle < 0$ for all \emph{pure} $x \neq x^*$. We want to establish that $\langle v(x), x - x^* \rangle < 0$ for \emph{all} (potentially non-pure) $x \neq x^*$.
	\begin{equation*}
		\begin{split}
			\langle F(x), x - x^* \rangle 
			&= \sum_{i = 1}^{n} u_i(x) - u_i(x_i^*, x_{-i}) \\
			&= \sum_{i = 1}^{n} \E_{a \sim x}\left[u_i(a) - u_i(a_i^*, a_{-i}) \right]\\
%			&= \sum_{i = 1}^{n} \sum_{a_{-i} \in \Acal_{-i}} x_{-i}(a_{-i}) \cdot \left( \left(\sum_{a_i \in \Acal_i} x_i(a_i) \cdot u_i(a_i, a_{-i})\right) - \left(\sum_{a_i \in \Acal_i} x_i(a_i) \cdot u_i(a_i^*, x_{-i})\right) \right) \\
			&= \sum_{i = 1}^{n} \sum_{a \in \Acal} x(a) \cdot \left(u_i(a) - u_i(a^*, a_{-i})\right) \\
			&= \sum_{a \in \Acal} x(a) \underbrace{\sum_{i = 1}^{n} \left(u_i(a) - u_i(a^*, a_{-i})\right)}_{< 0} < 0
		\end{split}
	\end{equation*}
\end{proof}

\begin{proof}[Proof of Proposition~\ref{prop:unique_spne_no_global_convergence}]
We proof the statement by a counterexample. Consider the following game, which we call "Extended Matching Pennies", with parameters $r, q \in \mathbb{R}^+$, $q > 1$, and payoff matrices
\begin{equation*}
	\begin{aligned}
		A_1 = \begin{bmatrix}
		r & -q & -q \\
		- \nicefrac{q}{2} & 1 & -1 \\
		- \nicefrac{q}{2} & -1 & 1
	\end{bmatrix},
	& &
	A_2 = \begin{bmatrix}
		r & - \nicefrac{q}{2} & - \nicefrac{q}{2} \\
		- q & -1 & 1 \\
		- q & 1 & -1
	\end{bmatrix}
	\end{aligned}.
\end{equation*}
We denote the strategy components of player 1 and player 2 by $x_1 = (x_1^1, x_1^2, x_1^3)$ and $x_2 = (x_2^1, x_2^2, x_2^3)$.
This game is a matching pennies game for the last two actions of each player, but it also allows them to play a third action. The strict equilibrium of this game is achieved when both players play the first action and receive a reward of $r$. We want to analyze the convergence behavior of the game towards or away from this equilibrium. For this, we consider the (projected) gradients of the game and how they evolve for the component $x_1^1$.

The game gradient of player 1 is
\begin{equation*}
	F_1 = \nabla_{x_1} u_1 = A_1 x_2 = \begin{bmatrix}
		r x_2^1 - q(x_2^2 + x_2^3) \\
		- \nicefrac{q}{2} \cdot x_2^1 + x_2^2 - x_2^3 \\
		- \nicefrac{q}{2} \cdot x_2^1 - x_2^2 + x_2^3
	\end{bmatrix}
\end{equation*}

Assume that $x_2^1 = 0$. In this case, player 1 will not have an incentive to increase $x_1^1$. If randomly initialized, this scenario happens with probability zero. Next, we analyze the setting if $x_2^1 = \epsilon > 0$. Assuming all strategy components are non-zero, the LPDS projection of the gradient $F$ to the simplex can be described by a matrix product. Let $n = (1, 1, 1)^T$ be the normal vector of the simplex. Then the projected gradient is
\begin{equation*}
	\Pi_{T_{\Xcal}}(F_1) = (I - n (n^T n)^{-1} n^T) v_1 = \begin{bmatrix}
		\nicefrac{2}{3} r x_2^1 - q(x_2^2 + x_2^3) + \frac{q}{3}\\
		(\nicefrac{r}{3} - \nicefrac{q}{2}) x_2^1 + x_2^2 - x_2^3 + \frac{q}{3} \\
		(\nicefrac{r}{3} - \nicefrac{q}{2}) x_2^1 - x_2^2 + x_2^3 + \frac{q}{3}
	\end{bmatrix}
\end{equation*}

Let us analyze under which conditions the first component, $x_1^1$, increases.
\begin{equation*}
	\begin{split}
		\frac{2}{3} r x_2^1 - q(x_2^2 + x_2^3) + \frac{q}{3} &> 0 \\
		\frac{2}{3} r \epsilon - q(1 - \epsilon) + \frac{q}{3} &> 0 \\
		(\frac{2}{3} r + q) \epsilon &> \frac{2}{3} q \\
		\epsilon &> \frac{\frac{2}{3} q}{\frac{2}{3} r + q}
	\end{split}
\end{equation*}
A symmetric argument can be made for the utility gradient of player 2 and its change in component $x_2^1$. Thus, if the initial point is chosen such that $x_2^1 \leq \frac{\nicefrac{2}{3} q}{\nicefrac{2}{3} r + q}$ and $x_1^1 \leq \frac{\nicefrac{2}{3} q}{\nicefrac{2}{3} r + q}$, both agents will never increase their weight on action 1, meaning we will not converge to the strict Nash equilibrium. Since $\epsilon > 0$, such initializations occur with non-zero probability under most initialization methods.
\end{proof}


