5/2}
\end{center}
\end{figure}
In this case we have $a_0 = 0$ and so the spin 1/2 component 
$\phi^\alpha$ decouples leaving us with the Lagrangian
\begin{eqnarray}
{\cal L}_0 &=& - D \Phi_{\alpha\beta\dot\alpha} e^\beta{}_{\dot\beta}
\Phi^{\alpha\dot\alpha\dot\beta} + D \Phi_\alpha 
e^\alpha{}_{\dot\alpha} \Phi^{\dot\alpha} \nonumber \\
 && + \frac{M}{2} [ 3 \Phi_{\alpha\beta\dot\alpha} E^\beta{}_\gamma
\Phi^{\alpha\gamma\dot\alpha} - \Phi_{\alpha(2)\dot\alpha}
E^{\dot\alpha}{}_{\dot\beta} \Phi^{\alpha(2)\dot\beta}] \nonumber \\
 && + 2\tilde{m} \Phi_{\alpha(2)\dot\alpha} E^{\alpha(2)}
\Phi^{\dot\alpha} - 3M \Phi_\alpha E^\alpha{}_\beta \Phi^\beta, 
\end{eqnarray}
which is still invariant under the gauge transformations
\begin{eqnarray}
\delta \Phi^{\alpha(2)\dot\alpha} &=& D \rho^{\alpha(2)\dot\alpha}
 + e_\beta{}^{\dot\alpha} \rho^{\alpha(2)\beta}
 + \frac{M}{2} e^\alpha{}_{\dot\beta} \rho^{\alpha\dot\alpha\dot\beta}
+ \frac{\tilde{m}}{3} e^{\alpha\dot\alpha} \rho^\alpha, \nonumber \\
\delta \Phi^\alpha &=& D \rho^\alpha + \tilde{m} e_{\beta\dot\alpha}
\rho^{\alpha\beta\dot\alpha} + \frac{3M}{2} e^\alpha{}_{\dot\alpha}
\rho^{\dot\alpha}. 
\end{eqnarray}
The remaining gauge invariant curvatures look like:
\begin{eqnarray}
{\cal F}^{\alpha(3)} &=& D \Phi^{\alpha(3)} - \frac{2m^2}{3}
E^\alpha{}_\beta \phi^{\alpha(2)\beta}, \nonumber \\
{\cal F}^{\alpha(2)\dot\alpha} &=& D \Phi^{\alpha(2)\dot\alpha} + 
e_\beta{}^{\dot\alpha} \Phi^{\alpha(2)\beta} + 
\frac{M}{2} e^\alpha{}_{\dot\beta} \Phi^{\alpha\dot\alpha\dot\beta} +
\frac{\tilde{m}}{3} e^{\alpha\dot\alpha} \Phi^\alpha, \nonumber \\
{\cal F}^\alpha &=& D \Phi^\alpha + \tilde{m} e_{\beta\dot\alpha}
\Phi^{\alpha\beta\dot\alpha} + \frac{3M}{2} e^\alpha{}_{\dot\alpha}
\Phi^{\dot\alpha} - 2\tilde{m} E_{\beta(2)} \phi^{\alpha\beta(2)}, \\
{\cal C}^{\alpha(3)} &=& D \phi^{\alpha(3)} - \Phi^{\alpha(3)}.
\nonumber
\end{eqnarray}
In \cite{SV06} Skvortsov and Vasiliev proposed a very compact and
convenient description for bosonic partially massless fields. In 
\cite{KhZ19} we showed that such a description corresponds to the
partial gauge fixing of the general formalism, which arises from the
massive one for special values of mass and extend this procedure
to fermionic fields. For partially massless spin 5/2, this
corresponds to setting $\phi^{\alpha(3)} = 0$ and solving its
equation (see Appendix B of \cite{Zin24a} for more details).
This leaves us with one-forms $\Phi^{\alpha(2)\dot\alpha} + h.c.$,
$\Phi^\alpha + h.c.$ only and with the corresponding two-forms
\begin{eqnarray}
{\cal F}^{\alpha(2)\dot\alpha} &=& D \Phi^{\alpha(2)\dot\alpha} + 
\frac{M}{2} e^\alpha{}_{\dot\beta} \Phi^{\alpha\dot\alpha\dot\beta} +
\frac{\tilde{m}}{3} e^{\alpha\dot\alpha} \Phi^\alpha, \nonumber \\
{\cal F}^\alpha &=& D \Phi^\alpha + \tilde{m} e_{\beta\dot\alpha}
\Phi^{\alpha\beta\dot\alpha} + \frac{3M}{2} e^\alpha{}_{\dot\alpha}
\Phi^{\dot\alpha}.  
\end{eqnarray}
Now the free Lagrangian can be rewritten in the explicitly gauge
invariant form: 
\begin{equation}
{\cal L}_0 = - \frac{1}{2M} {\cal F}_{\alpha(2)\dot\alpha}
{\cal F}^{\alpha(2)\dot\alpha} + \frac{1}{3M} {\cal F}_\alpha
{\cal F}^\alpha + h.c. 
\end{equation}

\subsection{Massless spin 5/2}

In this case we have
\begin{equation}
m = 0 \quad \Rightarrow \quad M^2 = 4\lambda^2, \qquad 
a_0 = 16\lambda^2.
\end{equation}
The free Lagrangian is simply
\begin{equation}
{\cal L}_0 = - D \Phi_{\alpha\beta\dot\alpha} e^\beta{}_{\dot\beta}
\Phi^{\alpha\dot\alpha\dot\beta} + \lambda [ 3
\Phi_{\alpha\beta\dot\alpha} E^\beta{}_\gamma
\Phi^{\alpha\gamma\dot\alpha} - \Phi_{\alpha(2)\dot\alpha}
E^{\dot\alpha}{}_{\dot\beta} \Phi^{\alpha(2)\dot\beta}] + h.c.
\end{equation}
It is invariant under the gauge transformations
\begin{equation}
\delta \Phi^{\alpha(2)\dot\alpha} = D \rho^{\alpha(2)\dot\alpha}
+ e_\beta{}^{\dot\alpha} \rho^{\alpha(2)\beta} + \lambda
e^\alpha{}_{\dot\beta} \rho^{\alpha\dot\alpha\dot\beta}.
\end{equation}
To construct a complete set of the gauge invariant curvatures we still
need  an extra one-form $\Phi^{\alpha(3)} + h.c.$ with gauge
transformations
\begin{equation}
\delta \Phi^{\alpha(3)} = D \rho^{\alpha(3)} + \lambda^2
e^\alpha{}_{\dot\alpha} \rho^{\alpha(2)\dot\alpha}.
\end{equation}
The gauge invariant curvatures look like
\begin{eqnarray}
{\cal F}^{\alpha(3)}  &=& D \Phi^{\alpha(3)} + \lambda^2 
e^\alpha{}_{\dot\alpha} \Phi^{\alpha(2)\dot\alpha}, \nonumber \\
{\cal F}^{\alpha(2)\dot\alpha} &=& D \Phi^{\alpha(2)\dot\alpha}
+ e_\beta{}^{\dot\alpha} \Phi^{\alpha(2)\beta} + \lambda
e^\alpha{}_{\dot\beta} \Phi^{\alpha\dot\alpha\dot\beta}.
\end{eqnarray}
The free Lagrangian can be written as follows
\begin{equation}
{\cal L}_0 = - \frac{1}{12\lambda^3} {\cal F}_{\alpha(3)} 
{\cal F}^{\alpha(3)} - \frac{1}{4\lambda} 
{\cal F}_{\alpha(2)\dot\alpha} {\cal F}^{\alpha(2)\dot\alpha} + h.c.
\end{equation}

\subsection{Massless spin 2}

For the frame-like formalism we need one-forms $\omega^{\alpha(2)} +
h.c.$ and $h^{\alpha\dot\alpha}$  with the gauge transformations
\begin{eqnarray}
\delta \omega^{\alpha(2)} &=& D \eta^{\alpha(2)} + \lambda^2 
e^\alpha{}_{\dot\alpha} \xi^{\alpha\dot\alpha}, \nonumber \\
\delta h^{\alpha\dot\alpha} &=& D \xi^{\alpha\dot\alpha} +
e_\beta{}^{\dot\alpha} \eta^{\alpha\beta} + e^\alpha{}_{\dot\beta}
\eta^{\dot\alpha\dot\beta}.
\end{eqnarray}
The corresponding gauge invariant two-forms look like
\begin{eqnarray}
R^{\alpha(2)} &=& D \omega^{\alpha(2)} + \lambda^2
e^\alpha{}_{\dot\alpha} h^{\alpha\dot\alpha}, \nonumber \\
T^{\alpha\dot\alpha} &=& D h^{\alpha\dot\alpha} + 
e_\beta{}^{\dot\alpha} \omega^{\alpha\beta} + e^\alpha{}_{\dot\beta}
\omega^{\dot\alpha\dot\beta}. 
\end{eqnarray}
As it common in the frame-like formalism in gravity and supergravity,
we will use a so-called "torsion zero condition":
\begin{equation}
T^{\alpha\dot\alpha} \approx 0 \quad \Rightarrow \quad
D R^{\alpha(2)} \approx 0, \qquad
e_\beta{}^{\dot\alpha} R^{\alpha\beta} +
e^\alpha{}_{\dot\beta} R^{\dot\alpha\dot\beta} \approx 0.
\end{equation}
The free Lagrangian can be written as:
\begin{equation}
{\cal L}_0 = \frac{i}{4\lambda^2} R_{\alpha(2)} R^{\alpha(2)} + h.c.
\end{equation}
while its variation under the arbitrary variations of the physical
field can be calculated as follows
\begin{equation}
\delta {\cal L}_0 = R_{\alpha\beta} e^\beta{}_{\dot\alpha}
\delta h^{\alpha\dot\alpha} + h.c. 
\end{equation}

\section{Massless case}

In $d=4$ there exist two types of cubic vertices for the massless
fields \cite{Met18a,Met22}. One of these belongs to the so-called
trivially invariant vertices with the number of derivatives
$N_B = s_1 + s_2 + s_3$ for bosonic vertices and $N_F = s_1 + s_2 +
s_3 -1$ for fermionic ones. In \cite{Zin24a} it was shown that if
the so-called triangular inequality  $s_1 \le s_2 + s_3$ holds
(here we assume that $s_1 \ge s_2 \ge s_3$), such vertices can be
expressed using gauge invariant zero-forms. For the specific case 
$(5/2,5/2,2)$, the corresponding vertex can be written in two on-shell
equivalent forms:
\begin{equation}
{\cal L} \sim E W^{\alpha(2)\beta(2)}Y_{\alpha(2)\gamma(3)}
Y_{\beta(2)}{}^{\gamma(3)} \approx W^{\alpha(2)\beta(2)}
{\cal F}_{\alpha(2)\gamma} {\cal F}_{\beta(2)}{}^\gamma,
\end{equation}
where
$$
R^{\alpha(2)} \approx E_{\beta(2)} W^{\alpha(2)\beta(2)}.
$$
For the vertices of the second type the number of derivatives is 
$N_B = s_1 + s_2 - s_3$ for the bosonic case and $N_F = s_1 + s_2 -
s_3 - 1$  for the fermionic one. Moreover, if the so-called strict
triangular inequality $s_2 < s_2 + s_3$ holds, the corresponding
vertex appears to be non-abelian.

To construct a non-abelian vertex $(5/2,5/2,2)$ we use the 
Fradkin-Vasiliev formalism \cite{FV87,FV87a,Vas11,KhZ20a,Zin24a}.
Recall that the first step is to find consistent deformations of all
gauge invariant curvatures. Here, consistency means that the
deformed curvatures $\hat{\cal F} = {\cal F} + \Delta {\cal F}$
transform covariantly $\delta \hat{\cal F} \sim {\cal F}$. For the
spin 5/2 we obtain (we set coupling constant to be 1):
\begin{eqnarray}
\Delta {\cal F}^{\alpha(3)} &=& \omega^\alpha{}_\beta
\Phi^{\alpha(2)\beta} + \lambda^2 h^\alpha{}_{\dot\alpha}
\Phi^{\alpha(2)\dot\alpha}, \nonumber \\
\Delta {\cal F}^{\alpha(2)\dot\alpha} &=& \omega^\alpha{}_\beta
\Phi^{\alpha\beta\dot\alpha} + \omega^{\dot\alpha}{}_{\dot\beta}
\Phi^{\alpha(2)\dot\beta} + h_\beta{}^{\dot\alpha}
\Phi^{\alpha(2)\beta} + \lambda h^\alpha{}_{\dot\beta}
\Phi^{\alpha\dot\alpha\dot\beta}, 
\end{eqnarray}
which corresponds to the standard substitution rules. For the graviton
we obtain:
\begin{eqnarray}
\Delta R^{\alpha(2)} &=& b_1 [ \Phi^{\alpha\beta(2)}
\Phi^\alpha{}_{\beta(2)} + 2\lambda^2 \Phi^{\alpha\beta\dot\alpha}
\Phi^\alpha{}_{\beta\dot\alpha} + \lambda^2 \Phi^{\alpha\dot\alpha(2)}
\Phi^\alpha{}_{\dot\alpha(2)}], \nonumber \\
\Delta T^{\alpha\dot\alpha} &=& b_1 [ 2 \Phi^{\alpha\beta(2)}
\Phi_{\beta(2)}{}^{\dot\alpha} + \lambda \Phi^{\alpha\beta\dot\beta}
\Phi_{\beta\dot\beta}{}^{\dot\alpha} + 2 \Phi^{\alpha\dot\beta(2)}
\Phi^{\dot\alpha}{}_{\dot\beta(2)} ].
\end{eqnarray}
Now we consider a deformed Lagrangian (i.e. the sum of the free
Lagrangians where all curvatures are substituted by the covariant
ones)
\begin{equation}
\hat{\cal L} = - \frac{1}{12\lambda^3} \hat{\cal F}_{\alpha(3)}
\hat{\cal F}^{\alpha(3)} - \frac{1}{4\lambda}
\hat{\cal F}_{\alpha(2)\dot\alpha} \hat{\cal F}^{\alpha(2)\dot\alpha}
+ \frac{i}{4\lambda} \hat{R}_{\alpha(2)} \hat{R}^{\alpha(2)}
+ h.c. 
\end{equation}
and consider variation of this Lagrangian that do not vanish on-shell
\begin{equation}
\delta \hat{\cal F}^{\alpha(3)} = - R^{\alpha\beta} 
\rho^{\alpha(2)}{}_\beta, \qquad \delta \hat{R}^{\alpha(2)}
= 2b_1 {\cal F}^{\alpha\beta(2)} \rho^\alpha{}_{\beta(2)}.
\end{equation}
This produces
\begin{equation}
\delta \hat{\cal L} = [ \frac{1}{2\lambda^3} + \frac{2b_1}{\lambda^2}]
{\cal F}_{\alpha(2)\beta} R^{\beta\gamma} \rho^{\alpha(2)}{}_\gamma,
\end{equation}
so we have to put
$$
b_1 = - \frac{1}{4\lambda}.
$$
The deformed Lagrangian contains quadratic, cubic and quartic terms.
For the cubic part we obtain
\begin{eqnarray}
{\cal L}_1 &=& - \frac{1}{6\lambda^3} {\cal F}_{\alpha(3}
[ \omega^\alpha{}_\beta \Phi^{\alpha(2)\beta} + \lambda^2
h^\alpha{}_{\dot\alpha} \Phi^{\alpha(2)\dot\alpha}] \nonumber \\
 && - \frac{1}{2\lambda} {\cal F}_{\alpha(2)\dot\alpha}
[ \omega^\alpha{}_\beta \Phi^{\alpha\beta\dot\alpha}
+  \omega^{\dot\alpha}{}_{\dot\beta} \Phi^{\alpha(2)\dot\beta}
+ h_\beta{}^{\dot\alpha} \Phi^{\alpha(2)\beta} + \lambda
h^\alpha{}_{\dot\beta} \Phi^{\alpha\dot\alpha\dot\beta}] \nonumber \\
 && + \frac{b_1}{2\lambda^2} R_{\alpha(2)} [ 
\Phi^{\alpha\beta(2)} \Phi^\alpha{}_{\beta(2)} + 2\lambda^2
\Phi^{\alpha\beta\dot\alpha} \Phi^\alpha{}_{\beta\dot\alpha} +
\lambda^2 \Phi^{\alpha\dot\alpha(2)} \Phi^\alpha{}_{\dot\alpha(2)} ].
\end{eqnarray}
Note that we have terms with three derivatives, but they combine into
total derivative, as it is common in the massless case
\cite{Vas11,KhZ20a}. So the vertex has at most two derivatives, in
agreement with \cite{Met06a}. Using explicit expressions for
curvatures, integrating by parts, and using torsion zero condition, we
can bring this vertex to the following form:
\begin{eqnarray}
{\cal L}_1 &=& - \frac{1}{2\lambda} R^{\alpha\beta}
\Phi_{\alpha\dot\alpha(2)} \Phi_\beta{}^{\dot\alpha(2)} \nonumber \\
 && - D \Phi_{\alpha\beta\dot\alpha} h^\beta{}_{\dot\beta}
\Phi^{\beta\dot\alpha\dot\beta} - \frac{1}{2}
\Phi_{\alpha\dot\alpha\dot\beta} e_\alpha{}^{\dot\beta}
( \omega^\alpha{}_\beta \Phi^{\alpha\beta\dot\alpha} +
\omega^{\dot\alpha}{}_{\dot\gamma} \Phi^{\alpha(2)\dot\gamma})
\nonumber \\
 && + \lambda [ 3 \Phi_{\alpha\beta\dot\alpha}
e^\beta{}_{\dot\beta} h_\gamma{}^{\dot\beta}
\Phi^{\alpha\gamma\dot\alpha}- \Phi_{\alpha(2)\dot\alpha}
e_\beta{}^{\dot\alpha} h^\beta{}_{\dot\beta}
\Phi^{\alpha(2)\dot\beta}] + h.c. 
\end{eqnarray}
The terms in the last two lines correspond to the standard
covariantization of kinetic and mass-like terms in the free
Lagrangian:
\begin{equation}
e^{\alpha\dot\alpha} \Rightarrow e^{\alpha\dot\alpha} +
h^{\alpha\dot\alpha}, \qquad D \Rightarrow D + \omega^{\alpha(2)}
L_{\alpha(2)} + \omega^{\dot\alpha(2)} L_{\dot\alpha(2)},
\end{equation}
where $L_{\alpha(2)}$, $L_{\dot\alpha(2)}$ are generators of Lorentz
group. At the same time, the first line contains non-minimal
interactions that is necessary for the vertex to be gauge invariant
under the hypertransformations:
\begin{eqnarray}
\delta \Phi^{\alpha(2)\dot\alpha} &=& \omega^\alpha{}_\beta 
\rho^{\alpha\beta\dot\alpha} + \omega^{\dot\alpha}{}_{\dot\beta}
\rho^{\alpha(2)\dot\beta} + h_\beta{}^{\dot\alpha} 
\rho^{\alpha(2)\beta} + \lambda h^\alpha{}_{\dot\beta}
\rho^{\alpha\dot\alpha\dot\beta}, \nonumber \\
\delta h^{\alpha\dot\alpha} &=& b_1 [ - 2 \rho^{\alpha\beta(2)}
\Phi_{\beta(2)}{}^{\dot\alpha} + 2 \Phi^{\alpha\beta(2)}
\rho_{\beta(2)}{}^{\dot\alpha} + \lambda \Phi^{\alpha\beta\dot\beta}
\rho_{\beta\dot\beta}{}^{\dot\alpha} + h.c. ].
\end{eqnarray}
For the coupling constant of the non-minimal interactions we get
\begin{equation}
\kappa = - \frac{g}{2\lambda},
\end{equation}
where we restored the gravitational coupling constant $g$, which was
previously set to 1. Thus, by rescaling of the coupling constants, we
may obtain a non-singular flat limit, where only non-minimal
interactions survive. The same is true for the three massless fields
with arbitrary spins \cite{KhZ20a}.

\section{Partially massless case}

In this case one can construct two trivially gauge invariant vertices:
\begin{equation}
{\cal L} \sim h_1 E W^{\alpha(2)\beta(2)} {\cal F}_{\alpha(2)\gamma}
{\cal F}_{\beta(2)}{}^\gamma + h_2 R^{\alpha\beta}
 {\cal C}_{\alpha\gamma(2)} {\cal C}_\beta{}^{\gamma(2)} + h.c. 
\end{equation}
Using an explicit expression for curvature $R^{\alpha(2)}$,
integrating by parts and using differential identity for
${\cal C}^{\alpha(3)}$ one can show that the second vertex is
equivalent to the following combination of the abelian ones
\begin{equation}
{\cal L}_2 \sim - 2 \omega^{\alpha\beta} {\cal F}_{\alpha\gamma(2)}
{\cal C}_\beta{}^{\gamma(2)} + \lambda^2 e^{(\alpha}{}_{\dot\alpha}
h^{\beta)\dot\alpha} {\cal C}_{\alpha\gamma(2)} 
{\cal C}_\beta{}^{\gamma(2)} + h.c.
\end{equation}
It is easy to check that there are no other abelian vertices. 

Let us turn to the non-abelian vertices. For the cubic vertices in the
gauge invariant formalism, there also exist sufficient field
redefinitions to bring the vertex to abelian form \cite{Zin24a}. The
technical reason is that each gauge one-form has its own Stueckelberg
zero-form as it is natural when all gauge symmetries are spontaneously
broken. But in the partially massless case, some gauge one-forms do
not have their Stueckelberg zero-forms, and part of the gauge
symmetries remain unbroken. We investigated the most general
deformations of curvatures for both partially massless spin 5/2 as
well as massless spin 2, taking into account all possible field
redefinitions:
\begin{eqnarray}
\Phi^{\alpha(3)} &\Rightarrow& \Phi^{\alpha(3)} + \kappa_1
\phi^{\alpha(2)\beta} \omega^\alpha{}_\beta, \nonumber \\
\Phi^{\alpha(2)\dot\alpha} &\Rightarrow& \Phi^{\alpha(2)\dot\alpha}
+ \kappa_2 \phi^{\alpha(2)\beta} h_\beta{}^{\dot\alpha}, \\
\Phi^\alpha &\Rightarrow& \Phi^\alpha + \kappa_3 \phi^{\alpha\beta(2)}
\omega_{\beta(2)}, \nonumber 
\end{eqnarray}
\begin{eqnarray}
\omega^{\alpha(2)} &\Rightarrow& \omega^{\alpha(2)} + \kappa_4
\phi^\alpha{}_{\beta(2)} \Phi^{\alpha\beta(2)} + \kappa_5
\phi^{\alpha(2)}{}_\beta \Phi^\beta, \nonumber \\
h^{\alpha\dot\alpha} &\Rightarrow& h^{\alpha\dot\alpha} + \kappa_6
\phi^\alpha{}_{\beta(2)} \Phi^{\beta(2)\dot\alpha} + \kappa_7
e^{\alpha\dot\alpha} \phi_{\beta(3)} \phi^{\beta(3)}. 
\end{eqnarray}
It appears that there exists just one non-abelian deformation which
cannot be transformed into an abelian form. Not surprisingly, for the
partially massless spin 5/2 this deformation corresponds to the
standard minimal substitution rules.

The simplest way to construct such a vertex is to use our description
of the partially massless spin 5/2 a la Skvortsov-Vasiliev. It
contains only one-form fields, so the Fradkin-Vasiliev formalism
works without ambiguities, exactly as in the massless case. \\
{\bf Curvature deformations} For the partially massless spin 5/2 we
obtain (we again set coupling constant to be 1):
\begin{eqnarray}
\Delta {\cal F}^{\alpha(2)\dot\alpha} &=& \omega^\alpha{}_\beta
\Phi^{\alpha\beta\dot\alpha} + \omega^{\dot\alpha}{}_{\dot\beta}
\Phi^{\alpha(2)\dot\beta} + \frac{M}{2} h^\alpha{}_{\dot\beta}
\Phi^{\alpha\dot\alpha\dot\beta} + \frac{\tilde{m}}{3}
h^{\alpha\dot\alpha} \Phi^\alpha, \nonumber \\
\Delta {\cal F}^\alpha &=&  \omega^\alpha{}_\beta \Phi^\beta  
+ \tilde{m} h_{\beta\dot\alpha} \Phi^{\alpha\beta\dot\alpha} + 
\frac{3M}{2} h^\alpha{}_{\dot\alpha} \Phi^{\dot\alpha}. 
\end{eqnarray}
This gives for the hypertransformations
\begin{eqnarray}
\delta \Phi^{\alpha(2)\dot\alpha} &=& \omega^\alpha{}_\beta
\rho^{\alpha\beta\dot\alpha} + \omega^{\dot\alpha}{}_{\dot\beta}
\rho^{\alpha(2)\dot\beta} + \frac{M}{2} h^\alpha{}_{\dot\beta}
\rho^{\alpha\dot\alpha\dot\beta} + \frac{\tilde{m}}{3}
h^{\alpha\dot\alpha} \rho^\alpha, \nonumber \\
\delta \Phi^\alpha &=&  \omega^\alpha{}_\beta \rho^\beta  
+ \tilde{m} h_{\beta\dot\alpha} \rho^{\alpha\beta\dot\alpha} + 
\frac{3M}{2} h^\alpha{}_{\dot\alpha} \rho^{\dot\alpha}.
\end{eqnarray}
For the massless spin 2 the solution is also unique:
\begin{eqnarray}
\Delta R^{\alpha(2)} &=& b_1 \Phi^{\alpha\beta\dot\alpha}
\Phi^\alpha{}_{\beta\dot\alpha} + \frac{b_1}{2} 
\Phi^{\alpha\dot\alpha(2)} \Phi^\alpha{}_{\dot\alpha(2)} - 
\frac{b_1}{3} \Phi^\alpha \Phi^\alpha, \nonumber \\
\Delta T^{\alpha\dot\alpha} &=& \frac{b_1}{M}
\Phi^{\alpha\beta\dot\beta} \Phi_{\beta\dot\beta}{}^{\dot\alpha}
- \frac{5b_1}{2\tilde{m}} (\Phi^{\alpha\beta\dot\alpha} \Phi_\beta +  
\Phi^{\alpha\dot\alpha\dot\beta} \Phi_{\dot\beta}) - \frac{b_1}{M}
\Phi^\alpha \Phi^{\dot\alpha}. 
\end{eqnarray}
{\bf Invariance of the deformed Lagrangian} Let us consider a deformed
Lagrangian:
\begin{equation}
\hat{\cal L} = - \frac{1}{2M} \hat{\cal F}_{\alpha(2)\dot\alpha}
\hat{\cal F}^{\alpha(2)\dot\alpha} + \frac{1}{3M} \hat{\cal F}_\alpha
\hat{\cal F}^\alpha + \frac{i}{4\lambda^2} \hat{R}_{\alpha(2)}
\hat{R}^{\alpha(2)} + h.c. 
\end{equation}
Non-trivial hypertransformations for curvatures (taking into account
torsion zero condition) are
\begin{eqnarray}
\delta \hat{\cal F}^{\alpha(2)\dot\alpha} &=& R^\alpha{}_\beta
\rho^{\alpha\beta\dot\alpha} + R^{\dot\alpha}{}_{\dot\beta}
\rho^{\alpha(2)\dot\beta}, \qquad \delta \hat{\cal F}^\alpha =
R^\alpha{}_\beta \rho^\beta, \nonumber \\
\delta \hat{R}^{\alpha(2)} &=& 2b_1 {\cal F}^{\alpha\beta\dot\alpha}
\rho^\alpha{}_{\beta\dot\alpha} - \frac{2b_1}{3} {\cal F}^\alpha
\rho^\alpha.
\end{eqnarray}
They produce the following variations:
\begin{equation}
\delta \hat{\cal L} = [ \frac{b_1}{\lambda^2} + \frac{1}{M}]
R_{\alpha(2)} {\cal F}^{\alpha\beta\dot\alpha}
\rho^\alpha{}_{\beta\dot\alpha} - [\frac{b_1}{3\lambda^2}
+ \frac{1}{3M}] R_{\alpha2)} {\cal F}^\alpha \rho^\alpha + h.c.
\end{equation}
Thus we set (recall that $M^2 = \lambda^2)$
\begin{equation}
b_1 = - M.
\end{equation}
{\bf Cubic vertex} For the cubic part of the deformed Lagrangian we
obtain\begin{eqnarray}
{\cal L}_1 &=& - \frac{1}{M} {\cal F}_{\alpha(2)\dot\alpha}
[ \omega^\alpha{}_\beta \Phi^{\alpha\beta\dot\alpha} +
 \frac{M}{2} h^\alpha{}_{\dot\beta} \Phi^{\alpha\dot\alpha\dot\beta}
+ \frac{\tilde{m}}{3} h^{\alpha\dot\alpha} \Phi^\alpha ]
 + \frac{1}{M} {\cal F}_{\alpha\dot\alpha(2)} \omega^\alpha{}_\beta
\Phi^{\beta\dot\alpha(2)} \nonumber \\
 && + \frac{2}{3M} {\cal F}_\alpha [ \omega^\alpha{}_\beta
\Phi^\beta + \tilde{m} h_{\beta\dot\alpha}
\Phi^{\alpha\beta\dot\alpha} + \frac{3M}{2} h^\alpha{}_{\dot\alpha}
\Phi^{\dot\alpha}] \nonumber \\
 && + \frac{b_1}{2\lambda^2} R_{\alpha(2)} 
[ \Phi^{\alpha\beta\dot\alpha} \Phi^\alpha{}_{\beta\dot\alpha}
+ \frac{1}{2} \Phi^{\alpha\dot\alpha(2)} \Phi^\alpha{}_{\dot\alpha(2)}
- \frac{1}{3} \Phi^\alpha \Phi^\alpha ] + h.c.
\end{eqnarray}
Note that contrary to the massless case there are no terms with more
than two derivatives. Now using explicit expressions for the
curvatures, integrating by parts and using torsion zero condition one
can bring this vertex into the suggestive form:
\begin{eqnarray}
 {\cal L}_1 &=& - \frac{1}{M} \Phi_{\alpha\dot\alpha(2)}
R^{\alpha\beta} \Phi_\beta{}^{\dot\alpha(2)} \nonumber \\
 && - D \Phi_{\alpha\beta\dot\alpha} h^\alpha{}_{\dot\beta}
\Phi^{\beta\dot\alpha\dot\beta} + D \Phi_\alpha 
h^\alpha{}_{\dot\alpha} \Phi^{\dot\alpha} \nonumber \\
 && + \Phi_{\alpha\beta\dot\alpha} e^\beta{}_{\dot\beta}
\omega^\alpha{}_\gamma \Phi^{\gamma\dot\alpha\dot\beta}
+ \Phi_{\alpha\beta\dot\alpha} e^\beta{}_{\dot\beta}
\omega^{(\dot\alpha}{}_{\dot\gamma} \Phi^{\alpha|\dot\beta)\dot\gamma}
- \Phi_\alpha e^\alpha{}_{\dot\alpha} 
\omega^{\dot\alpha}{}_{\dot\beta} \Phi^{\dot\beta} \nonumber \\
 && - \frac{3M}{4} \Phi_{\alpha\beta\dot\alpha} 
e^{(\alpha}{}_{\dot\beta} h^{\gamma)\dot\beta} 
\Phi_\gamma{}^{\beta\dot\alpha} + \frac{M}{4} 
\Phi_{\alpha(2)\dot\alpha}  e_\beta{}^{(\dot\alpha} 
h^{\beta|\dot\beta)} \Phi^{\alpha(2)}{}_{\dot\beta} \nonumber \\
 && + 2\tilde{m} \Phi_{\alpha\beta\dot\beta} 
e^\alpha{}_{\dot\alpha} h^{\beta\dot\alpha} \Phi^{\dot\beta}
 + 3M \Phi_\alpha e^\alpha{}_{\dot\alpha}
h^{\beta\dot\alpha} \Phi_\beta + h.c. 
\end{eqnarray}
Indeed, in the first line we see the non-minimal interaction, while
all other terms correspond to the standard covariantization for the
kinetic and mass-like terms in the free Lagrangian.

\section{Massive case}

For the cubic vertices with one massless and two massive fields we
always have sufficient field redefinitions to bring the vertex to
abelian form. We begin our analysis with the  trivially gauge
invariant ones. They can be written in terms of the gauge invariant
zero-forms:
\begin{eqnarray*}
{\cal L} &\sim& E W^{\alpha(2)\beta(2)} [ h_1 Y_{\alpha(2)\gamma(3)}
Y_{\beta(2)}{}^{\gamma(3)} + h_2 Y_{\alpha(2)\gamma(2)\dot\alpha}
Y_{\beta(2)}{}^{\gamma(2)\dot\alpha} \\
 && \qquad + h_3  Y_{\alpha(2)\gamma\dot\alpha(2)} 
Y_{\beta(2)}{}^{\gamma\dot\alpha(2)} + h_4 Y_{\alpha(2)\dot\alpha(3)}
Y_{\beta(2)}{}^{\dot\alpha(3)}] + h.c.
\end{eqnarray*}
but we prefer their on-shell equivalent version:
\begin{equation}
{\cal L} \sim h_1 W^{\alpha(2)\beta(2)} {\cal F}_{\alpha(2)\gamma}
{\cal F}_{\beta(2)}{}^\gamma + {\cal R}^{\alpha\beta} [ h_2
{\cal C}_{\alpha\gamma(2)} {\cal C}_\beta{}^{\gamma(2)} + h_3
{\cal C}_{\alpha\gamma\dot\alpha} {\cal C}_\beta{}^{\gamma\dot\alpha}
+ h_4 {\cal C}_{\alpha\dot\alpha(2)} {\cal C}_\beta{}^{\dot\alpha(2)}]
+ h.c. 
\end{equation}
Then using explicit expression for ${\cal R}^{\alpha(2)}$,
integrating by parts and using differential identities for curvatures
one can show that the three last vertices are equivalent to some
combinations of the abelian ones:
\begin{eqnarray}
{\cal L}_2  &\approx& 2 \Omega^{\alpha\beta} 
[ - {\cal F}_{\alpha\gamma(2)} {\cal C}_\beta{}^{\gamma(2)} +
\frac{3a_0}{16} e_\alpha{}^{\dot\alpha} {\cal C}_{\gamma(2)\dot\alpha}
{\cal C}_\beta{}^{\gamma(2)} ] + \lambda^2 e^{(\alpha}{}_{\dot\alpha}
H^{\beta)\dot\alpha} {\cal C}_{\alpha\gamma(2)} 
{\cal C}_\beta{}^{\gamma(2)} + h.c., \nonumber \\
{\cal L}_3 &\approx& 2 \Omega^{\alpha\beta} 
[ - e_\alpha{}^{\dot\alpha}  {\cal C}_{\gamma(2)\dot\alpha} 
{\cal C}_\beta{}^{\gamma(2)} + M e_\alpha{}^{\dot\alpha} 
{\cal C}_{\gamma\dot\alpha\dot\beta} 
{\cal C}_\beta{}^{\gamma\dot\beta} ] + \lambda^2 
e^{(\alpha}{}_{\dot\beta} H^{\beta)\dot\beta} 
{\cal C}_{\alpha\gamma\dot\alpha} {\cal C}_\beta{}^{\gamma\dot\alpha}
 + h.c., \\
{\cal L}_4  &\approx& 2 \Omega^{\alpha\beta} [ e_\alpha{}^{\dot\alpha}
{\cal C}_{\dot\alpha\dot\beta(2)} {\cal C}_\beta{}^{\dot\beta(2)}
- M e_\alpha{}^{\dot\alpha} {\cal C}_{\gamma\dot\alpha\dot\beta}
{\cal C}_\beta{}^{\gamma\dot\beta} ] + \lambda^2 
e^{(\alpha}{}_{\dot\beta} H^{\beta)\dot\beta} 
{\cal C}_{\alpha\dot\alpha(2)} {\cal C}_\beta{}^{\dot\alpha(2)} + h.c.
\nonumber
\end{eqnarray}
\begin{eqnarray}
{\cal L}_a &=& \Omega^{\alpha\beta} [ g_1 {\cal F}_{\alpha\gamma(2)}
{\cal C}_\beta{}^{\gamma(2)} + g_2 e_\alpha{}^{\dot\alpha}
{\cal C}_{\gamma(2)\dot\alpha} {\cal C}_\beta{}^{\gamma(2)}
+ g_3 e_\alpha{}^{\dot\alpha} {\cal C}_{\gamma\dot\alpha\dot\beta}
{\cal C}_\beta{}^{\gamma\dot\beta} + g_4 e_\alpha{}^{\dot\alpha}
{\cal C}_{\dot\alpha\dot\beta(2)} {\cal C}_\beta{}^{\dot\beta(2)}]
\nonumber \\
 && + f_1 H^{\alpha\dot\alpha} {\cal F}_{\alpha\beta(2)}
{\cal C}^{\beta(2)}{}_{\dot\alpha} 
+ e^{(\alpha}{}_{\dot\alpha} H^{\beta)\dot\alpha} [ f_2
{\cal C}_{\alpha\gamma(2)} {\cal C}_\beta{}^{\gamma(2)} + f_3
{\cal C}_{\alpha\gamma\dot\beta} {\cal C}_\beta{}^{\gamma\dot\beta} +
f_4 {\cal C}_{\alpha\dot\beta(2)} {\cal C}_\beta{}^{\dot\beta(2)}]
\end{eqnarray}
The requirement that this expression be gauge invariant leads to four
solutions three of which being equivalent to the trivially gauge
invariant ones. Thus we have five possible cubic vertices.

\noindent
{\bf Minimal vertex} To construct a minimal vertex (i.e. a vertex
which contains standard minimal interactions and has the minimum
number of derivatives), we use the fact that the standard substitution
rules work completely non-linearly, not just at the cubic level. Thus
we take the Lagrangian (\ref{lag_m}), the gauge transformations
(\ref{gauge_1}), (\ref{gauge_2}),  and the curvatures (\ref{cur_1}),
(\ref{cur_2}), where the frame $e^{\alpha\dot\alpha}$ and Lorentz
covariant derivative are now dynamical. We still assume that torsion
is zero, so that the only source of non-invariance of the Lagrangian
is the non-commutativity of covariant derivatives. Then by
straightforward calculations we obtain:
\begin{equation}
\delta {\cal L}_0 =  2 e_\beta{}^{\dot\beta}
 (R^\alpha{}_\gamma \Phi_{\gamma\dot\alpha\dot\beta}
 + R_{\dot\alpha}{}^{\dot\gamma} \Phi_{\alpha\dot\beta\dot\gamma}
+ R_{\dot\beta}{}^{\dot\gamma} \Phi_{\alpha\dot\alpha\dot\gamma})
\rho^{\alpha\beta\dot\alpha}  - 2 e_\alpha{}^{\dot\alpha}
R_{\dot\alpha}{}^{\dot\beta} \Phi_{\dot\beta} \rho^\alpha + h.c.
\end{equation}
Using our experience from the partially massless case we add the
following ansatz for the non-minimal interactions:
\begin{equation}
{\cal L}_1 = \kappa R_{\alpha\beta} \Phi^{\alpha\dot\alpha(2)}
\Phi^\beta{}_{\dot\alpha(2)} + h.c.
\end{equation}
Calculating its variations we obtain
\begin{eqnarray}
\delta {\cal L}_1 &=& 2\kappa R_{\alpha\beta} 
\Phi^\alpha{}_{\dot\alpha(2)} [ D \rho^{\beta\dot\alpha(2)} +
e^\beta{}_{\dot\beta} \rho^{\dot\alpha(2)\dot\beta} + \frac{M}{2}
e_\gamma{}^{\dot\alpha} \rho^{\beta\gamma\dot\alpha} +
\frac{\tilde{m}}{3} e^{\beta\dot\alpha} \rho^{\dot\alpha}] + h.c.
\nonumber \\
 &\approx&  2\kappa R_{\dot\alpha\dot\beta} [ e_\beta{}^{\dot\alpha}
\Phi^{\alpha(2)\beta} + \frac{M}{2} e^\alpha{}_{\dot\gamma}
\Phi^{\alpha\dot\alpha\dot\gamma} + \frac{\tilde{m}}{3}
e^{\alpha\dot\alpha} \Phi^\alpha] \rho_{\alpha(2)}{}^{\dot\beta}
\nonumber \\
 && + M\kappa R_{\alpha\beta} \Phi^\alpha{}_{\dot\alpha(2)}
e_\gamma{}^{\dot\alpha} \rho^{\beta\gamma\dot\alpha} - 2\kappa
R_{\dot\alpha\dot\beta} \Phi_{\alpha(2)}{}^{\dot\alpha}
[ e_\beta{}^{\dot\beta} \rho^{\alpha(2)\beta} + \frac{\tilde{m}}{3}
e^{\alpha\dot\beta} \rho^\alpha ] + h.c.
\end{eqnarray}
Recall that $\approx$ means ''up to total derivatives and terms which
vanish on-shell''. Then if we set
\begin{equation}
\kappa = - \frac{1}{M},
\end{equation}
we get
\begin{eqnarray}
\delta ({\cal L}_0 + {\cal L}_1) &=& 
e^\gamma{}_{\dot\alpha} R_{\alpha\gamma} 
[ - \frac{2}{M} \rho^{\alpha\beta(2)} \Phi_{\beta(2)}{}^{\dot\alpha}
+ \frac{2}{M} \Phi^{\alpha\beta(2)} \rho_{\beta(2)}{}^{\dot\alpha} 
- 2 \rho^{\alpha\beta\dot\beta} \Phi_{\beta\dot\beta}{}^{\dot\alpha} 
\nonumber \\
 && \qquad + \frac{4\tilde{m}}{3M} (\Phi^{\alpha\beta\dot\alpha}
\rho_\beta - \rho^{\alpha\beta\dot\alpha} \Phi_\beta) - 2
\Phi^{\dot\alpha} \rho^\alpha ] + h.c.
\end{eqnarray}
Now all these terms can be compensated by the following corrections
\begin{eqnarray}
\delta H^{\alpha\dot\alpha} &=&  
[  \frac{1}{M} \rho^{\alpha\beta(2)} \Phi_{\beta(2)}{}^{\dot\alpha}
- \frac{1}{M} \Phi^{\alpha\beta(2)} \rho_{\beta(2)}{}^{\dot\alpha} 
+ \rho^{\alpha\beta\dot\beta} \Phi_{\beta\dot\beta}{}^{\dot\alpha} 
\nonumber \\
 && \qquad - \frac{2\tilde{m}}{3M} (\Phi^{\alpha\beta\dot\alpha}
\rho_\beta - \rho^{\alpha\beta\dot\alpha} \Phi_\beta) +
\Phi^{\dot\alpha} \rho^\alpha ] + h.c.
\end{eqnarray}
Note that in the framework of the Fradkin-Vasiliev formalism these
corrections correspond to the following deformation for the torsion:
\begin{equation}
\Delta T^{\alpha\dot\alpha} =  \frac{1}{M} \Phi^{\alpha\beta(2)}
\Phi_{\beta(2)}{}^{\dot\alpha} + \Phi^{\alpha\beta\dot\beta}
\Phi_{\beta\dot\beta}{}^{\dot\alpha} + \frac{2\tilde{m}}{3M}
\Phi^{\alpha\beta\dot\alpha} \Phi_\beta + \Phi^{\dot\alpha}
\Phi^\alpha + \dots + h.c. 
\end{equation}
where dots stand for the contributions of the zero-forms.

For the coefficient at the non-minimal interactions we get
\begin{equation}
\kappa = - \frac{g}{\sqrt{m^2 - 4\Lambda}},
\end{equation}
where we restore the gravitational coupling constant, which was
previously set to 1. Thus, for a non-zero cosmological constant
$\Lambda$, we have a smooth massless limit (unitary in $AdS_4$), while
for non-zero mass we have a smooth flat limit. The special point 
$m^2 = 4\Lambda$ corresponds to the boundary of the unitarity region.
As in the massless case, the only way to get a non-trivial result is
by rescaling of the coupling constant which leaves us with the 
non-minimal interactions only.

\section{Conclusion}

In this work, we investigated the gravitational interactions for
massive spin 5/2, including partially massless and massless limits. We
used the gauge invariant frame-like formalism for the description of
massive spin 5/2 and the Fradkin-Vasiliev formalism to construct
interactions. One of the technical problems in using a gauge
invariant description of massive fields, is related to field
redefinitions containing Stueckelberg zero-forms. In particular, for
any vertex with one massless and two massive fields (as it is the case
for gravitational interactions) one always has enough field
redefinitions to bring the vertex into an abelian form. We used this
fact for the classification of possible vertices. On the other
hand, to construct a minimal vertex (i.e. containing standard minimal
gravitational interactions and non-minimal ones with a minimum
number of derivatives) we used a fairly common down-up approach. And
it turned out that the simplest and most straightforward way to find
the appropriate form of the non-minimal interactions was to consider
the partially massless case within the Skvortsov-Vasiliev version of
the frame-like formalism. Our results indicate that there is a
specific point $m^2 = 4\Lambda$, which corresponds to the boundary of
unitary allowed region, where standard minimal interactions are
absent, leaving only non-minimal ones. In the companion paper, we will
apply the same strategy to the massive spin 3 field, including
its partially massless and massless limits.


