\title[ ]{On Some New Congruences For Biregular Overpartitions}
\author{ANAKHA V }
\address{ANAKHA V, NATIONAL INSTITUTE OF TECHNOLOGY CALICUT, KOZHIKODE, KERALA, INDIA 673601 }
\email{anakha$\textunderscore$p240019ma@nitc.ac.in }
\keywords{Congruence; Overpartition; Regular; Biregular; $q-$series }

\begin{abstract}

Inspired by the recent work by Nadji, Ahmia and Ramírez \cite{biregularNadji}, we examined the arithmetic properties of $\overline{B}_{\ell_1,\ell_2}(n)$, the number of overpartitions of $n$ whose parts are neither divisible by $\ell_1$ nor divisible by $\ell_2$. In particular, we establish some congruences modulo $k\in\{4,8,6,12\}$ satisfied by $\overline{B}_{\ell_1,\ell_2}(n)$ where $\ell_1$ and $\ell_2$ take values as arbitrary powers of $2$ and $3$. Moreover, we extend certain results proved in \cite{biregularNadji} and \cite{ghoshal2025arxiv} for $\ell_1$ and $\ell_2$ with random powers of $2$ and $3$. Generating functions, dissection formulas, and theta functions are used to prove our main findings.

\end{abstract}
\maketitle
\section{Introduction and statement of results}
\label{intro}
 Suppose that $n$ is a positive integer. A \emph{partition} of $n$ is a non-increasing sequence of positive integers $(\lambda_1,\lambda_2,\hdots,\lambda_k)$ such that $n=\lambda_1+\lambda_2+\cdots+\lambda_k$. Each of the $\lambda_i$ are called a \emph{part}. Let the number of partitions of $n$ is denoted by $p(n)$. By convention, $p(0)=1$. The generating function for $p(n)$ is given by
 \begin{align*}
    \sum_{n=0}^{\infty}{p}(n)q^n=\prod_{n=1}^\infty\frac{1}{1-q^n}=\frac{1}{(q;q)_\infty}.
\end{align*}

Here and throughout this paper we will use the standard $q-$series notation for $q\in\mathbb{C}$, $|q|<1$:

\begin{equation*}
\begin{split}
    (a;q)_0&:= 1 \\
     (a;q)_n&:=   \prod_{k=0}^{n-1}(1-aq^k) \text{ for }n\geq 1 \text{ and }\\
    (a;q)_\infty&:=\prod_{k=0}^{\infty}(1-aq^k).
\end{split} 
\end{equation*}


 An \emph{overpartition} of $n$ is a partition of $n$ in which the first occurrence of each part may be overlined. The number of overpartitions of $n$ is denoted by $\overline{p}(n)$, and by convention $\overline{p}(0)=1$. As an example, $\overline{p}(4)=14$ and the overpartitions are 
\begin{align*}
    (4),(\overline{4}), (3,1),(\overline{3},1),(3,\overline{1}),(\overline{3},\overline{1}),(2,2), (\overline{2},2), (2,1,1),(\overline{2},1,1), (2,\overline{1},1), (\overline{2},\overline{1},1), (1,1,1,1), (\overline{1},1,1,1).
\end{align*}

The generating function for the number of overpartitions is given by Corteel and Lovejoy \cite{corteel2004overpartitions},
\begin{align*}
    \sum_{n=0}^{\infty}\overline{p}(n)q^n=\prod_{n=1}^\infty\left(\frac{1+q^n}{1-q^n}\right)=\frac{(q^2;q^2)_\infty}{(q;q)_\infty^2}.
\end{align*}



Extensive studies have been conducted on arithmetic properties of overpartitions. Hirschhorn and Sellers \cite{hirschhorn2005overpartition} proved the following

\begin{align*}
    \overline{p}(9^\alpha(27n+18))\equiv 0\pmod 3
\end{align*}
and

\begin{align*}
    \overline{p}(27n)\equiv \overline{p}(3n) \pmod 3.
\end{align*}

For further reading on overpartitions we cite \cite{kim2008overpartition,kim2009short,xia2017overpartitions,yao2013overpartitions}.\\

For an integer $\ell>1$, an $\ell-$regular partition of $n$ is a partition that has no parts that are divisible by $\ell$. Let $b_\ell(n)$ denote the number of $\ell-$regular partitions of $n$. Then the generating function is given by
\begin{align*}
    \sum_{n=0}^\infty b_\ell(n)q^n=\frac{(q^\ell;q^\ell)_\infty}{(q;q)_\infty}.
\end{align*}
Numerous studies have explored the arithmetic properties of regular partitions. Cui and Gu \cite{cui2013regular} discovered several infinite families of congruences modulo $2$ for $\ell-$regular partition functions for $\ell=2,4,5,8,13,16$. Hirchhorn and Sellers yielded many Ramanujan type congruences for $b_5(n)$ in their work \cite{hirschhorn5regular}.\\

A bipartition of $n$ is a pair $(\lambda,\mu)$ of partitions such that the sum of all its parts is equal to $n$. In \cite{linl-regularbipartition}, Lin studied the properties of $B_{\ell}(n)$ which is the number of $\ell-$regular bipartitions of $n$ and having the generating function
\begin{align*}
    \sum_{n=0}^\infty B_\ell(n)q^n=\frac{(q^\ell;q^\ell)_\infty^2}{(q;q)_\infty^2}.
\end{align*}
In particular, he proved
\begin{align*}
    B_7\left(3^\alpha n+\frac{5\cdot3^{\alpha-1}-1}{2}\right)\equiv 0\pmod 3.
\end{align*}
Let $B_{\ell,m}(n)$ denotes the count for $(\ell,m)-$regular bipartitions of $n$ which is defined as a bipartition $(\lambda,\mu)$ of $n$ such that $\lambda$ is $\ell-$regular and $\mu$ is $m-$regular with a generating function given by

\begin{align*}
     \sum_{n=0}^\infty B_{\ell,m}(n)q^n=\frac{(q^\ell;q^\ell)_\infty (q^m;q^m)_\infty}{(q;q)_\infty^2}.
\end{align*}
In \cite{dou2016lm-regularbipartition} Dou proved 
\begin{align*}
    B_{3,11}\left(3^\alpha n+\frac{5\cdot3^{\alpha-1}-1}{2}\right)\equiv 0\pmod {11}.
\end{align*}
Some more arithmetic propertities of $B_{\ell,m}(n)$ can be found in \cite{wang2017arithmetic,adiga2019st-regularbipartition}.


Lovejoy \cite{lovejoy2003gordon} investigated the $\ell-$regular overpartition function $\overline{A}_\ell(n).$ Shen \cite{shen2016arithmetic}
 provided the generating function for $\overline{A}_\ell(n)$ as 
\begin{align*}
    \sum_{n=0}^\infty \overline{A}_\ell(n)q^n=\frac{(q^\ell;q^\ell)_\infty^2(q^2;q^2)_\infty}{(q;q)_\infty^2(q^{2\ell};q^{2\ell})_\infty}.
\end{align*}
and derived some congruences for $\overline{A}_3(n)$ and $\overline{A}_4(n)$. Saikia and Barua \cite{saikia2017congruences} proved congruences for $\overline{A}_5(n)$ modulo $4,$ $\overline{A}_6(n)$ modulo $3$, and $\overline{A}_8(n)$ modulo $4.$ One can refer \cite{shenlregular,alanazi2016infinite}, for more information. \\
 Andrews \cite{andrews2015singular} introduced singular overpartition function $\overline{C}_{k,i}(n)$ which enumerates the number of overpartitions of $n$ in which the parts are not divisible by $k$ and the only overlined parts are those which are congruent to $\pm i$ modulo $k$. The generating function for $\overline{C}_{k,i}(n)$ is given as 
 \begin{align*}
     \sum_{n=0}^{\infty}\overline{C}_{k,i}(n)q^n=\frac{(q^k;q^k)_{\infty}(-q^i;q^k)_{\infty}(-q^{k-i};q^k)_{\infty}}{(q;q)_{\infty}}
 \end{align*}
 for $k\geq 3$ and $1\leq i\leq \lfloor \frac{k}{2}\rfloor$.
 In the same article Andrews proved the following congruences:
 \begin{align*}
   \overline{C}_{3,1}(9n+3)\equiv \overline{C}_{3,1}(9n+6)\equiv 0 \pmod 3 \text{ \hspace{1cm} for all $n\geq 0$ }.  
 \end{align*}
 Singular overpartitions is a well established area of research. Chen, Hirschhorn and Sellers \cite{chen2015singular} discovered congruences for $\overline{C}_{3,1}(n)$, $\overline{C}_{4,1}(n),$ $\overline{C}_{6,1}(n)$ and $\overline{C}_{6,2}(n)$ modulo $3$ and powers of $2$. Later, Ahmed and Baruah \cite{ahmed2015singular} presented certain congruences for $\overline{C}_{3,1}(n),\overline{C}_{8,2}(n),\overline{C}_{12,2}(n),\overline{C}_{12,4}(n),\overline{C}_{24,8}(n) $ and $\overline{C}_{48,16}(n)$. In \cite{ray2024distribution}, Ray studied the distribution for $\overline{C}_{p,1}(n),$ where $p\geq 5$ is a prime number. The reader can look into \cite{barmanRay2019divisibility,singhBarman2021new} for more insights.

 Bringmann \emph{et al.} \cite{bringmann2015overpartitions} proposed and studied a new type of overpartitions characterized by restricted odd difference. It further researched by Hirschhorn and Sellers \cite{hirschhorn2020restricted} and proved some parity results. Many other results on restricted overpartitions can be found in the literature. Referrence \cite{baruah2025restricetd} provide a relevant  example examining the arithmetic properties of restricted overpartitions, specially focussing on parts belonging to certain residue classes modulo $8$. 

Recently, Nadji, Ahmia, and Ramrez \cite{biregularNadji} have delved into the arithmetic properties of biregular overpartitions, which is defined as follows:\\
For a pair of two relatively prime integers $(\ell_1,\ell_2)>1$, an $(\ell_1,\ell_2)-$\emph{biregular overpartitions} of $n$ is a partition in which none of the parts are divisible by $\ell_1$ or $\ell_2$.\\
They provided some congruences modulo $3$ and powers of $2$ for the values of pairs \hspace{0.06cm} $(\ell_1,\ell_2)\in \{(4,3),(4,9),\\
(8,3),(8,9)\}$. For proving these congruences they used generating functions, dissection formulas and Smoot's implementation of Radus's Ramanujan-Kolberg algorithm \cite{smoot2021computation}. To know more about Radu's algorithm, the reader can take a look into \cite{radu2015algorithmic1}. In \cite{manjil2024some}, Alanazi, Munagi and Saikia provided numerous congruences for the biregular overpartitions, which they showed through modular forms and generating functions. They also presented combinatorial proof for the congruences modulo $4$. They proved both analytically and combinatorially the following:
\begin{align*}
    \overline{B}_{\ell_1,\ell_2}(n)\equiv 0 \pmod{2}\text{ \hspace{1cm} for $n\geq 1$}.
\end{align*}
Subsequently, Ghoshal and Jana \cite{ghoshal2025arxiv} investigated additional properties of biregular overpartitions. To elaborate, through elementary methods they derived some of the congruences given in \cite{biregularNadji} in which the proof is done by making use of Radu's algorithm. Moreover, they developed a general method for proving congruences modulo $8$ which is applicable without any specific $2-$dissection requirements. Paudel, Sellers and Wang \cite{paudel2025extending} extended several results of Alanazi \emph{et al.} and established a large number of new congruences. They proved their findings  merely by making use of some $q-$series manipulations and dissection formulas.In \cite{newbiregular}, the authors have derived congruences for $(\ell_1,\ell_2)\in \{(2,9),(5,2),(8,3)\}$ and generally for $(\ell_1,\ell_2)\in \{(5,2^t),(3,2^t),(4,3^t)\}$.


In our paper, we follow the same notation $\overline{B}_{\ell_1,\ell_2}(n)$ as \cite{biregularNadji} for the number of $(\ell_1,\ell_2)-$biregular overpartitions of $n$.

The generating function for $\overline{B}_{\ell_1,\ell_2}(n)$ is 
\begin{equation}
\label{0}
    \begin{split}
        \sum_{n=0}^{\infty}\overline{B}_{\ell_1,\ell_2}(n)q^n&=\prod_{n=1}^\infty \frac{(1+q^n)(1+q^{\ell_1\ell_2 n})(1-q^{\ell_1 n})(1-q^{\ell_2 n})}{(1+q^{\ell_1 n})(1+q^{\ell_2 n})(1-q^n)(1-q^{\ell_1\ell_2 n})}\\
        &=\frac{(q^2;q^2)_\infty(q^{\ell_1};q^{\ell_1})_\infty^2(q^{\ell_2};q^{\ell_2})_\infty^2(q^{2\ell_1\ell_2};q^{2\ell_1\ell_2})_\infty}{(q;q)_\infty^2(q^{2\ell_1};q^{2\ell_1})_\infty(q^{2\ell_2};q^{2\ell_2})_\infty(q^{\ell_1\ell_2};q^{\ell_1\ell_2})_\infty^2}.
    \end{split}
\end{equation}

We give a certain kind of generalization for some of the results proved in \cite{biregularNadji} and \cite{ghoshal2025arxiv}. Besides that our new findings are also included. To be more exact, we present the proof of the following results in which we make use of generating functions and dissection formulas.

\begin{theorem}\label{thm1}
    For every integers $n\geq 0$ and for $\alpha\geq 2$, we have
    \begin{align}
    \label{7}
        \overline{B}_{2^\alpha,3}(4n+2)\equiv 0\pmod 4,\\
    \label{8}    
        \overline{B}_{2^\alpha,3}(8n+5)\equiv 0\pmod 4,
        \end{align}
 \hspace{1cm}  and for $\alpha\geq 3$
     \begin{align}  
     \label{9}   
        \overline{B}_{2^\alpha,3}(8n+6)\equiv 0\pmod 8.
    \end{align}
\end{theorem}




  \begin{theorem}\label{thm2}

      For every integer $n\geq 0$ and $\alpha>2k +1$, where $k\geq 0$ we have
\begin{align}\label{th2e1}
\overline{B}_{2^\alpha,3}(4^k(4n+3))\equiv 0 \pmod 6
\end{align}
 \hspace{1cm}  For $\alpha>2,$
     \begin{align} 
\label{th2e2}
\overline{B}_{2^\alpha,3}(8n+7)\equiv 0 \pmod {12}.
\end{align}


  \end{theorem}   



  \begin{theorem}\label{thm3}
      Let $n\geq 0$  and $\beta\geq 2$ be integers. Then for any integer $\alpha \geq 0$, we have
      \begin{align}\label{th3e1}
       \overline{B}_{2^{2\alpha +1},3^\beta}(9n+3i)\equiv 0 \pmod 4  
      \end{align}
      and for $\alpha \geq 1$, we have
\begin{align}\label{th3e2}
    \overline{B}_{2^{2\alpha},3^\beta}(9n+3i)\equiv 0 \pmod 8
\end{align}
   for $i=1,2.$   
  \end{theorem}

We make use of the proof techniques given in \cite{ghoshal2025arxiv} to prove the following theorem.

\begin{theorem}\label{THM}
    Let $\alpha\geq 2$, $\beta\geq 1$ and $n\geq 0$ be integers. If $\alpha$ is odd and $\beta$ is even or both $\alpha$ and $\beta$ are even, then
     \begin{align}\label{THe4}
        \overline{B}_{2^\alpha,3^\beta}(12n+3)\equiv0 \pmod 8\\
         \label{THe1}  \overline{B}_{2^\alpha,3^\beta}(12n+7)\equiv0 \pmod 8.
    \end{align}
    If $\alpha$ and $\beta$ have different parity or both $\alpha$ and $\beta$ are even, then
     \begin{align}
\label{THe2} \overline{B}_{2^\alpha,3^\beta}(12n+11)\equiv0 \pmod 8.
    \end{align}

\end{theorem}


\section{Preliminaries}

In this section, we state some lemmas and formulas which we use to prove our results. Ramanujan's theta function \cite[pp. 34, 18.1]{ramanujan3} $f(a,b)$ is defined by
\begin{align*}
    f(a,b)=\sum_{n=-\infty}^{\infty}a^{n(n+1)/2}b^{n(n-1)/2}=(-a;ab)_\infty(-b;ab)_\infty(ab;ab)_\infty, \text{ for }|ab|<1.
\end{align*}
 One of the important representations of theta function is given as:
 \begin{align*} 
     \varphi(q):=f(q,q)=1+2\sum_{n=1}^{\infty}q^{n^2}=\frac{(-q;q^2)_\infty(q^2;q^2)_\infty}{(q;q^2)_\infty(-q^2;q^2)_\infty}=\frac{(q^2;q^2)_\infty^5}{(q;q)_\infty^2 (q^4;q^4)_\infty^2}.
 \end{align*}
Replacing $q$ by $-q$ in the above equation yields

\begin{align*}
    \varphi(-q)=\frac{(q;q)_\infty^2}{(q^2;q^2)_\infty}.
\end{align*}


\begin{lemma}
    For all primes $p$ and all $k,m\geq 1$, we have
    \begin{align}\label{lp1}
        f_{pm}^{p^{k-1}}\equiv f_m^{p^k}\pmod{p^k}
    \end{align}
\end{lemma}

We list some dissection formulas which we use in our proofs.

\begin{lemma}
    We have
    \begin{align}
\label{1}
        \frac{(q^3;q^3)_\infty^2}{(q;q)_\infty^2}&=\frac{(q^4;q^4)_\infty^4(q^6;q^6)_\infty(q^{12};q^{12})_\infty^2}{(q^2;q^2)_\infty^5(q^8;q^8)_\infty(q^{24};q^{24})_\infty}+2q\frac{(q^4;q^4)_\infty(q^6;q^6)_\infty^2(q^8;q^8)_\infty(q^{24};q^{24})_\infty}{(q^2;q^2)_\infty^4(q^{12};q^{12})_\infty}\\
\label{2}
        \frac{(q^3;q^3)_\infty}{(q;q)_\infty^3}&=\frac{(q^4;q^4)_\infty^6(q^6;q^6)_\infty^3}{(q^2;q^2)_\infty^9(q^{12};q^{12})_\infty^2}+3q\frac{(q^4;q^4)_\infty^2(q^6;q^6)_\infty(q^{12};q^{12})_\infty^2}{(q^2;q^2)_\infty^7}   
    \end{align}
\end{lemma}
Xia and Yao \cite{xia2013analogues} proved equation (\ref{1}). Barua and Ojah \cite{baruah2012analogues} proved (\ref{2}).
\begin{lemma}
    We have
    \begin{align}
\label{3}
       \frac{1}{(q;q)_\infty^4}&=\frac{(q^4;q^4)_\infty^{14}}{(q^2;q^2)_\infty^{14}(q^8;q^8)_\infty^4}+4q\frac{(q^4;q^4)_\infty^2(q^8;q^8)_\infty^4}{(q^2;q^2)_\infty^{10}} \\
\label{4}      
       \frac{1}{(q;q)_\infty^2}&=\frac{(q^8;q^8)_\infty^5 }{(q^2;q^2)_\infty ^5 (q^{16};q^{16})_\infty^2}+2q \frac{(q^4;q^4)_\infty ^2  (q^{16};q^{16})_\infty^2}{(q^2;q^2)_\infty ^5 (q^{8};q^8)}      
    \end{align}
\end{lemma}
Equations (\ref{3}) and (\ref{4}) are consequences of dissection formulas of Ramanujan \cite{ramanujan3}. 

\begin{lemma}
    We have
    \begin{align}
    \label{5}
        \frac{(q;q)_\infty^2}{(q^2;q^2)_\infty}&=\frac{(q^9;q^9)_\infty^2}{(q^{18};q^{18})_\infty}-2q\frac{(q^3;q^3)_\infty(q^{18};q^{18})_\infty^2}{(q^6;q^6)_\infty(q^9;q^9)_\infty}\\
    \label{6}
         \frac{(q^2;q^2)_\infty}{(q;q)_\infty^2}&=\frac{(q^6;q^6)_\infty^4(q^9;q^9)_\infty^6}{(q^3;q^3)_\infty^8(q^{18};q^{18})_\infty^3}+2q\frac{(q^6;q^6)_\infty^3(q^9;q^9)_\infty^3}{(q^3;q^3)_\infty^7}+4q^2\frac{(q^6;q^6)_\infty^2(q^{18};q^{18})_\infty^3}{(q^3;q^3)_\infty^6}
    \end{align}
\end{lemma}
Equation (\ref{5}) is equivalent to the $3-$dissection of $\varphi(-q)$ \cite[Eqn. $14.3.2$]{hirschhorn2017powerofq}. Hirschhorn and Sellers \cite{hirschhornsellers} proved (\ref{6}).



