\begin{proof}[Proof of Theorem \ref{thm2}]

From both sides of (\ref{th1e8}) we identify and extract the terms containing $q^{2n+1}$ and then swap $q^2$ with $q$ to get

 \begin{align}\label{th2e3}
          \sum_{n=0}^{\infty}\overline{B}_{2^\alpha,3}(4n+3)q^n =6\frac{(q^2;q^2)_\infty^3(q^6;q^6)_\infty^3(q^{2^{\alpha-2}};q^{2^{\alpha-2}})_\infty^2 (q^{2^{\alpha-1}\cdot 3};q^{2^{\alpha-1}\cdot 3})_\infty}{(q;q)_\infty^6(q^{2^{\alpha-1}};q^{2^{\alpha-1}})_\infty(q^{2^{\alpha-2}\cdot 3};q^{2^{\alpha-2}\cdot 3})_\infty^2}.
       \end{align}

Consequently (\ref{th2e1}) follows for the case $k=0$.


Using (\ref{lp1}) in equation (\ref{th1e1}) gives
\begin{align}
        \sum_{n=0}^{\infty}\overline{B}_{2^\alpha,3}(n)q^n
        &\equiv \frac{(q^2;q^2)_\infty(q^{2^\alpha};q^{2^\alpha})_\infty^2(q;q)_\infty^6(q^{2^{\alpha+1}};q^{2^{\alpha+1}})_\infty^3}{(q;q)_\infty^2(q^{2^{\alpha+1}};q^{2^{\alpha+1}})_\infty(q^{2};q^{2})_\infty^3(q^{2^\alpha};q^{2^\alpha})_\infty^6}\\
 \label{th3e*3} &\equiv \frac{(q;q)_\infty^4 (q^{2^{\alpha+1}};q^{2^{\alpha+1}})_\infty^2}{(q^2;q^2)_\infty^2 (q^{2^\alpha};q^{2^\alpha})_\infty^4}\pmod 3.
    \end{align}
We can write (\ref{th3e*3}) as
\begin{align}
    \sum_{n=0}^{\infty}\overline{B}_{2^\alpha,3}(n)q^n
        &\equiv
        \left(\varphi(-q)\right)^2\frac{(q^{2^{\alpha+1}};q^{2^{\alpha+1}})_\infty^2}{(q^{2^\alpha};q^{2^\alpha})_\infty^4}\\
        &\equiv \left(1+2\sum_{i=1}^{\infty}(-q)^{i^2}\right)^2\frac{(q^{2^{\alpha+1}};q^{2^{\alpha+1}})_\infty^2}{(q^{2^\alpha};q^{2^\alpha})_\infty^4}\\
   \label{th3e*4}     &\equiv \left(1+\sum_{i=1}^{\infty}(-1)^{i^2}q^{i^2}+\sum_{i,j=1}^{\infty}(-1)^{i^2+j^2}q^{i^2+j^2}\right)\frac{(q^{2^{\alpha+1}};q^{2^{\alpha+1}})_\infty^2}{(q^{2^\alpha};q^{2^\alpha})_\infty^4}\pmod 3.
\end{align}
    Since $i^2\equiv 0\pmod 4$ if and only if $i$ is even, by extracting the terms containing $q^4$ from (\ref{th3e*4}) we can write,

    \begin{align}
    \sum_{n=0}^{\infty}\overline{B}_{2^\alpha,3}(4n)q^{4n}
      \label{th3e*+5}  &\equiv \left(\sum_{i=0}^{\infty}q^{4i^2}+\sum_{i,j=1}^{\infty}q^{4(i^2+j^2)}\right)\frac{(q^{2^{\alpha+1}};q^{2^{\alpha+1}})_\infty^2}{(q^{2^\alpha};q^{2^\alpha})_\infty^4}\pmod 3.
\end{align}
By replacing $q^4$ by $q$ in (\ref{th3e*+5}), we get
\begin{align}
     \sum_{n=0}^{\infty}\overline{B}_{2^\alpha,3}(4n)q^{n}
      \label{th3e*5}  &\equiv \left(\sum_{i=0}^{\infty}q^{i^2}+\sum_{i,j=1}^{\infty}q^{(i^2+j^2)}\right)\frac{(q^{2^{\alpha-1}};q^{2^{\alpha-1}})_\infty^2}{(q^{2^{\alpha-2}};q^{2^{\alpha-2}})_\infty^4}\pmod 3.
\end{align}
By using the facts that $i^2\equiv 0$ or $1\pmod 4$ and $i^2+j^2\equiv 0,1$ or $2\pmod 4$, we are able to conclude that there are no terms for the form $q^{4n+3}$ in (\ref{th3e*5}). Thus we can write if $\alpha>3$
\begin{align}
    \overline{B}_{2^\alpha,3}(4(4n+3))\equiv 0\pmod 3.
\end{align}
Since we have $\overline{B}_{2^\alpha,3}(4(4n+3))\equiv 0\pmod 2$, we will obtain (\ref{th2e1}) for the case $k=1$.

From both sides of (\ref{th3e*5}), if we extract the terms of the form $q^{4n}$, we will get

\begin{align}
    \sum_{n=0}^{\infty}\overline{B}_{2^\alpha,3}(4^2n)q^{4n}
    &\equiv \left(\sum_{i=0}^{\infty}q^{4i^2}+\sum_{i,j=1}^{\infty}q^{4(i^2+j^2)}\right)\frac{(q^{2^{\alpha-1}};q^{2^{\alpha-1}})_\infty^2}{(q^{2^{\alpha-2}};q^{2^{\alpha-2}})_\infty^4}\pmod 3
\end{align}

Replacing $q^4$ by $q$ we can write

\begin{align}
     \sum_{n=0}^{\infty}\overline{B}_{2^\alpha,3}(4^2n)q^{n}
    &\equiv \left(\sum_{i=0}^{\infty}q^{i^2}+\sum_{i,j=1}^{\infty}q^{i^2+j^2}\right)\frac{(q^{2^{\alpha-3}};q^{2^{\alpha-3}})_\infty^2}{(q^{2^{\alpha-4}};q^{2^{\alpha-4}})_\infty^4}\pmod 3.
\end{align}

Proceeding as above, if $\alpha>5$ we are able to write

\begin{align}
    \overline{B}_{2^\alpha,3}(4^2(4n+3))\equiv 0\pmod 6
\end{align}
which is the case for $k=2.$

If we continue to repeat this process, at the $k^{\text{th}}$ step we will obtain

\begin{align}
     \sum_{n=0}^{\infty}\overline{B}_{2^\alpha,3}(4^kn)q^{n}
    &\equiv \left(\sum_{i=0}^{\infty}q^{i^2}+\sum_{i,j=1}^{\infty}q^{i^2+j^2}\right)\frac{(q^{2^{\alpha+1-2k}};q^{2^{\alpha+1-2k}})_\infty^2}{(q^{2^{\alpha-2k}};q^{2^{\alpha-2k}})_\infty^4}\pmod 3.
\end{align}

Using the same arguments as above, if $\alpha>2k +1$, we get
\begin{align}
    \overline{B}_{2^\alpha,3}(4^k(4n+3))\equiv 0\pmod 6
\end{align}
which completes the proof of (\ref{th2e1})

Plugging (\ref{3}) and (\ref{4}) in (\ref{th2e3}) and interchanging $q^2$ with $q$ after collecting the terms comprising $q^{2n+1}$ on both sides, we get

\begin{align*}
