\begin{align*}
    +24 \frac{(q^4;q^4)_\infty^9(q^2;q^2)_\infty^2(q^3;q^3)_\infty^3 (q^{2^{\alpha-3}};q^{2^{\alpha-3}})_\infty^2(q^{2^{\alpha-2}\cdot 3};q^{2^{\alpha-2}\cdot 3})_\infty}{(q;q)_\infty^{12}(q^8;q^8)_\infty^2 (q^{2^{\alpha-2}};q^{2^{\alpha-2}})_\infty(q^{2^{\alpha-3}\cdot 3};q^{2^{\alpha-3}\cdot 3})_\infty^2}
\end{align*}

From this we obtain (\ref{th2e2}).

\end{proof}

\begin{proof}[Proof of Theorem \ref{thm3}]

