\end{align}

\begin{align*}
    \times
    \frac{(q^{3^{\beta-1}};q^{3^{\beta-1}})_\infty^2 (q^{2\cdot2^{2\alpha +1}\cdot 3^{\beta-1}};q^{2\cdot2^{2\alpha +1}\cdot 3^{\beta-1}})_\infty}{(q^{2\cdot 3^{\beta-1}};q^{2\cdot 3^{\beta-1}})_\infty (q^{2^{2\alpha +1}\cdot 3^{\beta-1}};q^{2^{2\alpha +1}\cdot 3^{\beta-1}})_\infty^2} \pmod 4
\end{align*}
    From this we can see that (\ref{th3e1}) holds.

   Again by setting $\ell_1=2^{2\alpha}$, $\ell_2=3^\beta$ in (\ref{0}) we get 

   \begin{align}\label{th3e6}
    \sum_{n=0}^{\infty}\overline{B}_{2^{2\alpha },3^\beta}(n)q^n
    = \frac{(q^2;q^2)_\infty(q^{2^{2\alpha}};q^{2^{2\alpha}})_\infty^2(q^{3^\beta};q^{3^\beta})_\infty^2 (q^{2\cdot2^{2\alpha }\cdot 3^\beta};q^{2\cdot2^{2\alpha }\cdot 3^\beta})_\infty}
    {(q;q)_\infty^2 (q^{2\cdot2^{2\alpha }};q^{2\cdot2^{2\alpha }})_\infty (q^{2\cdot 3^\beta};q^{2\cdot 3^\beta})_\infty (q^{2^{2\alpha }\cdot 3^{\beta}};q^{2^{2\alpha }\cdot 3^{\beta}})_\infty^2}
\end{align}

Applying (\ref{5}) with $q$ replaced by $q^{2^{2\alpha}}$ and (\ref{6}) in (\ref{th3e6}), we will obtain

\begin{align}\label{th3e7}
    \sum_{n=0}^{\infty}\overline{B}_{2^{2\alpha },3^\beta}(n)q^n
    = \left( \frac{(q^6;q^6)_\infty^4(q^9;q^9)_\infty^6}{(q^3;q^3)_\infty^8(q^{18};q^{18})_\infty^3}+2q\frac{(q^6;q^6)_\infty^3(q^9;q^9)_\infty^3}{(q^3;q^3)_\infty^7}+4q^2\frac{(q^6;q^6)_\infty^2(q^{18};q^{18})_\infty^3}{(q^3;q^3)_\infty^6} \right)
\end{align}
\begin{align*}
\times
     \left( \frac{(q^{9\cdot {2^{2\alpha}}};q^{9\cdot{2^{2\alpha}}})_\infty^2}{(q^{18\cdot {2^{2\alpha}}};q^{18\cdot {2^{2\alpha}}})_\infty}-2q^{2^{2\alpha}}\frac{(q^{3\cdot{2^{2\alpha}}};q^{3\cdot{2^{2\alpha}}})_\infty(q^{18\cdot{2^{2\alpha}}};q^{18\cdot{2^{2\alpha}}})_\infty^2}{(q^{6\cdot{2^{2\alpha}}};q^{6\cdot{2^{2\alpha}}})_\infty(q^{9\cdot{2^{2\alpha}}};q^{9\cdot{2^{2\alpha}}})_\infty} \right)
\end{align*}
   \begin{align*}
\times
\frac{(q^{3^\beta};q^{3^\beta})_\infty^2 (q^{2\cdot2^{2\alpha }\cdot 3^\beta};q^{2\cdot2^{2\alpha }\cdot 3^\beta})_\infty}
    {(q^{2\cdot 3^\beta};q^{2\cdot 3^\beta})_\infty (q^{2^{2\alpha }\cdot 3^{\beta}};q^{2^{2\alpha }\cdot 3^{\beta}})_\infty^2}
   \end{align*}

   Because we have $2^{2\alpha }+2\equiv 0\pmod 3$ and $2^{2\alpha }+1\not\equiv 0\pmod 3$, taking all the terms containing $q^{3n}$ from sides of (\ref{th3e7}) and replacing $q^3$ by $q$, and then by using (\ref{6}) we can see that




\begin{align}\label{th3e8}
     \sum_{n=0}^{\infty}\overline{B}_{2^{2\alpha },3^\beta}(3n)q^n
     \equiv   \frac{(q^6;q^6)_\infty^{13} (q^9;q^9)_\infty^{24} (q^{3\cdot 2^{2\alpha }};q^{3\cdot 2^{2\alpha }})_\infty^2 }
    {(q^3;q^3)_\infty^{26}(q^{18};q^{18})_\infty^{12} (q^{6\cdot 2^{2\alpha }};q^{6\cdot 2^{2\alpha }})_\infty}
\end{align}

\begin{align*}
    \times
    \frac{(q^{3^{\beta-1}};q^{3^{\beta-1}})_\infty^2 (q^{2\cdot2^{2\alpha }\cdot 3^{\beta-1}};q^{2\cdot2^{2\alpha }\cdot 3^{\beta-1}})_\infty}{(q^{2\cdot 3^{\beta-1}};q^{2\cdot 3^{\beta-1}})_\infty (q^{2^{2\alpha }\cdot 3^{\beta-1}};q^{2^{2\alpha }\cdot 3^{\beta-1}})_\infty^2} \pmod 8
\end{align*}

Accordingly, (\ref{th3e8}) implies (\ref{th3e2}).\\



\end{proof}

