\section{Congruences for $\overline{B}_{2^{\alpha},3^\beta}(n)$ }
This section is devoted for proving Theorem \ref{THM}.


\begin{proof}[Proof of Theorem \ref{THM}]
    Substituting $\ell_1=2^\alpha$ and $\ell_2=3^\beta$ in (\ref{0}), we can write
    \begin{align}\label{p1}
        \overline{B}_{2^\alpha, 3^\beta}(n)=\frac{(q^2;q^2)_\infty (q^{2^\alpha};q^{2^\alpha})_\infty^2(q^{3^\beta};q^{3^\beta})_\infty^2(q^{2^{\alpha+1}\cdot3^\beta};q^{2^{\alpha+1}\cdot3^\beta})_\infty}{(q;q)_\infty^2 (q^{2^{\alpha+1}};q^{2^{\alpha+1}})_\infty (q^{2\cdot3^\beta};q^{2\cdot3^\beta})_\infty (q^{2^{\alpha}\cdot3^\beta};q^{2^{\alpha}\cdot3^\beta})_\infty^2}
    \end{align}

     Since $\varphi(-q)=\frac{(q;q)_\infty^2}{(q^2;q^2)_\infty}$, we can rewrtite \ref{p1} as 
    \begin{align}\label{p2}
        \sum_{n=0}^{\infty}\overline{B}_{2^{\alpha },3^\beta}(n)q^n=\frac{\varphi(-q^{2^\alpha})\varphi(-q^{3^\beta})}{\varphi(-q)\varphi(-q^{2^{\alpha}\cdot3^{\beta}})}.
    \end{align}
    We use the facts that $\frac{1}{\varphi(-q)}=\varphi(q)(\varphi(q^2))^2(\varphi(q^4))^4(\varphi(q^8))^8\cdots$ and $(\varphi(q^i))^j\equiv 1\pmod 8$ if $j\geq 4$ and $j$ is a multiple of $4$, to rewrite (\ref{p2}) as

    \begin{align}\label{p3}
        \sum_{n=0}^{\infty}\overline{B}_{2^{\alpha },3^\beta}(n)q^n\equiv \frac{\varphi(-q^{2^\alpha})\varphi(-q^{3^\beta})\varphi(q)(\varphi(q^2))^2}{\varphi(-q^{2^{\alpha}\cdot3^{\beta}})}\pmod 8.
    \end{align}
For $\alpha\geq 2,$ $\varphi(-q^{2^{\alpha}\cdot3^{\alpha}})$ contains only the terms of the form $q^{12k}$. Now we consider the numerator part of (\ref{p3})

\begin{align}
   \notag &\varphi(-q^{2^\alpha})\varphi(-q^{3^\beta})\varphi(q)(\varphi(q^2))^2\\
  \notag & =\left(1+2\sum_{n=1}^{\infty}(-q^{2^\alpha})^{n^2} \right) \left(1+2\sum_{n=1}^{\infty}(-q^{3^\beta})^{n^2} \right) \left(1+2\sum_{n=1}^{\infty}q^{n^2} \right)
    \left(1+2\sum_{n=1}^{\infty}(q^{2})^{n^2} \right)^2\\
 \notag  & \equiv 1+ 2\sum_{n=1}^{\infty}(-q^{2^\alpha})^{n^2} +2 \sum_{n=1}^{\infty}(-q^{3^\beta})^{n^2} + 2 \sum_{n=1}^{\infty}q^{n^2}
   + 4 \sum_{n=1}^{\infty}(q^{2})^{n^2} + 4 \left(\sum_{n=1}^{\infty}(q^{2})^{n^2}\right)^2\\
\label{p4} & + 4 \sum_{i,j=1}^{\infty}(-q^{2^\alpha})^{i^2}(-q^{3^\beta})^{j^2} 
    + 4 \sum_{i,j=1}^{\infty}(-q^{2^\alpha})^{i^2}q^{j^2}
    + 4 \sum_{i,j=1}^{\infty}(-q^{3^\beta})^{i^2}q^{j^2} \pmod 8.
\end{align}

Since we have the facts that, 
  $  n^2 \equiv 0,1,4 \text{ or } 9 \pmod{12}, 
    2^\alpha \equiv 4 \text{ or } 8 \pmod{12} \text{ and }
    3^\beta \equiv 3 \text{ or } 9 \pmod{12}$, we can conclude the following.

If $\alpha$ is odd and $\beta$ is even,
\begin{align*}
  2^\alpha  n^2 &\equiv 0 \text{ or } 8 \pmod{12}\\ 
  3^\beta n^2 &\equiv 0 \text{ or } 9 \pmod{12}\\
    2^\alpha i^2 +j^2 &\equiv0,1 ,4,5,8 \text{ or } 9 \pmod{12} \\
    3^\beta i^2 +j^2 &\equiv 0,1 ,4,6,9 \text{ or } 10 \pmod{12}\\
  2^\alpha i^2  +3^\beta j^2 &\equiv 0,5,8 \text{ or } 9 \pmod{12}.
\end{align*}

When $\alpha$ is even and $\beta$ is odd,
\begin{align*}
  2^\alpha  n^2 &\equiv 0 \text{ or } 4 \pmod{12}\\ 
  3^\beta n^2 &\equiv 0 \text{ or } 3 \pmod{12}\\
    2^\alpha i^2 +j^2 &\equiv0,1 ,4,5,8 \text{ or } 9 \pmod{12} \\
    3^\beta i^2 +j^2 &\equiv 0,1 ,3,4,7 \text{ or } 9 \pmod{12}\\
  2^\alpha i^2  +3^\beta j^2 &\equiv 0,3,4 \text{ or } 7 \pmod{12}.
\end{align*}

If $\alpha$ and $\beta$ are odd,
\begin{align*}
  2^\alpha  n^2 &\equiv 0 \text{ or } 8 \pmod{12}\\ 
  3^\beta n^2 &\equiv 0 \text{ or } 3 \pmod{12}\\
    2^\alpha i^2 +j^2 &\equiv0,1 ,4,5,8 \text{ or } 9 \pmod{12} \\
    3^\beta i^2 +j^2 &\equiv  0,1 ,3,4,7\text{ or } 9 \pmod{12}\\
  2^\alpha i^2  +3^\beta j^2 &\equiv 0,3,8 \text{ or } 11 \pmod{12}.
\end{align*}

If $\alpha$ and $\beta$ are even,
\begin{align*}
  2^\alpha  n^2 &\equiv 0 \text{ or } 4 \pmod{12}\\ 
  3^\beta n^2 &\equiv 0 \text{ or } 9 \pmod{12}\\
    2^\alpha i^2 +j^2 &\equiv0,1 ,4,5,8 \text{ or } 9 \pmod{12} \\
    3^\beta i^2 +j^2 &\equiv 0,1,4,6,9 \text{ or } 10 \pmod{12}\\
  2^\alpha i^2  +3^\beta j^2 &\equiv 0,1,4 \text{ or } 9 \pmod{12}.
\end{align*}

If $\alpha$ is odd and $\beta$ is even, in (\ref{p4}) there exist no terms of the form $q^{12n+3}$, $q^{12n+7}$ and $q^{12n+11}$. When $\alpha$ is even and $\beta$ is odd, no terms of the form $q^{12n+11}$ can be found. For the case where both $\alpha$ and $\beta$ are even, there does not present any terms of the form $q^{12n+3}$, $q^{12n+7}$ and $q^{12n+11}$. From these discussions, we can deduce Theorem \ref{THM}.

\end{proof}


