The above equation also implies that $\omega_{\delta\nu}$ converges in $C_{loc}^{\infty}$-topology to $\omega_{\delta}$ as $\nu\to 0$. The K\"ahler metrics $\omega_{\delta}$ behave well around any point of $D$ in the following sense, which is clear by construction. 
\begin{Lemma}\label{isometry}
  Let $x\in D_{J}$ with $J\subset I$, we may choose a small coordinate neighborhood centered at $x$ such that the defining function of $D$ is $z_{1}\cdots z_{k}=0$. Then there exists a positive constants $C_{1}$ such that
  \begin{equation*}
    C_{1}^{-1}\cdot\omega_{\delta}\leq \sqrt{-1}\cdot \delta^2\cdot \sum_{i=1}^{k}\frac{\diff z_{i}\wedge \diff \overline{z_{i}}}{\left|z_{i}\right|^{2-2\delta}}+\sqrt{-1}\cdot \partial\overline{\partial}|z|^{2}\leq C_{1}\cdot\omega_{\delta}.
  \end{equation*}  
\end{Lemma}
 Notice that the pullback of $\omega_{\delta}$ by $\pi$ is a degenerated conical K\"ahler metric on $\widetilde{X}\setminus D$. Fix a normalized K\"ahler metric $\omega_{\widetilde{X}}$ on $\widetilde{X}$ such that $\int_{\widetilde{X}}\omega_{\widetilde{X}}^{n}=1$. We put $\omega_{\epsilon\delta}\coloneqq \omega_{\delta}+\epsilon\cdot\omega_{\widetilde{X}}$. Then $\omega_{\epsilon\delta}$ is a conical K\"ahler metric of $\widetilde{X}\setminus D$. And we have the following proposition.
\begin{Proposition}\label{Simpsonassumption}
  The K\"ahler manifold $(\widetilde{X}\setminus D, \omega_{\epsilon\delta})$ satisfies the following three assumptions:\begin{enumerate}
    \item The volume of $\widetilde{X}\setminus D$ is uniformly bounded independent of $\epsilon$ and $\delta$.
    \item There exists an exhaustion function $\phi$ with $\sqrt{-1}\Lambda_{\omega_{\epsilon\delta}}\partial\overline{\partial}\phi$ bounded.
    \item If $f$ is a bounded positive function on $\widetilde{X}\setminus D$ such that $\Delta_{\epsilon\delta}f\leq B$ for some positive function $B\in L^{p}$ $(p>n)$, then $\|f\|_{L^{\infty}}\leq C_{2}(\|B\|_{L^{p}}+\|f\|_{L^{1}})$. The constant $C_{2}$ is independent of $\epsilon$ and $\delta$. 
  \end{enumerate}
  Here $\Delta_{\epsilon\delta}=2\sqrt{-1}\Lambda_{\omega_{\epsilon\delta}}\overline{\partial}\partial$ is the negative Laplace operator and the Laplace operators appear in the rest of the paper will always be the negative one. 
  \begin{proof}
    The first assertion follows directly from the previous lemma. We put $\phi\coloneqq \log|\sigma|$. Then the second assertion follows from the Poincaré-Lelong formula.

    To proof the third assertion, we need a very important result of \cite{Go-Ph-So-Ja} which will also be used later. Let $(X,\omega_{X})$ be a compact K\"ahler manifold with a normalized K\"ahler metric $\omega_{X}$ such that $\int_{X}\omega_{X}^{n}=1$. Suppose that the complex dimension of $X$ is $n$. Given any K\"ahler metric $\omega$ on $X$, we denote its volume by $V_{\omega}\coloneqq[\omega]^{n}$ and define the relative volume density by \begin{equation*}
      e^{\lambda_{\omega}}\coloneqq \frac{1}{V_{\omega}}\frac{\omega^{n}}{\omega_{X}^{n}}.
    \end{equation*}
    Given $p\geq 1$ we define the $p$-th Nash-Yau entropy by 
    \begin{equation*}
      \mathcal{N}_{p}(\omega)\coloneqq \frac{1}{V_{\omega}}\int_{X}\left|\log\frac{1}{V_{\omega}}\cdot\frac{\omega^n}{\omega_X^n}\right|^{p}\cdot\omega^{n}.
    \end{equation*}
    For a given nonnegative continuous function $\gamma\in C^{0}(X)$, and given parameters $0<A\leq \infty$, $K>0$, we consider the following subset of the space of K\"ahler metrics on $X$:
    \begin{equation*}
      \mathcal{W}\coloneqq \mathcal{W}(n,p,A,K,\gamma)\coloneqq \left\{\omega:[\omega]\cdot[\omega_{X}]^{n-1}<A, \mathcal{N}_{p}\leq K, e^{\lambda_{\omega}} \geq \gamma\right\}.
    \end{equation*}
    The following theorem concerning the Sobolev inequality with respect to the K\"ahler metrics in $\mathcal{W}$ was obtained in \cite[Theorem 2.1]{Go-Ph-So-Ja}.
    \begin{Theorem}[Uniform Sobolev Inequality]
      Given $p>n$ and the zero locus of $\gamma$ has Hausdorff dimension less than $2n-1$, there exist $q=q(n,p)>1$ and $C_{3}=C_{3}(n,p,A,K,\gamma,q)>0$ such that for any $\omega\in \mathcal{W}$ and any $u\in L_{1}^{2}(X)$, we have the following Sobolev-type inequality 
      \begin{equation*}
        \left(\frac{1}{V_{\omega}}\int_{X}|u-\overline{u}|^{2q}\omega^{n}\right)^{\frac{1}{q}}\leq C_{3}\frac{1}{V_{\omega}}\int_{X}|\nabla u|^{2}\omega^{n},
      \end{equation*}
      where $\overline{u}\coloneqq \frac{1}{V_{\omega}}\int_{X}u\omega^{n}$.
    \end{Theorem}
  Now we return to the proof of the third assertion. We will apply the above theorem to investigate a family of metrics on $\widetilde{X}$. We put 
  \begin{equation*}
    \omega_{\epsilon\delta\nu}\coloneqq \omega_{\delta\nu}+\epsilon\cdot\omega_{\widetilde{X}}.
  \end{equation*}
  This is a smooth family of K\"ahler metrics on $\widetilde{X}$. Since $\omega_{0\delta\nu}$ only degenerates on the exceptional divisor $\mathscr{E}$, $\omega_{\epsilon\delta\nu}$ is supported by a continuous function $\gamma$ with vanishing locus of Hausdorff dimension $2n-2$. In order to apply the above theorem, we only need to check the Nash-Yau entropy condition. Recall that $\mathscr{E}\cup D$ is simple normal crossing. Hence we may choose a local coordinate patch \(z=(z',z'',z''')\), such that \(D=\bigcup_{i=1}^{k'}\{z'_i=0\}\) and \(\mathscr{E}=\bigcup_{j=1}^{k''}\{z''_j=0\}\). We may assume that \(|z|<1\). We put 
  \begin{equation*}
    f_{\epsilon\delta\nu}\coloneqq \frac{\omega_{\epsilon\delta\nu}^n}{\omega_{\widetilde{X}}^n}.
  \end{equation*}
  Then $f_{\epsilon\delta\nu}$ either degenerates to $0$ on $\mathscr{E}$ with a speed $\prod_{j}|z''_j|^{a}$ or blows up to infinity on $D$ with a speed $\prod_i|z'_i|^{-a}$ with some uniform \(a>0\). Therefore, if we fix a \(p>n\), we have
  \[
  |\log(f_{\epsilon\delta\nu})|^p\leq \frac{C_{15}}{\delta^{k'}\cdot\prod_{i=1}^{k'}|z_i'|^{\frac{\delta}{2}}\cdot\prod_{j=1}^{k''}|z_j''|^{\frac{1}{2}}}
  \]
  with $C_{15}$ a constant independent of $\delta$, \(\epsilon\) and \(\nu\). Then it follows from Lemma~\ref{isometry} that 
  \[
  |\log(f_{\epsilon\delta\nu})|^p\cdot \omega_{\epsilon\delta\nu}^n\leq \frac{C_{15}\cdot\delta^{k'}}{\prod_{i=1}^{k'}|z_i'|^{2-\frac{3\delta}{2}}\cdot\prod_{j=1}^{k''}|z_j''|^{\frac{1}{2}}}.
  \]
  Hence the integral of $|\log(f_{\epsilon\delta\nu})|^p\cdot \omega_{\epsilon\delta\nu}^n$ is uniformly bounded. Consequently, we can find suitable constants $p>n$, $A$ and $K$ such that the family of metrics $\omega_{\epsilon\delta\nu}$ belongs to $\mathcal{W}(n,p,A,K,\gamma)$. Then the above theorem implies the following lemma.
  \begin{Lemma}\label{uniSob}
    For any $f\in C_{0}^{\infty}(\widetilde{X}\setminus D^{*})$ and with respect to any conical K\"ahler metric $\omega_{\epsilon\delta}$ on $\widetilde{X}\setminus D^{*}$, we have the uniform Sobolev inequality \begin{equation*}
      \|f\|_{L^{q}}\leq C_{4}\|f\|_{L_{1}^{2}}
    \end{equation*}
    with $C_{4}$ independent of $\epsilon$ and $\delta$.
    \begin{proof}
      This is true because $f$ is compactly supported in $\widetilde{X}\setminus D^{*}$ and $\omega_{\epsilon\delta\nu}$ converges in $C_{loc}^{\infty}$-topology to $\omega_{\epsilon\delta}$ as $\nu$ tends to $0$.
    \end{proof}
  \end{Lemma}
  Now we are ready to prove the third assertion by Moser's iteration. Let $f$ be a positive bounded function which satisfies the assumption of the third assertion, i.e. $\Delta_{\omega_{\epsilon\delta}}f=\sqrt{-1}\Lambda_{\omega_{\epsilon\delta}}\partial\overline{\partial}f\leq B$. We put $f_{\nu}\coloneqq (f+\nu\log|\sigma|)^{+}$ with $0<\nu<1$. Then we have \begin{equation*}
    \Delta_{\omega_{\epsilon\delta}}f_{\nu}\leq B_{\nu}
  \end{equation*}
  in the weak sense, where $B_{\nu}$ converges to $B$ in $C^{\infty}$-topology as $\nu$ tends to $0$. As $f_{\nu}$ lies in the Sobolev closure of $C_{0}^{\infty}(\widetilde{X}\setminus D^{*})$, hence we may apply Moser's iteration to obtain the estimate \begin{equation*}
    \|f_{\nu}\|_{L^{\infty}}\leq C_{5}(\|f_{\nu}\|_{L^{1}}+\|B_{\nu}\|_{L^{p}})
  \end{equation*}
  with $p>n$. Taking the limit as $\nu$ tends to $0$ completes the proof.
  \end{proof}
\end{Proposition}
The uniform Sobolev inequality also implies the following uniform upper bound for the heat kernels on $\widetilde{X}\setminus D$ with repsect to the family of conical metrics $\omega_{\epsilon\delta}$. 
\begin{Proposition}\label{HeatkernelUB}
  Let $K_{\epsilon\delta}$ be the heat kernel with respect to $\omega_{\epsilon\delta}$, then for any $\tau>0$, there exists a constant $C_{K}(\tau)$ which is independent of $\epsilon$ and $\delta$ such that 
  \begin{equation*}
    0<K_{\epsilon\delta}(x,y,t)\leq C_{K}(\tau)\left(t^{n}\exp(-\frac{d_{\epsilon\delta}(x,y)}{(4+\tau)t})+1\right)
  \end{equation*}
  where $d_{\epsilon\delta}(\cdot,\cdot)$ is the distance function of $\widetilde{X}\setminus D^{*}$ with repsect to the metric $\omega_{\epsilon\delta}$.
  \begin{proof}
    Recall that $\omega_{\epsilon\delta\nu}$ is a family of smooth metrics on the compact manifold $\widetilde{X}$ such that the uniform Sobolev inequality is satisfied. On the one hand, by combining the diagonal heat kernel estimate shown in~\cite{Ch-Li} and the Gaussian upper bound estimate in~\cite[Theorem 1.1]{GrYan}, we have 
    \begin{equation*}
      0<K_{\epsilon\delta\nu}(x,y,t)\leq C_{K}(\tau)\left(t^{n}\exp(-\frac{d_{\epsilon\delta\nu}(x,y)}{(4+\tau)t})+1\right).
    \end{equation*}
    On the other hand, it is easy to show that $K_{\epsilon\delta\nu}$ converges uniformly to the heat kernel $K_{\epsilon\delta}$ on compact subsets of $(\widetilde{X}\setminus D^{*})\times (\widetilde{X}\setminus D^{*})$ as $\nu$ tends to $0$. Hence the proposition follows.
  \end{proof}
\end{Proposition}
\subsection{Parabolic metric}
The target of this subsection is to construct a Hermitian metric $\widehat{H}$ on the regular part of $\pF$ which is compatible with the parabolic structure in the sense of Definiton~\ref{comatibleandadmissible}. We also wish it to satisfy the following equations in the sense of currents on $X$: 
\begin{align*}
  %&\ch_{1}(\F)=\frac{\sqrt{-1}}{2\pi}\tr(F_{H_{0}})\\
  %&\ch_{1}(\F)^2=\left(\frac{\sqrt{-1}}{2\pi}\right)^{2}\tr(F_{H_{0}})\wedge \tr(F_{H_{0}})\\
  %&\ch_{2}(\F)=\frac{1}{2}\left(\frac{\sqrt{-1}}{2\pi}\right)^{2}\tr(F_{H_{0}}\wedge F_{H_{0}})\\
  &\ch_{1}(\pF)=\frac{\sqrt{-1}}{2\pi}\tr(F_{\widehat{H}})\\
  &\ch_{1}(\pF)^2=\left(\frac{\sqrt{-1}}{2\pi}\right)^{2}\tr(F_{\widehat{H}})\wedge \tr(F_{\widehat{H}})\\
  &\ch_{2}(\pF)=\frac{1}{2}\left(\frac{\sqrt{-1}}{2\pi}\right)^{2}\tr(F_{\widehat{H}}\wedge F_{\widehat{H}}).
\end{align*}
%\begin{Definition}
  %Given a torsion-free sheaf $\F$ over $X$. Let $X^{\circ}$ be the Zariski open subset where $\F$ is locally free. If a Hermitian metric $H$ defined on ${\F}_{|X^{\circ}}$ satisfies the first equation above, we call it adapted to $\F$ in codimension $1$. If it satisfies the first two equations, we call it adapted to $\F$ in codimension $2$.
%\end{Definition}
\begin{Definition}
  If a Hermitian metric $H$ defined on ${\pF}_{|X^{\circ}\setminus D}$ satisfies the first equation above, we call it adapted to $\pF$ in codimension $1$. If it satisfies all of the equations, we call it adapted to $\pF$ in codimension $2$.
\end{Definition}
In view of Lemma~\ref{cherncharacterpreserve}, it suffices to construct a Hermitian metric $H_0$ on the regular part of the locally abelian parabolic bundle $E_*'\coloneqq E\otimes[-P_0]$ which is adapted in codimension $2$. Indeed, should this be completed, we may choose a Hermitian metric $h_{P_0}$ for the line bundle $\mathcal{O}_{\widetilde{X}}(P_0)$ and then $\widehat{H}\coloneqq H_0\otimes h_{P_0}$ will be a Hermitian metric on $E_{|\widetilde{X}\setminus D^*}$ which in turn will induce a metric on the regular part of $\pF$. Since $E\otimes[-P]\cong \F$, it is easy to see that $\widehat{H}$ is adapted to $\pF$ in codimension $2$ because the singular locus has codimension at least $3$. 
% As we know from the last section, three irreducible components of $D^*$ can not intersection simultaneously. Hence without loss of generality, we may restrict ourselves to the setting that $D^*$ only has two irreducible components $D_1^*$ and $D_2^*$ and $D_1^* \cap D_2^*$ only has one irrducible component.

We introduce an appraoch to construct an adapted metric on a locally abelian parabolic bundle. The notation used in the construction process will be independent of that used elsewhere. Firstly, it is important to have a smooth decomposition of the bundle in a small neighborhood of the divisor $D$ which is in some sense compatible with the paraboic structrue. 

\subsubsection{Smooth decomposition}
\paragraph{Local patching}
Let $X$ be a complex manifold. Let $D=\bigcup_{ 1\leq i\leq \ell}D_{i}$ be a simple normal crossing divisor. We set $Y=\bigcap_{i=1}^{\ell}D_i$.
We set $S=\{0\leq a <1\}$. For any $1\leq i\leq\ell$, let $q_{i}:S^{\ell}\to S$ denote the projection onto the $i$-th component.

Let $F_*=(F,\boldsymbol{F})$ be a locally abelian parabolic bundle on $X$. Recall that $\boldsymbol{F}=({}^{i}\!F\,|\,i=1,\ldots,\ell)$ is a tuple of decreasing filtrations ${}^{i}\!F$ of $F_{|D_i}$ by holomorphic subbundles indexed by $S$ such that the following holds.

\begin{itemize}
\item For any $1\leq i\leq\ell$ and $a\in S$, there exists $\epsilon>0$ such that ${}^{i}\!F_{a}={}^{i}\!F_{a-\epsilon}$.
\item For any $P\in Y$, there exist a neighbourhood ${\U}_{P}$ of $P$ in $X$ and a holomorphic decomposition $F_{|\mathcal{U}_{P}}=\boplus_{\va\in S^{\ell}}{}^{P}\!G_{\va}$ such that \[\bigoplus_{q_{i}(\va)\geq @}{}^{P}\!G_{\va|D_i\cap{\U}_{P}}={}^{i}\!F_{|D_i\cap{\U}_{P}}.\]
\end{itemize}
Here the symbol ``@'' denotes a real variable taking values from $[0,1[$ and we regard $$\bigoplus_{q_{i}(\va)\geq @}{}^{P}\!G_{\va|D_i\cap{\U}_{P}}$$ as a left continuous filtration.
% \begin{Remark}
% In this note, we consider increasing filtrations, i.e., ${}^{t}\!F_{a}\subset{}^{t}\!F_{b}$ for $-1<a\leq b\leq 0$ following my preference.
% \end{Remark}

Let $X_{2}\subset X_{1}\subset X$ be open subsets such that the closure of $X_{2}$ is contained in $X_{1}$. Suppose that there exists a $C^{\infty}$-decomposition
\[F_{|X_{1}}=\bigoplus_{\boldsymbol{a}\in S^{\ell}}{}^{1}\!G_{\boldsymbol{a}}\]
such that the following holds:
\[\bigoplus_{q_{i}(\boldsymbol{a})\geq @}{}^{1}\!G_{\va|D_i\cap X_{1}}={}^{i}\!F_{|D_i\cap X_{1}}.\]

\begin{Proposition}\label{localpatching}
There exist a neighbourhood ${\U}$ of $Y$ and a $C^{\infty}$-decomposition
\[F_{|\mathcal{U}}=\bigoplus_{\boldsymbol{a}\in S^{\ell}}G_{\boldsymbol{a}}\]
such that the following holds:
\begin{itemize}
\item $\bigoplus_{q_{i}(\boldsymbol{a})\geq @}G_{\boldsymbol{a}|D_i\cap{\U}}={}^{i}\!F_{|D_i\cap{\U}}$.
\item $G_{\boldsymbol{a}|X_{2}}={}^{1}\!G_{\boldsymbol{a}|X_{2}}$.
\end{itemize}
\end{Proposition}

\begin{proof}
Since locally, $F_*$ is a direct sum of parabolic line bundles, there exists a tuple of open subsets ${\U}_{k}$ ($k\in\Gamma$) of $X$ such that the following holds:
\begin{itemize}
\item $Y\subset\mathcal{V}:=\bigcup{\U}_{k}\cup X_{1}$
\item On each $\mathcal{U}_{k}$, there exists a $C^{\infty}$-decomposition
\[F_{|\mathcal{U}_{k}}=\bigoplus_{\boldsymbol{a}\in S^{\ell}}{}^{k}\!G_{\boldsymbol{a}}\]
such that the following holds:
\[\bigoplus_{q_{i}(\boldsymbol{a})\geq @}{}^{k}\!G_{\boldsymbol{a}|D_i\cap\mathcal{U}_{k}}={}^{i}\!F_{|D_i\cap\mathcal{U}_{k}}.\]
\end{itemize}

Let $\{\chi_{k}\}\cup\{\chi_{X_{1}}\}$ be a partition of unity on $\mathcal{V}$ subordinate to the open covering $\mathcal{V}=\bigcup\mathcal{U}_{k}\cup X_{1}$. We may assume that $\chi_{X_{1}}=1$ on $X_{2}$. Let $\psi:S^{\ell}\to\mathbb{C}$ be an injection. We set \[f_{k}=\sum_{\boldsymbol{a}\in S^{\ell}}\psi(\boldsymbol{a})\cdot\id_{{}^{k}\!G_{\boldsymbol{a}}}\] and \[f_{X_{1}}=\sum_{\boldsymbol{a}\in S^{\ell}}\psi(\boldsymbol{a})\cdot\id_{{}^{1}\!G_{\boldsymbol{a}}}.\] We obtain the following $C^{\infty}$-endomorphism of $F$ on $\mathcal{V}$:
\[f=\sum_{k\in\Gamma}\chi_{k}\cdot f_{k}+\chi_{X_{1}}\cdot f_{X_{1}}.\]
In the mean time, we obtain the following lemma by the construction.

\begin{Lemma}\label{endpreserving}
The restriction $f_{|Y}$ preserves the filtrations ${}^{i}\!F$ ($i=1,\ldots,\ell$) of $F_{|Y}$. Moreover, the induced endomorphism on ${}^{\underline{\ell}}\!\Gr_{\boldsymbol{a}}(F_{|Y})$ equals the multiplication of $\psi(\boldsymbol{a})$.
\end{Lemma}

As a result, we obtain the eigen decomposition
\[(F,f)_{|Y}=\bigoplus_{\alpha\in\mathbb{C}}(K_{\alpha},\alpha\cdot\id_{K_{\alpha}}).\]
There exists a neighbourhood $\mathcal{U}$ of $Y$ and a decomposition
\[(F,f)_{|\mathcal{U}}=\bigoplus_{\alpha\in\mathbb{C}}(K_{\mathcal{U},\alpha},f_{\alpha})\]
such that $K_{\mathcal{U},\alpha|Y}=K_{\alpha}$. If $\mathcal{U}$ is sufficiently small, any eigenvalues of $f_{\alpha|P}$ ($P\in\mathcal{U}$) are close to $\alpha$. In particular, we may assume that there are no common eigenvalues of $f_{\alpha}$ and $f_{\beta}$ ($\alpha\neq\beta$). We set
\[G_{\boldsymbol{a}}=K_{\mathcal{U},\psi(\boldsymbol{a})}.\]
The restriction $f_{|D_i\cap\mathcal{U}}$ preserves the filtration ${}^{i}\!F$. We have
\[{}^{i}\!F_{b|Y}=\bigoplus_{q_{i}(\boldsymbol{a})\geq b}K_{\psi(\boldsymbol{a})}.\]
Then, we obtain $\bigoplus_{q_{i}(\boldsymbol{a})\geq @}G_{\boldsymbol{a}|D_i\cap\mathcal{U}}={}^{i}\!F_{|D_i\cap\mathcal{U}}$. Because $\chi_{X_{1}}=1$ on $X_{2}$, we have $G_{\boldsymbol{a}|X_{2}}={}^{1}\!G_{\boldsymbol{a}|X_{2}}$.
\end{proof}

\paragraph{Glocal decomposition}
With the above proposition at hand it is easy to get a global $C^{\infty}$-decomposition near $D$.
Let $X$ be a complex manifold. Let $D=\bigcup_{i\in \Lambda}D_{i}$ be a simple normal crossing divisor. For any $I\subset\Lambda$, we set $D_{I}=\bigcap_{i\in I}D_i$, $\partial D_{I}=\bigcup_{j\in\Lambda\setminus I}(D_{I}\cap D_{j})$ and $D_{I}^{\circ}=D_{I}\setminus\partial D_{I}$. For any $I\subset J\subset\Lambda$, let $q_{I,J}:S^{J}\to S^{I}$ denote the projection. As before, let $F_{*}=(F,\boldsymbol{F})$ be a parabolic bundle on $X$. Let $\boldsymbol{F}=({}^{i}\!F\,|\,i\in\Lambda)$ be the parabolic structure.

\begin{Proposition}\label{globaldecomposition}
There exist neighbourhoods ${\U}_{i}$ ($i\in\Lambda$) of $D_i$ and $C^{\infty}$-decompositions
\[F_{|{\U}_{i}}=\bigoplus_{a\in S}{}^{i}\!G_{a}\]
such that the following holds:
\begin{itemize}
\item $\bigoplus_{a\geq b}{}^{i}\!G_{a|D_i}={}^{i}\!F_{b}$ holds for any $b\in S$.
\item For any $I\subset\Lambda$ and $\boldsymbol{a}=({}^{i}\!a\,|\,i\in I)\in S^{I}$, on ${\U}_{I}=\bigcap_{i\in I}{\U}_{i}$, we set ${}^{I}\!G_{\boldsymbol{a}}=\bigcap_{i\in I}{}^{i}\!G_{{}^{i}\!a|{\U}_{I}}$. Then, $F_{|{\U}_{I}}=\bigoplus_{\boldsymbol{a}\in S^{I}}{}^{I}\!G_{\boldsymbol{a}}$ holds.
\end{itemize}

\begin{proof}
By using a descending induction on $|I|$, we shall construct neighbourhoods ${\cal V}_{I}$ ($I\subset\Lambda$) of $D_{I}$ and decompositions
\[F_{|{\cal V}_{I}}=\bigoplus_{\boldsymbol{a}\in S^{I}}{}^{I}\!G_{\boldsymbol{a}}\]
such that the following holds:
\begin{itemize}
\item[(a)] $\bigoplus_{q_{i,I}(\boldsymbol{a})\geq b}{}^{I}\!G_{\boldsymbol{a}|D_i\cap{\cal V}_{I}}={}^{i}\!F_{b|D_i\cap{\cal V}_{I}}$ holds for any $b\in S$.
\item[(b)] For $I\subset J$ and $\boldsymbol{a}\in S^{I}$, we have ${}^{I}\!G_{\boldsymbol{a}|{\cal V}_{J}}=\bigoplus_{q_{I,J}(\boldsymbol{b})=\boldsymbol{a}}{}^{J}\!G_{\boldsymbol{b}}$.
\end{itemize}

Suppose that we have already constructed such decompositions for $J\subset\Lambda$ with $|J|\geq k_{0}+1$. Let $I\subset\Lambda$ with $|I|=k_{0}$.
For $I\subset J\subset\Lambda$ with ${\U}_{J}\neq\varnothing$ and for $\boldsymbol{a}\in S^{I}$, we set
\begin{equation*}
{}^{J}\!G_{\boldsymbol{a}}\coloneqq\bigoplus_{q_{I,J}(\boldsymbol{b})=\va}{}^{J}\!G_{\boldsymbol{b}}.
\end{equation*}
We obtain the following decomposition:
\[F_{|{\U}_{J}}=\bigoplus_{\boldsymbol{a}\in S^{I}}{}^{J}\!G_{\boldsymbol{a}}\]
By the condition (b), we obtain ${}^{J}\!G_{\boldsymbol{a}|{\U}_{K}}={}^{K}\!G_{\boldsymbol{a}}$ for any $J\subset K$ and $\boldsymbol{a}\in S^{I}$. From ${}^{J}\!G_{\boldsymbol{a}}$ ($I\subsetneq J$), we obtain a $C^{\infty}$-subbundle $^{1,I}\!G_{\boldsymbol{a}}$ of $F$ on ${\U}_{I,1}=\bigcup_{I\subsetneq J}{\U}_{J}$. We obtain the decomposition
\[F_{|{\U}_{I,1}}=\bigoplus_{\boldsymbol{a}\in S^{I}}{}^{1,I}\!G_{\boldsymbol{a}}\]
Let ${\U}_{I,2}\subset{\U}_{I,1}$ be an open neighbourhood of $\partial D_{I}$ whose closure is contained in ${\U}_{I,1}$. By Proposition~\ref{localpatching}, there exist a neighbourhood ${\cal V}_{I}$ of $D_{I}$ and a decomposition
\[F_{|{\U}_{I}}=\bigoplus_{\boldsymbol{a}\in S^{I}}{}^{I}\!G_{\boldsymbol{a}}\]
such that the condition (a) holds for $I$ and that ${}^{I}\!G_{\boldsymbol{a}|{\U}_{I,2}}={}^{1,I}\!G_{\boldsymbol{a}|{\U}_{I,2}}$. We replace ${\cal V}_{J}$ with ${\cal V}_{J}\cap{\U}_{I}$ for any $J\ni I$. Then, we obtain the claim of the proposition.
\end{proof}
\end{Proposition}

\subsubsection{Construction of metric}
Let $H_{1}$ be a Hermitian metric of $F$ such that the following holds:
\begin{itemize}
\item The decomposition $F_{|{\U}_{I}}=\bigoplus {}^{I}\!G_{\boldsymbol{a}}$ is orthogonal with respect to $H_{1|{\U}_{I}}$.
\end{itemize}
Let $h^{(i)}$ ($i\in\Lambda$) be Hermitian metrics of ${\cal O}_{X}(D_i)$. We set $\tau_{i}=h^{(i)}(1,1)$. We may assume that $\tau_{i}$ is constantly $1$ on $X\setminus{\U}_{i}$. Let $\tau\coloneqq \bigotimes_{i\in \Lambda}\tau_i$ be the induced square length of the canonical section of $D$. Let $s_{i}$ be the automorphism of $F_{|X\setminus D_i}$ such that the following holds:
\begin{itemize}
\item $s_{i}=\id$ on $X\setminus{\U}_{i}$.
\item $s_{i}=\bigoplus_{{a}\in S}\tau_{i}^{-a}\id_{{}^{i}\!G_{a}}$ on ${\U}_{i}$.
\end{itemize}

We obtain the automorphism $s=\prod_{i\in\Lambda}s_{i}$ of $F$ which is self-adjoint with respect to $H_{1}$. We define the $C^{\infty}$-Hermitian metric $H_{0}$ of $F_{|X\setminus D}$ by $H_{0}(u,v)=H_{1}(su,v)$ for any local sections $u,v$ of $F$. And we may extend $H_{0}$ smoothly to $X$.

% We set $B:=\partial_{F,H_{0}}-\partial_{F,H_{1}}=s^{-1}\partial_{F,H_{1}}s$.

\subsubsection{Adaptedness}
It follows from the construction that for any $[\eta]\in H^{n-1,n-1}(X,\mathbb{C})$ we have:
\begin{Proposition}\label{adaptcod1bundle}
    $\ch_{1}(F_{*})\cdot [\eta]=\frac{\sqrt{-1}}{2\pi}\int_{X\setminus D}\tr(F_{\nabla_{H_0}})\wedge \eta$.
\end{Proposition}

Let $\varepsilon$ be the largest gap of the weights and $\kappa$ be the smallest gap of the weights. 

Let $(U,z_{1},\ldots,z_{n})$ be a holomorphic coordinate neighbourhood of $X$ such that $D\cap U=\bigcup_{i=1}^{\ell}\{z_{i}=0\}$.
For $1\leq i\leq\ell$, we have $\lambda(i)\in\Lambda$ such that $D_{U,\lambda(i)}\coloneqq D_{\lambda(i)}\cap U=\{z_{i}=0\}$. We set $I=\{\lambda(i)\,|\,i=1,\ldots,\ell\}$. By shrinking $U$, we assume $U\subset\U_{I}$. We obtain the induced $C^{\infty}$-decomposition
\[F_{|U}=\bigoplus_{\boldsymbol{a}\in S^{I}}{}^{I}\!G_{\boldsymbol{a}}.\]
For any $1\leq k\leq\ell$ and $a\in S$, we set
\[{}^{k}\!G_{a}=\bigoplus_{q_{\lambda(k)}(\boldsymbol{a})=a}{}^{I}\!G_{\boldsymbol{a}}.\]
We obtain the decomposition
\begin{equation}\label{decomeq}
  F_{|U}=\bigoplus_{a\in S}{}^{k}\!G_{a}.
\end{equation}

Let \(\iota_{\va}\) be the injection from ${}^{I}\!G_{\va}$ to $F$ and \(\pi_{\va}\) be the orthogonal projection from $F$ to ${}^{I}\!G_{\va}$ with respect to the metric $H_{1}$. We set $\nabla_{\va}\coloneqq \pi_{\va}\cdot \nabla_{H_1}\cdot \iota_{\va}$ as the induced connection on ${}^{I}\!G_{\va}$. Then $\widetilde{\nabla}\coloneqq \boplus_{\va}\nabla_{\va}$ is a unitary connection which preserves the decomposition. We have for any $a$ and $k$, restricting on ${}^{k}\!G_{a|D_k}={}^{k}\Gr_a F_{*}$, $\widetilde{\nabla}=\nabla_{H_1}$.

We consider the decomposition
    \[
    \nabla_{H_1}=\widetilde{\nabla}+\Psi
    \] 
where $\Psi$ is a section of
\[\bigoplus_{\va\neq \vb}A^{1}(\operatorname{Hom}({}^{I}\!G_{\vb},{}^{I}\!G_{\va})).\]

Let $\Psi=\Psi^{1,0}+\Psi^{0,1}$ be the decomposition into the $(1,0)$-part and the $(0,1)$-part. We express
\[\Psi^{1,0}=\sum \Psi_{j}^{1,0}\,dz_{j},\quad \Psi^{0,1}=\sum \Psi_{j}^{0,1}d\overline{z}_{j}.\]
We have the decompositions
\[\Psi_{j}^{p,q}=\sum(\Psi_{j}^{p,q})_{\va,\vb},\qquad (\Psi_{j}^{p,q})_{\va,\vb}\in A^{0}(\operatorname{Hom}({}^{I}\!G_{\vb},{}^{I}\!G_{\va})).\]
By the construction, $(\Psi_{j}^{p,q})_{\va,\va}=0$ for any $1\leq j\leq n$ and $\va\in S^I$.

We denote $F_{\nabla}$ as the curvature tensor with respect to some connection $\nabla$. Then we have the following lemma.
\begin{Lemma}\label{curvatureboundbundle}
    $|F_{\nabla_{H_0}}|_{H_0}=O(\tau^{-\frac{1+\varepsilon}{2}})$
\end{Lemma}

\begin{proof}
    It suffices to consider in $U$. 
    We have 
    \[F_{\nabla_{H_1}}=F_{\widetilde{\nabla}}+\widetilde{\nabla}(\Psi)+\Psi\wedge \Psi.\]

    Hence 
    \begin{align*}
        F_{\nabla_{H_0}}=&F_{\nabla_{H_1}}+\overline{\partial}(s^{-1}\nabla_{H_1}^{1,0}s)\\
        =&F_{\widetilde{\nabla}}+\widetilde{\nabla}(\Psi)+\Psi\wedge \Psi+\overline{\partial}(s^{-1}\wnablayl s+s^{-1}[\Psi,s])\\
        =&B+\overline{\partial}(s^{-1}\Psi s)
    \end{align*}
