\title{Interpretable Neural Network Quantum States for Solving the Steady States of the Nonlinear Schrödinger Equation}

\author{Mingshu Zhao}
% \affiliation{Hebei Key Laboratory of Physics and Energy Technology, Department of Mathematics and Physics, North China Electric Power University, Baoding, Hebei 071003, China}

\author{Zhanyuan Yan}
 \email{yanzhanyuan@ncepu.edu.cn}
